VERSION = "0.5.0-sequence5"
WORKSPACE_ROOT = Path(__file__).resolve().parent.parent
SOURCE_WORKSPACE_ROOT = WORKSPACE_ROOT
_WORKSPACE_IMPORT_ROOT = str(WORKSPACE_ROOT)
# Direct `python scripts/ui_ux_theme_handoff.py ...` execution otherwise
# exposes only `scripts/` as the import root.  Remove any lower-priority copy
# and make the resolved workspace the unambiguous `scripts.*` import authority.
sys.path[:] = [
    entry for entry in sys.path if entry != _WORKSPACE_IMPORT_ROOT
]
sys.path.insert(0, _WORKSPACE_IMPORT_ROOT)
_SCRIPTS_IMPORT_ROOT = str((WORKSPACE_ROOT / "scripts").resolve(strict=True))
_scripts_package = sys.modules.get("scripts")
if _scripts_package is None:
    _scripts_package = type(sys)("scripts")
    _scripts_package.__package__ = "scripts"
    _scripts_package.__path__ = [_SCRIPTS_IMPORT_ROOT]
    sys.modules["scripts"] = _scripts_package
else:
    _scripts_origin = getattr(_scripts_package, "__file__", None)
    _scripts_paths = tuple(
        str(Path(entry).resolve())
        for entry in getattr(_scripts_package, "__path__", ())
    )
    if _scripts_origin is not None or _SCRIPTS_IMPORT_ROOT not in _scripts_paths:
        raise RuntimeError("scripts import authority differs from workspace")
    _scripts_package.__path__ = [_SCRIPTS_IMPORT_ROOT]

