class ContractViolation(ValueError):
    """A closed grammar, schema, authentication, or transition was rejected."""


class NamespaceCollision(ContractViolation):
    """A fixed public path or owned lifecycle namespace collided."""


class PrimitiveUnavailable(RuntimeError):
    """A required filesystem primitive failed before any commit."""


class ThemeHandoffNotImplemented(RuntimeError):
    """An intentional Task-1 red test reached behavior owned by Task 2+."""

    def __init__(self, test_ids: str | Sequence[str], behavior: str) -> None:
        normalized = (test_ids,) if isinstance(test_ids, str) else tuple(test_ids)
        if not normalized or any(re.fullmatch(r"TEST-[0-9]{3}", item) is None for item in normalized):
            raise ValueError("missing-behavior exception requires one or more TEST-NNN ids")
        self.test_ids = normalized
        self.test_id = normalized[0]
        self.behavior = behavior
        super().__init__(f"{'/'.join(normalized)} missing behavior: {behavior}")


class ProbeSocket(Protocol):
    def bind(self, address: Any, /) -> None: ...
    def listen(self, backlog: int = 1, /) -> None: ...
    def getsockname(self) -> Any: ...
    def accept(self) -> tuple["ProbeSocket", Any]: ...
    def connect(self, address: Any, /) -> None: ...
    def sendall(self, data: bytes, flags: int = 0, /) -> None: ...
    def sendto(self, data: bytes, address: Any, /) -> int: ...
    def recv(self, bufsize: int, flags: int = 0, /) -> bytes: ...
    def recvfrom(self, bufsize: int, flags: int = 0, /) -> tuple[bytes, Any]: ...
    def settimeout(self, value: float | None, /) -> None: ...
    def close(self) -> None: ...


class InProcessPrimitives(Protocol):
    def import_module(self, name: str, package: str | None = None) -> Any: ...
    def open(self, path: str, flags: int, mode: int = 0o777) -> int: ...
    def read(self, fd: int, size: int) -> bytes: ...
    def write(self, fd: int, data: bytes) -> int: ...
    def fstat(self, fd: int) -> Any: ...
    def lstat(self, path: str) -> Any: ...
    def close(self, fd: int) -> None: ...
    def unlink(self, path: str) -> None: ...
    def fsync(self, fd: int) -> None: ...
    def listdir(self, path: str) -> list[str]: ...
    def scandir(self, path: str) -> Any: ...
    def socket(self, family: int, type: int, proto: int = 0) -> ProbeSocket: ...
    def socketpair(self) -> tuple[ProbeSocket, ProbeSocket]: ...
    def getaddrinfo(
        self,
        host: str,
        port: int,
        family: int,
        type: int,
    ) -> list[Any]: ...


