def _authenticate_selector_archive(
    archive_bytes: bytes,
    expected_members: Sequence[dict[str, Any]],
) -> dict[str, Any]:
    if not isinstance(archive_bytes, bytes):
        raise ContractViolation("selector archive must be bytes")
    if len(archive_bytes) != SELECTOR_ARCHIVE_SIZE:
        raise ContractViolation("selector archive size mismatch")
    if hashlib.sha256(archive_bytes).hexdigest() != SELECTOR_ARCHIVE_SHA256:
        raise ContractViolation("selector archive digest mismatch")
    return _parse_selector_archive_projection(archive_bytes, expected_members)


def _parse_selector_archive_projection(
    archive_bytes: bytes,
    expected_members: Sequence[dict[str, Any]],
) -> dict[str, Any]:
    """Parse an already-authenticated selector archive without extraction.

    Keeping the structural parser separate lets TEST-004 exercise malformed
    tar members without adding a caller-controlled digest bypass to the
    authentication boundary.  Task 2 must call this only after authenticating
    the frozen outer archive bytes.
    """

    if list(expected_members) != list(SELECTOR_MEMBERS):
        raise ContractViolation("selector member contract mismatch")

    requested = {row["path"]: row for row in SELECTOR_MEMBERS}
    observed: dict[str, dict[str, Any]] = {}
    try:
        with tarfile.open(fileobj=io.BytesIO(archive_bytes), mode="r:*") as archive:
            for member in archive.getmembers():
                expected = requested.get(member.name)
                if expected is None:
                    continue
                if member.name in observed:
                    raise ContractViolation(f"duplicate selector member: {member.name}")
                normalized = posixpath.normpath(member.name)
                if (
                    normalized != member.name
                    or member.name.startswith("/")
                    or member.name in (".", "..")
                    or member.name.startswith("../")
                ):
                    raise ContractViolation(f"unsafe selector member path: {member.name}")
                if not member.isfile() or member.linkname:
                    raise ContractViolation(f"selector member is not a regular unlinked file: {member.name}")
                if member.mode != 0o644 or member.uid != 501 or member.gid != 20:
                    raise ContractViolation(f"selector member metadata mismatch: {member.name}")
                if member.size != expected["size"]:
                    raise ContractViolation(f"selector member size mismatch: {member.name}")
                payload_file = archive.extractfile(member)
                if payload_file is None:
                    raise ContractViolation(f"selector member payload unavailable: {member.name}")
                payload = payload_file.read()
                if len(payload) != member.size or hashlib.sha256(payload).hexdigest() != expected["sha256"]:
                    raise ContractViolation(f"selector member payload mismatch: {member.name}")
                observed[member.name] = dict(expected)
    except ContractViolation:
        raise
    except (tarfile.TarError, OSError, EOFError, ValueError) as exc:
        raise ContractViolation("invalid selector archive") from exc

    if set(observed) != set(requested):
        raise ContractViolation("selector archive is missing a required member")
    return {
        "historicalSelectorModes": [observed[row["path"]] for row in SELECTOR_MEMBERS],
        "sourceDigest": HISTORICAL_SOURCE_SHA256,
    }


def _workspace_namespace_paths(root: Path) -> tuple[str, ...]:
    if not root.exists():
        return ()
    rows: list[str] = []
    for path in root.rglob("*"):
        suffix = "/" if path.is_dir() and not path.is_symlink() else ""
        rows.append(path.relative_to(root).as_posix() + suffix)
    return tuple(sorted(rows))


def _read_fd_bytes(fd: int, *, limit: int = LIVE_IMAGE_HASH_LIMIT_BYTES) -> bytes:
    original = os.lseek(fd, 0, os.SEEK_CUR)
    chunks: list[bytes] = []
    size = 0
    try:
        os.lseek(fd, 0, os.SEEK_SET)
        while True:
            chunk = os.read(fd, 131_072)
            if not chunk:
                break
            size += len(chunk)
            if size > limit:
                raise ContractViolation("descriptor content exceeds the authenticated read bound")
            chunks.append(chunk)
    finally:
        os.lseek(fd, original, os.SEEK_SET)
    return b"".join(chunks)


def _file_record_from_fd(path: str, fd: int) -> dict[str, Any]:
    if not _is_safe_relative_path(path):
        raise ContractViolation("file record path is unsafe")
    before = os.fstat(fd)
    if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
        raise ContractViolation("file record requires a one-link regular file")
    data = _read_fd_bytes(fd)
    after = os.fstat(fd)
    if (before.st_dev, before.st_ino, before.st_size) != (after.st_dev, after.st_ino, after.st_size):
        raise ContractViolation("file changed while building its record")
    return {
        "path": path,
        "sha256": hashlib.sha256(data).hexdigest(),
        "size": len(data),
        "mode": f"{stat.S_IMODE(before.st_mode):04o}",
        "uid": before.st_uid,
        "gid": before.st_gid,
        "device": before.st_dev,
        "inode": before.st_ino,
        "nlink": before.st_nlink,
    }


def _relative_regular_record_and_bytes(
    root_fd: int,
    relative: str,
) -> tuple[dict[str, Any], bytes]:
    try:
        parent_fd, name = _open_relative_parent_fd(root_fd, relative)
    except FileNotFoundError as exc:
        raise ContractViolation(
            f"required regular file is unavailable: {relative}"
        ) from exc
    fd: int | None = None
    try:
        try:
            named_before = os.stat(
                name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            fd = os.open(
                name,
                os.O_RDONLY
                | os.O_NOFOLLOW
                | getattr(os, "O_CLOEXEC", 0),
                dir_fd=parent_fd,
            )
        except OSError as exc:
            raise ContractViolation(
                f"required regular file is unavailable: {relative}"
            ) from exc
        opened = os.fstat(fd)
        if (
            (
                named_before.st_dev,
                named_before.st_ino,
            )
            != (
                opened.st_dev,
                opened.st_ino,
            )
        ):
            raise ContractViolation(
                f"required regular file path drifted: {relative}"
            )
        record = _file_record_from_fd(relative, fd)
        data = _read_fd_bytes(fd)
        named_after = os.stat(
            name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if (
            (
                named_after.st_dev,
                named_after.st_ino,
            )
            != (
                opened.st_dev,
                opened.st_ino,
            )
            or hashlib.sha256(data).hexdigest() != record["sha256"]
            or len(data) != record["size"]
        ):
            raise ContractViolation(
                f"required regular file changed while retained: {relative}"
            )
        _require_relative_parent_current(root_fd, relative, parent_fd)
        return record, data
    except OSError as exc:
        raise ContractViolation(
            f"required regular file cannot be authenticated: {relative}"
        ) from exc
    finally:
        if fd is not None:
            os.close(fd)
        os.close(parent_fd)


def _relative_file_record(root_fd: int, relative: str) -> dict[str, Any]:
    record, _ = _relative_regular_record_and_bytes(root_fd, relative)
    return record


def _read_relative_canonical_evidence(
    root_fd: int,
    relative: str,
) -> dict[str, Any]:
    record, data = _relative_regular_record_and_bytes(root_fd, relative)
    if (
        record["mode"] != "0600"
        or record["uid"] != os.getuid()
        or record["gid"] != os.getgid()
        or record["nlink"] != 1
    ):
        raise ContractViolation(
            f"canonical evidence metadata differs: {relative}"
        )
    value = _strict_json_bytes(data, allow_float=True)
    if not isinstance(value, dict):
        raise ContractViolation("lifecycle evidence must be a JSON object")
    return value


def _file_record_at(root: Path, physical: str, logical: str | None = None) -> dict[str, Any]:
    try:
        fd = os.open(root / physical, os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0))
    except OSError as exc:
        raise ContractViolation(f"required regular file is unavailable: {physical}") from exc
    try:
        return _file_record_from_fd(physical if logical is None else logical, fd)
    finally:
        os.close(fd)


def _source_file_record(source_root_fd: int, relative: str) -> tuple[dict[str, Any], bytes]:
    return _relative_regular_record_and_bytes(source_root_fd, relative)


def _sequence7_failed_manifest_record(
    source_root_fd: int,
) -> tuple[dict[str, Any], bytes]:
    """Open the immutable gid-0 canary directory without relaxing traversal."""

    relative = SEQUENCE7_FAILED_CANARY_MANIFEST_REF["path"]
    directory_relative = posixpath.dirname(relative)
    manifest_name = posixpath.basename(relative)
    parent_fd, directory_name = _open_relative_parent_fd(
        source_root_fd,
        directory_relative,
    )
    directory_fd: int | None = None
    manifest_fd: int | None = None
    try:
        named_directory = os.stat(
            directory_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        directory_fd = os.open(
            directory_name,
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0),
            dir_fd=parent_fd,
        )
        opened_directory = os.fstat(directory_fd)
        if (
            not stat.S_ISDIR(named_directory.st_mode)
            or not stat.S_ISDIR(opened_directory.st_mode)
            or (
                named_directory.st_dev,
                named_directory.st_ino,
            )
            != (
                opened_directory.st_dev,
                opened_directory.st_ino,
            )
            or opened_directory.st_ino != 13_456_363
            or stat.S_IMODE(opened_directory.st_mode) != 0o700
            or opened_directory.st_uid != 501
            or opened_directory.st_gid != 0
        ):
            raise ContractViolation(
                "Sequence 7 canary directory identity differs"
            )
        named_manifest = os.stat(
            manifest_name,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
        manifest_fd = os.open(
            manifest_name,
            os.O_RDONLY
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0),
            dir_fd=directory_fd,
        )
        opened_manifest = os.fstat(manifest_fd)
        if (
            (
                named_manifest.st_dev,
                named_manifest.st_ino,
            )
            != (
                opened_manifest.st_dev,
                opened_manifest.st_ino,
            )
        ):
            raise ContractViolation(
                "Sequence 7 canary manifest path drifted"
            )
        record = _file_record_from_fd(relative, manifest_fd)
        data = _read_fd_bytes(manifest_fd)
        directory_after = os.stat(
            directory_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        manifest_after = os.stat(
            manifest_name,
            dir_fd=directory_fd,
            follow_symlinks=False,
        )
        if (
            (
                directory_after.st_dev,
                directory_after.st_ino,
            )
            != (
                opened_directory.st_dev,
                opened_directory.st_ino,
            )
            or (
                manifest_after.st_dev,
                manifest_after.st_ino,
            )
            != (
                opened_manifest.st_dev,
                opened_manifest.st_ino,
            )
            or hashlib.sha256(data).hexdigest() != record["sha256"]
            or len(data) != record["size"]
        ):
            raise ContractViolation(
                "Sequence 7 canary manifest changed while retained"
            )
        _require_relative_parent_current(
            source_root_fd,
            directory_relative,
            parent_fd,
        )
        return record, data
    except ContractViolation:
        raise
    except OSError as exc:
        raise ContractViolation(
            "Sequence 7 canary manifest is unavailable"
        ) from exc
    finally:
        if manifest_fd is not None:
            os.close(manifest_fd)
        if directory_fd is not None:
            os.close(directory_fd)
        os.close(parent_fd)


def _require_source_module_origin(
    module: Any,
    relative: str,
) -> Any:
    if not _is_safe_relative_path(relative):
        raise ContractViolation("source module path is unsafe")
    module_path = getattr(module, "__file__", None)
    if not isinstance(module_path, str):
        raise ContractViolation("source module has no file origin")
    try:
        observed = Path(module_path).resolve(strict=True)
        expected = (SOURCE_WORKSPACE_ROOT / relative).resolve(strict=True)
    except OSError as exc:
        raise ContractViolation("source module origin is unavailable") from exc
    if observed != expected:
        raise ContractViolation(
            f"source module origin differs: {relative}"
        )
    return module


def _compatibility_contract_bytes() -> bytes:
    expected_keys = {
        "forwardPatchSha256",
        "forwardPatchSize",
        "mode",
        "path",
        "postSha256",
        "postSize",
        "preSha256",
        "preSize",
    }
    rows = [dict(row) for row in COMPATIBILITY_ROWS]
    if [row.get("path") for row in rows] != sorted(
        row.get("path") for row in rows
    ):
        raise ContractViolation("compatibility contract path order differs")
    for row in rows:
        if set(row) != expected_keys:
            raise ContractViolation("compatibility contract row keys differ")
        for field in ("forwardPatchSize", "postSize", "preSize"):
            if type(row[field]) is not int or row[field] < 0:
                raise ContractViolation("compatibility contract size is invalid")
        for field in expected_keys - {
            "forwardPatchSize",
            "postSize",
            "preSize",
        }:
            if not isinstance(row[field], str):
                raise ContractViolation("compatibility contract string is invalid")
        for field in ("forwardPatchSha256", "postSha256", "preSha256"):
            if re.fullmatch(r"[0-9a-f]{64}", row[field]) is None:
                raise ContractViolation("compatibility contract digest is invalid")
        if (
            row["mode"] != "0444"
            or not _is_safe_relative_path(row["path"])
        ):
            raise ContractViolation("compatibility contract path/mode is invalid")
    encoded = _canonical_json_bytes(rows)
    if (
        len(encoded) != COMPATIBILITY_CONTRACT_SIZE
        or hashlib.sha256(encoded).hexdigest()
        != COMPATIBILITY_CONTRACT_SHA256
    ):
        raise ContractViolation("compatibility contract canonical bytes differ")
    return encoded


def _reverse_compatibility_source(path: str, postimage: bytes) -> bytes:
    if not isinstance(path, str) or not isinstance(postimage, bytes):
        raise ContractViolation("compatibility reverse inputs are invalid")
    _compatibility_contract_bytes()
    rows = {row["path"]: row for row in COMPATIBILITY_ROWS}
    if set(rows) != set(COMPATIBILITY_REVERSE_EDITS):
        raise ContractViolation("compatibility reverse path set differs")
    row = rows.get(path)
    if row is None:
        raise ContractViolation("compatibility reverse path is not authorized")
    if (
        len(postimage) != row["postSize"]
        or hashlib.sha256(postimage).hexdigest() != row["postSha256"]
    ):
        raise ContractViolation("compatibility live postimage differs")

    reconstructed = postimage
    edits = COMPATIBILITY_REVERSE_EDITS[path]
    if (
        not isinstance(edits, tuple)
        or not edits
        or any(
            not isinstance(edit, tuple)
            or len(edit) != 2
            or not isinstance(edit[0], bytes)
            or not isinstance(edit[1], bytes)
            or not edit[0]
            for edit in edits
        )
    ):
        raise ContractViolation("compatibility reverse edits are invalid")
    order_digest = hashlib.sha256(
        b"quant-radar-ui-ux-regression-compatibility-reverse-edit-order/v1\0"
    )
    order_digest.update(path.encode("utf-8"))
    order_digest.update(b"\0")
    for post_fragment, pre_fragment in edits:
        order_digest.update(len(post_fragment).to_bytes(8, "big"))
        order_digest.update(post_fragment)
        order_digest.update(len(pre_fragment).to_bytes(8, "big"))
        order_digest.update(pre_fragment)
    if (
        set(COMPATIBILITY_REVERSE_EDIT_ORDER_SHA256)
        != set(COMPATIBILITY_REVERSE_EDITS)
        or order_digest.hexdigest()
        != COMPATIBILITY_REVERSE_EDIT_ORDER_SHA256.get(path)
    ):
        raise ContractViolation("compatibility reverse edit order differs")
    for post_fragment, pre_fragment in edits:
        if reconstructed.count(post_fragment) != 1:
            raise ContractViolation(
                "compatibility reverse fragment cardinality differs"
            )
        reconstructed = reconstructed.replace(
            post_fragment,
            pre_fragment,
            1,
        )
    if (
        len(reconstructed) != row["preSize"]
        or hashlib.sha256(reconstructed).hexdigest() != row["preSha256"]
    ):
        raise ContractViolation("compatibility reconstructed preimage differs")

    try:
        before_text = reconstructed.decode("utf-8", errors="strict")
        after_text = postimage.decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise ContractViolation("compatibility source is not UTF-8") from exc
    patch = "".join(
        difflib.unified_diff(
            before_text.splitlines(keepends=True),
            after_text.splitlines(keepends=True),
            fromfile=f"a/{path}",
            tofile=f"b/{path}",
            n=3,
        )
    ).encode("utf-8")
    if (
        len(patch) != row["forwardPatchSize"]
        or hashlib.sha256(patch).hexdigest()
        != row["forwardPatchSha256"]
    ):
        raise ContractViolation("compatibility forward patch differs")
    return reconstructed


def _reauthenticate_compatibility_boundary(
    source_root_fd: int,
) -> dict[str, Any]:
    if (
        type(source_root_fd) is not int
        or source_root_fd < 0
        or not stat.S_ISDIR(os.fstat(source_root_fd).st_mode)
    ):
        raise ContractViolation("compatibility source-root descriptor is invalid")
    contract_bytes = _compatibility_contract_bytes()
    live_postimages: list[dict[str, Any]] = []
    historical_preimages: list[dict[str, Any]] = []
    retained_postimages: list[tuple[dict[str, Any], bytes]] = []
    for row in COMPATIBILITY_ROWS:
        live_record, postimage = _source_file_record(
            source_root_fd,
            row["path"],
        )
        if (
            live_record["sha256"] != row["postSha256"]
            or live_record["size"] != row["postSize"]
        ):
            raise ContractViolation(
                f"compatibility live authority differs: {row['path']}"
            )
        live_postimages.append(live_record)
        retained_postimages.append((row, postimage))
    for row, postimage in retained_postimages:
        preimage = _reverse_compatibility_source(row["path"], postimage)
        historical_preimages.append(
            {
                "path": row["path"],
                "sha256": hashlib.sha256(preimage).hexdigest(),
                "size": len(preimage),
                "mode": row["mode"],
            }
        )
    return {
        "contract": {
            "sha256": hashlib.sha256(contract_bytes).hexdigest(),
            "size": len(contract_bytes),
        },
        "livePostimages": live_postimages,
        "historicalPreimages": historical_preimages,
    }


def _reconstruct_historical_source_projection(
    current_records: Sequence[dict[str, Any]],
    source_root_fd: int,
) -> dict[str, Any]:
    if not isinstance(current_records, Sequence) or isinstance(
        current_records,
        (str, bytes),
    ):
        raise ContractViolation("current source projection is invalid")
    normalized: list[dict[str, Any]] = []
    for row in current_records:
        if (
            not isinstance(row, dict)
            or set(row) != {"path", "sha256", "size", "mode"}
            or not isinstance(row.get("path"), str)
            or not _is_safe_relative_path(row["path"])
            or not isinstance(row.get("sha256"), str)
            or re.fullmatch(r"[0-9a-f]{64}", row["sha256"]) is None
            or type(row.get("size")) is not int
            or row["size"] < 0
            or row.get("mode") not in {"0444", "0555"}
        ):
            raise ContractViolation("current source projection row is invalid")
        normalized.append(dict(row))
    paths = [row["path"] for row in normalized]
    if paths != sorted(paths) or len(paths) != len(set(paths)):
        raise ContractViolation("current source projection order differs")

    records = {row["path"]: row for row in normalized}
    for contract_row in COMPATIBILITY_ROWS:
        expected_postimage = {
            "path": contract_row["path"],
            "sha256": contract_row["postSha256"],
            "size": contract_row["postSize"],
            "mode": contract_row["mode"],
        }
        if records.get(contract_row["path"]) != expected_postimage:
            raise ContractViolation(
                "compatibility mirror postimage differs"
            )
    boundary = _reauthenticate_compatibility_boundary(source_root_fd)
    for contract_row, preimage_row in zip(
        COMPATIBILITY_ROWS,
        boundary["historicalPreimages"],
    ):
        records[contract_row["path"]] = dict(preimage_row)

    for relative in (
        "scripts/test_ui_ux_awake_gate.py",
        "scripts/test_ui_ux_theme_handoff.py",
        "scripts/ui_ux_awake_gate.py",
        "scripts/ui_ux_theme_handoff.py",
    ):
        if relative not in records:
            raise ContractViolation(
                "historical verifier path is absent from current projection"
            )
        del records[relative]
    for row in SELECTOR_MEMBERS:
        if row["path"] not in records:
            raise ContractViolation(
                "historical selector path is absent from current projection"
            )
        records[row["path"]] = {
            "path": row["path"],
            "sha256": row["sha256"],
            "size": row["size"],
            "mode": row["mirrorMode"],
        }

    historical_rows = [records[path] for path in sorted(records)]
    digest_payload = {
        "schemaVersion": "quant-radar-ui-ux-ux1b-source-mirror/v1",
        "files": historical_rows,
    }
    digest = hashlib.sha256(_canonical_json_bytes(digest_payload)).hexdigest()
    if digest != HISTORICAL_SOURCE_SHA256:
        raise ContractViolation("historical source projection digest differs")
    return {
        **digest_payload,
        "digest": digest,
        "compatibilityContract": dict(boundary["contract"]),
    }


def _resolve_sequence8_historical_source_projection(
    current_records: Sequence[dict[str, Any]],
    source_root_fd: int,
) -> dict[str, Any]:
    """Use live reverse reconstruction for a fresh Sequence 8 operation."""

    return _reconstruct_historical_source_projection(
        current_records,
        source_root_fd,
    )


def _artifact_ref(record: Mapping[str, Any]) -> dict[str, Any]:
    return {"path": record["path"], "sha256": record["sha256"], "size": record["size"]}


def _write_new_file(root: Path, relative: str, data: bytes, mode: int = 0o600) -> int:
    path = root / relative
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    fd = os.open(
        path,
        os.O_CREAT | os.O_EXCL | os.O_RDWR | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
        mode,
    )
    view = memoryview(data)
    while view:
        written = os.write(fd, view)
        if written <= 0:
            os.close(fd)
            raise OSError(errno.EIO, "short bootstrap write")
        view = view[written:]
    return fd


def _read_canonical_file(root: Path, relative: str) -> dict[str, Any]:
    try:
        fd = os.open(root / relative, os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0))
    except OSError as exc:
        raise ContractViolation(f"required canonical evidence is unavailable: {relative}") from exc
    try:
        data = _read_fd_bytes(fd)
    finally:
        os.close(fd)
    value = _strict_json_bytes(data, allow_float=True)
    if not isinstance(value, dict):
        raise ContractViolation("lifecycle evidence must be a JSON object")
    return value


