def _reauthenticate_upstream_authorities(
    source_root_fd: int,
) -> list[dict[str, Any]]:
    if (
        type(source_root_fd) is not int
        or source_root_fd < 0
        or not stat.S_ISDIR(os.fstat(source_root_fd).st_mode)
    ):
        raise ContractViolation("upstream authority source-root descriptor is invalid")
    records: list[dict[str, Any]] = []
    retained: dict[str, bytes] = {}
    for relative in sorted(UPSTREAM_AUTHORITY_SHA256):
        record, data = _source_file_record(source_root_fd, relative)
        if record["sha256"] != UPSTREAM_AUTHORITY_SHA256[relative]:
            raise ContractViolation(f"upstream authority content mismatch: {relative}")
        records.append(record)
        retained[relative] = data

    archive_path = (
        ".claude/ui_snapshots/ux1b/recovery/"
        "prechange-bundle-20260716T145533Z/prechange-files.tar"
    )
    _authenticate_selector_archive(retained[archive_path], SELECTOR_MEMBERS)
    classification_path = (
        "docs/ui-ux/quant-radar-ui-v2-ux1b-classification.json"
    )
    try:
        classification = json.loads(
            retained[classification_path].decode("utf-8", errors="strict")
        )
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ContractViolation("classification authority JSON is invalid") from exc
    if (
        not isinstance(classification, dict)
        or classification.get("state") != "pending"
    ):
        raise ContractViolation("classification authority is not the pending preimage")
    return records


def _reauthenticate_capture_stack(
    source_root_fd: int,
) -> dict[str, Any]:
    if (
        type(source_root_fd) is not int
        or source_root_fd < 0
        or not stat.S_ISDIR(os.fstat(source_root_fd).st_mode)
    ):
        raise ContractViolation("capture-stack source-root descriptor is invalid")
    contract_path = "docs/ui-ux/quant-radar-ui-v2-ux1b-capture-stack.json"
    contract_record, contract_bytes = _source_file_record(
        source_root_fd,
        contract_path,
    )
    if {
        key: contract_record[key] for key in ("sha256", "size", "mode")
    } != {
        "sha256": "8b354ec6d7f84e4bfbd96c098ffd1dae2db0d90f7f9cf86d168bc8a9298df820",
        "size": 5_340,
        "mode": "0600",
    }:
        raise ContractViolation("capture-stack contract authority mismatch")
    try:
        contract = json.loads(contract_bytes.decode("utf-8", errors="strict"))
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ContractViolation("capture-stack contract JSON is invalid") from exc
    if (
        not isinstance(contract, dict)
        or set(contract)
        != {
            "schemaVersion",
            "baseCaptureStackDigest",
            "captureStackDigest",
            "members",
            "controlCatalog",
            "workerCatalog",
        }
        or contract.get("schemaVersion")
        != "quant-radar-ui-ux-ux1b-capture-stack/v1"
        or contract.get("baseCaptureStackDigest")
        != "6c1f08266d479d3e3e3e77f35dc06b6b5cd81c5160c9a1df91ed0e7b7dcdbfe7"
        or contract.get("captureStackDigest")
        != "69eeec0dcdffdab16d5696896cb4fc5ddb27071591953d04b4c907ea5b78055e"
        or not isinstance(contract.get("members"), list)
        or len(contract["members"]) != 9
    ):
        raise ContractViolation("capture-stack contract fields mismatch")

    member_records: list[dict[str, Any]] = []
    digest_rows: list[dict[str, Any]] = []
    for expected in contract["members"]:
        if (
            not isinstance(expected, dict)
            or set(expected) != {"path", "sha256", "size", "mode"}
            or type(expected["mode"]) is not int
            or expected["mode"] != 0o644
        ):
            raise ContractViolation("capture-stack member declaration is invalid")
        record, _ = _source_file_record(source_root_fd, expected["path"])
        if {
            "path": record["path"],
            "sha256": record["sha256"],
            "size": record["size"],
            "mode": int(record["mode"], 8),
        } != expected:
            raise ContractViolation(
                f"capture-stack member authority mismatch: {expected['path']}"
            )
        member_records.append(record)
        digest_rows.append(expected)
    if [row["path"] for row in digest_rows] != sorted(
        row["path"] for row in digest_rows
    ):
        raise ContractViolation("capture-stack member order mismatch")

    evidence_member = next(
        row for row in digest_rows if row["path"] == "scripts/ui_ux_evidence.py"
    )
    if (
        evidence_member["sha256"]
        != "3ae2a02b519a70f4e8ef146c486f0ad4cd306718ad5429ec20dd8ccf951f009a"
    ):
        raise ContractViolation("capture-stack digest implementation is not frozen")
    from scripts import ui_ux_evidence

    _require_source_module_origin(
        ui_ux_evidence,
        "scripts/ui_ux_evidence.py",
    )
    observed_base_digest = ui_ux_evidence.capture_stack_digest(
        [row["path"] for row in digest_rows],
        root_fd=source_root_fd,
    )
    if observed_base_digest != contract["baseCaptureStackDigest"]:
        raise ContractViolation("capture-stack base digest mismatch")
    return {
        "contract": contract_record,
        "baseDigest": contract["baseCaptureStackDigest"],
        "digest": contract["captureStackDigest"],
        "members": member_records,
    }


def _reauthenticate_sequence12_capture_stack(
    source_root_fd: int,
) -> dict[str, Any]:
    """Authenticate Sequence 12 as exact whole-file historical authority."""

    if (
        type(source_root_fd) is not int
        or source_root_fd < 0
        or not stat.S_ISDIR(os.fstat(source_root_fd).st_mode)
    ):
        raise ContractViolation(
            "Sequence 12 capture-stack source-root descriptor is invalid"
        )
    from scripts import ui_ux_evidence

    contract_record, payload = _relative_regular_record_and_bytes(
        source_root_fd,
        SEQUENCE12_CAPTURE_STACK_REF["path"],
    )
    if {
        key: contract_record[key]
        for key in ("path", "sha256", "size", "mode")
    } != SEQUENCE12_CAPTURE_STACK_REF:
        raise ContractViolation(
            "Sequence 12 capture-stack contract authority differs"
        )
    contract = _strict_json_bytes(payload)
    if (
        not isinstance(contract, dict)
        or payload != _canonical_json_bytes(contract)
        or set(contract)
        != {
            "schemaVersion",
            "baseCaptureStackDigest",
            "captureStackDigest",
            "controlCatalog",
            "members",
            "rootExpansionSha256",
            "workerCatalog",
        }
        or not isinstance(contract.get("members"), list)
        or not isinstance(contract.get("controlCatalog"), dict)
    ):
        raise ContractViolation(
            "Sequence 12 capture-stack document differs"
        )
    expected_paths = tuple(
        relative
        for relative, _sha256 in SNAPSHOT_SUBSET_CLOSURE[1:]
    )
    observed_paths = tuple(
        member["path"] for member in contract["members"]
    )
    if (
        observed_paths != expected_paths
        or contract.get("rootExpansionSha256")
        != ROOT_CAPTURE_EXPANSION_REF["sha256"]
        or contract.get("baseCaptureStackDigest")
        != (
            "fbe9866e12ab5f6a70c8127cddb9b0b"
            "db0dc09a5f16762f3af8e16bec4aac920"
        )
        or contract.get("captureStackDigest")
        != (
            "5cc960797587028ea31388c6556c569f"
            "fe75455b1d852bbf6d3e733849f5af9d"
        )
    ):
        raise ContractViolation(
            "Sequence 12 capture-stack contract fields differ"
        )
    return {
        "contract": contract_record,
        "baseDigest": contract["baseCaptureStackDigest"],
        "digest": contract["captureStackDigest"],
        "members": [
            {
                "path": member["path"],
                "sha256": member["sha256"],
                "size": member["size"],
                "mode": format(member["mode"], "04o"),
            }
            for member in contract["members"]
        ],
        "controlCatalog": copy.deepcopy(
            contract["controlCatalog"]
        ),
        "rootExpansion": copy.deepcopy(ROOT_CAPTURE_EXPANSION_REF),
    }


def _source_namespace_file_records(
    source_root_fd: int,
    relative_root: str,
) -> list[dict[str, Any]]:
    if (
        type(source_root_fd) is not int
        or source_root_fd < 0
        or not _is_safe_relative_path(relative_root)
    ):
        raise ContractViolation("source namespace inputs are invalid")
    flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | os.O_NOFOLLOW
        | getattr(os, "O_CLOEXEC", 0)
    )
    try:
        root_fd = os.open(relative_root, flags, dir_fd=source_root_fd)
    except OSError as exc:
        raise ContractViolation(
            f"source namespace is unavailable: {relative_root}"
        ) from exc
    records: list[dict[str, Any]] = []

    def walk(directory_fd: int, logical_parent: str) -> None:
        for name in sorted(os.listdir(directory_fd)):
            if name in {"", ".", ".."} or "/" in name or "\0" in name:
                raise ContractViolation("source namespace name is unsafe")
            observed = os.stat(
                name,
                dir_fd=directory_fd,
                follow_symlinks=False,
            )
            logical = f"{logical_parent}/{name}"
            if stat.S_ISLNK(observed.st_mode):
                raise ContractViolation(
                    f"source namespace contains a symlink: {logical}"
                )
            if stat.S_ISDIR(observed.st_mode):
                child_fd = os.open(name, flags, dir_fd=directory_fd)
                try:
                    opened = os.fstat(child_fd)
                    if (
                        opened.st_dev,
                        opened.st_ino,
                    ) != (
                        observed.st_dev,
                        observed.st_ino,
                    ):
                        raise ContractViolation(
                            "source namespace directory identity changed"
                        )
                    walk(child_fd, logical)
                    if (
                        opened.st_dev,
                        opened.st_ino,
                    ) != (
                        os.fstat(child_fd).st_dev,
                        os.fstat(child_fd).st_ino,
                    ):
                        raise ContractViolation(
                            "source namespace directory changed while reading"
                        )
                finally:
                    os.close(child_fd)
                continue
            if not stat.S_ISREG(observed.st_mode) or observed.st_nlink != 1:
                raise ContractViolation(
                    f"source namespace contains an unsafe leaf: {logical}"
                )
            file_fd = os.open(
                name,
                os.O_RDONLY
                | os.O_NOFOLLOW
                | getattr(os, "O_CLOEXEC", 0),
                dir_fd=directory_fd,
            )
            try:
                record = _file_record_from_fd(logical, file_fd)
                opened = os.fstat(file_fd)
                if (
                    opened.st_dev,
                    opened.st_ino,
                ) != (
                    observed.st_dev,
                    observed.st_ino,
                ):
                    raise ContractViolation(
                        "source namespace file identity changed"
                    )
                records.append(record)
            finally:
                os.close(file_fd)

    try:
        walk(root_fd, relative_root)
    finally:
        os.close(root_fd)
    paths = [record["path"] for record in records]
    if paths != sorted(paths) or len(paths) != len(set(paths)):
        raise ContractViolation("source namespace record set/order differs")
    return records


def _reauthenticate_task6_inputs(
    source_root_fd: int,
) -> dict[str, Any]:
    if (
        type(source_root_fd) is not int
        or source_root_fd < 0
        or not stat.S_ISDIR(os.fstat(source_root_fd).st_mode)
    ):
        raise ContractViolation("Task 6 source-root descriptor is invalid")
    bundles: dict[str, dict[str, Any]] = {}
    all_records: list[dict[str, Any]] = []
    for expected in TASK6_MANIFEST_ROWS:
        manifest_record, manifest_bytes = _source_file_record(
            source_root_fd,
            expected["path"],
        )
        if {
            key: manifest_record[key]
            for key in ("sha256", "size", "mode")
        } != {
            "sha256": expected["sha256"],
            "size": expected["size"],
            "mode": "0600",
        }:
            raise ContractViolation(
                f"Task 6 manifest authority differs: {expected['kind']}"
            )
        try:
            manifest = json.loads(
                manifest_bytes.decode("utf-8", errors="strict")
            )
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise ContractViolation("Task 6 manifest JSON is invalid") from exc
        captures = manifest.get("captures") if isinstance(manifest, dict) else None
        if (
            not isinstance(captures, list)
            or len(captures) != expected["captureCount"]
            or manifest.get("status") != "passed"
            or manifest.get("childrenQuiescent") is not True
            or manifest.get("sourceDigestStart") != HISTORICAL_SOURCE_SHA256
            or manifest.get("sourceDigestEnd") != HISTORICAL_SOURCE_SHA256
        ):
            raise ContractViolation("Task 6 manifest lifecycle fields differ")

        manifest_root = str(PurePosixPath(expected["path"]).parent)
        namespace_records = _source_namespace_file_records(
            source_root_fd,
            manifest_root,
        )
        by_path = {record["path"]: record for record in namespace_records}
        expected_paths = {expected["path"]}
        capture_ids: list[str] = []
        artifact_count = 0
        for capture in captures:
            if (
                not isinstance(capture, dict)
                or set(capture) != {"artifacts", "id", "status"}
                or capture["status"] != "passed"
                or not isinstance(capture["id"], str)
                or not _is_safe_relative_path(capture["id"])
                or not isinstance(capture["artifacts"], dict)
                or set(capture["artifacts"]) != {"png", "renderSidecar"}
            ):
                raise ContractViolation("Task 6 capture row differs")
            capture_id = capture["id"]
            capture_ids.append(capture_id)
            for artifact_kind, leaf_name, keys in (
                (
                    "png",
                    "capture.png",
                    {"height", "path", "sha256", "size", "width"},
                ),
                (
                    "renderSidecar",
                    "render.json",
                    {"path", "schemaVersion", "sha256", "size"},
                ),
            ):
                descriptor = capture["artifacts"][artifact_kind]
                expected_relative = f"captures/{capture_id}/{leaf_name}"
                if (
                    not isinstance(descriptor, dict)
                    or set(descriptor) != keys
                    or descriptor.get("path") != expected_relative
                    or not isinstance(descriptor.get("sha256"), str)
                    or re.fullmatch(
                        r"[0-9a-f]{64}",
                        descriptor["sha256"],
                    )
                    is None
                    or type(descriptor.get("size")) is not int
                    or descriptor["size"] <= 0
                ):
                    raise ContractViolation(
                        "Task 6 artifact descriptor differs"
                    )
                logical = f"{manifest_root}/{expected_relative}"
                record = by_path.get(logical)
                if (
                    record is None
                    or record["sha256"] != descriptor["sha256"]
                    or record["size"] != descriptor["size"]
                    or record["mode"] != "0600"
                ):
                    raise ContractViolation(
                        "Task 6 artifact bytes differ from its manifest"
                    )
                expected_paths.add(logical)
                artifact_count += 1
        if (
            capture_ids != sorted(capture_ids)
            or len(capture_ids) != len(set(capture_ids))
            or artifact_count != expected["artifactCount"]
            or len(namespace_records) != expected["namespaceLeafCount"]
            or set(by_path) != expected_paths
        ):
            raise ContractViolation("Task 6 namespace set/order differs")
        all_records.extend(namespace_records)
        bundles[expected["kind"]] = {
            "manifest": manifest_record,
            "captureCount": len(capture_ids),
            "artifactCount": artifact_count,
            "namespaceLeafCount": len(namespace_records),
            "captureIdsSha256": hashlib.sha256(
                _canonical_json_bytes(capture_ids)
            ).hexdigest(),
        }
    paths = [record["path"] for record in all_records]
    if len(paths) != len(set(paths)):
        raise ContractViolation("Task 6 input namespaces overlap")
    return {
        "pages": bundles["pages"],
        "controls": bundles["controls"],
        "records": sorted(all_records, key=lambda item: item["path"]),
    }


def _build_authenticated_current_source_projection(
    source_root_fd: int,
) -> dict[str, Any]:
    if (
        type(source_root_fd) is not int
        or source_root_fd < 0
        or not stat.S_ISDIR(os.fstat(source_root_fd).st_mode)
    ):
        raise ContractViolation("source-projection descriptor is invalid")
    from scripts import ui_ux_isolation as isolation
    from scripts import ui_ux_snapshot_matrix as snapshot_matrix

    _require_source_module_origin(
        isolation,
        "scripts/ui_ux_isolation.py",
    )
    _require_source_module_origin(
        snapshot_matrix,
        "scripts/ui_ux_snapshot_matrix.py",
    )
    try:
        with isolation.owned_run_root(
            Path(tempfile.gettempdir()),
            prefix="ux1b-handoff-source-",
        ) as owned:
            mirror = isolation.build_source_mirror(
                workspace_root_fd=source_root_fd,
                run_root=owned.path / "mirror",
                policy=isolation.SourceMirrorPolicy(
                    include=snapshot_matrix._expanded_ux1b_source_mirror_policy(),
                    exclude=(
                        ".agents",
                        ".claude",
                        ".git",
                        ".venv",
                        ".env*",
                        "__pycache__",
                        "data",
                        "reports",
                    ),
                ),
            )
            authenticated = isolation.authenticate_source_mirror(
                mirror,
                expected_digest=mirror.digest,
            )
            manifest_bytes = mirror.manifest_path.read_bytes()
            manifest = json.loads(
                manifest_bytes.decode("utf-8", errors="strict")
            )
            if (
                authenticated.get("passed") is not True
                or not isinstance(manifest, dict)
                or set(manifest)
                != {"schemaVersion", "files", "digest"}
                or manifest.get("schemaVersion")
                != "quant-radar-ui-ux-ux1b-source-mirror/v1"
                or manifest.get("digest") != mirror.digest
                or not isinstance(manifest.get("files"), list)
            ):
                raise ContractViolation(
                    "current source mirror authentication differs"
                )
            return manifest
    except ContractViolation:
        raise
    except (
        isolation.IsolationContractError,
        OSError,
        UnicodeError,
        json.JSONDecodeError,
        ValueError,
    ) as exc:
        raise ContractViolation(
            "current source mirror could not be authenticated"
        ) from exc


def _source_projection_value(
    schema_version: str,
    include: Sequence[str],
    exclude: Sequence[str],
    records: Sequence[Mapping[str, Any]],
    *,
    digest: str | None = None,
) -> dict[str, Any]:
    if schema_version not in {
        "quant-radar-ui-ux-ux1b-source-mirror/v1",
        "quant-radar-ui-ux-supplemental-source/v1",
    }:
        raise ContractViolation("source projection schema is invalid")
    if (
        not isinstance(include, Sequence)
        or isinstance(include, (str, bytes))
        or not isinstance(exclude, Sequence)
        or isinstance(exclude, (str, bytes))
        or any(not isinstance(rule, str) or not rule for rule in (*include, *exclude))
    ):
        raise ContractViolation("source projection policy is invalid")
    normalized: list[dict[str, Any]] = []
    for record in records:
        if (
            not isinstance(record, Mapping)
            or set(record) != {"path", "sha256", "size", "mode"}
            or not isinstance(record.get("path"), str)
            or not _is_safe_relative_path(record["path"])
            or not isinstance(record.get("sha256"), str)
            or re.fullmatch(r"[0-9a-f]{64}", record["sha256"]) is None
            or type(record.get("size")) is not int
            or record["size"] < 0
            or record.get("mode") not in {"0444", "0555"}
        ):
            raise ContractViolation("source projection record is invalid")
        normalized.append(dict(record))
    paths = [record["path"] for record in normalized]
    if paths != sorted(paths) or len(paths) != len(set(paths)):
        raise ContractViolation("source projection records are not unique/path-sorted")
    observed_digest = hashlib.sha256(
        _canonical_json_bytes(
            {"schemaVersion": schema_version, "files": normalized}
        )
    ).hexdigest()
    if digest is not None and digest != observed_digest:
        raise ContractViolation("source projection digest differs")
    return {
        "schemaVersion": schema_version,
        "policy": {
            "include": list(include),
            "exclude": list(exclude),
        },
        "records": normalized,
        "digest": observed_digest,
    }


def _import_stored_source_projections_history(
    source_root_fd: int,
    authority: Mapping[str, Any],
) -> dict[str, Any]:
    """Authenticate one retained preflight and return only its projections."""

    required = {
        "path",
        "sha256",
        "size",
        "mode",
        "schemaVersion",
        "sourceDigest",
        "supplementalCount",
        "supplementalDigest",
    }
    if not isinstance(authority, Mapping) or set(authority) != required:
        raise ContractViolation("historical projection authority is invalid")
    record, payload = _source_file_record(
        source_root_fd,
        authority["path"],
    )
    if {
        key: record[key]
        for key in ("path", "sha256", "size", "mode")
    } != {
        key: authority[key]
        for key in ("path", "sha256", "size", "mode")
    }:
        raise ContractViolation(
            "historical projection preflight authority differs"
        )
    preflight = _strict_json_bytes(payload, allow_float=True)
    if (
        not isinstance(preflight, dict)
        or preflight.get("schemaVersion") != authority["schemaVersion"]
        or preflight.get("status") != "passed"
    ):
        raise ContractViolation(
            "historical projection preflight identity differs"
        )
    validated: dict[str, dict[str, Any]] = {}
    for field in ("sourceProjection", "supplementalProjection"):
        projection = preflight.get(field)
        if (
            not isinstance(projection, dict)
            or set(projection)
            != {"schemaVersion", "policy", "records", "digest"}
            or not isinstance(projection.get("policy"), dict)
            or set(projection["policy"]) != {"include", "exclude"}
            or not isinstance(projection.get("records"), list)
        ):
            raise ContractViolation(
                f"historical {field} structure differs"
            )
        value = _source_projection_value(
            projection["schemaVersion"],
            projection["policy"]["include"],
            projection["policy"]["exclude"],
            projection["records"],
            digest=projection["digest"],
        )
        if value != projection:
            raise ContractViolation(
                f"historical {field} canonical value differs"
            )
        validated[field] = value
    source_projection = validated["sourceProjection"]
    supplemental = validated["supplementalProjection"]
    if (
        source_projection["schemaVersion"]
        != "quant-radar-ui-ux-ux1b-source-mirror/v1"
        or source_projection["policy"]
        != {
            "include": list(_MIRROR_INCLUDE_POLICY),
            "exclude": list(_MIRROR_EXCLUDE_POLICY),
        }
        or len(source_projection["records"]) != 270
        or source_projection["digest"] != authority["sourceDigest"]
        or len(supplemental["records"])
        != authority["supplementalCount"]
        or supplemental["digest"]
        != authority["supplementalDigest"]
    ):
        raise ContractViolation(
            "historical source projection receipt differs"
        )
    return {
        "sourceProjection": copy.deepcopy(source_projection),
        "supplementalProjection": copy.deepcopy(supplemental),
    }


def _import_sequence8_source_projections_history(
    source_root_fd: int,
) -> dict[str, Any]:
    authority = {
        **SEQUENCE8_PREFLIGHT_REF,
        "schemaVersion": (
            "quant-radar-ui-ux-formal-handoff-preflight/v2"
        ),
        "sourceDigest": (
            "ce35963d1cacba10eb562c616eb894c23b973d1fe2a03b9d23f4c95f6e77691f"
        ),
        "supplementalCount": 57,
        "supplementalDigest": (
            "de4be442df77699c71b1f357d3cb468deaa98dd93f2f62b50d254ba7b09a66d0"
        ),
    }
    return _import_stored_source_projections_history(
        source_root_fd,
        authority,
    )


def _import_later_source_projections_history(
    source_root_fd: int,
    sequence: str,
) -> dict[str, Any]:
    authority = HISTORICAL_SOURCE_PROJECTION_REFS.get(sequence)
    if authority is None:
        raise ContractViolation(
            "historical source projection sequence is invalid"
        )
    return _import_stored_source_projections_history(
        source_root_fd,
        authority,
    )


def _validate_amendment_entry_source_projection(
    source_root_fd: int,
    *,
    current_manifest: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Validate the 271-record Codex entry receipt without freezing new bytes."""

    current = _build_authenticated_current_source_projection(
        source_root_fd
    )
    if (
        current_manifest is not None
        and current_manifest != current
    ):
        raise ContractViolation(
            "amendment-entry manifest differs from live source"
        )
    if (
        not isinstance(current, Mapping)
        or set(current) != {"schemaVersion", "files", "digest"}
        or not isinstance(current.get("files"), list)
    ):
        raise ContractViolation(
            "amendment-entry source manifest is invalid"
        )
    raw = _source_projection_value(
        current["schemaVersion"],
        _MIRROR_INCLUDE_POLICY,
        _MIRROR_EXCLUDE_POLICY,
        current["files"],
        digest=current["digest"],
    )
    if len(raw["records"]) != 271:
        raise ContractViolation(
            "amendment-entry source count differs"
        )
    historical = _import_sequence8_source_projections_history(
        source_root_fd
    )["sourceProjection"]
    current_by_path = {
        row["path"]: row for row in raw["records"]
    }
    historical_by_path = {
        row["path"]: row for row in historical["records"]
    }
    removed = [
        {
            "operation": "remove",
            **historical_by_path[path],
        }
        for path in sorted(
            set(historical_by_path) - set(current_by_path)
        )
    ]
    added = [
        {
            "operation": "add",
            **current_by_path[path],
        }
        for path in sorted(
            set(current_by_path) - set(historical_by_path)
        )
    ]
    operations = [*removed, *added]
    operations_payload = b"".join(
        _canonical_json_bytes(row) + b"\n"
        for row in operations
    )
    if (
        operations != list(AMENDMENT_ENTRY_PATH_SET_OPERATIONS)
        or len(operations_payload) != 1_480
        or hashlib.sha256(operations_payload).hexdigest()
        != "0de1f29316171802cd30328bd386e0f7b741dc19bf618a5aa0b24a46f4b186b4"
    ):
        raise ContractViolation(
            "amendment-entry path-set transition differs"
        )
    normalized_by_path = copy.deepcopy(current_by_path)
    for path, entry_record in (
        AMENDMENT_ENTRY_IMPLEMENTATION_RECORDS.items()
    ):
        observed = normalized_by_path.get(path)
        if observed is None or observed.get("mode") != "0444":
            raise ContractViolation(
                "amendment implementation source mode differs: "
                + path
            )
        normalized_by_path[path] = copy.deepcopy(entry_record)
    normalized = _source_projection_value(
        raw["schemaVersion"],
        _MIRROR_INCLUDE_POLICY,
        _MIRROR_EXCLUDE_POLICY,
        [
            normalized_by_path[path]
            for path in sorted(normalized_by_path)
        ],
        digest=AMENDMENT_ENTRY_SOURCE_DIGEST,
    )
    return {
        "rawProjection": raw,
        "historicalProjection": historical,
        "pathSetOperations": operations,
        "pathSetOperationsSha256": hashlib.sha256(
            operations_payload
        ).hexdigest(),
        "entryNormalizedProjection": normalized,
    }


def _build_preflight_source_projections(
    source_root_fd: int,
    *,
    current_manifest: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    current = (
        _build_authenticated_current_source_projection(source_root_fd)
        if current_manifest is None
        else current_manifest
    )
    if (
        not isinstance(current, Mapping)
        or set(current) != {"schemaVersion", "files", "digest"}
        or current.get("schemaVersion")
        != "quant-radar-ui-ux-ux1b-source-mirror/v1"
        or not isinstance(current.get("files"), list)
        or not isinstance(current.get("digest"), str)
    ):
        raise ContractViolation("current source projection manifest is invalid")
    mirror = _source_projection_value(
        current["schemaVersion"],
        _MIRROR_INCLUDE_POLICY,
        _MIRROR_EXCLUDE_POLICY,
        current["files"],
        digest=current["digest"],
    )
    supplemental_paths = sorted(
        {
            "requirements.txt",
            "Makefile",
            AUTHORIZATION_DOCUMENT_PATH,
            BASE_DRAFT_PATH,
            AUTHORIZED_PLAN_REF["path"],
            AUTHORIZED_LEDGER_REF["path"],
            SEQUENCE7_PLAN_REF["path"],
            SEQUENCE7_LEDGER_REF["path"],
            SEQUENCE7_FAILED_CANARY_MANIFEST_REF["path"],
            SEQUENCE6_PLAN_REF["path"],
            SEQUENCE6_LEDGER_REF["path"],
            SEQUENCE6_PREFLIGHT_REF["path"],
            SEQUENCE6_INTENT_REF["path"],
            SEQUENCE6_TERMINAL_REF["path"],
            SEQUENCE6_FAILED_POSTCONTROL_MANIFEST_REF["path"],
            SEQUENCE5_PLAN_REF["path"],
            SEQUENCE5_LEDGER_REF["path"],
            SEQUENCE5_PREFLIGHT_REF["path"],
            SEQUENCE5_INTENT_REF["path"],
            SEQUENCE5_CONTROL_REF["path"],
            SEQUENCE5_PRETHEME_GATE_REF["path"],
            SEQUENCE5_CONTROL_MANIFEST_REF["path"],
            SEQUENCE5_FAILED_PRETHEME_MANIFEST_REF["path"],
            SEQUENCE4_PLAN_REF["path"],
            SEQUENCE4_LEDGER_REF["path"],
            SEQUENCE4_PREFLIGHT_REF["path"],
            SEQUENCE4_INTENT_REF["path"],
            SEQUENCE4_TERMINAL_REF["path"],
            SEQUENCE3_PLAN_REF["path"],
            SEQUENCE3_LEDGER_REF["path"],
            SEQUENCE3_PREFLIGHT_REF["path"],
            SEQUENCE3_INTENT_REF["path"],
            SEQUENCE2_PLAN_REF["path"],
            SEQUENCE2_LEDGER_REF["path"],
            SEQUENCE2_PREFLIGHT_REF["path"],
            PARENT_PLAN_REF["path"],
            PARENT_LEDGER_REF["path"],
            *UPSTREAM_AUTHORITY_SHA256,
        }
        - {record["path"] for record in mirror["records"]}
    )
    supplemental_records: list[dict[str, Any]] = []
    for relative in supplemental_paths:
        record, _ = (
            _sequence7_failed_manifest_record(source_root_fd)
            if relative
            == SEQUENCE7_FAILED_CANARY_MANIFEST_REF["path"]
            else _source_file_record(source_root_fd, relative)
        )
        supplemental_records.append(
            {
                "path": relative,
                "sha256": record["sha256"],
                "size": record["size"],
                "mode": (
                    "0555"
                    if int(record["mode"], 8) & 0o111
                    else "0444"
                ),
            }
        )
    supplemental = _source_projection_value(
        "quant-radar-ui-ux-supplemental-source/v1",
        supplemental_paths,
        _MIRROR_INCLUDE_POLICY,
        supplemental_records,
    )
    return {"sourceProjection": mirror, "supplementalProjection": supplemental}


def _resolve_sequence8_preflight_source_projections(
    source_root_fd: int,
    *,
    current_manifest: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Use live source authority for a fresh Sequence 8 operation."""

    return _build_preflight_source_projections(
        source_root_fd,
        current_manifest=current_manifest,
    )


def _validate_preflight_provisional_sources(
    source_root_fd: int,
    source_projection: Mapping[str, Any],
) -> None:
    records = source_projection.get("records")
    if not isinstance(records, list):
        raise ContractViolation("preflight source projection records are invalid")
    by_path = {
        record.get("path"): record
        for record in records
        if isinstance(record, Mapping)
        and isinstance(record.get("path"), str)
    }
    for relative in TIER0_DESTINATIONS[:2]:
        physical, _ = _source_file_record(source_root_fd, relative)
        projected = by_path.get(relative)
        projected_mode = (
            "0555"
            if int(physical["mode"], 8) & 0o111
            else "0444"
        )
        if (
            physical["uid"] != os.getuid()
            or physical["gid"] != os.getgid()
            or physical["nlink"] != 1
            or not _safe_regular_mode(physical["mode"])
            or projected
            != {
                "path": relative,
                "sha256": physical["sha256"],
                "size": physical["size"],
                "mode": projected_mode,
            }
        ):
            raise ContractViolation(
                f"preflight provisional source authority differs: {relative}"
            )


def _resolve_sequence8_preflight_provisional_sources(
    source_root_fd: int,
    source_projection: Mapping[str, Any],
) -> None:
    """Use live provisional-source validation for a fresh Sequence 8 run."""

    _validate_preflight_provisional_sources(
        source_root_fd,
        source_projection,
    )


def _validate_sequence8_historical_provisional_sources(
    source_root_fd: int,
    source_projection: Mapping[str, Any],
) -> None:
    expected = _import_sequence8_source_projections_history(
        source_root_fd
    )["sourceProjection"]
    if source_projection != expected:
        raise ContractViolation(
            "Sequence 8 historical provisional source differs"
        )


def _build_preflight_task6(
    task6_inputs: Mapping[str, Any],
    historical_projection: Mapping[str, Any],
    capture_stack: Mapping[str, Any],
) -> dict[str, Any]:
    if (
        not isinstance(task6_inputs, Mapping)
        or set(task6_inputs) != {"pages", "controls", "records"}
        or not isinstance(historical_projection, Mapping)
        or not isinstance(capture_stack, Mapping)
    ):
        raise ContractViolation("preflight Task 6 inputs are invalid")
    historical = _source_projection_value(
        "quant-radar-ui-ux-ux1b-source-mirror/v1",
        _MIRROR_INCLUDE_POLICY,
        _MIRROR_EXCLUDE_POLICY,
        historical_projection.get("files", ()),
        digest=historical_projection.get("digest"),
    )

    def bundle(kind: str, mode: str) -> dict[str, Any]:
        value = task6_inputs.get(kind)
        if not isinstance(value, Mapping) or set(value) != {
            "manifest",
            "captureCount",
            "artifactCount",
            "namespaceLeafCount",
            "captureIdsSha256",
        }:
            raise ContractViolation(f"preflight Task 6 {kind} input differs")
        capture_count = value["captureCount"]
        return {
            "manifest": dict(value["manifest"]),
            "mode": mode,
            "phase": "precontrol",
            "expectedCaptureCount": capture_count,
            "capturedCount": capture_count,
            "artifactCount": value["artifactCount"],
            "namespaceLeafCount": value["namespaceLeafCount"],
            "captureIdsSha256": value["captureIdsSha256"],
            "sourceDigest": HISTORICAL_SOURCE_SHA256,
            "captureStackDigest": capture_stack.get("digest"),
        }

    return {
        "pages": bundle("pages", "ux1b-full-pages"),
        "controls": bundle("controls", "ux1b-selection-controls"),
        "historicalSourceProjection": historical,
    }


def _selector_delta_expected_postimages(
    contract_bytes: bytes,
) -> list[dict[str, Any]]:
    try:
        contract_value = json.loads(
            contract_bytes.decode("utf-8", errors="strict")
        )
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ContractViolation(
            "selector-delta contract JSON is invalid"
        ) from exc
    file_rows = (
        contract_value.get("files")
        if isinstance(contract_value, dict)
        else None
    )
    if not isinstance(file_rows, list) or len(file_rows) != len(
        SELECTOR_MEMBERS
    ):
        raise ContractViolation("selector-delta file authority set differs")
    migrated_by_path: dict[str, dict[str, Any]] = {}
    for row in file_rows:
        if (
            not isinstance(row, dict)
            or not isinstance(row.get("path"), str)
            or row["path"] in migrated_by_path
            or not isinstance(row.get("migratedSha256"), str)
            or re.fullmatch(r"[0-9a-f]{64}", row["migratedSha256"]) is None
            or type(row.get("migratedSize")) is not int
            or row["migratedSize"] < 0
        ):
            raise ContractViolation(
                "selector-delta migrated authority is invalid"
            )
        migrated_by_path[row["path"]] = row
    if set(migrated_by_path) != {
        row["path"] for row in SELECTOR_MEMBERS
    }:
        raise ContractViolation("selector-delta migrated path set differs")
    return [
        {
            "path": row["path"],
            "sha256": migrated_by_path[row["path"]]["migratedSha256"],
            "size": migrated_by_path[row["path"]]["migratedSize"],
            "mode": "0444",
        }
        for row in sorted(SELECTOR_MEMBERS, key=lambda item: item["path"])
    ]


def _authenticate_selector_delta(
    source_root_fd: int,
    *,
    historical_postimages: Sequence[Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    contract, contract_bytes = _source_file_record(
        source_root_fd,
        SELECTOR_DELTA_CONTRACT_REF["path"],
    )
    if {
        key: contract[key]
        for key in ("path", "sha256", "size", "mode")
    } != SELECTOR_DELTA_CONTRACT_REF:
        raise ContractViolation("selector-delta contract authority differs")
    expected = _selector_delta_expected_postimages(contract_bytes)
    if historical_postimages is not None:
        if (
            not isinstance(historical_postimages, Sequence)
            or isinstance(historical_postimages, (str, bytes))
            or [dict(row) for row in historical_postimages] != expected
        ):
            raise ContractViolation(
                "stored selector postimage authority differs"
            )
        postimages = expected
    else:
        postimages = []
        for expected_row in expected:
            record, _ = _source_file_record(
                source_root_fd,
                expected_row["path"],
            )
            if (
                record["sha256"] != expected_row["sha256"]
                or record["size"] != expected_row["size"]
                or record["mode"] != "0644"
            ):
                raise ContractViolation(
                    "selector migrated postimage differs: "
                    + expected_row["path"]
                )
            postimages.append(dict(expected_row))
    return {"contract": contract, "postimages": postimages}


def _read_sequence8_preflight_history(
    source_root_fd: int,
) -> dict[str, Any]:
    """Read the immutable Sequence 8 preflight as historical evidence."""
    record, payload = _source_file_record(
        source_root_fd,
        SEQUENCE8_PREFLIGHT_REF["path"],
    )
    if {
        key: record[key]
        for key in ("path", "sha256", "size", "mode")
    } != SEQUENCE8_PREFLIGHT_REF:
        raise ContractViolation(
            "Sequence 8 preflight authority differs"
        )
    try:
        preflight = json.loads(payload.decode("utf-8", errors="strict"))
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ContractViolation(
            "Sequence 8 preflight JSON is invalid"
        ) from exc
    if (
        not isinstance(preflight, dict)
        or preflight.get("schemaVersion")
        != "quant-radar-ui-ux-formal-handoff-preflight/v2"
        or preflight.get("status") != "passed"
        or preflight.get("recoveryId") != AUTHORIZED_RECOVERY_ID
    ):
        raise ContractViolation("Sequence 8 preflight identity differs")
    return preflight


def _import_sequence8_selector_delta_history(
    source_root_fd: int,
) -> dict[str, Any]:
    """Authenticate the accepted Sequence 8 selector receipt without live members."""

    preflight = _read_sequence8_preflight_history(source_root_fd)
    selector_delta = preflight.get("selectorDelta")
    if (
        not isinstance(selector_delta, dict)
        or set(selector_delta) != {"contract", "postimages"}
        or not isinstance(selector_delta.get("contract"), dict)
        or {
            key: selector_delta["contract"].get(key)
            for key in ("path", "sha256", "size", "mode")
        }
        != SELECTOR_DELTA_CONTRACT_REF
        or not isinstance(selector_delta.get("postimages"), list)
    ):
        raise ContractViolation(
            "Sequence 8 stored selector receipt differs"
        )
    return _authenticate_selector_delta(
        source_root_fd,
        historical_postimages=selector_delta["postimages"],
    )


def _import_sequence8_runtime_history(
    source_root_fd: int,
    *,
    capture_stack: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Authenticate the stored Sequence 8 runtime receipt without live runtimes."""

    preflight = _read_sequence8_preflight_history(source_root_fd)
    if (
        capture_stack is not None
        and capture_stack != preflight.get("captureStack")
    ):
        raise ContractViolation(
            "Sequence 8 stored capture-stack authority differs"
        )
    runtime_receipt = preflight.get("runtimeReceipt")
    if (
        not isinstance(runtime_receipt, dict)
        or runtime_receipt.get("schemaVersion")
        != "quant-radar-ui-ux-runtime-receipt/v1"
        or runtime_receipt.get("tempRootParent")
        != str(SEQUENCE8_RUNTIME_ROOT)
    ):
        raise ContractViolation("Sequence 8 stored runtime receipt differs")
    _validate_schema("RuntimeReceipt", runtime_receipt)
    return runtime_receipt


def _import_sequence8_tier0_inputs_history(
    source_root_fd: int,
) -> dict[str, Any]:
    """Authenticate stored Tier 0 inputs without reopening evolved sources."""

    preflight = _read_sequence8_preflight_history(source_root_fd)
    expected = preflight.get("rollback", {}).get("prechange")
    if (
        not isinstance(expected, dict)
        or set(expected) != {"path", "sha256", "size"}
    ):
        raise ContractViolation(
            "Sequence 8 stored prechange reference differs"
        )
    record, payload = _source_file_record(
        source_root_fd,
        expected["path"],
    )
    if (
        _artifact_ref(record) != expected
        or record["mode"] != "0600"
    ):
        raise ContractViolation(
            "Sequence 8 stored prechange authority differs"
        )
    value = _strict_json_bytes(payload, allow_float=True)
    if (
        not isinstance(value, dict)
        or value.get("schemaVersion")
        != "quant-radar-ui-ux-theme-handoff-prechange/v1"
        or value.get("status") != "captured"
        or value.get("recoveryId") != AUTHORIZED_RECOVERY_ID
        or not isinstance(value.get("liveRecords"), list)
        or len(value["liveRecords"]) != 320
        or not isinstance(value.get("authorities"), list)
        or len(value["authorities"]) != 53
    ):
        raise ContractViolation(
            "Sequence 8 stored Tier 0 input set differs"
        )
    live_paths = [
        row.get("path")
        for row in value["liveRecords"]
        if isinstance(row, dict)
    ]
    authority_paths = [
        row.get("path")
        for row in value["authorities"]
        if isinstance(row, dict)
    ]
    if (
        len(live_paths) != 320
        or live_paths != sorted(live_paths)
        or len(live_paths) != len(set(live_paths))
        or len(authority_paths) != 53
        or authority_paths != sorted(authority_paths)
        or len(authority_paths) != len(set(authority_paths))
    ):
        raise ContractViolation(
            "Sequence 8 stored Tier 0 ordering differs"
        )
    return {
        "liveRecords": copy.deepcopy(value["liveRecords"]),
        "authorities": copy.deepcopy(value["authorities"]),
        "task6": copy.deepcopy(preflight["task6"]),
    }


def _import_sequence8_compatibility_history(
    source_root_fd: int,
) -> dict[str, Any]:
    stored = _import_sequence8_tier0_inputs_history(source_root_fd)
    by_path = {
        row["path"]: row for row in stored["liveRecords"]
    }
    postimages = [
        copy.deepcopy(by_path[row["path"]])
        for row in COMPATIBILITY_ROWS
    ]
    if len(postimages) != len(COMPATIBILITY_ROWS):
        raise ContractViolation(
            "Sequence 8 stored compatibility set differs"
        )
    return {
        "contract": {
            "sha256": COMPATIBILITY_CONTRACT_SHA256,
            "size": COMPATIBILITY_CONTRACT_SIZE,
        },
        "livePostimages": postimages,
        "historicalPreimages": [
            {
                "path": row["path"],
                "sha256": row["preSha256"],
                "size": row["preSize"],
                "mode": row["mode"],
            }
            for row in COMPATIBILITY_ROWS
        ],
    }


def _build_preflight_selector_delta(
    source_root_fd: int,
) -> dict[str, Any]:
    """Authenticate live selector members for a fresh operation."""

    return _authenticate_selector_delta(source_root_fd)


def _collect_tier0_existing_inputs(
    source_root_fd: int,
    *,
    package: Mapping[str, Any] | None = None,
    upstream_records: Sequence[dict[str, Any]] | None = None,
    capture_stack: Mapping[str, Any] | None = None,
    task6: Mapping[str, Any] | None = None,
    compatibility: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    package_value = (
        _reauthenticate_authorization_package(source_root_fd)
        if package is None
        else package
    )
    upstream_value = (
        _reauthenticate_upstream_authorities(source_root_fd)
        if upstream_records is None
        else list(upstream_records)
    )
    capture_value = (
        _reauthenticate_capture_stack(source_root_fd)
        if capture_stack is None
        else capture_stack
    )
    task6_value = (
        _reauthenticate_task6_inputs(source_root_fd)
        if task6 is None
        else task6
    )
    compatibility_value = (
        _reauthenticate_compatibility_boundary(source_root_fd)
        if compatibility is None
        else compatibility
    )

    authority_records = sorted(
        [
            *upstream_value,
            *package_value["authorityRecords"],
        ],
        key=lambda item: item["path"],
    )
    authority_paths = [record["path"] for record in authority_records]
    if len(authority_paths) != 53 or len(authority_paths) != len(
        set(authority_paths)
    ):
        raise ContractViolation("Tier 0 authority set differs")

    records_by_path: dict[str, dict[str, Any]] = {}

    def add(record: Mapping[str, Any]) -> None:
        normalized = dict(record)
        path = normalized.get("path")
        if not isinstance(path, str) or not _is_safe_relative_path(path):
            raise ContractViolation("Tier 0 input record path is invalid")
        existing = records_by_path.get(path)
        if existing is not None and existing != normalized:
            raise ContractViolation(
                f"Tier 0 duplicate input record differs: {path}"
            )
        records_by_path[path] = normalized

    for record in authority_records:
        add(record)
    for record in (
        capture_value["contract"],
        *capture_value["members"],
        *task6_value["records"],
        *compatibility_value["livePostimages"],
    ):
        add(record)
    fixed_paths = (
        "Makefile",
        "scripts/ui_ux_awake_gate.py",
        "scripts/test_ui_ux_awake_gate.py",
        AUTHORIZATION_DOCUMENT_PATH,
        BASE_DRAFT_PATH,
        *TIER0_DESTINATIONS[:3],
        *TIER0_JOURNAL_PATHS,
        *THEME_BATCH_PREIMAGE_SHA256,
    )
    for relative in fixed_paths:
        record, _ = _source_file_record(source_root_fd, relative)
        expected_sha256 = THEME_BATCH_PREIMAGE_SHA256.get(relative)
        if (
            expected_sha256 is not None
            and (
                record["sha256"] != expected_sha256
                or record["mode"] != "0644"
            )
        ):
            raise ContractViolation(
                f"theme-batch live preimage differs: {relative}"
            )
        add(record)
    live_records = [
        records_by_path[path] for path in sorted(records_by_path)
    ]
    if len(live_records) != 320:
        raise ContractViolation("Tier 0 live input cardinality differs")
    return {
        "liveRecords": live_records,
        "authorities": authority_records,
        "task6": task6_value,
    }


def _resolve_sequence8_tier0_inputs(
    source_root_fd: int,
    **kwargs: Any,
) -> dict[str, Any]:
    """Use live Tier 0 inputs for a fresh Sequence 8 operation."""

    return _collect_tier0_existing_inputs(
        source_root_fd,
        **kwargs,
    )


def _resolve_sequence8_compatibility_boundary(
    source_root_fd: int,
) -> dict[str, Any]:
    """Use live compatibility inputs for a fresh Sequence 8 operation."""

    return _reauthenticate_compatibility_boundary(source_root_fd)


def _validate_tier0_input_sets(
    prechange: Mapping[str, Any],
    *,
    expected: Mapping[str, Any] | None = None,
) -> None:
    live_records = prechange.get("liveRecords")
    authorities = prechange.get("authorities")
    if not isinstance(live_records, list) or not isinstance(authorities, list):
        raise ContractViolation("Tier 0 input sets must be arrays")
    live_paths = [record.get("path") for record in live_records]
    authority_paths = [record.get("path") for record in authorities]
    if (
        live_paths != sorted(live_paths)
        or len(live_paths) != len(set(live_paths))
        or authority_paths != sorted(authority_paths)
        or len(authority_paths) != len(set(authority_paths))
    ):
        raise ContractViolation("Tier 0 input set order/uniqueness differs")
    expected_authority_sha256 = {
        **UPSTREAM_AUTHORITY_SHA256,
        AUTHORIZED_PLAN_REF["path"]: AUTHORIZED_PLAN_REF["sha256"],
        AUTHORIZED_LEDGER_REF["path"]: AUTHORIZED_LEDGER_REF["sha256"],
        SEQUENCE7_PLAN_REF["path"]: SEQUENCE7_PLAN_REF["sha256"],
        SEQUENCE7_LEDGER_REF["path"]: SEQUENCE7_LEDGER_REF["sha256"],
        SEQUENCE7_FAILED_CANARY_MANIFEST_REF["path"]:
            SEQUENCE7_FAILED_CANARY_MANIFEST_REF["sha256"],
        SEQUENCE6_PLAN_REF["path"]: SEQUENCE6_PLAN_REF["sha256"],
        SEQUENCE6_LEDGER_REF["path"]: SEQUENCE6_LEDGER_REF["sha256"],
        SEQUENCE6_PREFLIGHT_REF["path"]:
            SEQUENCE6_PREFLIGHT_REF["sha256"],
        SEQUENCE6_INTENT_REF["path"]: SEQUENCE6_INTENT_REF["sha256"],
        SEQUENCE6_TERMINAL_REF["path"]:
            SEQUENCE6_TERMINAL_REF["sha256"],
        SEQUENCE6_FAILED_POSTCONTROL_MANIFEST_REF["path"]:
            SEQUENCE6_FAILED_POSTCONTROL_MANIFEST_REF["sha256"],
        SEQUENCE5_PLAN_REF["path"]: SEQUENCE5_PLAN_REF["sha256"],
        SEQUENCE5_LEDGER_REF["path"]: SEQUENCE5_LEDGER_REF["sha256"],
        SEQUENCE5_PREFLIGHT_REF["path"]:
            SEQUENCE5_PREFLIGHT_REF["sha256"],
        SEQUENCE5_INTENT_REF["path"]: SEQUENCE5_INTENT_REF["sha256"],
        SEQUENCE5_CONTROL_REF["path"]: SEQUENCE5_CONTROL_REF["sha256"],
        SEQUENCE5_PRETHEME_GATE_REF["path"]:
            SEQUENCE5_PRETHEME_GATE_REF["sha256"],
        SEQUENCE5_CONTROL_MANIFEST_REF["path"]:
            SEQUENCE5_CONTROL_MANIFEST_REF["sha256"],
        SEQUENCE5_FAILED_PRETHEME_MANIFEST_REF["path"]:
            SEQUENCE5_FAILED_PRETHEME_MANIFEST_REF["sha256"],
        SEQUENCE4_PLAN_REF["path"]: SEQUENCE4_PLAN_REF["sha256"],
        SEQUENCE4_LEDGER_REF["path"]: SEQUENCE4_LEDGER_REF["sha256"],
        SEQUENCE4_PREFLIGHT_REF["path"]:
            SEQUENCE4_PREFLIGHT_REF["sha256"],
        SEQUENCE4_INTENT_REF["path"]: SEQUENCE4_INTENT_REF["sha256"],
        SEQUENCE4_TERMINAL_REF["path"]:
            SEQUENCE4_TERMINAL_REF["sha256"],
        SEQUENCE3_PLAN_REF["path"]: SEQUENCE3_PLAN_REF["sha256"],
        SEQUENCE3_LEDGER_REF["path"]: SEQUENCE3_LEDGER_REF["sha256"],
        SEQUENCE3_PREFLIGHT_REF["path"]:
            SEQUENCE3_PREFLIGHT_REF["sha256"],
        SEQUENCE3_INTENT_REF["path"]: SEQUENCE3_INTENT_REF["sha256"],
        SEQUENCE2_PLAN_REF["path"]: SEQUENCE2_PLAN_REF["sha256"],
        SEQUENCE2_LEDGER_REF["path"]: SEQUENCE2_LEDGER_REF["sha256"],
        SEQUENCE2_PREFLIGHT_REF["path"]: SEQUENCE2_PREFLIGHT_REF["sha256"],
        PARENT_PLAN_REF["path"]: PARENT_PLAN_REF["sha256"],
        PARENT_LEDGER_REF["path"]: PARENT_LEDGER_REF["sha256"],
    }
    if (
        authority_paths != sorted(expected_authority_sha256)
        or any(
            record.get("sha256")
            != expected_authority_sha256.get(record.get("path"))
            for record in authorities
        )
    ):
        raise ContractViolation("Tier 0 authority records differ")
    live_by_path = {record["path"]: record for record in live_records}
    for authority in authorities:
        if live_by_path.get(authority["path"]) != authority:
            raise ContractViolation(
                "Tier 0 authority is absent from existing inputs"
            )
    for row in COMPATIBILITY_ROWS:
        record = live_by_path.get(row["path"])
        if (
            record is None
            or record.get("sha256") != row["postSha256"]
            or record.get("size") != row["postSize"]
            or record.get("mode") != "0644"
        ):
            raise ContractViolation(
                "Tier 0 compatibility postimage set differs"
            )
    required_paths = {
        "Makefile",
        AUTHORIZATION_DOCUMENT_PATH,
        BASE_DRAFT_PATH,
        *TIER0_DESTINATIONS[:3],
        *TIER0_JOURNAL_PATHS,
        *THEME_BATCH_PREIMAGE_SHA256,
        "docs/ui-ux/quant-radar-ui-v2-ux1b-capture-stack.json",
        *(row["path"] for row in TASK6_MANIFEST_ROWS),
    }
    if not required_paths.issubset(live_by_path):
        raise ContractViolation("Tier 0 required existing input is absent")
    if expected is not None and (
        live_records != expected.get("liveRecords")
        or authorities != expected.get("authorities")
    ):
        raise ContractViolation("Tier 0 exact existing input set differs")


def _tier0_record_from_disk(root: Path) -> dict[str, Any]:
    prechange = _read_canonical_file(root, TIER0_DESTINATIONS[4])
    bundle_manifest = _read_canonical_file(root, TIER0_DESTINATIONS[9])
    rollback = _read_canonical_file(root, TIER0_DESTINATIONS[5])
    lock_record = _file_record_at(root, TIER0_DESTINATIONS[2])
    lease_record = _file_record_at(root, TIER0_DESTINATIONS[3])
    return {
        "exitCode": EXIT_SUCCESS,
        "tierId": TIER_ID,
        "tier0DestinationSet": [{"path": path} for path in TIER0_DESTINATIONS],
        "lock": {"artifact": lock_record},
        "lease": {"artifact": lease_record},
        "prechange": prechange,
        "bundleManifest": bundle_manifest,
        "rollback": rollback,
        "bundle": bundle_manifest,
        "complete": True,
        "reopenedChain": [
            "lock", "lease", "prechange", "bundle-owner", "bundle-archive",
            "bundle-manifest", "rollback-terminal",
        ],
        "freshLockGrant": False,
        "readOnlyReconciled": False,
        "createdPaths": [],
        "repaired": False,
        "lockRemoved": False,
        "namespacePaths": list(_workspace_namespace_paths(root)),
    }


def _tier0_record_from_retained(workspace_fd: int) -> dict[str, Any]:
    prechange = _read_relative_canonical_evidence(
        workspace_fd,
        TIER0_DESTINATIONS[4],
    )
    bundle_manifest = _read_relative_canonical_evidence(
        workspace_fd,
        TIER0_DESTINATIONS[9],
    )
    rollback = _read_relative_canonical_evidence(
        workspace_fd,
        TIER0_DESTINATIONS[5],
    )
    lock_record = _relative_file_record(
        workspace_fd,
        TIER0_DESTINATIONS[2],
    )
    lease_record = _relative_file_record(
        workspace_fd,
        TIER0_DESTINATIONS[3],
    )
    return {
        "exitCode": EXIT_SUCCESS,
        "tierId": TIER_ID,
        "tier0DestinationSet": [
            {"path": path} for path in TIER0_DESTINATIONS
        ],
        "lock": {"artifact": lock_record},
        "lease": {"artifact": lease_record},
        "prechange": prechange,
        "bundleManifest": bundle_manifest,
        "rollback": rollback,
        "bundle": bundle_manifest,
        "complete": True,
        "reopenedChain": [
            "lock",
            "lease",
            "prechange",
            "bundle-owner",
            "bundle-archive",
            "bundle-manifest",
            "rollback-terminal",
        ],
        "freshLockGrant": False,
        "readOnlyReconciled": False,
        "createdPaths": [],
        "repaired": False,
        "lockRemoved": False,
        "namespacePaths": [],
    }


def _bootstrap_tier0(
    workspace_fd: int,
    recovery_id: str,
    *,
    source_root_fd: int | None = None,
    fault_after: str | None = None,
    syscalls: Any | None = None,
    fd_syscalls: Any | None = None,
) -> dict[str, Any]:
    if recovery_id != AUTHORIZED_RECOVERY_ID:
        raise ContractViolation("bootstrap recovery ID is not authorized")
    if (
        type(workspace_fd) is not int
        or workspace_fd < 0
        or not stat.S_ISDIR(os.fstat(workspace_fd).st_mode)
    ):
        raise ContractViolation("bootstrap workspace descriptor is invalid")
    soft_limit, hard_limit = resource.getrlimit(resource.RLIMIT_NOFILE)
    descriptor_budget = _plan_fd_budget(
        (),
        worst_case_unique_retained_leaves=164,
        max_path_depth=12,
        soft_limit=soft_limit,
        hard_limit=hard_limit,
        syscalls=fd_syscalls,
    )

    def failed(exit_code: int) -> dict[str, Any]:
        return {
            "exitCode": exit_code,
            "complete": False,
            "freshLockGrant": False,
            "readOnlyReconciled": False,
            "createdPaths": [],
            "repaired": False,
            "lockRemoved": False,
            "namespacePaths": list(
                _workspace_namespace_paths(WORKSPACE_ROOT)
            ),
        }

    if descriptor_budget.get("exitCode") == EXIT_UNAVAILABLE:
        return failed(EXIT_UNAVAILABLE)
    if descriptor_budget.pop("softRestored", None) is not True:
        raise ContractViolation(
            "bootstrap descriptor limit was not restored"
        )
    budget = _validate_descriptor_budget(descriptor_budget)
    try:
        with _apply_preflight_descriptor_budget(budget):
            return _bootstrap_tier0_impl(
                workspace_fd,
                recovery_id,
                source_root_fd=source_root_fd,
                fault_after=fault_after,
                syscalls=syscalls,
            )
    except NamespaceCollision:
        return failed(EXIT_COLLISION)
    except PrimitiveUnavailable:
        return failed(EXIT_UNAVAILABLE)


def _bootstrap_tier0_impl(
    workspace_fd: int,
    recovery_id: str,
    *,
    source_root_fd: int | None = None,
    fault_after: str | None = None,
    syscalls: Any | None = None,
) -> dict[str, Any]:
    if recovery_id != AUTHORIZED_RECOVERY_ID:
        raise ContractViolation("bootstrap recovery ID is not authorized")
    if type(workspace_fd) is not int or workspace_fd < 0:
        raise ContractViolation("bootstrap workspace descriptor is invalid")
    workspace_stat = os.fstat(workspace_fd)
    named_workspace = os.lstat(WORKSPACE_ROOT)
    if not stat.S_ISDIR(workspace_stat.st_mode) or (workspace_stat.st_dev, workspace_stat.st_ino) != (
        named_workspace.st_dev,
        named_workspace.st_ino,
    ):
        raise ContractViolation("bootstrap workspace descriptor/path mismatch")
    if source_root_fd is None:
        source_root_fd = workspace_fd
    if type(source_root_fd) is not int or source_root_fd < 0 or not stat.S_ISDIR(os.fstat(source_root_fd).st_mode):
        raise ContractViolation("bootstrap source-root descriptor is invalid")
    if fault_after is not None and fault_after not in BOOTSTRAP_ORDERED_BOUNDARIES:
        raise ContractViolation("unknown bootstrap fault boundary")

    root = WORKSPACE_ROOT
    if _relative_leaf_lstat(
        workspace_fd,
        TIER0_DESTINATIONS[5],
    ) is not None:
        before = _workspace_namespace_paths(root)
        record = _tier0_record_from_retained(workspace_fd)
        _validate_tier0_complete(
            workspace_fd,
            record,
            source_root_fd=source_root_fd,
        )
        record.update(
            {
                "readOnlyReconciled": True,
                "createdPaths": [],
                "freshLockGrant": False,
                "repaired": False,
                "namespacePaths": list(before),
            }
        )
        return record
    if _relative_leaf_lstat(
        workspace_fd,
        TIER0_DESTINATIONS[2],
    ) is None:
        raise ContractViolation(
            "Sequence 5 requires the imported global lock"
        )

    created_paths: list[str] = []
    open_fds: list[int] = []

    def record_boundary(name: str) -> None:
        if syscalls is not None:
            syscalls.record(name)

    def fsync_parent(relative: str) -> None:
        _fsync_relative_parent(workspace_fd, relative)

    try:
        package = _reauthenticate_authorization_package(source_root_fd)
        record_boundary("revalidate-authorization-package")
        upstream_records = _reauthenticate_upstream_authorities(
            source_root_fd
        )
        capture_stack = _reauthenticate_capture_stack(source_root_fd)
        current_projection = _build_authenticated_current_source_projection(
            source_root_fd
        )
        historical_projection = (
            _resolve_sequence8_historical_source_projection(
            current_projection["files"],
            source_root_fd,
            )
        )
        if historical_projection["digest"] != HISTORICAL_SOURCE_SHA256:
            raise ContractViolation(
                "bootstrap historical source projection differs"
            )
        task6 = _reauthenticate_task6_inputs(source_root_fd)
        compatibility = _resolve_sequence8_compatibility_boundary(
            source_root_fd
        )
        tier0_inputs = _resolve_sequence8_tier0_inputs(
            source_root_fd,
            package=package,
            upstream_records=upstream_records,
            capture_stack=capture_stack,
            task6=task6,
            compatibility=compatibility,
        )
        record_boundary("revalidate-live-preimages")
        for destination in TIER0_DESTINATIONS[3:]:
            if _relative_leaf_lstat(
                workspace_fd,
                destination.rstrip("/"),
            ) is not None:
                raise NamespaceCollision(
                    f"Tier 0 destination collision: {destination}"
                )
        record_boundary("revalidate-future-absence")

        script_records: dict[str, dict[str, Any]] = {}
        script_bytes: dict[str, bytes] = {}
        for relative in TIER0_DESTINATIONS[:2]:
            source_record, data = _source_file_record(source_root_fd, relative)
            script_bytes[relative] = data
            if _relative_leaf_lstat(workspace_fd, relative) is None:
                raise ContractViolation(
                    "Sequence 5 verifier input is absent"
                )
            script_records[relative] = _relative_file_record(
                workspace_fd,
                relative,
            )
            if (script_records[relative]["sha256"], script_records[relative]["size"]) != (
                source_record["sha256"], source_record["size"],
            ):
                raise ContractViolation("bootstrap verifier copy does not match its source")
        lock_fd = _open_relative_leaf_fd(
            workspace_fd,
            TIER0_DESTINATIONS[2],
            os.O_RDWR
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0),
        )
        open_fds.append(lock_fd)
        record_boundary("lock-create")
        imported_lock = os.fstat(lock_fd)
        if (
            not stat.S_ISREG(imported_lock.st_mode)
            or stat.S_IMODE(imported_lock.st_mode) != 0o600
            or imported_lock.st_uid != os.getuid()
            or imported_lock.st_gid != os.getgid()
            or imported_lock.st_nlink != 1
            or imported_lock.st_size != 0
        ):
            raise ContractViolation(
                "Sequence 5 imported global lock metadata differs"
            )
        try:
            fcntl.flock(
                lock_fd,
                fcntl.LOCK_EX | fcntl.LOCK_NB,
            )
        except BlockingIOError:
            return {
                "exitCode": EXIT_BUSY,
                "complete": False,
                "freshLockGrant": False,
                "readOnlyReconciled": False,
                "createdPaths": [],
                "repaired": False,
                "lockRemoved": False,
                "namespacePaths": list(
                    _workspace_namespace_paths(root)
                ),
            }
        record_boundary("lock-acquire")
        os.fsync(lock_fd)
        record_boundary("lock-fsync")
        lock_reopen = _open_relative_leaf_fd(
            workspace_fd,
            TIER0_DESTINATIONS[2],
            os.O_RDWR
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0),
        )
        open_fds.append(lock_reopen)
        if os.fstat(lock_reopen).st_ino != os.fstat(lock_fd).st_ino:
            raise ContractViolation("bootstrap lock reopen identity mismatch")
        record_boundary("lock-reopen")

        lease_fd = _create_relative_file(
            workspace_fd,
            TIER0_DESTINATIONS[3],
            b"",
            0o600,
        )
        open_fds.append(lease_fd)
        created_paths.append(TIER0_DESTINATIONS[3])
        record_boundary("lease-create")
        try:
            fcntl.flock(
                lease_fd,
                fcntl.LOCK_EX | fcntl.LOCK_NB,
            )
        except BlockingIOError:
            return {
                "exitCode": EXIT_BUSY,
                "complete": False,
                "freshLockGrant": False,
                "readOnlyReconciled": False,
                "createdPaths": [],
                "repaired": False,
                "lockRemoved": False,
                "namespacePaths": list(
                    _workspace_namespace_paths(root)
                ),
            }
        record_boundary("lease-acquire")
        os.fsync(lease_fd)
        fsync_parent(TIER0_DESTINATIONS[3])
        record_boundary("lease-fsync")
        lease_reopen = _open_relative_leaf_fd(
            workspace_fd,
            TIER0_DESTINATIONS[3],
            os.O_RDWR
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0),
        )
        open_fds.append(lease_reopen)
        if os.fstat(lease_reopen).st_ino != os.fstat(lease_fd).st_ino:
            raise ContractViolation("bootstrap lease reopen identity mismatch")
        record_boundary("lease-reopen")

        lock_record = _relative_file_record(
            workspace_fd,
            TIER0_DESTINATIONS[2],
        )
        lease_record = _relative_file_record(
            workspace_fd,
            TIER0_DESTINATIONS[3],
        )
        created_controls = [
            {
                "path": TIER0_DESTINATIONS[2],
                "preconditionAbsent": False,
                "artifact": lock_record,
                "disposition": "imported_operational",
            },
            {
                "path": TIER0_DESTINATIONS[3],
                "preconditionAbsent": True,
                "artifact": lease_record,
                "disposition": "retain_operational",
            },
        ]
        base_path = "docs/superpowers/plans/2026-07-19-quant-radar-ui-ux-ux1b-formal-theme-handoff-remediation.md"
        base_record, _ = _source_file_record(source_root_fd, base_path)
        prior_paths = (
            "docs/ui-ux/quant-radar-ui-v2-ux1b-recovery-prechange.json",
            "docs/ui-ux/quant-radar-ui-v2-ux1b-recovery-rollback.json",
        )
        prior_refs = []
        for relative in prior_paths:
            prior_record, _ = _source_file_record(source_root_fd, relative)
            prior_refs.append(_artifact_ref(prior_record))
        prechange = {
            "schemaVersion": "quant-radar-ui-ux-theme-handoff-prechange/v1",
            "status": "captured",
            "tierId": TIER_ID,
            "recoveryId": AUTHORIZED_RECOVERY_ID,
            "authorizationRecord": _authorization_binding(),
            "baseDraft": _artifact_ref(base_record),
            "replacementPlan": dict(AUTHORIZED_PLAN_REF),
            "traceability": dict(AUTHORIZED_LEDGER_REF),
            "createdControls": created_controls,
            "eligibleDestinations": [
                {"path": path.rstrip("/"), "exists": False}
                for path in TIER0_DESTINATIONS[4:]
            ],
            "liveRecords": tier0_inputs["liveRecords"],
            "anchors": [],
            "authorities": tier0_inputs["authorities"],
            "priorRollbackSources": sorted(prior_refs, key=lambda item: item["path"]),
            "bundlePath": TIER0_DESTINATIONS[6].rstrip("/"),
            "selfHash": "omitted-by-contract",
        }
        prechange_bytes = _canonical_json_bytes(prechange)
        prechange_temp = "docs/ui-ux/.tmp.theme-handoff-prechange." + secrets.token_hex(16)
        prechange_fd = _create_relative_file(
            workspace_fd,
            prechange_temp,
            b"",
            0o600,
        )
        open_fds.append(prechange_fd)
        created_paths.append(prechange_temp)
        record_boundary("prechange-temp-create")
        os.write(prechange_fd, prechange_bytes)
        record_boundary("prechange-write")
        os.fsync(prechange_fd)
        record_boundary("prechange-fsync")
        if hashlib.sha256(_read_fd_bytes(prechange_fd)).hexdigest() != hashlib.sha256(prechange_bytes).hexdigest():
            raise ContractViolation("prechange rehash mismatch")
        record_boundary("prechange-rehash")
        if (
            _relative_file_record(
                workspace_fd,
                TIER0_DESTINATIONS[2],
            )
            != lock_record
            or _relative_file_record(
                workspace_fd,
                TIER0_DESTINATIONS[3],
            )
            != lease_record
        ):
            raise ContractViolation("bootstrap controls drifted before prechange commit")
        record_boundary("prechange-input-reauthenticate")
        _rename_relative_exclusive(
            workspace_fd,
            prechange_temp,
            TIER0_DESTINATIONS[4],
        )
        created_paths.append(TIER0_DESTINATIONS[4])
        record_boundary("prechange-rename-excl")
        fsync_parent(TIER0_DESTINATIONS[4])
        record_boundary("prechange-parent-fsync")
        if (
            _read_relative_canonical_evidence(
                workspace_fd,
                TIER0_DESTINATIONS[4],
            )
            != prechange
        ):
            raise ContractViolation("prechange reopen mismatch")
        record_boundary("prechange-reopen")

        bundle_final = TIER0_DESTINATIONS[6].rstrip("/")
        bundle_staging = ".claude/ui_snapshots/ux1b/recovery/.tmp.theme-handoff-prechange." + secrets.token_hex(16)
        bundle_parent_fd, bundle_staging_name = (
            _ensure_relative_parent_fd(
                workspace_fd,
                bundle_staging,
            )
        )
        try:
            try:
                os.mkdir(
                    bundle_staging_name,
                    0o700,
                    dir_fd=bundle_parent_fd,
                )
            except FileExistsError as exc:
                raise NamespaceCollision(
                    "bootstrap bundle staging collision"
                ) from exc
            bundle_named = os.stat(
                bundle_staging_name,
                dir_fd=bundle_parent_fd,
                follow_symlinks=False,
            )
            if (
                not stat.S_ISDIR(bundle_named.st_mode)
                or stat.S_IMODE(bundle_named.st_mode) != 0o700
                or bundle_named.st_uid != os.getuid()
                or bundle_named.st_gid != os.getgid()
            ):
                raise ContractViolation(
                    "bootstrap bundle staging metadata differs"
                )
            _require_relative_parent_current(
                workspace_fd,
                bundle_staging,
                bundle_parent_fd,
            )
        finally:
            os.close(bundle_parent_fd)
        created_paths.append(bundle_staging + "/")
        record_boundary("bundle-staging-create")
        owner_physical = bundle_staging + "/.quant-radar-theme-handoff-owner"
        owner_fd = _create_relative_file(
            workspace_fd,
            owner_physical,
            _canonical_json_bytes(
                {
                    "schemaVersion": "quant-radar-ui-ux-theme-handoff-owner/v1",
                    "tierId": TIER_ID,
                }
            ),
            0o600,
        )
        open_fds.append(owner_fd)
        record_boundary("bundle-owner-write")
        os.fsync(owner_fd)
        record_boundary("bundle-owner-fsync")
        archive_buffer = io.BytesIO()
        with tarfile.open(fileobj=archive_buffer, mode="w", format=tarfile.USTAR_FORMAT) as archive:
            for relative in sorted(script_bytes):
                data = script_bytes[relative]
                info = tarfile.TarInfo(relative)
                info.size = len(data)
                info.mode = 0o644
                info.uid = os.getuid()
                info.gid = os.getgid()
                info.mtime = 0
                archive.addfile(info, io.BytesIO(data))
        archive_physical = bundle_staging + "/prechange-files.tar"
        archive_fd = _create_relative_file(
            workspace_fd,
            archive_physical,
            archive_buffer.getvalue(),
            0o600,
        )
        open_fds.append(archive_fd)
        record_boundary("bundle-archive-write")
        os.fsync(archive_fd)
        record_boundary("bundle-archive-fsync")
        owner_record = _relative_file_record(
            workspace_fd,
            owner_physical,
        )
        owner_record["path"] = TIER0_DESTINATIONS[7]
        archive_record = _relative_file_record(
            workspace_fd,
            archive_physical,
        )
        archive_record["path"] = TIER0_DESTINATIONS[8]
        bundle_manifest = {
            "schemaVersion": "quant-radar-ui-ux-theme-handoff-prechange-bundle/v1",
            "status": "sealed",
            "tierId": TIER_ID,
            "ownerMarker": owner_record,
            "archive": archive_record,
            "archivedPaths": sorted(script_bytes),
            "namespaceLeafCount": 3,
            "selfHash": "omitted-by-contract",
        }
        manifest_physical = bundle_staging + "/bundle-manifest.json"
        manifest_fd = _create_relative_file(
            workspace_fd,
            manifest_physical,
            _canonical_json_bytes(bundle_manifest),
            0o600,
        )
        open_fds.append(manifest_fd)
        record_boundary("bundle-manifest-write")
        os.fsync(manifest_fd)
        record_boundary("bundle-manifest-fsync")
        staging_fd = _open_relative_directory_fd(
            workspace_fd,
            bundle_staging,
        )
        try:
            os.fsync(staging_fd)
        finally:
            os.close(staging_fd)
        record_boundary("bundle-staging-fsync")
        _rename_relative_exclusive(
            workspace_fd,
            bundle_staging,
            bundle_final,
        )
        created_paths.append(bundle_final + "/")
        record_boundary("bundle-rename-excl")
        fsync_parent(bundle_final)
        record_boundary("bundle-parent-fsync")
        if (
            _read_relative_canonical_evidence(
                workspace_fd,
                TIER0_DESTINATIONS[9],
            )
            != bundle_manifest
        ):
            raise ContractViolation("bundle tree reopen mismatch")
        record_boundary("bundle-tree-reopen")

        prechange_ref = _artifact_ref(
            _relative_file_record(
                workspace_fd,
                TIER0_DESTINATIONS[4],
            )
        )
        bundle_manifest_ref = _artifact_ref(
            _relative_file_record(
                workspace_fd,
                TIER0_DESTINATIONS[9],
            )
        )
        rollback_entries = []
        for control in created_controls:
            artifact = control["artifact"]
            content = {
                "path": artifact["path"],
                "sha256": artifact["sha256"],
                "size": artifact["size"],
                "mode": artifact["mode"],
            }
            rollback_entries.append(
                {
                    "path": control["path"],
                    "preimage": (
                        content
                        if control["disposition"] == "imported_operational"
                        else None
                    ),
                    "postimage": content,
                    "anchor": None,
                    "disposition": control["disposition"],
                }
            )
        rollback = {
            "schemaVersion": "quant-radar-ui-ux-theme-handoff-rollback/v1",
            "status": "ready",
            "tierId": TIER_ID,
            "prechange": prechange_ref,
            "bundleManifest": bundle_manifest_ref,
            "entries": rollback_entries,
            "destructiveGitAllowed": False,
            "selfHash": "omitted-by-contract",
        }
        rollback_temp = "docs/ui-ux/.tmp.theme-handoff-rollback." + secrets.token_hex(16)
        rollback_fd = _create_relative_file(
            workspace_fd,
            rollback_temp,
            b"",
            0o600,
        )
        open_fds.append(rollback_fd)
        created_paths.append(rollback_temp)
        record_boundary("rollback-temp-create")
        os.write(rollback_fd, _canonical_json_bytes(rollback))
        record_boundary("rollback-write")
        os.fsync(rollback_fd)
        record_boundary("rollback-fsync")
        if _strict_json_bytes(_read_fd_bytes(rollback_fd)) != rollback:
            raise ContractViolation("rollback rehash mismatch")
        record_boundary("rollback-rehash")
        if (
            _artifact_ref(
                _relative_file_record(
                    workspace_fd,
                    TIER0_DESTINATIONS[4],
                )
            )
            != prechange_ref
            or _artifact_ref(
                _relative_file_record(
                    workspace_fd,
                    TIER0_DESTINATIONS[9],
                )
            )
            != bundle_manifest_ref
        ):
            raise ContractViolation("rollback inputs drifted before commit")
        record_boundary("rollback-input-reauthenticate")
        _rename_relative_exclusive(
            workspace_fd,
            rollback_temp,
            TIER0_DESTINATIONS[5],
        )
        created_paths.append(TIER0_DESTINATIONS[5])
        record_boundary("rollback-rename-excl")
        fsync_parent(TIER0_DESTINATIONS[5])
        record_boundary("rollback-parent-fsync")
        if (
            _read_relative_canonical_evidence(
                workspace_fd,
                TIER0_DESTINATIONS[5],
            )
            != rollback
        ):
            raise ContractViolation("rollback reopen mismatch")
        record_boundary("rollback-reopen")
        record = _tier0_record_from_retained(workspace_fd)
        _validate_tier0_complete(
            workspace_fd,
            record,
            source_root_fd=source_root_fd,
        )
        record_boundary("terminal-chain-reopen")
        record.update(
            {
                "freshLockGrant": True,
                "readOnlyReconciled": False,
                "createdPaths": created_paths,
                "repaired": False,
                "namespacePaths": list(_workspace_namespace_paths(root)),
            }
        )
        return record
    except OSError:
        try:
            fresh_lock_grant = (
                _relative_leaf_lstat(
                    workspace_fd,
                    TIER0_DESTINATIONS[2],
                )
                is not None
            )
        except ContractViolation:
            fresh_lock_grant = False
        return {
            "exitCode": EXIT_UNCERTAIN,
            "complete": False,
            "freshLockGrant": fresh_lock_grant,
            "readOnlyReconciled": False,
            "createdPaths": created_paths,
            "repaired": False,
            "lockRemoved": False,
            "namespacePaths": list(_workspace_namespace_paths(root)),
        }
    finally:
        for fd in reversed(open_fds):
            try:
                os.close(fd)
            except OSError:
                pass


def _bootstrap_lock_probe(
    workspace_fd: int,
    start_fd: int,
    *,
    fault_after: str | None = None,
) -> dict[str, Any]:
    if any(type(fd) is not int or fd < 0 for fd in (workspace_fd, start_fd)):
        raise ContractViolation("bootstrap lock-probe descriptors are invalid")
    if workspace_fd == start_fd:
        raise ContractViolation("bootstrap lock-probe descriptors must be distinct")
    if fault_after is not None:
        raise ContractViolation("lock probe does not expose lifecycle fault injection")
    if os.read(start_fd, 1) != b"x":
        raise ContractViolation("bootstrap lock-probe start barrier failed")
    workspace_stat = os.fstat(workspace_fd)
    named = os.lstat(WORKSPACE_ROOT)
    if not stat.S_ISDIR(workspace_stat.st_mode) or (workspace_stat.st_dev, workspace_stat.st_ino) != (
        named.st_dev,
        named.st_ino,
    ):
        raise ContractViolation("bootstrap lock-probe workspace binding mismatch")
    lock_relative = TIER0_DESTINATIONS[2]
    lock_path = WORKSPACE_ROOT / lock_relative
    flags = os.O_CREAT | os.O_EXCL | os.O_RDWR | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
    fresh = False
    fd: int | None = None
    parent_fd, lock_name = _ensure_relative_parent_fd(
        workspace_fd,
        lock_relative,
    )
    try:
        try:
            fd = os.open(
                lock_name,
                flags,
                0o600,
                dir_fd=parent_fd,
            )
            fresh = True
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
            os.fsync(fd)
            os.fsync(parent_fd)
        except FileExistsError:
            fd = os.open(
                lock_name,
                os.O_RDWR
                | os.O_NOFOLLOW
                | getattr(os, "O_CLOEXEC", 0),
                dir_fd=parent_fd,
            )
        observed = os.fstat(fd)
        named_lock = os.stat(
            lock_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISREG(observed.st_mode)
            or stat.S_IMODE(observed.st_mode) != 0o600
            or observed.st_uid != os.getuid()
            or observed.st_gid != os.getgid()
            or observed.st_nlink != 1
            or (
                observed.st_dev,
                observed.st_ino,
            )
            != (
                named_lock.st_dev,
                named_lock.st_ino,
            )
        ):
            raise ContractViolation("bootstrap lock-probe observed unsafe lock metadata")
        _require_relative_parent_current(
            workspace_fd,
            lock_relative,
            parent_fd,
        )
        return {
            "freshLockGrant": fresh,
            "lockRemoved": False,
            "lockPath": str(lock_path),
            "lockIdentity": [observed.st_dev, observed.st_ino],
        }
    finally:
        if fd is not None:
            os.close(fd)
        os.close(parent_fd)


def _validate_tier0_complete(
    workspace_fd: int,
    record: dict[str, Any],
    *,
    source_root_fd: int | None = None,
) -> dict[str, Any]:
    if type(workspace_fd) is not int or workspace_fd < 0 or not isinstance(record, dict):
        raise ContractViolation("Tier 0 validation inputs are invalid")
    expected_chain = [
        "lock", "lease", "prechange", "bundle-owner", "bundle-archive",
        "bundle-manifest", "rollback-terminal",
    ]
    if record.get("complete") is not True or record.get("reopenedChain") != expected_chain:
        raise ContractViolation("Tier 0 terminal reopen chain is incomplete")
    root = WORKSPACE_ROOT
    named = os.lstat(root)
    observed_workspace = os.fstat(workspace_fd)
    if (named.st_dev, named.st_ino) != (observed_workspace.st_dev, observed_workspace.st_ino):
        raise ContractViolation("Tier 0 validator workspace binding mismatch")
    current_lock = _relative_file_record(
        workspace_fd,
        TIER0_DESTINATIONS[2],
    )
    current_lease = _relative_file_record(
        workspace_fd,
        TIER0_DESTINATIONS[3],
    )
    for label, control in (
        ("lock", current_lock),
        ("lease", current_lease),
    ):
        if (
            control["mode"] != "0600"
            or control["uid"] != os.getuid()
            or control["gid"] != os.getgid()
            or control["nlink"] != 1
            or control["size"] != 0
        ):
            raise ContractViolation(
                f"Tier 0 {label} metadata differs"
            )
    if record.get("lock", {}).get("artifact") != current_lock or record.get("lease", {}).get("artifact") != current_lease:
        raise ContractViolation("Tier 0 control record mismatch")
    prechange = _read_relative_canonical_evidence(
        workspace_fd,
        TIER0_DESTINATIONS[4],
    )
    created_controls = {
        item.get("path"): item.get("artifact")
        for item in prechange.get("createdControls", ())
        if isinstance(item, dict)
    }
    if (
        created_controls.get(TIER0_DESTINATIONS[2]) != current_lock
        or created_controls.get(TIER0_DESTINATIONS[3]) != current_lease
    ):
        raise ContractViolation("Tier 0 operational control identity drifted")
    bundle_manifest = _read_relative_canonical_evidence(
        workspace_fd,
        TIER0_DESTINATIONS[9],
    )
    rollback = _read_relative_canonical_evidence(
        workspace_fd,
        TIER0_DESTINATIONS[5],
    )
    if record.get("prechange") != prechange or record.get("bundleManifest") != bundle_manifest or record.get("rollback") != rollback:
        raise ContractViolation("Tier 0 evidence bytes do not match the supplied record")
    if _artifact_ref(
        _relative_file_record(workspace_fd, TIER0_DESTINATIONS[4])
    ) != rollback.get("prechange"):
        raise ContractViolation("Tier 0 rollback prechange reference mismatch")
    if _artifact_ref(
        _relative_file_record(workspace_fd, TIER0_DESTINATIONS[9])
    ) != rollback.get("bundleManifest"):
        raise ContractViolation("Tier 0 rollback bundle reference mismatch")
    for relative, field in (
        (TIER0_DESTINATIONS[7], "ownerMarker"),
        (TIER0_DESTINATIONS[8], "archive"),
    ):
        if _relative_file_record(workspace_fd, relative) != bundle_manifest.get(field):
            raise ContractViolation(f"Tier 0 bundle {field} mismatch")
    for schema_name, value in (
        (prechange["schemaVersion"], prechange),
        (bundle_manifest["schemaVersion"], bundle_manifest),
        (rollback["schemaVersion"], rollback),
    ):
        _validate_schema(schema_name, value)
    owned_source_fd = False
    if source_root_fd is None:
        source_root_fd = os.open(
            SOURCE_WORKSPACE_ROOT,
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_CLOEXEC", 0),
        )
        owned_source_fd = True
    try:
        expected_inputs = _resolve_sequence8_tier0_inputs(
            source_root_fd
        )
        _validate_tier0_input_sets(
            prechange,
            expected=expected_inputs,
        )
    finally:
        if owned_source_fd:
            os.close(source_root_fd)
    return record


def _preflight_eligible_destinations(
    workspace_fd: int,
    *,
    destination_policy: Literal[
        "fresh",
        "task9-active",
    ] = "fresh",
) -> list[dict[str, Any]]:
    if destination_policy not in {"fresh", "task9-active"}:
        raise ContractViolation(
            "preflight destination policy is invalid"
        )
    active_paths = {
        *(relative for relative, _ in TASK9_LIFECYCLE),
        TIER0_DESTINATIONS[16].rstrip("/"),
        TIER0_DESTINATIONS[17].rstrip("/"),
    }
    values: list[dict[str, Any]] = []
    for relative in TIER0_DESTINATIONS[11:]:
        normalized = relative.rstrip("/")
        exists = (
            _relative_leaf_lstat(
                workspace_fd,
                normalized,
            )
            is not None
        )
        if exists and (
            destination_policy == "fresh"
            or normalized not in active_paths
        ):
            raise ContractViolation(
                f"preflight future destination collision: {normalized}"
            )
        values.append({"path": normalized, "exists": False})
    return values


def _validate_descriptor_budget(value: Any) -> dict[str, Any]:
    keys = {
        "baselineOpenCount",
        "baselineMaxFd",
        "hardLimit",
        "protocolAdditional",
        "peakOpenCount",
        "requiredSoft",
        "softApplied",
        "reserve",
    }
    if (
        not isinstance(value, dict)
        or set(value) != keys
        or any(type(value[key]) is not int for key in keys)
        or value["baselineOpenCount"] < 0
        or value["baselineMaxFd"] < -1
        or value["hardLimit"] < 0
        or value["reserve"] != 64
    ):
        raise ContractViolation("preflight descriptor budget is invalid")
    expected_additional = 164 + 2 * 12 + 64
    expected_peak = value["baselineOpenCount"] + expected_additional
    expected_required = max(
        value["baselineMaxFd"] + 1,
        expected_peak,
    )
    if (
        value["protocolAdditional"] != expected_additional
        or value["peakOpenCount"] != expected_peak
        or value["requiredSoft"] != expected_required
        or value["requiredSoft"] > value["hardLimit"]
        or value["requiredSoft"] > 1_536
        or value["peakOpenCount"] > 1_536
        or value["softApplied"] < value["requiredSoft"]
        or value["softApplied"] > value["hardLimit"]
    ):
        raise ContractViolation("preflight descriptor budget differs")
    return value


def _validate_stored_descriptor_budget(value: Any) -> dict[str, Any]:
    """Validate frozen Sequence 9 telemetry without ambient replanning."""

    budget = _validate_descriptor_budget(copy.deepcopy(value))
    _, current_hard = resource.getrlimit(resource.RLIMIT_NOFILE)
    if budget["hardLimit"] != current_hard:
        raise ContractViolation(
            "stored descriptor budget hard limit drifted"
        )
    return budget


def _validate_descriptor_profile(value: Any) -> dict[str, Any]:
    keys = {
        "hardLimit",
        "maxPathDepth",
        "protocolAdditional",
        "raiseCeiling",
        "reserve",
        "schemaVersion",
        "worstCaseUniqueRetainedLeaves",
    }
    if (
        not isinstance(value, dict)
        or set(value) != keys
        or value.get("schemaVersion")
        != "quant-radar-ui-ux-descriptor-profile/v1"
        or any(
            type(value[key]) is not int
            for key in keys - {"schemaVersion"}
        )
        or value["hardLimit"] < 0
        or value["maxPathDepth"] != 12
        or value["worstCaseUniqueRetainedLeaves"] != 164
        or value["reserve"] != 64
        or value["raiseCeiling"] != 1_536
        or value["protocolAdditional"]
        != (
            value["worstCaseUniqueRetainedLeaves"]
            + 2 * value["maxPathDepth"]
            + value["reserve"]
        )
    ):
        raise ContractViolation("descriptor profile is invalid")
    return value


def _build_descriptor_profile() -> dict[str, Any]:
    _, hard_limit = resource.getrlimit(resource.RLIMIT_NOFILE)
    return _validate_descriptor_profile(
        {
            "hardLimit": hard_limit,
            "maxPathDepth": 12,
            "protocolAdditional": 164 + 2 * 12 + 64,
            "raiseCeiling": 1_536,
            "reserve": 64,
            "schemaVersion": (
                "quant-radar-ui-ux-descriptor-profile/v1"
            ),
            "worstCaseUniqueRetainedLeaves": 164,
        }
    )


@contextlib.contextmanager
def _runtime_descriptor_budget(
    descriptor_profile: Mapping[str, Any],
) -> Any:
    """Apply fresh process capacity without serializing ambient telemetry."""

    profile = _validate_descriptor_profile(
        copy.deepcopy(dict(descriptor_profile))
    )
    original_soft, original_hard = resource.getrlimit(
        resource.RLIMIT_NOFILE
    )
    if profile["hardLimit"] != original_hard:
        raise ContractViolation("descriptor profile hard limit drifted")
    planned = _plan_fd_budget(
        (),
        worst_case_unique_retained_leaves=profile[
            "worstCaseUniqueRetainedLeaves"
        ],
        max_path_depth=profile["maxPathDepth"],
        soft_limit=original_soft,
        hard_limit=original_hard,
    )
    if planned.get("exitCode") == EXIT_UNAVAILABLE:
        raise PrimitiveUnavailable(
            "runtime descriptor capacity is unavailable"
        )
    if planned.pop("softRestored", None) is not True:
        raise ContractViolation(
            "runtime descriptor planning did not restore limits"
        )
    budget = _validate_descriptor_budget(planned)
    if resource.getrlimit(resource.RLIMIT_NOFILE) != (
        original_soft,
        original_hard,
    ):
        raise ContractViolation(
            "runtime descriptor planning changed caller limits"
        )
    with _apply_preflight_descriptor_budget(budget):
        yield copy.deepcopy(budget)
    if resource.getrlimit(resource.RLIMIT_NOFILE) != (
        original_soft,
        original_hard,
    ):
        raise ContractViolation(
            "runtime descriptor limits were not restored"
        )


def _plan_preflight_descriptor_budget() -> dict[str, Any]:
    soft_limit, hard_limit = resource.getrlimit(resource.RLIMIT_NOFILE)
    result = _plan_fd_budget(
        (),
        worst_case_unique_retained_leaves=164,
        max_path_depth=12,
        soft_limit=soft_limit,
        hard_limit=hard_limit,
    )
    if result.get("exitCode") == EXIT_UNAVAILABLE:
        return {"exitCode": EXIT_UNAVAILABLE}
    if result.pop("softRestored", None) is not True:
        raise ContractViolation("preflight descriptor limit was not restored")
    return _validate_descriptor_budget(result)


@contextlib.contextmanager
def _apply_preflight_descriptor_budget(
    value: Mapping[str, Any],
) -> Any:
    budget = _validate_descriptor_budget(dict(value))
    original_soft, original_hard = resource.getrlimit(resource.RLIMIT_NOFILE)
    if budget["hardLimit"] != original_hard:
        raise ContractViolation("preflight descriptor hard limit drifted")
    target_soft = max(original_soft, budget["requiredSoft"])
    raised = target_soft != original_soft
    if target_soft > original_hard or (raised and target_soft > 1_536):
        raise ContractViolation("preflight descriptor soft limit is unavailable")
    if raised:
        try:
            resource.setrlimit(
                resource.RLIMIT_NOFILE,
                (target_soft, original_hard),
            )
        except OSError as exc:
            raise ContractViolation(
                "preflight descriptor soft limit could not be applied"
            ) from exc
        if resource.getrlimit(resource.RLIMIT_NOFILE) != (
            target_soft,
            original_hard,
        ):
            resource.setrlimit(
                resource.RLIMIT_NOFILE,
                (original_soft, original_hard),
            )
            raise ContractViolation(
                "preflight descriptor soft limit did not take effect"
            )
    try:
        yield budget
    finally:
        if raised:
            try:
                resource.setrlimit(
                    resource.RLIMIT_NOFILE,
                    (original_soft, original_hard),
                )
            except OSError as exc:
                raise ContractViolation(
                    "preflight descriptor soft limit was not restored"
                ) from exc
            if resource.getrlimit(resource.RLIMIT_NOFILE) != (
                original_soft,
                original_hard,
            ):
                raise ContractViolation(
                    "preflight descriptor soft limit restore differs"
                )


def _build_preflight_value(
    workspace_fd: int,
    source_root_fd: int,
    descriptor_budget: Mapping[str, Any],
    *,
    destination_policy: Literal[
        "fresh",
        "task9-active",
    ] = "fresh",
) -> dict[str, Any]:
    if (
        type(workspace_fd) is not int
        or workspace_fd < 0
        or type(source_root_fd) is not int
        or source_root_fd < 0
    ):
        raise ContractViolation("preflight descriptors are invalid")
    tier0 = _tier0_record_from_retained(workspace_fd)
    _validate_tier0_complete(
        workspace_fd,
        tier0,
        source_root_fd=source_root_fd,
    )
    eligible = _preflight_eligible_destinations(
        workspace_fd,
        destination_policy=destination_policy,
    )
    package = _reauthenticate_authorization_package(source_root_fd)
    upstream = _reauthenticate_upstream_authorities(source_root_fd)
    capture_stack = _reauthenticate_capture_stack(source_root_fd)
    current_manifest = _build_authenticated_current_source_projection(
        source_root_fd
    )
    historical_manifest = _resolve_sequence8_historical_source_projection(
        current_manifest["files"],
        source_root_fd,
    )
    task6_inputs = _reauthenticate_task6_inputs(source_root_fd)
    projections = _resolve_sequence8_preflight_source_projections(
        source_root_fd,
        current_manifest=current_manifest,
    )
    _resolve_sequence8_preflight_provisional_sources(
        source_root_fd,
        projections["sourceProjection"],
    )
    task6 = _build_preflight_task6(
        task6_inputs,
        historical_manifest,
        capture_stack,
    )
    selector_delta = _build_preflight_selector_delta(source_root_fd)
    runtime_receipt = _build_runtime_receipt(
        source_root_fd,
        capture_stack=capture_stack,
    )
    authorities = sorted(
        [*upstream, *package["authorityRecords"]],
        key=lambda record: record["path"],
    )
    if len(authorities) != 53 or len(
        {record["path"] for record in authorities}
    ) != 53:
        raise ContractViolation("preflight authority set differs")
    rollback = {
        "prechange": _artifact_ref(
            _relative_file_record(workspace_fd, TIER0_DESTINATIONS[4])
        ),
        "rollback": _artifact_ref(
            _relative_file_record(workspace_fd, TIER0_DESTINATIONS[5])
        ),
        "bundleManifest": _artifact_ref(
            _relative_file_record(workspace_fd, TIER0_DESTINATIONS[9])
        ),
    }
    lease = _relative_file_record(workspace_fd, TIER0_DESTINATIONS[3])
    value = {
        "schemaVersion": "quant-radar-ui-ux-formal-handoff-preflight/v2",
        "status": "passed",
        "recoveryId": AUTHORIZED_RECOVERY_ID,
        "authorizationRecord": package["authorizationRecord"],
        "baseDraft": package["baseDraft"],
        "replacementPlan": package["replacementPlan"],
        "traceability": package["traceability"],
        "authorities": authorities,
        "rollback": rollback,
        "captureStack": capture_stack,
        "task6": task6,
        "selectorDelta": selector_delta,
        "historicalSelectorModes": [
            dict(record)
            for record in sorted(
                SELECTOR_MEMBERS,
                key=lambda item: item["path"],
            )
        ],
        **projections,
        "runtimeReceipt": runtime_receipt,
        "eligibleDestinations": eligible,
        "descriptorBudget": _validate_descriptor_budget(
            dict(descriptor_budget)
        ),
        "lease": lease,
    }
    _validate_schema(value["schemaVersion"], value)
    for field in ("sourceProjection", "supplementalProjection"):
        _validate_schema("SourceProjection", value[field])
    _validate_schema(
        "SourceProjection",
        value["task6"]["historicalSourceProjection"],
    )
    _validate_schema("RuntimeReceipt", value["runtimeReceipt"])
    return value


def _validate_preflight_complete(
    workspace_fd: int,
    value: Mapping[str, Any],
    *,
    source_root_fd: int,
    destination_policy: Literal[
        "fresh",
        "task9-active",
    ] = "fresh",
) -> dict[str, Any]:
    if not isinstance(value, Mapping):
        raise ContractViolation("preflight value is not an object")
    normalized = dict(value)
    descriptor_budget = _validate_descriptor_budget(
        normalized.get("descriptorBudget")
    )
    expected = _build_preflight_value(
        workspace_fd,
        source_root_fd,
        descriptor_budget,
        destination_policy=destination_policy,
    )
    if normalized != expected:
        raise ContractViolation("preflight bytes differ from current authority")
    current_hard = resource.getrlimit(resource.RLIMIT_NOFILE)[1]
    if descriptor_budget["hardLimit"] != current_hard:
        raise ContractViolation("preflight descriptor hard limit drifted")
    return normalized


def _preflight_lifecycle(
    workspace_fd: int,
    recovery_id: str,
    authorization_record_sha: str | None,
    *,
    source_root_fd: int,
    verify_only: bool = False,
) -> dict[str, Any]:
    if (
        recovery_id != AUTHORIZED_RECOVERY_ID
        or (
            not verify_only
            and authorization_record_sha != AUTH_BODY_SHA256
        )
        or (
            verify_only
            and authorization_record_sha is not None
        )
    ):
        raise ContractViolation("preflight authorization arguments differ")
    workspace_observed = os.fstat(workspace_fd)
    workspace_named = os.lstat(WORKSPACE_ROOT)
    if (
        not stat.S_ISDIR(workspace_observed.st_mode)
        or (
            workspace_observed.st_dev,
            workspace_observed.st_ino,
        )
        != (
            workspace_named.st_dev,
            workspace_named.st_ino,
        )
        or not stat.S_ISDIR(os.fstat(source_root_fd).st_mode)
    ):
        raise ContractViolation("preflight descriptor binding differs")

    lock_fd: int | None = None
    try:
        lock_parent_fd, lock_name = _open_relative_parent_fd(
            workspace_fd,
            TIER0_DESTINATIONS[2],
        )
        try:
            lock_fd = os.open(
                lock_name,
                os.O_RDWR
                | os.O_NOFOLLOW
                | getattr(os, "O_CLOEXEC", 0),
                dir_fd=lock_parent_fd,
            )
            lock_named = os.stat(
                lock_name,
                dir_fd=lock_parent_fd,
                follow_symlinks=False,
            )
            _require_relative_parent_current(
                workspace_fd,
                TIER0_DESTINATIONS[2],
                lock_parent_fd,
            )
        finally:
            os.close(lock_parent_fd)
    except OSError as exc:
        if lock_fd is not None:
            os.close(lock_fd)
        raise ContractViolation(
            "preflight global lock cannot be safely opened"
        ) from exc
    except BaseException:
        if lock_fd is not None:
            os.close(lock_fd)
        raise
    if lock_fd is None:
        raise ContractViolation("preflight global lock was not opened")
    try:
        lock_observed = os.fstat(lock_fd)
        lock_record = _file_record_from_fd(
            TIER0_DESTINATIONS[2],
            lock_fd,
        )
        if (
            not stat.S_ISREG(lock_observed.st_mode)
            or lock_observed.st_nlink != 1
            or lock_observed.st_uid != os.getuid()
            or lock_observed.st_gid != os.getgid()
            or stat.S_IMODE(lock_observed.st_mode) != 0o600
            or lock_observed.st_size != 0
            or (
                lock_observed.st_dev,
                lock_observed.st_ino,
            )
            != (
                lock_named.st_dev,
                lock_named.st_ino,
            )
        ):
            raise ContractViolation("preflight global lock authority differs")
        try:
            fcntl.flock(lock_fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            return {"exitCode": EXIT_BUSY}
        try:
            def require_current_lock() -> None:
                current = _relative_file_record(
                    workspace_fd,
                    TIER0_DESTINATIONS[2],
                )
                retained = os.fstat(lock_fd)
                if (
                    current != lock_record
                    or (
                        retained.st_dev,
                        retained.st_ino,
                    )
                    != (
                        current["device"],
                        current["inode"],
                    )
                ):
                    raise ContractViolation(
                        "preflight global lock path/descriptor drifted"
                    )

            require_current_lock()
            preflight_path = TIER0_DESTINATIONS[10]
            if _relative_leaf_lstat(workspace_fd, preflight_path) is not None:
                try:
                    existing = _read_relative_canonical_evidence(
                        workspace_fd,
                        preflight_path,
                    )
                except ContractViolation:
                    return {"exitCode": EXIT_COLLISION}
                operational_budget = _plan_preflight_descriptor_budget()
                if operational_budget.get("exitCode") == EXIT_UNAVAILABLE:
                    return {"exitCode": EXIT_UNAVAILABLE}
                try:
                    with _apply_preflight_descriptor_budget(
                        operational_budget
                    ):
                        _validate_preflight_complete(
                            workspace_fd,
                            existing,
                            source_root_fd=source_root_fd,
                        )
                        require_current_lock()
                except ContractViolation:
                    return {"exitCode": EXIT_COLLISION}
                return {
                    "exitCode": EXIT_SUCCESS,
                    "value": existing,
                    "created": False,
                    "reconciled": True,
                }
            if verify_only:
                return {"exitCode": EXIT_CONTRACT}

            descriptor_budget = _plan_preflight_descriptor_budget()
            if descriptor_budget.get("exitCode") == EXIT_UNAVAILABLE:
                return {"exitCode": EXIT_UNAVAILABLE}
            with _apply_preflight_descriptor_budget(descriptor_budget):
                value = _build_preflight_value(
                    workspace_fd,
                    source_root_fd,
                    descriptor_budget,
                )
                _preflight_eligible_destinations(workspace_fd)
                require_current_lock()
                parent_fd, preflight_name = _open_relative_parent_fd(
                    workspace_fd,
                    preflight_path,
                )
                try:
                    published = _publish_regular_exact(
                        parent_fd,
                        preflight_name,
                        _canonical_json_bytes(value),
                    )
                    if published.get("exitCode") != EXIT_SUCCESS:
                        return {
                            "exitCode": published.get("exitCode")
                        }
                    if (
                        type(published.get("created")) is not bool
                        or type(published.get("reconciled")) is not bool
                        or published["created"] == published["reconciled"]
                    ):
                        raise ContractViolation(
                            "preflight publication outcome is invalid"
                        )
                    try:
                        _require_relative_parent_current(
                            workspace_fd,
                            preflight_path,
                            parent_fd,
                        )
                    except (ContractViolation, OSError):
                        return {
                            "exitCode": (
                                EXIT_UNCERTAIN
                                if published["created"]
                                else EXIT_COLLISION
                            )
                        }
                finally:
                    os.close(parent_fd)
                try:
                    reopened = _read_relative_canonical_evidence(
                        workspace_fd,
                        preflight_path,
                    )
                    _validate_preflight_complete(
                        workspace_fd,
                        reopened,
                        source_root_fd=source_root_fd,
                    )
                    require_current_lock()
                except (ContractViolation, OSError):
                    return {
                        "exitCode": (
                            EXIT_UNCERTAIN
                            if published["created"]
                            else EXIT_COLLISION
                        )
                    }
            return {
                "exitCode": EXIT_SUCCESS,
                "value": reopened,
                "created": published.get("created") is True,
                "reconciled": published.get("reconciled") is True,
            }
        finally:
            fcntl.flock(lock_fd, fcntl.LOCK_UN)
    finally:
        os.close(lock_fd)


def _plan_fd_budget(
    inherited_fds: Sequence[int],
    *,
    worst_case_unique_retained_leaves: int,
    max_path_depth: int,
    soft_limit: int,
    hard_limit: int,
    syscalls: Any | None = None,
) -> dict[str, Any]:
    if (
        any(type(fd) is not int or fd < 0 for fd in inherited_fds)
        or len(set(inherited_fds)) != len(inherited_fds)
        or type(worst_case_unique_retained_leaves) is not int
        or worst_case_unique_retained_leaves < 0
        or type(max_path_depth) is not int
        or max_path_depth < 0
        or type(soft_limit) is not int
        or type(hard_limit) is not int
        or soft_limit < 0
        or hard_limit < soft_limit
    ):
        raise ContractViolation("invalid descriptor-budget inputs")

    class HostFdSyscalls:
        def open_fd_inventory(self) -> tuple[tuple[int, ...], int]:
            inventory_fd = os.open("/dev/fd", os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0))
            candidates = tuple(
                sorted(
                    int(name)
                    for name in os.listdir("/dev/fd")
                    if name.isdigit() and int(name) != inventory_fd
                )
            )
            return candidates, inventory_fd

        def fstat(self, fd: int) -> os.stat_result:
            return os.fstat(fd)

        def close_fd_inventory(self, token: int) -> None:
            os.close(token)

        def get_nofile_limit(self) -> tuple[int, int]:
            return resource.getrlimit(resource.RLIMIT_NOFILE)

        def set_nofile_limit(self, current_soft: int, current_hard: int) -> None:
            resource.setrlimit(resource.RLIMIT_NOFILE, (current_soft, current_hard))

    calls = HostFdSyscalls() if syscalls is None else syscalls
    inventory: tuple[int, ...] = ()
    inventory_token: int | None = None
    valid_fds: list[int] = []
    try:
        inventory_raw, inventory_token = calls.open_fd_inventory()
        inventory = tuple(inventory_raw)
        if len(set(inventory)) != len(inventory) or any(type(fd) is not int or fd < 0 for fd in inventory):
            raise ContractViolation("descriptor inventory is malformed")
        for fd in inventory:
            try:
                calls.fstat(fd)
            except OSError as exc:
                # Darwin's /dev/fd directory enumeration may expose the
                # short-lived descriptor used internally by listdir after it
                # has already closed.  It grants no retained authority and is
                # excluded only when the confirming fstat proves EBADF.
                if exc.errno == errno.EBADF:
                    continue
                raise
            valid_fds.append(fd)
    finally:
        if inventory_token is not None:
            calls.close_fd_inventory(inventory_token)

    observed_soft, observed_hard = calls.get_nofile_limit()
    if (observed_soft, observed_hard) != (soft_limit, hard_limit):
        raise ContractViolation("descriptor limits changed during inventory")
    baseline_count = len(valid_fds)
    baseline_max = max(valid_fds, default=-1)
    reserve = 64
    protocol_additional = worst_case_unique_retained_leaves + 2 * max_path_depth + reserve
    peak_open_count = baseline_count + protocol_additional
    required_soft = max(baseline_max + 1, peak_open_count)
    if (
        peak_open_count > 1_536
        or required_soft > 1_536
        or required_soft > hard_limit
    ):
        return {
            "exitCode": EXIT_UNAVAILABLE,
            "stdout": b"",
            "published": False,
            "softRestored": True,
        }

    raised = required_soft > soft_limit
    if raised:
        try:
            calls.set_nofile_limit(required_soft, hard_limit)
        except OSError:
            try:
                calls.set_nofile_limit(soft_limit, hard_limit)
            except OSError as exc:
                raise ContractViolation("failed to restore descriptor soft limit") from exc
            return {
                "exitCode": EXIT_UNAVAILABLE,
                "stdout": b"",
                "published": False,
                "softRestored": True,
            }
        try:
            current_soft, current_hard = calls.get_nofile_limit()
            if (current_soft, current_hard) != (required_soft, hard_limit):
                raise ContractViolation("descriptor soft-limit raise did not take effect")
        finally:
            calls.set_nofile_limit(soft_limit, hard_limit)
    return {
        "baselineOpenCount": baseline_count,
        "baselineMaxFd": baseline_max,
        "hardLimit": hard_limit,
        "protocolAdditional": protocol_additional,
        "peakOpenCount": peak_open_count,
        "requiredSoft": required_soft,
        "softApplied": required_soft if raised else soft_limit,
        "reserve": reserve,
        "softRestored": True,
    }


def _verify_staged_root_fd(
    workspace_fd: int,
    stage_fd: int,
    receipt_fd: int,
    nonce: str,
) -> dict[str, Any]:
    if any(type(fd) is not int or fd < 0 for fd in (workspace_fd, stage_fd, receipt_fd)):
        raise ContractViolation("private verifier descriptors must be nonnegative integers")
    if len({workspace_fd, stage_fd, receipt_fd}) != 3:
        raise ContractViolation("private verifier descriptors must be distinct")
    if not isinstance(nonce, str) or NONCE_PATTERN.fullmatch(nonce) is None:
        raise ContractViolation("private verifier nonce is invalid")

    workspace_stat = os.fstat(workspace_fd)
    stage_stat = os.fstat(stage_fd)
    receipt_stat = os.fstat(receipt_fd)
    if not stat.S_ISDIR(workspace_stat.st_mode):
        raise ContractViolation("workspace descriptor is not a directory")
    if not stat.S_ISREG(stage_stat.st_mode) or stage_stat.st_uid != os.getuid() or stage_stat.st_nlink != 1:
        raise ContractViolation("stage descriptor is not an owned one-link regular file")
    if not stat.S_ISFIFO(receipt_stat.st_mode):
        raise ContractViolation("receipt descriptor is not a pipe")
    named_workspace = os.lstat(WORKSPACE_ROOT)
    if (workspace_stat.st_dev, workspace_stat.st_ino) != (named_workspace.st_dev, named_workspace.st_ino):
        raise ContractViolation("workspace descriptor/path identity mismatch")

    try:
        raw_path = fcntl.fcntl(stage_fd, 50, b"\0" * 1024)
        absolute_stage = Path(raw_path.split(b"\0", 1)[0].decode("utf-8", errors="strict"))
        relative_stage = absolute_stage.relative_to(WORKSPACE_ROOT).as_posix()
    except (OSError, UnicodeError, ValueError) as exc:
        raise ContractViolation("could not bind the staged descriptor path") from exc
    if not _is_safe_relative_path(relative_stage):
        raise ContractViolation("staged descriptor path is unsafe")
    named_stage = os.stat(relative_stage, dir_fd=workspace_fd, follow_symlinks=False)
    if (stage_stat.st_dev, stage_stat.st_ino) != (named_stage.st_dev, named_stage.st_ino):
        raise ContractViolation("staged descriptor/name identity mismatch")

    original_offset = os.lseek(stage_fd, 0, os.SEEK_CUR)
    try:
        os.lseek(stage_fd, 0, os.SEEK_SET)
        digest = hashlib.sha256()
        size = 0
        while True:
            chunk = os.read(stage_fd, 131_072)
            if not chunk:
                break
            size += len(chunk)
            if size > LIVE_IMAGE_HASH_LIMIT_BYTES:
                raise ContractViolation("staged verifier input exceeds the hash bound")
            digest.update(chunk)
    finally:
        os.lseek(stage_fd, original_offset, os.SEEK_SET)
    if size != stage_stat.st_size:
        raise ContractViolation("staged descriptor size changed while hashing")
    stage_after = os.fstat(stage_fd)
    if (stage_after.st_dev, stage_after.st_ino, stage_after.st_size) != (
        stage_stat.st_dev,
        stage_stat.st_ino,
        stage_stat.st_size,
    ):
        raise ContractViolation("staged descriptor changed while validating")

    stage_record = {
        "path": relative_stage,
        "sha256": digest.hexdigest(),
        "size": size,
        "mode": f"{stat.S_IMODE(stage_stat.st_mode):04o}",
        "uid": stage_stat.st_uid,
        "gid": stage_stat.st_gid,
        "device": stage_stat.st_dev,
        "inode": stage_stat.st_ino,
        "nlink": stage_stat.st_nlink,
    }
    receipt = {
        "nonce": nonce,
        "workspace": {"device": workspace_stat.st_dev, "inode": workspace_stat.st_ino},
        "stage": stage_record,
        "inheritedFdCount": 3,
        "openedLock": False,
        "published": False,
    }
    encoded = _canonical_json_bytes(receipt)
    if len(encoded) > 1_048_576:
        raise ContractViolation("private verifier receipt exceeds the byte bound")
    view = memoryview(encoded)
    while view:
        written = os.write(receipt_fd, view)
        if written <= 0:
            raise OSError(errno.EIO, "short private receipt write")
        view = view[written:]
    return receipt


def _validate_private_receipt(
    expected: dict[str, Any],
    receipt: dict[str, Any],
) -> None:
    if not isinstance(expected, dict) or set(expected) != {
        "nonce", "workspace", "stage", "inheritedFdCount"
    }:
        raise ContractViolation("private receipt expectation is malformed")
    if not isinstance(receipt, dict) or set(receipt) != {
        "nonce", "workspace", "stage", "inheritedFdCount", "openedLock", "published"
    }:
        raise ContractViolation("private receipt keys are not closed")
    if receipt.get("openedLock") is not False or receipt.get("published") is not False:
        raise ContractViolation("private verifier claimed forbidden authority")
    if any(receipt.get(key) != expected[key] for key in expected):
        raise ContractViolation("private verifier receipt does not match parent authority")
    if type(receipt.get("inheritedFdCount")) is not int or receipt["inheritedFdCount"] != 3:
        raise ContractViolation("private verifier descriptor count mismatch")


def _public_lock_probe(workspace_fd: int) -> dict[str, Any]:
    if type(workspace_fd) is not int or workspace_fd < 0 or not stat.S_ISDIR(os.fstat(workspace_fd).st_mode):
        raise ContractViolation("public lock probe requires a directory descriptor")
    relative = ".claude/ui_snapshots/ux1b/.formal-theme-handoff.lock"
    flags = os.O_RDWR | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
    fd = _open_relative_leaf_fd(
        workspace_fd,
        relative,
        flags,
    )
    try:
        observed = os.fstat(fd)
        if (
            not stat.S_ISREG(observed.st_mode)
            or observed.st_uid != os.getuid()
            or observed.st_gid != os.getgid()
            or observed.st_nlink != 1
            or observed.st_size != 0
            or stat.S_IMODE(observed.st_mode) != 0o600
        ):
            raise ContractViolation("public lock metadata mismatch")
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            return {"exitCode": EXIT_BUSY, "stdout": b"", "published": False}
        fcntl.flock(fd, fcntl.LOCK_UN)
        return {"exitCode": EXIT_SUCCESS, "stdout": b"", "published": False}
    finally:
        os.close(fd)


def _is_normalized_publisher_component(name: object) -> bool:
    return (
        isinstance(name, str)
        and bool(name)
        and "/" not in name
        and name not in (".", "..")
        and re.fullmatch(
            r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}",
            name,
        )
        is not None
    )


def _publish_regular_exact(
    parent_fd: int,
    name: str,
    payload: bytes,
    *,
    fault_after: str | None = None,
    syscalls: Any | None = None,
    precommit: Callable[[], None] | None = None,
    postrename_prefsync: Callable[[], None] | None = None,
    postfsync: Callable[[], None] | None = None,
    postcommit: Callable[[], None] | None = None,
) -> dict[str, Any]:
    if type(parent_fd) is not int or parent_fd < 0 or not stat.S_ISDIR(os.fstat(parent_fd).st_mode):
        raise ContractViolation("publisher parent must be a directory descriptor")
    if not _is_normalized_publisher_component(name):
        raise ContractViolation("publisher name must be one normalized component")
    if not isinstance(payload, bytes):
        raise ContractViolation("publisher payload must be bytes")
    if any(
        callback is not None and not callable(callback)
        for callback in (
            precommit,
            postrename_prefsync,
            postfsync,
            postcommit,
        )
    ):
        raise ContractViolation(
            "publisher commit callbacks must be callable"
        )
    if fault_after not in {None, "before-rename", "after-rename", "after-parent-fsync", "after-reopen"}:
        raise ContractViolation("unknown publisher fault boundary")

    expected_digest = hashlib.sha256(payload).hexdigest()
    read_flags = os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
    open_flags = os.O_CREAT | os.O_EXCL | os.O_RDWR | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
    static_result = {
        "openFlags": open_flags,
        "mode": "0600",
        "renamePrimitive": "renameatx_np",
        "renameFlags": 0x00000004,
        "writesAfterUncertainty": 0,
    }

    def inspect_public(
        *,
        expected_identity: tuple[int, int] | None = None,
        use_calls: bool = False,
    ) -> dict[str, Any] | None:
        try:
            named_before = os.stat(
                name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            return None
        except OSError as exc:
            raise ContractViolation(
                "public evidence cannot be safely inspected"
            ) from exc
        fd: int | None = None
        try:
            try:
                fd = (
                    calls.reopen(name, read_flags)
                    if use_calls
                    else os.open(
                        name,
                        read_flags,
                        dir_fd=parent_fd,
                    )
                )
            except OSError as exc:
                raise ContractViolation(
                    "public evidence cannot be safely opened"
                ) from exc
            observed = os.fstat(fd)
            if (
                not stat.S_ISREG(observed.st_mode)
                or stat.S_IMODE(observed.st_mode) != 0o600
                or observed.st_uid != os.getuid()
                or observed.st_gid != os.getgid()
                or observed.st_nlink != 1
                or observed.st_size != len(payload)
                or (
                    named_before.st_dev,
                    named_before.st_ino,
                )
                != (
                    observed.st_dev,
                    observed.st_ino,
                )
                or (
                    expected_identity is not None
                    and (
                        observed.st_dev,
                        observed.st_ino,
                    )
                    != expected_identity
                )
            ):
                raise ContractViolation("public evidence metadata collision")
            digest = hashlib.sha256()
            total = 0
            while True:
                chunk = os.read(fd, 131_072)
                if not chunk:
                    break
                total += len(chunk)
                if total > len(payload):
                    raise ContractViolation("public evidence exceeds expected bytes")
                digest.update(chunk)
            if total != len(payload) or digest.hexdigest() != expected_digest:
                raise ContractViolation("public evidence content collision")
            after = os.fstat(fd)
            named_after = os.stat(
                name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
            if (
                (
                    after.st_dev,
                    after.st_ino,
                    after.st_size,
                )
                != (
                    observed.st_dev,
                    observed.st_ino,
                    observed.st_size,
                )
                or (
                    named_after.st_dev,
                    named_after.st_ino,
                )
                != (
                    observed.st_dev,
                    observed.st_ino,
                )
            ):
                raise ContractViolation(
                    "public evidence changed while retained"
                )
            return {
                "path": name,
                "sha256": digest.hexdigest(),
                "size": total,
                "mode": f"{stat.S_IMODE(observed.st_mode):04o}",
                "uid": observed.st_uid,
                "gid": observed.st_gid,
                "device": observed.st_dev,
                "inode": observed.st_ino,
                "nlink": observed.st_nlink,
            }
        finally:
            if fd is not None:
                (
                    calls.close(fd)
                    if use_calls
                    else os.close(fd)
                )

    try:
        existing = inspect_public()
    except ContractViolation:
        return {
            **static_result,
            "exitCode": EXIT_COLLISION,
            "created": False,
            "reconciled": False,
            "writeCount": 0,
            "writePaths": [],
        }
    if existing is not None:
        if precommit is not None:
            precommit()
        if postcommit is not None:
            postcommit()
        return {
            **static_result,
            "exitCode": EXIT_SUCCESS,
            "sameInode": True,
            "created": False,
            "reconciled": True,
            "writeCount": 0,
            "writePaths": [],
            "published": existing,
        }

    class DefaultPublisherSyscalls:
        def __init__(self) -> None:
            self.paths: dict[int, str] = {}

        def open_exclusive(self, relative: str, flags: int, mode: int) -> int:
            fd = os.open(relative, flags, mode, dir_fd=parent_fd)
            self.paths[fd] = relative
            return fd

        def write_all(self, fd: int, data: bytes) -> None:
            view = memoryview(data)
            while view:
                written = os.write(fd, view)
                if written <= 0:
                    raise OSError(errno.EIO, "short evidence write")
                view = view[written:]

        def fsync_file(self, fd: int) -> None:
            os.fsync(fd)

        def rehash(self, fd: int) -> str:
            os.lseek(fd, 0, os.SEEK_SET)
            digest = hashlib.sha256()
            while chunk := os.read(fd, 131_072):
                digest.update(chunk)
            return digest.hexdigest()

        def rename_excl(self, source: str, destination: str) -> tuple[int, int]:
            if sys.platform != "darwin":
                raise OSError(errno.ENOTSUP, "RENAME_EXCL requires Darwin")
            source_inode = os.stat(source, dir_fd=parent_fd, follow_symlinks=False).st_ino
            libc = ctypes.CDLL(None, use_errno=True)
            renameatx_np = libc.renameatx_np
            renameatx_np.argtypes = (ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint)
            renameatx_np.restype = ctypes.c_int
            if renameatx_np(parent_fd, os.fsencode(source), parent_fd, os.fsencode(destination), 0x00000004) != 0:
                error_number = ctypes.get_errno()
                raise OSError(error_number, os.strerror(error_number), destination)
            destination_inode = os.stat(destination, dir_fd=parent_fd, follow_symlinks=False).st_ino
            return source_inode, destination_inode

        def fsync_parent(self, relative: str = ".") -> None:
            if relative != ".":
                raise ContractViolation("regular publisher owns only its retained parent")
            os.fsync(parent_fd)

        def reopen(self, relative: str, flags: int) -> int:
            fd = os.open(relative, flags, dir_fd=parent_fd)
            self.paths[fd] = relative
            return fd

        def close(self, fd: int) -> None:
            self.paths.pop(fd, None)
            os.close(fd)

        def unlink_same_inode(self, relative: str, expected_inode: int) -> None:
            observed = os.stat(relative, dir_fd=parent_fd, follow_symlinks=False)
            if observed.st_ino != expected_inode:
                raise ContractViolation("refusing to remove a replaced publisher temp")
            os.unlink(relative, dir_fd=parent_fd)

    calls = DefaultPublisherSyscalls() if syscalls is None else syscalls
    kind = name.rsplit(".", 1)[0]
    temporary = f".tmp.{kind}.{secrets.token_hex(16)}"
    stage_fd: int | None = None
    stage_identity: tuple[int, int] | None = None
    renamed = False
    try:
        stage_fd = calls.open_exclusive(temporary, open_flags, 0o600)
        stage_stat = os.fstat(stage_fd)
        stage_identity = (stage_stat.st_dev, stage_stat.st_ino)
        if (
            not stat.S_ISREG(stage_stat.st_mode)
            or stat.S_IMODE(stage_stat.st_mode) != 0o600
            or stage_stat.st_uid != os.getuid()
            or stage_stat.st_gid != os.getgid()
            or stage_stat.st_nlink != 1
        ):
            raise ContractViolation("publisher temp metadata mismatch")
        calls.write_all(stage_fd, payload)
        calls.fsync_file(stage_fd)
        if calls.rehash(stage_fd) != expected_digest:
            raise ContractViolation("publisher temp rehash mismatch")
        if precommit is not None:
            precommit()
        if fault_after == "before-rename":
            calls.close(stage_fd)
            stage_fd = None
            calls.unlink_same_inode(temporary, stage_identity[1])
            return {
                **static_result,
                "exitCode": EXIT_CONTRACT,
                "created": False,
                "reconciled": False,
                "writeCount": 1,
                "writePaths": [temporary],
            }
        try:
            source_inode, destination_inode = calls.rename_excl(temporary, name)
            renamed = True
        except FileExistsError:
            calls.close(stage_fd)
            stage_fd = None
            calls.unlink_same_inode(temporary, stage_identity[1])
            try:
                reconciled = inspect_public()
            except ContractViolation:
                reconciled = None
            if reconciled is None:
                return {
                    **static_result,
                    "exitCode": EXIT_COLLISION,
                    "created": False,
                    "reconciled": False,
                    "writeCount": 0,
                    "writePaths": [],
                }
            if postcommit is not None:
                postcommit()
            return {
                **static_result,
                "exitCode": EXIT_SUCCESS,
                "sameInode": True,
                "created": False,
                "reconciled": True,
                "writeCount": 0,
                "writePaths": [],
                "published": reconciled,
            }
        except OSError:
            try:
                destination_after_error = os.stat(
                    name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except FileNotFoundError:
                return {
                    **static_result,
                    "exitCode": EXIT_UNAVAILABLE,
                    "created": False,
                    "reconciled": False,
                    "writeCount": 1,
                    "writePaths": [temporary],
                }
            except OSError:
                renamed = True
                return {
                    **static_result,
                    "exitCode": EXIT_UNCERTAIN,
                    "created": False,
                    "reconciled": False,
                    "writeCount": 1,
                    "writePaths": [temporary],
                }
            if (
                destination_after_error.st_dev,
                destination_after_error.st_ino,
            ) == stage_identity:
                renamed = True
                return {
                    **static_result,
                    "exitCode": EXIT_UNCERTAIN,
                    "created": True,
                    "reconciled": False,
                    "writeCount": 1,
                    "writePaths": [temporary],
                }
            return {
                **static_result,
                "exitCode": EXIT_COLLISION,
                "created": False,
                "reconciled": False,
                "writeCount": 1,
                "writePaths": [temporary],
            }
        if source_inode != destination_inode or destination_inode != stage_identity[1]:
            raise ContractViolation("RENAME_EXCL did not preserve the staged inode")
        if postrename_prefsync is not None:
            postrename_prefsync()
        if fault_after == "after-rename":
            return {
                **static_result,
                "exitCode": EXIT_UNCERTAIN,
                "created": True,
                "reconciled": False,
                "writeCount": 1,
                "writePaths": [temporary],
            }
        calls.fsync_parent(".")
        if postfsync is not None:
            postfsync()
        if fault_after == "after-parent-fsync":
            return {
                **static_result,
                "exitCode": EXIT_UNCERTAIN,
                "created": True,
                "reconciled": False,
                "writeCount": 1,
                "writePaths": [temporary],
            }
        published = inspect_public(
            expected_identity=stage_identity,
            use_calls=True,
        )
        if published is None:
            raise ContractViolation(
                "published evidence disappeared after reopen"
            )
        if postcommit is not None:
            postcommit()
        if fault_after == "after-reopen":
            return {
                **static_result,
                "exitCode": EXIT_UNCERTAIN,
                "created": True,
                "reconciled": False,
                "writeCount": 1,
                "writePaths": [temporary],
            }
        return {
            **static_result,
            "exitCode": EXIT_SUCCESS,
            "sameInode": True,
            "created": True,
            "reconciled": False,
            "writeCount": 1,
            "writePaths": [temporary],
            "published": published,
        }
    except (ContractViolation, OSError):
        if renamed:
            return {
                **static_result,
                "exitCode": EXIT_UNCERTAIN,
                "created": True,
                "reconciled": False,
                "writeCount": 1,
                "writePaths": [temporary],
            }
        raise
    finally:
        if stage_fd is not None:
            calls.close(stage_fd)
        if not renamed and stage_identity is not None:
            try:
                observed = os.stat(temporary, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                if observed.st_ino == stage_identity[1]:
                    calls.unlink_same_inode(temporary, stage_identity[1])


class _Task9RunnerFailure(RuntimeError):
    """A terminal runner failure with a closed public exit mapping."""

    def __init__(self, exit_code: int, message: str) -> None:
        if exit_code not in {
            EXIT_CONTRACT,
            EXIT_COLLISION,
            EXIT_UNAVAILABLE,
            EXIT_UNCERTAIN,
            EXIT_BUSY,
            EXIT_EXHAUSTED,
            EXIT_MANUAL,
            EXIT_INTERRUPTED,
        }:
            raise ContractViolation("Task 9 runner failure exit is invalid")
        super().__init__(message)
        self.exit_code = exit_code


def _task9_retain_directory_at(
    parent_fd: int,
    name: str,
    *,
    expected_identity: tuple[int, int] | None = None,
    normalize_system_gid: bool = False,
) -> tuple[int, tuple[int, int]]:
    if (
        type(parent_fd) is not int
        or parent_fd < 0
        or not isinstance(name, str)
        or not name
        or name in {".", ".."}
        or "/" in name
        or "\0" in name
        or type(normalize_system_gid) is not bool
    ):
        raise ContractViolation(
            "Task 9 directory authority is invalid"
        )
    flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | os.O_NOFOLLOW
        | getattr(os, "O_CLOEXEC", 0)
    )
    try:
        named = os.stat(
            name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        retained_fd = os.open(
            name,
            flags,
            dir_fd=parent_fd,
        )
    except OSError as exc:
        raise ContractViolation(
            "Task 9 directory cannot be retained"
        ) from exc
    try:
        retained = os.fstat(retained_fd)
        identity = (retained.st_dev, retained.st_ino)
        if (
            not stat.S_ISDIR(named.st_mode)
            or not stat.S_ISDIR(retained.st_mode)
            or (named.st_dev, named.st_ino) != identity
            or retained.st_uid != os.getuid()
            or stat.S_IMODE(retained.st_mode) != 0o700
            or (
                expected_identity is not None
                and identity != expected_identity
            )
        ):
            raise ContractViolation(
                "Task 9 directory identity/metadata differs"
            )
        if normalize_system_gid:
            try:
                entries = os.listdir(retained_fd)
            except OSError as exc:
                raise ContractViolation(
                    "Task 9 system temporary root cannot be enumerated"
                ) from exc
            if entries:
                raise _Task9RunnerFailure(
                    EXIT_COLLISION,
                    "Task 9 system temporary root is not empty",
                )
        if retained.st_gid != os.getgid():
            if not normalize_system_gid or retained.st_gid != 0:
                raise ContractViolation(
                    "Task 9 directory identity/metadata differs"
                )
            try:
                os.fchown(
                    retained_fd,
                    -1,
                    os.getgid(),
                )
            except OSError as exc:
                raise ContractViolation(
                    "Task 9 system temporary root group cannot be normalized"
                ) from exc
            retained = os.fstat(retained_fd)
            if (
                (retained.st_dev, retained.st_ino) != identity
                or not stat.S_ISDIR(retained.st_mode)
                or retained.st_uid != os.getuid()
                or retained.st_gid != os.getgid()
                or stat.S_IMODE(retained.st_mode) != 0o700
            ):
                raise ContractViolation(
                    "Task 9 normalized directory metadata differs"
                )
        return retained_fd, identity
    except BaseException:
        os.close(retained_fd)
        raise


def _task9_create_directory_at(
    parent_fd: int,
    name: str,
) -> tuple[int, tuple[int, int]]:
    try:
        os.mkdir(name, 0o700, dir_fd=parent_fd)
    except FileExistsError as exc:
        raise _Task9RunnerFailure(
            EXIT_COLLISION,
            "Task 9 private environment already exists",
        ) from exc
    except OSError as exc:
        raise _Task9RunnerFailure(
            EXIT_UNAVAILABLE,
            "Task 9 private environment cannot be created",
        ) from exc
    return _task9_retain_directory_at(parent_fd, name)


def _task9_open_temp_root(
    temp_parent: Path,
    *,
    root_policy: Literal["initial", "active"] = "initial",
) -> tuple[int, tuple[int, int]]:
    spelling = str(temp_parent)
    if (
        not spelling.startswith("/")
        or posixpath.normpath(spelling) != spelling
        or spelling == "/"
        or "\0" in spelling
        or not isinstance(root_policy, str)
        or root_policy not in {"initial", "active"}
    ):
        raise ContractViolation(
            "Task 9 temporary-root path is invalid"
        )
    immediate_parent = temp_parent.parent
    leaf = temp_parent.name
    flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | os.O_NOFOLLOW
        | getattr(os, "O_CLOEXEC", 0)
    )
    try:
        named_parent = os.lstat(immediate_parent)
        parent_fd = os.open(immediate_parent, flags)
    except OSError as exc:
        raise ContractViolation(
            "Task 9 temporary-root parent is unavailable"
        ) from exc
    try:
        retained_parent = os.fstat(parent_fd)
        parent_identity = (
            retained_parent.st_dev,
            retained_parent.st_ino,
        )
        parent_mode = stat.S_IMODE(retained_parent.st_mode)
        owned_safe = (
            retained_parent.st_uid == os.getuid()
            and retained_parent.st_gid == os.getgid()
            and _safe_directory_mode(f"{parent_mode:04o}")
        )
        system_tmp = (
            str(immediate_parent) == "/private/tmp"
            and retained_parent.st_uid == 0
            and retained_parent.st_gid == 0
            and parent_mode == 0o1777
        )
        if (
            not stat.S_ISDIR(named_parent.st_mode)
            or not stat.S_ISDIR(retained_parent.st_mode)
            or (
                named_parent.st_dev,
                named_parent.st_ino,
            )
            != parent_identity
            or not (owned_safe or system_tmp)
        ):
            raise ContractViolation(
                "Task 9 temporary-root parent is unsafe"
            )
        try:
            os.mkdir(leaf, 0o700, dir_fd=parent_fd)
        except FileExistsError:
            pass
        except OSError as exc:
            raise _Task9RunnerFailure(
                EXIT_UNAVAILABLE,
                "Task 9 temporary root cannot be created",
            ) from exc
        temp_root_fd, temp_root_identity = (
            _task9_retain_directory_at(
                parent_fd,
                leaf,
                normalize_system_gid=(
                    system_tmp
                    and root_policy == "initial"
                ),
            )
        )
        try:
            try:
                entries = sorted(os.listdir(temp_root_fd))
            except OSError as exc:
                raise ContractViolation(
                    "Task 9 temporary root cannot be enumerated"
                ) from exc
            expected_entries = (
                []
                if root_policy == "initial"
                else [AUTHORIZED_RECOVERY_ID]
            )
            if entries != expected_entries:
                raise _Task9RunnerFailure(
                    EXIT_COLLISION,
                    "Task 9 temporary-root lifecycle collides",
                )
            current_parent = os.lstat(immediate_parent)
            if (
                current_parent.st_dev,
                current_parent.st_ino,
            ) != parent_identity:
                raise ContractViolation(
                    "Task 9 temporary-root parent identity drifted"
                )
            return temp_root_fd, temp_root_identity
        except BaseException:
            os.close(temp_root_fd)
            raise
    finally:
        os.close(parent_fd)


def _task9_capture_runner_plan(
    runtime_receipt: Mapping[str, Any],
    stage: str,
) -> dict[str, Any]:
    if stage not in {"postcontrol", "pretheme"}:
        raise ContractViolation("Task 9 capture stage is invalid")
    destination = {
        "postcontrol": TIER0_DESTINATIONS[16].rstrip("/"),
        "pretheme": TIER0_DESTINATIONS[17].rstrip("/"),
    }[stage]
    plan = _capture_runner_plan_value(
        runtime_receipt,
        "posttheme",
        destination,
    )
    profile, phase, count = {
        "postcontrol": ("ux1b-selection-controls", "postcontrol", 36),
        "pretheme": ("ux1b-full-pages", "pretheme", 81),
    }[stage]
    plan.update(
        {
            "stage": stage,
            "expectedMode": profile,
            "expectedPhase": phase,
            "expectedCount": count,
        }
    )
    plan["execution"]["argv"] = [
        ".venv/bin/python",
        "scripts/ui_ux_snapshot_matrix.py",
        "--profile",
        profile,
        "--phase",
        phase,
        "--browser",
        "chromium",
        "--out-dir",
        destination,
        "--no-prompt",
        "--json",
    ]
    temp_parent = runtime_receipt["tempRootParent"]
    private = (
        f"{temp_parent}/{AUTHORIZED_RECOVERY_ID}/{stage}"
    )
    environment = plan["execution"]["environment"]
    environment.update(
        {
            "HOME": f"{private}/home",
            "TMPDIR": f"{private}/tmp",
            "TMP": f"{private}/tmp",
            "TEMP": f"{private}/tmp",
            "XDG_CACHE_HOME": f"{private}/cache",
            "XDG_CONFIG_HOME": f"{private}/config",
            "XDG_DATA_HOME": f"{private}/data",
        }
    )
    _validate_schema("CaptureRunnerPlan", plan)
    return plan


def _build_task9_production_context(
    workspace_fd: int,
    source_root_fd: int,
    preflight_relative: str,
    *,
    event: Literal["capture", "reconcile"],
) -> dict[str, Any]:
    if (
        event not in {"capture", "reconcile"}
        or preflight_relative != TIER0_DESTINATIONS[10]
        or type(workspace_fd) is not int
        or workspace_fd < 0
        or type(source_root_fd) is not int
        or source_root_fd < 0
    ):
        raise ContractViolation("Task 9 preflight binding differs")
    preflight = _read_relative_canonical_evidence(
        workspace_fd,
        preflight_relative,
    )
    _validate_preflight_complete(
        workspace_fd,
        preflight,
        source_root_fd=source_root_fd,
        destination_policy=(
            "fresh"
            if event == "capture"
            else "task9-active"
        ),
    )
    preflight_ref = _artifact_ref(
        _relative_file_record(workspace_fd, preflight_relative)
    )
    runtime_receipt = copy.deepcopy(preflight["runtimeReceipt"])
    source_projection = copy.deepcopy(preflight["sourceProjection"])
    capture_stack = copy.deepcopy(preflight["captureStack"])
    plans = [
        _task9_capture_runner_plan(runtime_receipt, "postcontrol"),
        _task9_capture_runner_plan(runtime_receipt, "pretheme"),
    ]
    destinations = [
        {"path": plan["destination"], "exists": False}
        for plan in plans
    ]
    common = {
        "recoveryId": AUTHORIZED_RECOVERY_ID,
        "runtimeReceipt": runtime_receipt,
    }
    templates = {
        "quant-radar-ui-ux-capture-intent/v1": {
            "schemaVersion": "quant-radar-ui-ux-capture-intent/v1",
            "status": "started",
            **common,
            "preflight": preflight_ref,
            "nonce": secrets.token_hex(16),
            "lease": copy.deepcopy(preflight["lease"]),
            "runnerPlans": copy.deepcopy(plans),
            "sourceProjection": source_projection,
            "captureStack": capture_stack,
            "destinations": destinations,
        },
        "quant-radar-ui-ux-capture-control-checkpoint/v1": {
            "schemaVersion":
                "quant-radar-ui-ux-capture-control-checkpoint/v1",
            "status": "passed",
            **common,
            "intent": None,
            "runnerReceipt": None,
            "bundle": None,
        },
        "quant-radar-ui-ux-capture-pretheme-gate/v1": {
            "schemaVersion":
                "quant-radar-ui-ux-capture-pretheme-gate/v1",
            "status": "passed",
            **common,
            "intent": None,
            "controlCheckpoint": None,
            "runnerPlan": copy.deepcopy(plans[1]),
            "sourceProjection": copy.deepcopy(source_projection),
            "captureStack": copy.deepcopy(capture_stack),
        },
        "quant-radar-ui-ux-capture-pretheme-checkpoint/v1": {
            "schemaVersion":
                "quant-radar-ui-ux-capture-pretheme-checkpoint/v1",
            "status": "passed",
            **common,
            "gate": None,
            "runnerReceipt": None,
            "bundle": None,
        },
        "quant-radar-ui-ux-capture-terminal/v1": {
            "schemaVersion": "quant-radar-ui-ux-capture-terminal/v1",
            "status": "passed",
            **common,
            "intent": None,
            "controlCheckpoint": None,
            "prethemeGate": None,
            "prethemeCheckpoint": None,
            "reason": None,
        },
    }
    _validate_schema(
        "quant-radar-ui-ux-capture-intent/v1",
        templates["quant-radar-ui-ux-capture-intent/v1"],
    )
    return {
        "preflight": preflight,
        "preflightRef": preflight_ref,
        "templates": templates,
        "plans": plans,
    }


def _scan_task9_capture_tree(
    workspace_fd: int,
    destination: str,
) -> dict[str, dict[str, Any]]:
    root_fd = _open_relative_directory_fd(workspace_fd, destination)
    records: dict[str, dict[str, Any]] = {}

    def walk(directory_fd: int, prefix: str, depth: int) -> None:
        if depth > 12:
            raise ContractViolation("Task 9 capture tree is too deep")
        try:
            names = sorted(os.listdir(directory_fd))
        except OSError as exc:
            raise ContractViolation(
                "Task 9 capture directory cannot be listed"
            ) from exc
        if len(names) > 1_024:
            raise ContractViolation(
                "Task 9 capture directory fanout is excessive"
            )
        for name in names:
            if (
                not isinstance(name, str)
                or not name
                or name in {".", ".."}
                or "/" in name
                or "\x00" in name
            ):
                raise ContractViolation(
                    "Task 9 capture tree name is unsafe"
                )
            relative = f"{prefix}/{name}" if prefix else name
            try:
                observed = os.stat(
                    name,
                    dir_fd=directory_fd,
                    follow_symlinks=False,
                )
            except OSError as exc:
                raise ContractViolation(
                    "Task 9 capture tree changed while scanning"
                ) from exc
            if stat.S_ISDIR(observed.st_mode):
                flags = (
                    os.O_RDONLY
                    | getattr(os, "O_DIRECTORY", 0)
                    | os.O_NOFOLLOW
                    | getattr(os, "O_CLOEXEC", 0)
                )
                child_fd = os.open(name, flags, dir_fd=directory_fd)
                try:
                    retained = os.fstat(child_fd)
                    if (
                        (retained.st_dev, retained.st_ino)
                        != (observed.st_dev, observed.st_ino)
                        or retained.st_uid != os.getuid()
                        or retained.st_gid != os.getgid()
                        or not _safe_directory_mode(
                            f"{stat.S_IMODE(retained.st_mode):04o}"
                        )
                    ):
                        raise ContractViolation(
                            "Task 9 capture directory identity differs"
                        )
                    walk(child_fd, relative, depth + 1)
                finally:
                    os.close(child_fd)
                continue
            if (
                not stat.S_ISREG(observed.st_mode)
                or observed.st_nlink != 1
                or observed.st_uid != os.getuid()
                or observed.st_gid != os.getgid()
            ):
                raise ContractViolation(
                    "Task 9 capture leaf metadata is unsafe"
                )
            flags = (
                os.O_RDONLY
                | os.O_NOFOLLOW
                | getattr(os, "O_CLOEXEC", 0)
            )
            leaf_fd = os.open(name, flags, dir_fd=directory_fd)
            try:
                retained = os.fstat(leaf_fd)
                if (
                    (retained.st_dev, retained.st_ino)
                    != (observed.st_dev, observed.st_ino)
                    or retained.st_size > 67_108_864
                    or stat.S_IMODE(retained.st_mode) != 0o600
                ):
                    raise ContractViolation(
                        "Task 9 capture leaf identity/size differs"
                    )
                digest = hashlib.sha256()
                total = 0
                while True:
                    chunk = os.read(leaf_fd, 1_048_576)
                    if not chunk:
                        break
                    total += len(chunk)
                    if total > 67_108_864:
                        raise ContractViolation(
                            "Task 9 capture leaf exceeded its limit"
                        )
                    digest.update(chunk)
                logical = f"{destination}/{relative}"
                records[relative] = {
                    "path": logical,
                    "sha256": digest.hexdigest(),
                    "size": total,
                    "mode": f"{stat.S_IMODE(retained.st_mode):04o}",
                    "uid": retained.st_uid,
                    "gid": retained.st_gid,
                    "device": retained.st_dev,
                    "inode": retained.st_ino,
                    "nlink": retained.st_nlink,
                }
            finally:
                os.close(leaf_fd)
            if len(records) > 163:
                raise ContractViolation(
                    "Task 9 capture namespace has excess leaves"
                )

    try:
        walk(root_fd, "", 0)
    finally:
        os.close(root_fd)
    return records


def _validate_task9_manifest_bundle(
    workspace_fd: int,
    plan: Mapping[str, Any],
    context: Mapping[str, Any],
) -> dict[str, Any]:
    stage = plan.get("stage")
    expected = {
        "postcontrol": (36, 72, 73),
        "pretheme": (81, 162, 163),
    }.get(stage)
    if expected is None:
        raise ContractViolation("Task 9 manifest stage is invalid")
    capture_count, artifact_count, leaf_count = expected
    destination = plan.get("destination")
    if not isinstance(destination, str):
        raise ContractViolation("Task 9 manifest destination is invalid")
    records = _scan_task9_capture_tree(workspace_fd, destination)
    if len(records) != leaf_count or "manifest.json" not in records:
        raise ContractViolation(
            "Task 9 capture namespace leaf count differs"
        )
    manifest_relative = f"{destination}/manifest.json"
    manifest_record, manifest_bytes = _relative_regular_record_and_bytes(
        workspace_fd,
        manifest_relative,
    )
    if (
        manifest_record != records["manifest.json"]
        or manifest_record["mode"] != "0600"
        or manifest_record["uid"] != os.getuid()
        or manifest_record["gid"] != os.getgid()
        or not manifest_bytes.endswith(b"\n")
        or manifest_bytes.endswith(b"\n\n")
    ):
        raise ContractViolation(
            "Task 9 capture manifest metadata/termination differs"
        )
    manifest = _strict_json_bytes(
        manifest_bytes[:-1],
        allow_float=True,
    )
    if not isinstance(manifest, dict):
        raise ContractViolation(
            "Task 9 capture manifest is not an object"
        )
    expected_keys = {
        "attestations",
        "captureStackContract",
        "captureStackDigest",
        "capturedCount",
        "captures",
        "childrenQuiescent",
        "expectedCaptureCount",
        "fixtureEntrypoint",
        "mode",
        "mutatorCounters",
        "network",
        "phase",
        "processes",
        "prohibitedCounters",
        "providerCounters",
        "runId",
        "schemaVersion",
        "sourceDigestEnd",
        "sourceDigestStart",
        "status",
    }
    source_digest = context["preflight"]["sourceProjection"]["digest"]
    stack = context["preflight"]["captureStack"]
    expected_fixture = {
        "postcontrol": "scripts/ui_ux_selection_fixture_app.py",
        "pretheme": "scripts/ui_ux_fixture_app.py",
    }[stage]
    run_id = manifest.get("runId")
    if (
        set(manifest) != expected_keys
        or manifest.get("schemaVersion")
        != "quant-radar-ui-ux-evidence/v1"
        or manifest.get("status") != "passed"
        or manifest.get("mode") != plan.get("expectedMode")
        or manifest.get("phase") != plan.get("expectedPhase")
        or manifest.get("expectedCaptureCount") != capture_count
        or manifest.get("capturedCount") != capture_count
        or manifest.get("childrenQuiescent") is not True
        or manifest.get("sourceDigestStart") != source_digest
        or manifest.get("sourceDigestEnd") != source_digest
        or manifest.get("captureStackDigest") != stack.get("digest")
        or manifest.get("captureStackContract")
        != {
            "path": stack["contract"]["path"],
            "sha256": stack["contract"]["sha256"],
        }
        or manifest.get("fixtureEntrypoint") != expected_fixture
        or not isinstance(run_id, str)
        or re.fullmatch(r"ux1b-[0-9a-f]{24}", run_id) is None
    ):
        raise ContractViolation(
            "Task 9 capture manifest lifecycle fields differ"
        )

    attestations = manifest.get("attestations")
    if (
        not isinstance(attestations, dict)
        or set(attestations)
        != {"calibrationSha256", "comparatorSha256"}
        or any(
            not isinstance(value, str)
            or re.fullmatch(r"[0-9a-f]{64}", value) is None
            for value in attestations.values()
        )
    ):
        raise ContractViolation(
            "Task 9 capture attestations differ"
        )
    network = manifest.get("network")
    if (
        not isinstance(network, dict)
        or set(network) != {"appOrigin", "appPort"}
        or type(network.get("appPort")) is not int
        or not 1 <= network["appPort"] <= 65_535
        or network.get("appOrigin")
        != f"http://127.0.0.1:{network['appPort']}"
    ):
        raise ContractViolation(
            "Task 9 capture network assignment differs"
        )

    def validate_counter_closure(
        value: Any,
        label: str,
        *,
        require_zero: bool,
    ) -> None:
        if (
            not isinstance(value, dict)
            or set(value) != {"expected", "actual"}
            or not isinstance(value.get("expected"), dict)
            or not isinstance(value.get("actual"), dict)
            or not value["expected"]
            or value["actual"] != value["expected"]
            or any(
                not isinstance(key, str)
                or not key
                or type(counter) is not int
                or counter < 0
                for counters in (
                    value["expected"],
                    value["actual"],
                )
                for key, counter in counters.items()
            )
            or (
                require_zero
                and any(value["actual"].values())
            )
        ):
            raise ContractViolation(
                f"Task 9 {label} counter closure differs"
            )

    validate_counter_closure(
        manifest.get("providerCounters"),
        "provider",
        require_zero=False,
    )
    validate_counter_closure(
        manifest.get("mutatorCounters"),
        "mutator",
        require_zero=True,
    )
    prohibited = manifest.get("prohibitedCounters")
    if (
        not isinstance(prohibited, dict)
        or set(prohibited)
        != {
            "network.outbound",
            "production.read",
            "production.write",
        }
        or any(
            type(value) is not int or value != 0
            for value in prohibited.values()
        )
    ):
        raise ContractViolation(
            "Task 9 prohibited counters differ"
        )

    captures = manifest.get("captures")
    if not isinstance(captures, list) or len(captures) != capture_count:
        raise ContractViolation("Task 9 capture rows differ")
    capture_ids = [
        row.get("id") for row in captures if isinstance(row, dict)
    ]
    if (
        len(capture_ids) != capture_count
        or capture_ids != sorted(capture_ids)
        or len(set(capture_ids)) != capture_count
        or any(
            not isinstance(capture_id, str)
            or not _is_safe_relative_path(capture_id)
            for capture_id in capture_ids
        )
    ):
        raise ContractViolation("Task 9 capture IDs differ")
    descriptor_paths: list[str] = []
    for row in captures:
        if (
            not isinstance(row, dict)
            or set(row) != {"id", "status", "artifacts"}
            or row.get("status") != "passed"
            or not isinstance(row.get("artifacts"), dict)
            or set(row["artifacts"]) != {"png", "renderSidecar"}
        ):
            raise ContractViolation("Task 9 capture row is not closed")
        capture_id = row["id"]
        png = row["artifacts"]["png"]
        sidecar = row["artifacts"]["renderSidecar"]
        if (
            not isinstance(png, dict)
            or set(png)
            != {"path", "sha256", "size", "width", "height"}
            or not isinstance(sidecar, dict)
            or set(sidecar)
            != {"path", "sha256", "size", "schemaVersion"}
            or png.get("path")
            != f"captures/{capture_id}/capture.png"
            or sidecar.get("path")
            != f"captures/{capture_id}/render.json"
            or sidecar.get("schemaVersion")
            != "quant-radar-ui-ux-render/v1"
            or any(
                type(png.get(key)) is not int or png[key] <= 0
                for key in ("width", "height")
            )
        ):
            raise ContractViolation(
                "Task 9 capture artifact descriptor differs"
            )
        for descriptor in (png, sidecar):
            relative = descriptor["path"]
            artifact = records.get(relative)
            if (
                artifact is None
                or descriptor.get("sha256") != artifact["sha256"]
                or descriptor.get("size") != artifact["size"]
            ):
                raise ContractViolation(
                    "Task 9 capture artifact bytes differ"
                )
            descriptor_paths.append(relative)
    if (
        len(descriptor_paths) != artifact_count
        or len(set(descriptor_paths)) != artifact_count
        or set(records) != {"manifest.json", *descriptor_paths}
    ):
        raise ContractViolation(
            "Task 9 capture artifact namespace differs"
        )

    processes = manifest.get("processes")
    process_keys = {
        "launchIdentitySha256",
        "processId",
        "quiescent",
        "returnCode",
        "role",
        "sessionId",
        "signal",
    }
    expected_app_process_id = {
        "postcontrol": "app/selection-controls",
        "pretheme": "app/full-pages",
    }[stage]

    def valid_process_row(
        value: Any,
        *,
        role: str,
        process_id: str,
    ) -> bool:
        return (
            isinstance(value, dict)
            and set(value) == process_keys
            and value.get("role") == role
            and value.get("processId") == process_id
            and value.get("sessionId") == run_id
            and isinstance(
                value.get("launchIdentitySha256"),
                str,
            )
            and re.fullmatch(
                r"[0-9a-f]{64}",
                value["launchIdentitySha256"],
            )
            is not None
            and value.get("quiescent") is True
            and type(value.get("returnCode")) is int
            and value["returnCode"] == 0
            and value.get("signal") is None
        )

    if (
        not isinstance(processes, dict)
        or set(processes) != {"app", "browsers", "attestationDigests"}
        or not valid_process_row(
            processes.get("app"),
            role="app",
            process_id=expected_app_process_id,
        )
        or not isinstance(processes.get("browsers"), dict)
        or list(processes["browsers"]) != capture_ids
        or not isinstance(processes.get("attestationDigests"), dict)
    ):
        raise ContractViolation("Task 9 inner process receipt differs")

    digests = processes["attestationDigests"]
    if (
        set(digests) != {"app", "browsers"}
        or not isinstance(digests.get("app"), str)
        or re.fullmatch(r"[0-9a-f]{64}", digests["app"]) is None
        or not isinstance(digests.get("browsers"), dict)
        or set(digests["browsers"]) != set(capture_ids)
    ):
        raise ContractViolation(
            "Task 9 inner process digest set differs"
        )
    for capture_id in capture_ids:
        row = processes["browsers"].get(capture_id)
        if (
            not valid_process_row(
                row,
                role="browser",
                process_id=capture_id,
            )
            or not isinstance(
                digests["browsers"].get(capture_id),
                str,
            )
            or re.fullmatch(
                r"[0-9a-f]{64}",
                digests["browsers"][capture_id],
            )
            is None
        ):
            raise ContractViolation(
                "Task 9 browser process receipt differs"
            )
    return {
        "manifest": manifest_record,
        "mode": plan["expectedMode"],
        "phase": plan["expectedPhase"],
        "expectedCaptureCount": capture_count,
        "capturedCount": capture_count,
        "artifactCount": artifact_count,
        "namespaceLeafCount": leaf_count,
        "captureIdsSha256": hashlib.sha256(
            _canonical_json_bytes(capture_ids)
        ).hexdigest(),
        "sourceDigest": source_digest,
        "captureStackDigest": stack["digest"],
    }


class _Task9ProductionDriver:
    def __init__(
        self,
        workspace_fd: int,
        source_root_fd: int,
        context: dict[str, Any],
    ) -> None:
        self.workspace_fd = workspace_fd
        self.source_root_fd = source_root_fd
        self.context = context
        self.calls: list[dict[str, Any]] = []
        self._private_epoch_identity: tuple[int, int] | None = None

    @staticmethod
    def _timestamp() -> str:
        return time.strftime(
            "%Y-%m-%dT%H:%M:%SZ",
            time.gmtime(),
        )

    @staticmethod
    def _kill_group(process_group_id: int) -> None:
        try:
            os.killpg(process_group_id, signal.SIGKILL)
        except ProcessLookupError:
            pass

    @staticmethod
    def _observe_outer_family(
        process_group_id: int,
        phase: str,
    ) -> dict[str, Any]:
        argv = [
            "/bin/ps",
            "eww",
            "-axo",
            "pid=,uid=,pgid=,stat=,xstat=,command=",
        ]
        environment = {
            "PATH": "/usr/bin:/bin:/usr/sbin:/sbin",
            "LANG": "C",
            "LC_ALL": "C",
        }
        observer = subprocess.Popen(
            argv,
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            close_fds=True,
            start_new_session=True,
            env=environment,
        )
        try:
            stdout, stderr = observer.communicate(timeout=2)
        except subprocess.TimeoutExpired as exc:
            _Task9ProductionDriver._kill_group(observer.pid)
            try:
                observer.wait(timeout=0.5)
            except subprocess.TimeoutExpired:
                pass
            raise ContractViolation(
                "Task 9 process observer timed out"
            ) from exc
        if (
            observer.returncode != 0
            or stderr != b""
            or len(stdout) > 4_194_304
            or observer.pid == process_group_id
        ):
            raise ContractViolation("Task 9 process observer failed")
        rows: list[dict[str, Any]] = []
        observer_seen = 0
        observed_pids: list[int] = []
        for raw_line in stdout.splitlines():
            fields = raw_line.split(maxsplit=5)
            if len(fields) != 6:
                raise ContractViolation(
                    "Task 9 process observer row is malformed"
                )
            try:
                pid = int(fields[0])
                uid = int(fields[1])
                pgid = int(fields[2])
                state = fields[3].decode("ascii", errors="strict")
                wait_status_text = fields[4].decode(
                    "ascii",
                    errors="strict",
                )
                wait_status = int(wait_status_text, 16)
            except (UnicodeDecodeError, ValueError) as exc:
                raise ContractViolation(
                    "Task 9 process observer field is malformed"
                ) from exc
            observed_pids.append(pid)
            if pid == observer.pid:
                observer_seen += 1
                if pgid != observer.pid:
                    raise ContractViolation(
                        "Task 9 observer group is not private"
                    )
                continue
            if (
                uid == os.getuid()
                and pgid == process_group_id
            ):
                rows.append(
                    {
                        "pid": pid,
                        "uid": uid,
                        "processGroupId": pgid,
                        "state": state,
                        "waitStatus": wait_status,
                        "markerMatch": False,
                    }
                )
        if (
            observer_seen != 1
            or len(observed_pids) != len(set(observed_pids))
        ):
            raise ContractViolation(
                "Task 9 process observer set differs"
            )
        rows.sort(key=lambda row: row["pid"])
        return {
            "phase": phase,
            "observerPid": observer.pid,
            "observerProcessGroupId": observer.pid,
            "rows": rows,
            "observerReturnCode": 0,
            "observerSignal": None,
            "stdoutSha256": hashlib.sha256(stdout).hexdigest(),
            "stderrSha256": hashlib.sha256(stderr).hexdigest(),
            "stdoutBytes": len(stdout),
            "stderrBytes": len(stderr),
            "runnerStdoutEof": True,
            "runnerStderrEof": True,
        }

    def reauthenticate(self) -> None:
        current = _read_relative_canonical_evidence(
            self.workspace_fd,
            TIER0_DESTINATIONS[10],
        )
        _validate_preflight_complete(
            self.workspace_fd,
            current,
            source_root_fd=self.source_root_fd,
            destination_policy="task9-active",
        )
        if (
            current != self.context["preflight"]
            or _artifact_ref(
                _relative_file_record(
                    self.workspace_fd,
                    TIER0_DESTINATIONS[10],
                )
            )
            != self.context["preflightRef"]
        ):
            raise ContractViolation(
                "Task 9 preflight authority drifted"
            )

    def _prepare_private_environment(
        self,
        temp_parent: Path,
        stage: str,
    ) -> None:
        if stage not in {"postcontrol", "pretheme"}:
            raise ContractViolation(
                "Task 9 private stage is invalid"
            )
        temp_root_fd, _ = _task9_open_temp_root(
            temp_parent,
            root_policy=(
                "initial"
                if stage == "postcontrol"
                else "active"
            ),
        )
        epoch_fd: int | None = None
        stage_fd: int | None = None
        try:
            if stage == "postcontrol":
                if self._private_epoch_identity is not None:
                    raise ContractViolation(
                        "Task 9 private epoch was already retained"
                    )
                epoch_fd, epoch_identity = (
                    _task9_create_directory_at(
                        temp_root_fd,
                        AUTHORIZED_RECOVERY_ID,
                    )
                )
                self._private_epoch_identity = epoch_identity
            else:
                if self._private_epoch_identity is None:
                    raise _Task9RunnerFailure(
                        EXIT_COLLISION,
                        "Task 9 private epoch is not retained",
                    )
                epoch_fd, _ = _task9_retain_directory_at(
                    temp_root_fd,
                    AUTHORIZED_RECOVERY_ID,
                    expected_identity=self._private_epoch_identity,
                )
            stage_fd, _ = _task9_create_directory_at(
                epoch_fd,
                stage,
            )
            for name in (
                "home",
                "tmp",
                "cache",
                "config",
                "data",
            ):
                child_fd, _ = _task9_create_directory_at(
                    stage_fd,
                    name,
                )
                os.close(child_fd)
        finally:
            if stage_fd is not None:
                os.close(stage_fd)
            if epoch_fd is not None:
                os.close(epoch_fd)
            os.close(temp_root_fd)

    def validate_bundle(
        self,
        plan: Mapping[str, Any],
    ) -> dict[str, Any]:
        return _validate_task9_manifest_bundle(
            self.workspace_fd,
            plan,
            self.context,
        )

    def _execute(
        self,
        plan: Mapping[str, Any],
        lease_fd: int,
    ) -> dict[str, Any]:
        execution = plan.get("execution")
        if (
            not isinstance(execution, dict)
            or execution.get("cwd") != "."
            or execution.get("stdin") != "devnull"
            or execution.get("processGroup") != "new"
            or execution.get("passFds") != ["lease"]
            or execution.get("timeoutSeconds") != 14_400
            or execution.get("stdoutLimitBytes") != 67_108_864
            or execution.get("stderrLimitBytes") != 67_108_864
            or execution.get("processFamily", {}).get("kind")
            != "outer_pgid"
        ):
            raise ContractViolation(
                "Task 9 execution plan differs"
            )
        argv = execution.get("argv")
        environment = execution.get("environment")
        if (
            not isinstance(argv, list)
            or any(not isinstance(item, str) for item in argv)
            or not isinstance(environment, dict)
            or any(
                not isinstance(key, str)
                or not isinstance(value, str)
                for key, value in environment.items()
            )
        ):
            raise ContractViolation(
                "Task 9 execution arguments differ"
            )
        private = Path(environment["HOME"]).parent
        temp_parent = Path(
            self.context["preflight"]["runtimeReceipt"][
                "tempRootParent"
            ]
        )
        expected_private = (
            temp_parent
            / AUTHORIZED_RECOVERY_ID
            / plan["stage"]
        )
        expected_environment = {
            "HOME": str(expected_private / "home"),
            "TMPDIR": str(expected_private / "tmp"),
            "TMP": str(expected_private / "tmp"),
            "TEMP": str(expected_private / "tmp"),
            "XDG_CACHE_HOME": str(expected_private / "cache"),
            "XDG_CONFIG_HOME": str(expected_private / "config"),
            "XDG_DATA_HOME": str(expected_private / "data"),
        }
        if (
            private != expected_private
            or any(
                environment.get(key) != value
                for key, value in expected_environment.items()
            )
        ):
            raise ContractViolation(
                "Task 9 private environment binding differs"
            )
        self._prepare_private_environment(
            temp_parent,
            plan["stage"],
        )
        started_at = self._timestamp()
        try:
            process = subprocess.Popen(
                list(argv),
                cwd=SOURCE_WORKSPACE_ROOT,
                env=dict(environment),
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                pass_fds=(lease_fd,),
                close_fds=True,
                start_new_session=True,
            )
        except OSError as exc:
            raise _Task9RunnerFailure(
                EXIT_UNAVAILABLE,
                "Task 9 runner could not start",
            ) from exc
        if process.stdout is None or process.stderr is None:
            self._kill_group(process.pid)
            process.wait()
            raise _Task9RunnerFailure(
                EXIT_UNAVAILABLE,
                "Task 9 runner streams are unavailable",
            )
        streams = {
            process.stdout.fileno(): ("stdout", process.stdout),
            process.stderr.fileno(): ("stderr", process.stderr),
        }
        buffers = {"stdout": bytearray(), "stderr": bytearray()}
        selector = selectors.DefaultSelector()
        deadline = time.monotonic() + execution["timeoutSeconds"]
        outcome: str | None = None
        try:
            for fd in streams:
                os.set_blocking(fd, False)
                selector.register(fd, selectors.EVENT_READ)
            while streams:
                now = time.monotonic()
                if now >= deadline:
                    outcome = "timed_out"
                    break
                for key, _ in selector.select(
                    min(0.05, max(0.0, deadline - now))
                ):
                    fd = key.fd
                    role, stream = streams[fd]
                    try:
                        chunk = os.read(fd, 65_536)
                    except BlockingIOError:
                        continue
                    if not chunk:
                        selector.unregister(fd)
                        stream.close()
                        del streams[fd]
                        continue
                    limit = execution[
                        f"{role}LimitBytes"
                    ]
                    retained = max(
                        0,
                        limit + 1 - len(buffers[role]),
                    )
                    buffers[role].extend(chunk[:retained])
                    if len(buffers[role]) > limit:
                        outcome = "output_overflow"
                        break
                if outcome is not None:
                    break
        except KeyboardInterrupt as exc:
            self._kill_group(process.pid)
            process.wait()
            raise _Task9RunnerFailure(
                EXIT_INTERRUPTED,
                "Task 9 runner was interrupted",
            ) from exc
        except BaseException:
            self._kill_group(process.pid)
            process.wait()
            raise
        finally:
            selector.close()
            for _role, stream in streams.values():
                if not stream.closed:
                    stream.close()
        if outcome is not None:
            self._kill_group(process.pid)
            process.wait()
            raise _Task9RunnerFailure(
                EXIT_MANUAL,
                f"Task 9 runner {outcome}",
            )

        quiescence_deadline = time.monotonic() + 25
        pre_reap: dict[str, Any] | None = None
        while time.monotonic() < quiescence_deadline:
            sample = self._observe_outer_family(
                process.pid,
                "pre_reap",
            )
            leader_rows = [
                row
                for row in sample["rows"]
                if row["pid"] == process.pid
            ]
            if (
                len(sample["rows"]) == 1
                and len(leader_rows) == 1
                and leader_rows[0]["state"].startswith("Z")
                and leader_rows[0]["processGroupId"]
                == process.pid
            ):
                pre_reap = sample
                break
            time.sleep(0.05)
        if pre_reap is None:
            self._kill_group(process.pid)
            process.wait()
            raise _Task9RunnerFailure(
                EXIT_MANUAL,
                "Task 9 outer process family did not quiesce",
            )
        waited_pid, wait_status = os.waitpid(process.pid, 0)
        if waited_pid != process.pid:
            raise ContractViolation("Task 9 reaped the wrong runner")
        process.returncode = os.waitstatus_to_exitcode(wait_status)
        raw_return_code = process.returncode
        return_code = (
            raw_return_code if raw_return_code >= 0 else None
        )
        signal_number = (
            -raw_return_code if raw_return_code < 0 else None
        )
        post_reap = self._observe_outer_family(
            process.pid,
            "post_reap",
        )
        if post_reap["rows"] != []:
            raise _Task9RunnerFailure(
                EXIT_MANUAL,
                "Task 9 outer family remained after reap",
            )
        process_family = (
            _CandidateRegressionProcessDriver._family_receipt(
                process_family_plan=copy.deepcopy(
                    execution["processFamily"]
                ),
                process_group_id=process.pid,
                exit_watch_result={
                    "registration": "esrch",
                    "outcome": "owned_zombie",
                    "eventCount": 0,
                },
                samples=(pre_reap, post_reap),
                return_code=return_code,
                signal_number=signal_number,
                wait_status=wait_status,
            )
        )
        return {
            "startedAt": started_at,
            "finishedAt": self._timestamp(),
            "returnCode": return_code,
            "signal": signal_number,
            "stdout": bytes(buffers["stdout"]),
            "stderr": bytes(buffers["stderr"]),
            "processGroupId": process.pid,
            "processFamily": process_family,
        }

    def run_capture(
        self,
        plan: dict[str, Any],
        *,
        lease_fd: int,
    ) -> dict[str, Any]:
        expected_by_stage = {
            item["stage"]: item for item in self.context["plans"]
        }
        stage = plan.get("stage")
        if (
            stage not in expected_by_stage
            or plan != expected_by_stage[stage]
            or any(call["stage"] == stage for call in self.calls)
        ):
            raise ContractViolation(
                "Task 9 runner plan was reused or drifted"
            )
        lease = os.fstat(lease_fd)
        current = _relative_file_record(
            self.workspace_fd,
            TIER0_DESTINATIONS[3],
        )
        if (
            (lease.st_dev, lease.st_ino)
            != (current["device"], current["inode"])
        ):
            raise ContractViolation(
                "Task 9 inherited lease identity differs"
            )
        self.calls.append(
            {
                "stage": stage,
                "argv": list(plan["execution"]["argv"]),
            }
        )
        execution = self._execute(plan, lease_fd)
        if (
            execution["returnCode"] != 0
            or execution["signal"] is not None
            or execution["stderr"] != b""
        ):
            raise _Task9RunnerFailure(
                EXIT_MANUAL,
                "Task 9 runner did not exit cleanly",
            )
        stdout = execution["stdout"]
        lines = stdout.splitlines()
        if len(lines) != 1:
            raise _Task9RunnerFailure(
                EXIT_MANUAL,
                "Task 9 runner summary is not one JSON line",
            )
        def closed_object(
            pairs: list[tuple[str, Any]],
        ) -> dict[str, Any]:
            value: dict[str, Any] = {}
            for key, item in pairs:
                if key in value:
                    raise ContractViolation(
                        "Task 9 runner summary has a duplicate key"
                    )
                value[key] = item
            return value
        try:
            summary = json.loads(
                lines[0].decode("utf-8", errors="strict"),
                object_pairs_hook=closed_object,
                parse_constant=lambda _value: (
                    (_ for _ in ()).throw(
                        ContractViolation(
                            "Task 9 runner summary has a non-finite value"
                        )
                    )
                ),
            )
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise _Task9RunnerFailure(
                EXIT_MANUAL,
                "Task 9 runner summary is invalid JSON",
            ) from exc
        if (
            not isinstance(summary, dict)
            or stdout
            != (
                json.dumps(
                    summary,
                    ensure_ascii=False,
                    sort_keys=True,
                ).encode("utf-8")
                + b"\n"
            )
            or set(summary)
            != {
                "status",
                "run",
                "captures",
                "browserCapabilities",
                "manual",
            }
            or summary.get("status") != "passed"
            or summary.get("captures")
            != {
                "total": plan["expectedCount"],
                "passed": plan["expectedCount"],
            }
        ):
            raise _Task9RunnerFailure(
                EXIT_MANUAL,
                "Task 9 runner summary differs",
            )
        bundle = _validate_task9_manifest_bundle(
            self.workspace_fd,
            plan,
            self.context,
        )
        runner_receipt = {
            "plan": copy.deepcopy(plan),
            "outcome": "exited",
            "processGroupId": execution["processGroupId"],
            "startedAt": execution["startedAt"],
            "finishedAt": execution["finishedAt"],
            "returnCode": execution["returnCode"],
            "signal": execution["signal"],
            "stdoutSha256": hashlib.sha256(stdout).hexdigest(),
            "stdoutBytes": len(stdout),
            "stderrSha256": hashlib.sha256(
                execution["stderr"]
            ).hexdigest(),
            "stderrBytes": len(execution["stderr"]),
            "processFamily": execution["processFamily"],
        }
        _validate_schema("RunnerReceipt", runner_receipt)
        return {
            "runnerReceipt": runner_receipt,
            "bundle": bundle,
        }


def _task9_transition(
    workspace_fd: int,
    recovery_id: str,
    event: str,
    *,
    driver: Any | None = None,
    fault_after: str | None = None,
) -> dict[str, Any]:
    if recovery_id != AUTHORIZED_RECOVERY_ID or event not in {"capture", "reconcile"}:
        raise ContractViolation("Task 9 transition grammar mismatch")
    if type(workspace_fd) is not int or workspace_fd < 0:
        raise ContractViolation("Task 9 workspace descriptor is invalid")
    workspace_stat = os.fstat(workspace_fd)
    named = os.lstat(WORKSPACE_ROOT)
    if not stat.S_ISDIR(workspace_stat.st_mode) or (workspace_stat.st_dev, workspace_stat.st_ino) != (
        named.st_dev,
        named.st_ino,
    ):
        raise ContractViolation("Task 9 workspace binding mismatch")
    boundaries = {
        "intent-precommit", "intent-postcommit", "control-launch", "control-receipt",
        "control-checkpoint", "pretheme-gate", "pretheme-launch", "pretheme-receipt",
        "pretheme-checkpoint", "terminal",
    }
    if fault_after is not None and fault_after not in boundaries:
        raise ContractViolation("unknown Task 9 fault boundary")
    if driver is None or not hasattr(driver, "context") or not hasattr(driver, "run_capture"):
        raise ContractViolation("Task 9 transition requires an authenticated runner driver")

    direct_destinations = [
        TIER0_DESTINATIONS[16].rstrip("/"),
        TIER0_DESTINATIONS[17].rstrip("/"),
    ]
    any_lifecycle = any(
        _relative_leaf_lstat(workspace_fd, relative) is not None
        for relative, _ in TASK9_LIFECYCLE
    )
    any_direct_output = any(
        _relative_leaf_lstat(workspace_fd, relative) is not None
        for relative in direct_destinations
    )
    if event == "capture" and (any_lifecycle or any_direct_output):
        return {
            "exitCode": EXIT_EXHAUSTED,
            "freshGrant": False,
            "launched": False,
            "publishedRoot": False,
        }

    lease_fd: int | None = None
    global_lock_fd = _open_relative_leaf_fd(
        workspace_fd,
        TIER0_DESTINATIONS[2],
        os.O_RDWR | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
    )
    try:
        try:
            fcntl.flock(
                global_lock_fd,
                fcntl.LOCK_EX | fcntl.LOCK_NB,
            )
        except BlockingIOError:
            return {"exitCode": EXIT_BUSY, "launched": False, "published": False}
        global_lock_record = _relative_file_record(
            workspace_fd,
            TIER0_DESTINATIONS[2],
        )
        if (
            global_lock_record["mode"] != "0600"
            or global_lock_record["uid"] != os.getuid()
            or global_lock_record["gid"] != os.getgid()
            or global_lock_record["nlink"] != 1
            or global_lock_record["size"] != 0
        ):
            raise ContractViolation("Task 9 global lock metadata differs")
        lease_fd = _open_relative_leaf_fd(
            workspace_fd,
            TIER0_DESTINATIONS[3],
            os.O_RDWR | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
        )
        try:
            fcntl.flock(
                lease_fd,
                fcntl.LOCK_EX | fcntl.LOCK_NB,
            )
        except BlockingIOError:
            return {
                "exitCode": EXIT_BUSY,
                "launched": False,
                "published": False,
            }
        lease_record = _relative_file_record(
            workspace_fd,
            TIER0_DESTINATIONS[3],
        )
        if (
            lease_record["mode"] != "0600"
            or lease_record["uid"] != os.getuid()
            or lease_record["gid"] != os.getgid()
            or lease_record["nlink"] != 1
            or lease_record["size"] != 0
        ):
            raise ContractViolation("Task 9 lease metadata differs")
        templates = driver.context.get("templates")
        plans = driver.context.get("plans")
        if not isinstance(templates, dict) or not isinstance(plans, list) or len(plans) != 2:
            raise ContractViolation("Task 9 driver context is not closed")

        def publish(index: int, value: dict[str, Any]) -> dict[str, Any]:
            relative, schema_name = TASK9_LIFECYCLE[index]
            if value.get("schemaVersion") != schema_name:
                raise ContractViolation("Task 9 publication schema mismatch")
            encoded = _canonical_json_bytes(value)
            parent_fd, name = _open_relative_parent_fd(
                workspace_fd,
                relative,
            )
            try:
                result = _publish_regular_exact(
                    parent_fd,
                    name,
                    encoded,
                )
                if (
                    result.get("exitCode") != EXIT_SUCCESS
                    or result.get("created") is not True
                    or result.get("reconciled") is not False
                ):
                    exit_code = result.get("exitCode")
                    if exit_code == EXIT_COLLISION:
                        raise NamespaceCollision(
                            "Task 9 lifecycle destination collision"
                        )
                    if exit_code in {
                        EXIT_UNAVAILABLE,
                        EXIT_UNCERTAIN,
                    }:
                        raise _Task9RunnerFailure(
                            exit_code,
                            "Task 9 lifecycle publication did not complete",
                        )
                    raise ContractViolation(
                        "Task 9 lifecycle publication was not fresh"
                    )
                _require_relative_parent_current(
                    workspace_fd,
                    relative,
                    parent_fd,
                )
            finally:
                os.close(parent_fd)
            reopened = _read_relative_canonical_evidence(
                workspace_fd,
                relative,
            )
            _validate_schema(schema_name, reopened)
            if reopened != value:
                raise ContractViolation("Task 9 publication reopen mismatch")
            return _artifact_ref(
                _relative_file_record(workspace_fd, relative)
            )

        def read_chain() -> tuple[list[dict[str, Any] | None], bool]:
            values: list[dict[str, Any] | None] = []
            seen_gap = False
            valid = True
            for relative, schema_name in TASK9_LIFECYCLE:
                if _relative_leaf_lstat(workspace_fd, relative) is None:
                    seen_gap = True
                    values.append(None)
                    continue
                if seen_gap:
                    valid = False
                try:
                    item = _read_relative_canonical_evidence(
                        workspace_fd,
                        relative,
                    )
                    _validate_schema(schema_name, item)
                except ContractViolation:
                    valid = False
                    item = None
                values.append(item)
            return values, valid

        def refs_for(values: Sequence[dict[str, Any] | None]) -> list[dict[str, Any] | None]:
            refs: list[dict[str, Any] | None] = []
            for (relative, _), value in zip(TASK9_LIFECYCLE, values):
                refs.append(
                    _artifact_ref(
                        _relative_file_record(workspace_fd, relative)
                    )
                    if value is not None
                    else None
                )
            return refs

        def validate_chain(values: Sequence[dict[str, Any] | None]) -> bool:
            refs = refs_for(values)
            if values[0] is not None:
                intent = values[0]
                intent_template = templates[
                    "quant-radar-ui-ux-capture-intent/v1"
                ]
                if (
                    intent.get("preflight")
                    != driver.context.get("preflightRef")
                    or intent.get("lease") != lease_record
                    or intent.get("runnerPlans") != plans
                    or intent.get("sourceProjection")
                    != intent_template.get("sourceProjection")
                    or intent.get("captureStack")
                    != intent_template.get("captureStack")
                    or intent.get("runtimeReceipt")
                    != intent_template.get("runtimeReceipt")
                    or intent.get("destinations")
                    != intent_template.get("destinations")
                    or not isinstance(intent.get("nonce"), str)
                    or NONCE_PATTERN.fullmatch(intent["nonce"]) is None
                ):
                    return False
            if values[1] is not None:
                control = values[1]
                if (
                    control.get("intent") != refs[0]
                    or control.get("runnerReceipt", {}).get("plan")
                    != plans[0]
                    or control.get("runnerReceipt", {})
                    .get("processFamily", {})
                    .get("quiescent")
                    is not True
                    or control.get("runtimeReceipt")
                    != templates[
                        "quant-radar-ui-ux-capture-control-checkpoint/v1"
                    ].get("runtimeReceipt")
                ):
                    return False
            if values[2] is not None:
                gate = values[2]
                gate_template = templates[
                    "quant-radar-ui-ux-capture-pretheme-gate/v1"
                ]
                if (
                    gate.get("intent") != refs[0]
                    or gate.get("controlCheckpoint") != refs[1]
                    or gate.get("runnerPlan") != plans[1]
                    or gate.get("sourceProjection")
                    != gate_template.get("sourceProjection")
                    or gate.get("captureStack")
                    != gate_template.get("captureStack")
                    or gate.get("runtimeReceipt")
                    != gate_template.get("runtimeReceipt")
                ):
                    return False
            if values[3] is not None:
                checkpoint = values[3]
                if (
                    checkpoint.get("gate") != refs[2]
                    or checkpoint.get("runnerReceipt", {}).get("plan")
                    != plans[1]
                    or checkpoint.get("runnerReceipt", {})
                    .get("processFamily", {})
                    .get("quiescent")
                    is not True
                    or checkpoint.get("runtimeReceipt")
                    != templates[
                        "quant-radar-ui-ux-capture-pretheme-checkpoint/v1"
                    ].get("runtimeReceipt")
                ):
                    return False
            if values[4] is not None:
                terminal = values[4]
                expected_refs = refs[:4]
                if (
                    [
                        terminal.get(key)
                        for key in (
                            "intent",
                            "controlCheckpoint",
                            "prethemeGate",
                            "prethemeCheckpoint",
                        )
                    ]
                    != expected_refs
                    or terminal.get("runtimeReceipt")
                    != templates[
                        "quant-radar-ui-ux-capture-terminal/v1"
                    ].get("runtimeReceipt")
                ):
                    return False
            validate_bundle = getattr(driver, "validate_bundle", None)
            if validate_bundle is not None:
                if not callable(validate_bundle):
                    return False
                if (
                    values[1] is not None
                    and values[1].get("bundle")
                    != validate_bundle(plans[0])
                ):
                    return False
                if (
                    values[3] is not None
                    and values[3].get("bundle")
                    != validate_bundle(plans[1])
                ):
                    return False
            return True

        def reauthenticate_authority() -> None:
            reauthenticate = getattr(
                driver,
                "reauthenticate",
                None,
            )
            if reauthenticate is None:
                return
            if not callable(reauthenticate):
                raise ContractViolation(
                    "Task 9 authority refresh hook is invalid"
                )
            reauthenticate()

        def terminalize_runner_failure(
            failure: _Task9RunnerFailure,
            *,
            intent_ref: Mapping[str, Any],
            control_ref: Mapping[str, Any] | None,
            gate_ref: Mapping[str, Any] | None,
            reason: str,
        ) -> dict[str, Any]:
            terminal = copy.deepcopy(
                templates[
                    "quant-radar-ui-ux-capture-terminal/v1"
                ]
            )
            terminal.update(
                {
                    "status": "revoked",
                    "intent": dict(intent_ref),
                    "controlCheckpoint": (
                        None
                        if control_ref is None
                        else dict(control_ref)
                    ),
                    "prethemeGate": (
                        None
                        if gate_ref is None
                        else dict(gate_ref)
                    ),
                    "prethemeCheckpoint": None,
                    "reason": reason,
                }
            )
            publish(4, terminal)
            return {
                "exitCode": failure.exit_code,
                "status": "revoked",
                "launched": True,
                "published": True,
            }

        if event == "reconcile":
            values, contiguous = read_chain()
            if not contiguous or not validate_chain(values):
                return {
                    "exitCode": EXIT_CONTRACT,
                    "status": "invalid",
                    "launched": False,
                    "published": False,
                }
            prefix = 0
            for value in values:
                if value is None:
                    break
                prefix += 1
            if (
                prefix == 3
                and _relative_leaf_lstat(
                    workspace_fd,
                    direct_destinations[1],
                )
                is not None
                and not any(call.get("stage") == "pretheme" for call in getattr(driver, "calls", ()) if isinstance(call, dict))
            ):
                return {
                    "exitCode": EXIT_CONTRACT,
                    "status": "invalid",
                    "launched": False,
                    "published": False,
                }
            if prefix == 5:
                terminal = values[4]
                assert terminal is not None
                return {
                    "exitCode": EXIT_SUCCESS if terminal["status"] == "passed" else EXIT_EXHAUSTED,
                    "status": terminal["status"],
                    "launched": False,
                    "published": False,
                }
            if prefix == 0 or prefix > 4:
                return {
                    "exitCode": EXIT_CONTRACT,
                    "status": "invalid",
                    "launched": False,
                    "published": False,
                }
            refs = refs_for(values)
            terminal = copy.deepcopy(templates["quant-radar-ui-ux-capture-terminal/v1"])
            if prefix == 4:
                terminal.update(
                    {
                        "status": "passed",
                        "intent": refs[0],
                        "controlCheckpoint": refs[1],
                        "prethemeGate": refs[2],
                        "prethemeCheckpoint": refs[3],
                        "reason": None,
                    }
                )
                publish(4, terminal)
                return {"exitCode": EXIT_SUCCESS, "status": "passed", "launched": False, "published": True}
            terminal.update(
                {
                    "status": "revoked",
                    "intent": refs[0],
                    "controlCheckpoint": refs[1] if prefix >= 2 else None,
                    "prethemeGate": refs[2] if prefix >= 3 else None,
                    "prethemeCheckpoint": None,
                    "reason": {
                        1: "control_nested_quiescence_unverified",
                        2: "intent_owner_lost",
                        3: "pretheme_nested_quiescence_unverified",
                    }[prefix],
                }
            )
            publish(4, terminal)
            return {"exitCode": EXIT_EXHAUSTED, "status": "revoked", "launched": False, "published": True}

        if fault_after == "intent-precommit":
            return {"exitCode": EXIT_UNCERTAIN, "freshGrant": True, "launched": False, "publishedRoot": False}
        reauthenticate_authority()
        intent = copy.deepcopy(templates["quant-radar-ui-ux-capture-intent/v1"])
        intent.update(
            {
                "preflight": driver.context["preflightRef"],
                "lease": lease_record,
                "runnerPlans": copy.deepcopy(plans),
            }
        )
        intent_ref = publish(0, intent)
        if fault_after == "intent-postcommit":
            return {"exitCode": EXIT_UNCERTAIN, "freshGrant": True, "launched": False, "publishedRoot": False}
        if fault_after == "control-launch":
            return {"exitCode": EXIT_UNCERTAIN, "freshGrant": True, "launched": False, "publishedRoot": False}
        try:
            control_output = driver.run_capture(
                copy.deepcopy(plans[0]),
                lease_fd=lease_fd,
            )
        except _Task9RunnerFailure as exc:
            return terminalize_runner_failure(
                exc,
                intent_ref=intent_ref,
                control_ref=None,
                gate_ref=None,
                reason=(
                    "control_nested_quiescence_unverified"
                ),
            )
        if fault_after == "control-receipt":
            return {"exitCode": EXIT_UNCERTAIN, "freshGrant": True, "launched": True, "publishedRoot": False}
        control = copy.deepcopy(templates["quant-radar-ui-ux-capture-control-checkpoint/v1"])
        control.update({"intent": intent_ref, **control_output})
        control_ref = publish(1, control)
        if fault_after == "control-checkpoint":
            return {"exitCode": EXIT_UNCERTAIN, "freshGrant": True, "launched": True, "publishedRoot": False}
        reauthenticate_authority()
        gate = copy.deepcopy(templates["quant-radar-ui-ux-capture-pretheme-gate/v1"])
        gate.update(
            {
                "intent": intent_ref,
                "controlCheckpoint": control_ref,
                "runnerPlan": copy.deepcopy(plans[1]),
            }
        )
        gate_ref = publish(2, gate)
        if fault_after == "pretheme-gate":
            return {"exitCode": EXIT_UNCERTAIN, "freshGrant": True, "launched": True, "publishedRoot": False}
        if fault_after == "pretheme-launch":
            return {"exitCode": EXIT_UNCERTAIN, "freshGrant": True, "launched": True, "publishedRoot": False}
        try:
            pretheme_output = driver.run_capture(
                copy.deepcopy(plans[1]),
                lease_fd=lease_fd,
            )
        except _Task9RunnerFailure as exc:
            return terminalize_runner_failure(
                exc,
                intent_ref=intent_ref,
                control_ref=control_ref,
                gate_ref=gate_ref,
                reason=(
                    "pretheme_nested_quiescence_unverified"
                ),
            )
        if fault_after == "pretheme-receipt":
            return {"exitCode": EXIT_UNCERTAIN, "freshGrant": True, "launched": True, "publishedRoot": False}
        checkpoint = copy.deepcopy(templates["quant-radar-ui-ux-capture-pretheme-checkpoint/v1"])
        checkpoint.update({"gate": gate_ref, **pretheme_output})
        checkpoint_ref = publish(3, checkpoint)
        if fault_after == "pretheme-checkpoint":
            return {"exitCode": EXIT_UNCERTAIN, "freshGrant": True, "launched": True, "publishedRoot": False}
        complete_prefix, contiguous = read_chain()
        if (
            not contiguous
            or tuple(item is not None for item in complete_prefix)
            != (True, True, True, True, False)
            or not validate_chain(complete_prefix)
        ):
            raise ContractViolation(
                "Task 9 complete preterminal chain differs"
            )
        terminal = copy.deepcopy(templates["quant-radar-ui-ux-capture-terminal/v1"])
        terminal.update(
            {
                "status": "passed",
                "intent": intent_ref,
                "controlCheckpoint": control_ref,
                "prethemeGate": gate_ref,
                "prethemeCheckpoint": checkpoint_ref,
                "reason": None,
            }
        )
        publish(4, terminal)
        if fault_after == "terminal":
            return {"exitCode": EXIT_UNCERTAIN, "freshGrant": True, "launched": True, "publishedRoot": False}
        terminal_chain, contiguous = read_chain()
        if (
            not contiguous
            or not all(item is not None for item in terminal_chain)
            or not validate_chain(terminal_chain)
            or terminal_chain[4].get("status") != "passed"
        ):
            raise ContractViolation(
                "Task 9 terminal chain reopen differs"
            )
        return {
            "exitCode": EXIT_SUCCESS,
            "status": "passed",
            "freshGrant": True,
            "launched": True,
            "publishedRoot": False,
        }
    finally:
        if lease_fd is not None:
            try:
                fcntl.flock(lease_fd, fcntl.LOCK_UN)
            finally:
                os.close(lease_fd)
        try:
            fcntl.flock(global_lock_fd, fcntl.LOCK_UN)
        finally:
            os.close(global_lock_fd)


def _validate_artifact_ref_value(value: Any, label: str) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != {"path", "sha256", "size"}:
        raise ContractViolation(f"{label} keys are not closed")
    if not isinstance(value["path"], str) or not _is_safe_relative_path(value["path"]):
        raise ContractViolation(f"{label} path is unsafe")
    if not isinstance(value["sha256"], str) or re.fullmatch(r"[0-9a-f]{64}", value["sha256"]) is None:
        raise ContractViolation(f"{label} digest is invalid")
    if type(value["size"]) is not int or value["size"] < 0:
        raise ContractViolation(f"{label} size is invalid")
    return value


def _validate_content_ref_value(value: Any, label: str) -> dict[str, Any]:
    if not isinstance(value, dict) or set(value) != {"path", "sha256", "size", "mode"}:
        raise ContractViolation(f"{label} keys are not closed")
    _validate_artifact_ref_value(
        {key: value[key] for key in ("path", "sha256", "size")},
        label,
    )
    if not isinstance(value["mode"], str) or re.fullmatch(r"0[0-7]{3}", value["mode"]) is None:
        raise ContractViolation(f"{label} mode is invalid")
    return value


def _validate_review_dimensions(value: Any) -> None:
    if (
        not isinstance(value, dict)
        or set(value) != {"width", "height"}
        or type(value["width"]) is not int
        or type(value["height"]) is not int
        or value["width"] <= 0
        or value["height"] <= 0
    ):
        raise ContractViolation("review item dimensions are invalid")


def _read_fd_exact(fd: int, expected_size: int) -> bytes:
    if type(expected_size) is not int or expected_size < 0 or expected_size > 16_777_216:
        raise ContractViolation("retained review input size is invalid")
    original = os.lseek(fd, 0, os.SEEK_CUR)
    try:
        os.lseek(fd, 0, os.SEEK_SET)
        chunks: list[bytes] = []
        total = 0
        while total <= expected_size:
            chunk = os.read(fd, min(131_072, expected_size + 1 - total))
            if not chunk:
                break
            chunks.append(chunk)
            total += len(chunk)
        data = b"".join(chunks)
    finally:
        os.lseek(fd, original, os.SEEK_SET)
    if len(data) != expected_size:
        raise ContractViolation("retained review input size mismatch")
    return data


def _review_paths(
    kind: str,
    root_sha256: str | None,
    lineage_id: str,
) -> tuple[str, str, str]:
    if kind == "control-migration":
        if root_sha256 is not None or lineage_id != AUTHORIZED_RECOVERY_ID:
            raise ContractViolation("control-migration review path authority mismatch")
        return (
            f".claude/ui_snapshots/ux1b/recovery/control-migration-review-packet-{lineage_id}.json",
            f".claude/ui_snapshots/ux1b/review-intake/control-migration-{lineage_id}.json",
            f".claude/ui_snapshots/ux1b/recovery/control-migration-manual-review-{lineage_id}.json",
        )
    if not isinstance(root_sha256, str) or re.fullmatch(r"[0-9a-f]{64}", root_sha256) is None:
        raise ContractViolation("review root digest is invalid")
    if kind == "theme-batch":
        return (
            f".claude/ui_snapshots/ux1b/theme-batches/{root_sha256}/{lineage_id}/review-packet.json",
            f".claude/ui_snapshots/ux1b/review-intake/theme-batch-{root_sha256}-{lineage_id}.json",
            f".claude/ui_snapshots/ux1b/theme-batches/{root_sha256}/{lineage_id}/review.json",
        )
    if kind == "theme-states":
        return (
            f".claude/ui_snapshots/ux1b/review-packet-theme-states-{lineage_id}.json",
            f".claude/ui_snapshots/ux1b/review-intake/theme-states-{lineage_id}.json",
            f".claude/ui_snapshots/ux1b/theme-state-manual-review-{lineage_id}.json",
        )
    if kind == "posttheme":
        return (
            f".claude/ui_snapshots/ux1b/review-packet-posttheme-{lineage_id}.json",
            f".claude/ui_snapshots/ux1b/review-intake/posttheme-{lineage_id}.json",
            f".claude/ui_snapshots/ux1b/theme-delta-manual-review-{lineage_id}.json",
        )
    raise ContractViolation("unknown review path kind")


def _validate_review_packet_value(packet: Any) -> None:
    keys = {
        "schemaVersion", "status", "kind", "rootContract", "lineageId", "machineReport",
        "prompt", "promptSha256", "inputs", "inputsSha256", "itemSetSha256", "items",
    }
    if not isinstance(packet, dict) or set(packet) != keys:
        raise ContractViolation("review packet keys are not closed")
    kind = packet["kind"]
    schema_version = packet["schemaVersion"]
    is_root_migration_packet = (
        schema_version == "quant-radar-ui-ux-review-packet/v2"
        and kind == "control-migration"
    )
    if (
        kind not in REVIEW_PROMPTS
        or schema_version
        not in {
            "quant-radar-ui-ux-review-packet/v1",
            "quant-radar-ui-ux-review-packet/v2",
        }
        or (
            schema_version == "quant-radar-ui-ux-review-packet/v2"
            and not is_root_migration_packet
        )
        or packet["status"] != "review_required"
    ):
        raise ContractViolation("review packet fixed fields mismatch")
    if packet["prompt"] != REVIEW_PROMPTS[kind] or packet["promptSha256"] != hashlib.sha256(
        _canonical_json_bytes(packet["prompt"])
    ).hexdigest():
        raise ContractViolation("review packet prompt binding mismatch")
    if kind == "control-migration":
        if packet["rootContract"] is not None or packet["lineageId"] != AUTHORIZED_RECOVERY_ID:
            raise ContractViolation("review packet recovery lineage mismatch")
    else:
        _validate_artifact_ref_value(packet["rootContract"], "review packet root contract")
        if not isinstance(packet["lineageId"], str) or BATCH_ID_PATTERN.fullmatch(packet["lineageId"]) is None:
            raise ContractViolation("review packet lineage ID is invalid")
    _validate_artifact_ref_value(packet["machineReport"], "review packet machine report")
    if not isinstance(packet["inputs"], list) or not packet["inputs"]:
        raise ContractViolation("review packet inputs are invalid")
    for index, item in enumerate(packet["inputs"]):
        _validate_artifact_ref_value(item, f"review packet input {index}")
    if packet["inputs"] != sorted(packet["inputs"], key=lambda item: item["path"]):
        raise ContractViolation("review packet inputs are not path-sorted")
    if len({item["path"] for item in packet["inputs"]}) != len(packet["inputs"]):
        raise ContractViolation("review packet inputs contain duplicates")
    if packet["machineReport"] not in packet["inputs"] or packet["inputsSha256"] != hashlib.sha256(
        _canonical_json_bytes(packet["inputs"])
    ).hexdigest():
        raise ContractViolation("review packet input binding mismatch")
    if not isinstance(packet["items"], list):
        raise ContractViolation("review packet items are invalid")
    if is_root_migration_packet:
        _validate_root_migration_review_items(packet["items"])
    else:
        _validate_review_items(kind, packet["items"])
    item_ids = [item["id"] for item in packet["items"]]
    if packet["itemSetSha256"] != hashlib.sha256(_canonical_json_bytes(sorted(item_ids))).hexdigest():
        raise ContractViolation("review packet item-set binding mismatch")
    expected_counts = {
        "control-migration": (5, 117),
        "theme-batch": (6, 5),
        "theme-states": (4, 12),
        "posttheme": (6, 81),
    }
    expected_count = (
        (5, 125)
        if is_root_migration_packet
        else expected_counts[kind]
    )
    if (len(packet["inputs"]), len(packet["items"])) != expected_count:
        raise ContractViolation("review packet input/item cardinality mismatch")


def _validate_retained_intake_fd(
    intake_fd: int,
    intake_record: Any,
    expected_path: str,
) -> tuple[bytes, dict[str, Any]]:
    record_keys = {
        "path", "sha256", "size", "mode", "uid", "gid", "device", "inode", "nlink",
    }
    if not isinstance(intake_record, dict) or set(intake_record) != record_keys:
        raise ContractViolation("review intake FileRecord keys are not closed")
    if intake_record["path"] != expected_path or not _is_safe_relative_path(expected_path):
        raise ContractViolation("review intake path mismatch")
    observed = os.fstat(intake_fd)
    try:
        named = os.stat(WORKSPACE_ROOT / expected_path, follow_symlinks=False)
    except OSError as exc:
        raise ContractViolation("named review intake is unavailable") from exc
    metadata = {
        "mode": f"{stat.S_IMODE(observed.st_mode):04o}",
        "uid": observed.st_uid,
        "gid": observed.st_gid,
        "device": observed.st_dev,
        "inode": observed.st_ino,
        "nlink": observed.st_nlink,
        "size": observed.st_size,
    }
    if (
        not stat.S_ISREG(observed.st_mode)
        or stat.S_IMODE(observed.st_mode) != 0o600
        or observed.st_uid != os.getuid()
        or observed.st_nlink != 1
        or (observed.st_dev, observed.st_ino) != (named.st_dev, named.st_ino)
        or any(intake_record[key] != value for key, value in metadata.items())
    ):
        raise ContractViolation("review intake descriptor metadata mismatch")
    data = _read_fd_exact(intake_fd, intake_record["size"])
    if hashlib.sha256(data).hexdigest() != intake_record["sha256"]:
        raise ContractViolation("review intake bytes differ from FileRecord")
    value = _strict_json_bytes(data)
    if not isinstance(value, dict):
        raise ContractViolation("review intake JSON is not an object")
    return data, value


def _validate_manual_review_value(
    review: Any,
    packet: dict[str, Any],
    packet_path: str,
    packet_bytes: bytes,
) -> None:
    keys = {
        "schemaVersion", "kind", "status", "reviewedAt", "reviewer", "packet",
        "promptSha256", "inputs", "inputsSha256", "itemSetSha256", "decision",
        "items", "findings",
    }
    if not isinstance(review, dict) or set(review) != keys:
        raise ContractViolation("manual review keys are not closed")
    if review["schemaVersion"] != "quant-radar-ui-ux-manual-review/v2" or review["kind"] != packet["kind"]:
        raise ContractViolation("manual review schema/kind mismatch")
    if review["status"] not in ("accepted", "rejected") or review["decision"] != review["status"]:
        raise ContractViolation("manual review status/decision mismatch")
    if not isinstance(review["reviewedAt"], str) or re.fullmatch(
        r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z",
        review["reviewedAt"],
    ) is None:
        raise ContractViolation("manual review timestamp is not UTC RFC3339 seconds")
    try:
        time.strptime(review["reviewedAt"], "%Y-%m-%dT%H:%M:%SZ")
    except ValueError as exc:
        raise ContractViolation("manual review timestamp is out of range") from exc
    reviewer = review["reviewer"]
    if (
        not isinstance(reviewer, dict)
        or set(reviewer) != {"type", "id"}
        or reviewer["type"] != "independent-code-reviewer"
        or not isinstance(reviewer["id"], str)
        or not reviewer["id"]
    ):
        raise ContractViolation("manual review reviewer assertion is invalid")
    expected_packet_ref = {
        "path": packet_path,
        "sha256": hashlib.sha256(packet_bytes).hexdigest(),
        "size": len(packet_bytes),
    }
    if review["packet"] != expected_packet_ref:
        raise ContractViolation("manual review packet reference mismatch")
    for key in ("promptSha256", "inputs", "inputsSha256", "itemSetSha256"):
        if review[key] != packet[key]:
            raise ContractViolation(f"manual review {key} binding mismatch")
    if not isinstance(review["items"], list) or [item.get("id") for item in review["items"] if isinstance(item, dict)] != [
        item["id"] for item in packet["items"]
    ]:
        raise ContractViolation("manual review item ID set/order mismatch")
    for item in review["items"]:
        if (
            not isinstance(item, dict)
            or set(item) != {"id", "verdict", "explanation"}
            or item["verdict"] not in ("accepted", "rejected")
            or not isinstance(item["explanation"], str)
            or not item["explanation"]
        ):
            raise ContractViolation("manual review decision item is invalid")
    if review["decision"] == "accepted" and any(item["verdict"] != "accepted" for item in review["items"]):
        raise ContractViolation("accepted manual review contains a rejected item")
    if not isinstance(review["findings"], list):
        raise ContractViolation("manual review findings are invalid")
    for finding in review["findings"]:
        if (
            not isinstance(finding, dict)
            or set(finding) != {"id", "severity", "status", "summary"}
            or finding["severity"] not in ("High", "Medium", "Low")
            or finding["status"] not in ("resolved", "unresolved")
            or not isinstance(finding["id"], str)
            or not isinstance(finding["summary"], str)
        ):
            raise ContractViolation("manual review finding is invalid")
        if review["decision"] == "accepted" and finding["severity"] in ("High", "Medium") and finding["status"] == "unresolved":
            raise ContractViolation("accepted manual review contains an unresolved blocking finding")


def _build_review_packet(
    kind: str,
    root_contract: dict[str, Any] | None,
    lineage_id: str,
    machine_report: dict[str, Any],
    inputs: Sequence[dict[str, Any]],
    items: Sequence[dict[str, Any]],
    *,
    patch_sources: dict[str, tuple[bytes, bytes]] | None = None,
) -> dict[str, Any]:
    if kind not in REVIEW_PROMPTS:
        raise ContractViolation("unknown review packet kind")
    if not isinstance(lineage_id, str) or not lineage_id:
        raise ContractViolation("review packet lineage ID is invalid")
    if kind == "control-migration":
        if root_contract is not None or lineage_id != AUTHORIZED_RECOVERY_ID:
            raise ContractViolation("control-migration review lineage mismatch")
    else:
        _validate_artifact_ref_value(root_contract, "review root contract")
        if kind == "theme-batch":
            if BATCH_ID_PATTERN.fullmatch(lineage_id) is None:
                raise ContractViolation("theme-batch review lineage ID is invalid")
        elif BATCH_ID_PATTERN.fullmatch(lineage_id) is None:
            raise ContractViolation("theme review run ID is invalid")
    _validate_artifact_ref_value(machine_report, "review machine report")
    if not isinstance(inputs, Sequence) or isinstance(inputs, (str, bytes)) or not inputs:
        raise ContractViolation("review inputs must be a nonempty sequence")
    ordered_inputs = [copy.deepcopy(item) for item in sorted(inputs, key=lambda item: item.get("path", ""))]
    if len({item.get("path") for item in ordered_inputs if isinstance(item, dict)}) != len(ordered_inputs):
        raise ContractViolation("review inputs contain duplicate paths")
    for index, item in enumerate(ordered_inputs):
        _validate_artifact_ref_value(item, f"review input {index}")
    if machine_report not in ordered_inputs:
        raise ContractViolation("review machine report is not in the authenticated input set")
    _validate_review_items(kind, items)
    copied_items = copy.deepcopy(list(items))

    if kind == "theme-batch":
        if patch_sources is None:
            raise ContractViolation("theme-batch review requires exact patch sources")
        patch = _build_theme_patch(patch_sources)
        if [item["id"] for item in copied_items] != list(APPLY_PATHS):
            raise ContractViolation("theme-batch review item order/set mismatch")
        section_by_path = {section["path"]: section for section in patch["sections"]}
        for item in copied_items:
            preimage, postimage = patch_sources[item["path"]]
            if (
                item["preimage"]["sha256"] != hashlib.sha256(preimage).hexdigest()
                or item["preimage"]["size"] != len(preimage)
                or item["postimage"]["sha256"] != hashlib.sha256(postimage).hexdigest()
                or item["postimage"]["size"] != len(postimage)
                or item["patchSectionSha256"] != section_by_path[item["path"]]["sha256"]
            ):
                raise ContractViolation("theme-batch review item differs from patch sources")
    elif patch_sources is not None:
        raise ContractViolation("non-batch review cannot carry patch sources")

    prompt = copy.deepcopy(REVIEW_PROMPTS[kind])
    item_ids = sorted(item["id"] for item in copied_items)
    return {
        "schemaVersion": "quant-radar-ui-ux-review-packet/v1",
        "status": "review_required",
        "kind": kind,
        "rootContract": copy.deepcopy(root_contract),
        "lineageId": lineage_id,
        "machineReport": copy.deepcopy(machine_report),
        "prompt": prompt,
        "promptSha256": hashlib.sha256(_canonical_json_bytes(prompt)).hexdigest(),
        "inputs": ordered_inputs,
        "inputsSha256": hashlib.sha256(_canonical_json_bytes(ordered_inputs)).hexdigest(),
        "itemSetSha256": hashlib.sha256(_canonical_json_bytes(item_ids)).hexdigest(),
        "items": copied_items,
    }


def _build_root_migration_review_packet(
    *,
    lineage_id: str,
    machine_report: dict[str, Any],
    inputs: Sequence[dict[str, Any]],
    items: Sequence[dict[str, Any]],
) -> dict[str, Any]:
    if lineage_id != AUTHORIZED_RECOVERY_ID:
        raise ContractViolation(
            "root migration review lineage mismatch"
        )
    _validate_artifact_ref_value(
        machine_report,
        "root migration machine report",
    )
    if (
        not isinstance(inputs, Sequence)
        or isinstance(inputs, (str, bytes))
    ):
        raise ContractViolation(
            "root migration review inputs are invalid"
        )
    ordered_inputs = [
        copy.deepcopy(item)
        for item in sorted(
            inputs,
            key=lambda item: item.get("path", ""),
        )
    ]
    if len(ordered_inputs) != 5 or len(
        {
            item.get("path")
            for item in ordered_inputs
            if isinstance(item, dict)
        }
    ) != len(ordered_inputs):
        raise ContractViolation(
            "root migration review inputs differ"
        )
    for index, item in enumerate(ordered_inputs):
        _validate_artifact_ref_value(
            item,
            f"root migration review input {index}",
        )
    if machine_report not in ordered_inputs:
        raise ContractViolation(
            "root migration machine report is not an input"
        )
    _validate_root_migration_review_items(items)
    copied_items = copy.deepcopy(list(items))
    prompt = copy.deepcopy(REVIEW_PROMPTS["control-migration"])
    item_ids = sorted(item["id"] for item in copied_items)
    packet = {
        "schemaVersion": "quant-radar-ui-ux-review-packet/v2",
        "status": "review_required",
        "kind": "control-migration",
        "rootContract": None,
        "lineageId": lineage_id,
        "machineReport": copy.deepcopy(machine_report),
        "prompt": prompt,
        "promptSha256": hashlib.sha256(
            _canonical_json_bytes(prompt)
        ).hexdigest(),
        "inputs": ordered_inputs,
        "inputsSha256": hashlib.sha256(
            _canonical_json_bytes(ordered_inputs)
        ).hexdigest(),
        "itemSetSha256": hashlib.sha256(
            _canonical_json_bytes(item_ids)
        ).hexdigest(),
        "items": copied_items,
    }
    _validate_review_packet_value(packet)
    return packet


def _build_theme_patch(
    sources: dict[str, tuple[bytes, bytes]],
) -> dict[str, Any]:
    if not isinstance(sources, dict) or tuple(sources) != APPLY_PATHS:
        raise ContractViolation("theme patch source order/set mismatch")
    sections: list[dict[str, Any]] = []
    for path in APPLY_PATHS:
        pair = sources[path]
        if (
            not isinstance(pair, tuple)
            or len(pair) != 2
            or not all(isinstance(image, bytes) for image in pair)
        ):
            raise ContractViolation(f"theme patch source shape mismatch: {path}")
        preimage, postimage = pair
        try:
            before = preimage.decode("utf-8", errors="strict")
            after = postimage.decode("utf-8", errors="strict")
        except UnicodeError as exc:
            raise ContractViolation("theme patch source is not UTF-8") from exc
        section_bytes = "".join(
            difflib.unified_diff(
                before.splitlines(keepends=True),
                after.splitlines(keepends=True),
                fromfile="a/" + path,
                tofile="b/" + path,
                fromfiledate="",
                tofiledate="",
                n=3,
                lineterm="\n",
            )
        ).encode("utf-8")
        if not section_bytes:
            raise ContractViolation(f"theme patch section is empty: {path}")
        section_sha = hashlib.sha256(
            b"quant-radar-ui-ux-theme-patch-section/v1\0"
            + path.encode("utf-8")
            + b"\0"
            + section_bytes
        ).hexdigest()
        sections.append({"path": path, "bytes": section_bytes, "sha256": section_sha})
    return {"sections": sections, "bytes": b"".join(section["bytes"] for section in sections)}


def _publish_review_exact(
    workspace_fd: int,
    packet: dict[str, Any],
    intake_fd: int,
    intake_record: dict[str, Any],
    *,
    decision_out: dict[str, str] | None = None,
) -> dict[str, Any]:
    if type(workspace_fd) is not int or type(intake_fd) is not int:
        raise ContractViolation("review publisher descriptors are invalid")
    workspace_stat = os.fstat(workspace_fd)
    named_workspace = os.lstat(WORKSPACE_ROOT)
    if (
        not stat.S_ISDIR(workspace_stat.st_mode)
        or (workspace_stat.st_dev, workspace_stat.st_ino)
        != (named_workspace.st_dev, named_workspace.st_ino)
    ):
        raise ContractViolation("review publisher workspace descriptor mismatch")
    _validate_review_packet_value(packet)
    kind = packet["kind"]
    root_sha = None if packet["rootContract"] is None else packet["rootContract"]["sha256"]
    lineage_id = packet["lineageId"]
    packet_path, intake_path, destination_path = _review_paths(kind, root_sha, lineage_id)

    packet_bytes = _canonical_json_bytes(packet)
    packet_fd: int | None = None
    try:
        packet_fd = os.open(
            packet_path,
            os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
            dir_fd=workspace_fd,
        )
        packet_stat = os.fstat(packet_fd)
        if (
            not stat.S_ISREG(packet_stat.st_mode)
            or stat.S_IMODE(packet_stat.st_mode) != 0o600
            or packet_stat.st_uid != os.getuid()
            or packet_stat.st_nlink != 1
            or _read_fd_exact(packet_fd, len(packet_bytes)) != packet_bytes
        ):
            raise ContractViolation("immutable published review packet mismatch")
    except OSError as exc:
        raise ContractViolation("immutable published review packet is unavailable") from exc
    finally:
        if packet_fd is not None:
            os.close(packet_fd)

    intake = _validate_retained_intake_fd(intake_fd, intake_record, intake_path)
    review_bytes, review = intake
    _validate_manual_review_value(review, packet, packet_path, packet_bytes)
    if decision_out is not None:
        if decision_out:
            raise ContractViolation(
                "review decision output must start empty"
            )
        decision_out["decision"] = review["decision"]
    destination_parent, destination_name = destination_path.rsplit("/", 1)
    parent_fd = os.open(
        destination_parent,
        os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0),
        dir_fd=workspace_fd,
    )
    try:
        try:
            os.stat(destination_name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise ContractViolation("manual-review destination collision")
        published = _publish_regular_exact(parent_fd, destination_name, review_bytes)
        record = dict(published["published"])
        record["path"] = destination_path
    finally:
        os.close(parent_fd)
    if record["inode"] == intake_record["inode"]:
        raise ContractViolation("manual review destination aliases its intake inode")
    return record


def _validate_review_items(kind: str, items: Sequence[dict[str, Any]]) -> None:
    if kind not in REVIEW_PROMPTS or not isinstance(items, Sequence) or isinstance(items, (str, bytes)):
        raise ContractViolation("review items kind/sequence is invalid")
    seen: set[str] = set()
    for index, item in enumerate(items):
        if not isinstance(item, dict) or not isinstance(item.get("id"), str) or not item["id"]:
            raise ContractViolation(f"review item {index} is invalid")
        if item["id"] in seen:
            raise ContractViolation("review item IDs are not unique")
        seen.add(item["id"])
        if kind in ("control-migration", "posttheme"):
            if set(item) != {"id", "before", "after", "dimensions", "changed"}:
                raise ContractViolation("paired review item keys are not closed")
            _validate_artifact_ref_value(item["before"], "paired review before")
            _validate_artifact_ref_value(item["after"], "paired review after")
            _validate_review_dimensions(item["dimensions"])
            if type(item["changed"]) is not bool or item["changed"] != (
                item["before"]["sha256"] != item["after"]["sha256"]
            ):
                raise ContractViolation("paired review changed flag differs from artifact hashes")
        elif kind == "theme-states":
            if set(item) != {"id", "artifact", "dimensions"}:
                raise ContractViolation("theme-state review item keys are not closed")
            _validate_artifact_ref_value(item["artifact"], "theme-state artifact")
            _validate_review_dimensions(item["dimensions"])
        else:
            if set(item) != {
                "id", "path", "preimage", "postimage", "patchSectionSha256"
            }:
                raise ContractViolation("theme-batch review item keys are not closed")
            if item["id"] != item["path"] or item["path"] not in APPLY_PATHS:
                raise ContractViolation("theme-batch review item path mismatch")
            _validate_content_ref_value(item["preimage"], "theme-batch preimage")
            _validate_content_ref_value(item["postimage"], "theme-batch postimage")
            if item["preimage"]["path"] != item["path"] or item["postimage"]["path"] != item["path"]:
                raise ContractViolation("theme-batch nested logical path mismatch")
            if not isinstance(item["patchSectionSha256"], str) or re.fullmatch(
                r"[0-9a-f]{64}", item["patchSectionSha256"]
            ) is None:
                raise ContractViolation("theme-batch patch section digest is invalid")
    return None


def _validate_root_migration_review_items(
    items: Sequence[dict[str, Any]],
) -> None:
    if (
        not isinstance(items, Sequence)
        or isinstance(items, (str, bytes))
        or len(items) != 125
    ):
        raise ContractViolation(
            "root migration review item cardinality differs"
        )
    from scripts import ui_ux_evidence

    expected_roots = {
        row["rootCaptureId"]: row
        for row in ui_ux_evidence.root_capture_expansion_rows()
    }
    seen: set[str] = set()
    page_count = 0
    root_count = 0
    corrected_pngs: set[tuple[str, str, int]] = set()
    corrected_sidecars: set[tuple[str, str, int]] = set()
    for index, item in enumerate(items):
        if (
            not isinstance(item, dict)
            or not isinstance(item.get("id"), str)
            or not item["id"]
            or item["id"] in seen
        ):
            raise ContractViolation(
                f"root migration review item {index} is invalid"
            )
        seen.add(item["id"])
        kind = item.get("kind")
        if kind == "page":
            if set(item) != {
                "kind",
                "id",
                "before",
                "after",
                "dimensions",
                "changed",
            }:
                raise ContractViolation(
                    "root migration page review keys are not closed"
                )
            page_count += 1
        elif kind == "control-root":
            if set(item) != {
                "kind",
                "id",
                "logicalCaptureId",
                "rootCaptureId",
                "rootOrdinal",
                "rootSelector",
                "before",
                "after",
                "afterSidecar",
                "dimensions",
                "changed",
            }:
                raise ContractViolation(
                    "root migration control review keys are not closed"
                )
            root_id = item["rootCaptureId"]
            expected = expected_roots.get(root_id)
            if (
                expected is None
                or item["id"] != root_id
                or item["logicalCaptureId"]
                != expected["logicalCaptureId"]
                or item["rootOrdinal"] != expected["rootOrdinal"]
                or item["rootSelector"] != expected["rootSelector"]
            ):
                raise ContractViolation(
                    "root migration review identity differs"
                )
            _validate_artifact_ref_value(
                item["afterSidecar"],
                "root migration corrected sidecar",
            )
            after_key = (
                item["after"]["path"],
                item["after"]["sha256"],
                item["after"]["size"],
            )
            sidecar_key = (
                item["afterSidecar"]["path"],
                item["afterSidecar"]["sha256"],
                item["afterSidecar"]["size"],
            )
            if (
                after_key in corrected_pngs
                or sidecar_key in corrected_sidecars
            ):
                raise ContractViolation(
                    "root migration corrected artifact is reused"
                )
            corrected_pngs.add(after_key)
            corrected_sidecars.add(sidecar_key)
            root_count += 1
        else:
            raise ContractViolation(
                "root migration review item kind differs"
            )
        _validate_artifact_ref_value(
            item["before"], "root migration review before"
        )
        _validate_artifact_ref_value(
            item["after"], "root migration review after"
        )
        _validate_review_dimensions(item["dimensions"])
        if type(item["changed"]) is not bool or item["changed"] != (
            item["before"]["sha256"] != item["after"]["sha256"]
        ):
            raise ContractViolation(
                "root migration review changed flag differs"
            )
    if (
        page_count != 81
        or root_count != 44
        or set(expected_roots) != {
            item["rootCaptureId"]
            for item in items
            if item.get("kind") == "control-root"
        }
    ):
        raise ContractViolation(
            "root migration page/root coverage differs"
        )


def _candidate_source_root_for_seal(
    _workspace_root: Path,
    _fixture: Mapping[str, Any],
) -> Path:
    return SOURCE_WORKSPACE_ROOT


