def _scratch_require(condition: bool, message: str) -> None:
    if not condition:
        raise ContractViolation(message)


def _scratch_decode(images: Mapping[str, bytes], path: str) -> str:
    try:
        return images[path].decode("utf-8")
    except (KeyError, UnicodeDecodeError) as exc:
        raise ContractViolation(f"{path} is not valid UTF-8") from exc


def _scratch_assigned_names(node: ast.AST) -> frozenset[str]:
    targets: list[ast.AST] = []
    if isinstance(node, (ast.Assign, ast.AnnAssign)):
        targets = list(node.targets) if isinstance(node, ast.Assign) else [node.target]
    names = {
        target.id
        for target in targets
        if isinstance(target, ast.Name)
    }
    return frozenset(names)


def _scratch_eval_static(node: ast.AST, environment: Mapping[str, Any]) -> Any:
    """Evaluate only the closed literal/token subset allowed in the CSS builder."""

    if isinstance(node, ast.Constant):
        return node.value
    if isinstance(node, ast.Name):
        if node.id not in environment:
            raise ContractViolation(f"theme static expression uses unknown name: {node.id}")
        return environment[node.id]
    if isinstance(node, ast.Dict):
        result: dict[Any, Any] = {}
        for key, value in zip(node.keys, node.values):
            if key is None:
                spread = _scratch_eval_static(value, environment)
                _scratch_require(isinstance(spread, Mapping), "theme dict spread is not a mapping")
                result.update(spread)
            else:
                result[_scratch_eval_static(key, environment)] = _scratch_eval_static(
                    value, environment
                )
        return result
    if isinstance(node, (ast.Tuple, ast.List, ast.Set)):
        values = [_scratch_eval_static(value, environment) for value in node.elts]
        if isinstance(node, ast.Tuple):
            return tuple(values)
        if isinstance(node, ast.Set):
            return set(values)
        return values
    if isinstance(node, ast.Subscript):
        value = _scratch_eval_static(node.value, environment)
        key = _scratch_eval_static(node.slice, environment)
        try:
            return value[key]
        except (KeyError, IndexError, TypeError) as exc:
            raise ContractViolation("theme static subscript is invalid") from exc
    if isinstance(node, ast.JoinedStr):
        parts: list[str] = []
        for value in node.values:
            if isinstance(value, ast.Constant) and isinstance(value.value, str):
                parts.append(value.value)
            elif isinstance(value, ast.FormattedValue) and value.format_spec is None:
                parts.append(str(_scratch_eval_static(value.value, environment)))
            else:
                raise ContractViolation("theme CSS f-string contains a dynamic format")
        return "".join(parts)
    if isinstance(node, ast.BinOp):
        left = _scratch_eval_static(node.left, environment)
        right = _scratch_eval_static(node.right, environment)
        operations: dict[type[ast.operator], Callable[[Any, Any], Any]] = {
            ast.Add: lambda first, second: first + second,
            ast.Sub: lambda first, second: first - second,
            ast.Mult: lambda first, second: first * second,
            ast.Div: lambda first, second: first / second,
        }
        operation = operations.get(type(node.op))
        if operation is None:
            raise ContractViolation("theme static expression uses a forbidden operator")
        try:
            return operation(left, right)
        except (TypeError, ValueError, ZeroDivisionError) as exc:
            raise ContractViolation("theme static expression operation failed") from exc
    if isinstance(node, ast.UnaryOp) and isinstance(node.op, (ast.UAdd, ast.USub)):
        value = _scratch_eval_static(node.operand, environment)
        return value if isinstance(node.op, ast.UAdd) else -value
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Name):
        _scratch_require(not node.keywords and len(node.args) == 1, "theme static call shape is invalid")
        value = _scratch_eval_static(node.args[0], environment)
        if node.func.id == "MappingProxyType":
            _scratch_require(isinstance(value, Mapping), "MappingProxyType input is not a mapping")
            return dict(value)
        if node.func.id == "frozenset":
            return frozenset(value)
        if node.func.id == "tuple":
            return tuple(value)
    raise ContractViolation(
        f"theme static expression contains forbidden AST: {type(node).__name__}"
    )


def _scratch_design_environment(tree: ast.Module) -> dict[str, Any]:
    environment: dict[str, Any] = {}
    for node in tree.body:
        names = _scratch_assigned_names(node)
        if len(names) != 1:
            continue
        name = next(iter(names))
        value_node = node.value if isinstance(node, (ast.Assign, ast.AnnAssign)) else None
        if value_node is None:
            continue
        try:
            environment[name] = _scratch_eval_static(value_node, environment)
        except ContractViolation:
            continue
    required = {
        "SURFACE_TOKENS",
        "TEXT_TOKENS",
        "BORDER_TOKENS",
        "INTERACTIVE_TOKENS",
        "FEEDBACK_TOKENS",
        "SIGNAL_TOKENS",
        "COLOR_TOKENS",
        "CHIP_COLORS",
        "THEME_SELECTOR_CONTRACT",
    }
    missing = sorted(required - set(environment))
    _scratch_require(not missing, f"theme design static declarations are missing: {missing}")
    return environment


def _scratch_render_theme_builder(tree: ast.Module, environment: Mapping[str, Any]) -> str:
    builders = [
        node
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name == "build_global_theme_css"
    ]
    _scratch_require(len(builders) == 1, "theme CSS builder must exist exactly once")
    builder = builders[0]
    arguments = builder.args
    _scratch_require(
        not arguments.posonlyargs
        and not arguments.args
        and not arguments.kwonlyargs
        and arguments.vararg is None
        and arguments.kwarg is None
        and not builder.decorator_list,
        "theme CSS builder must be a plain no-input function",
    )
    local = dict(environment)
    returned: Any = None
    saw_return = False
    for statement in builder.body:
        if (
            isinstance(statement, ast.Expr)
            and isinstance(statement.value, ast.Constant)
            and isinstance(statement.value.value, str)
        ):
            continue
        if isinstance(statement, (ast.Assign, ast.AnnAssign)):
            names = _scratch_assigned_names(statement)
            _scratch_require(len(names) == 1, "theme CSS builder assignment is not a simple local")
            value = _scratch_eval_static(statement.value, local)
            local[next(iter(names))] = value
            continue
        if isinstance(statement, ast.Return):
            _scratch_require(not saw_return, "theme CSS builder has multiple return paths")
            returned = _scratch_eval_static(statement.value, local)
            saw_return = True
            continue
        raise ContractViolation(
            f"theme CSS builder contains forbidden statement: {type(statement).__name__}"
        )
    _scratch_require(saw_return and isinstance(returned, str), "theme CSS builder did not return static text")
    return returned


def _scratch_filtered_design_ast(tree: ast.Module) -> str:
    allowed_names = {
        "TEXT_TOKENS",
        "INTERACTIVE_TOKENS",
        "COLOR_TOKENS",
        "THEME_SELECTOR_CONTRACT",
    }
    retained: list[ast.stmt] = []
    for node in tree.body:
        if _scratch_assigned_names(node) & allowed_names:
            continue
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == "build_global_theme_css":
            continue
        retained.append(node)
    return ast.dump(ast.Module(body=retained, type_ignores=[]), include_attributes=False)


def _scratch_qualname(node: ast.AST) -> str:
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        parent = _scratch_qualname(node.value)
        return f"{parent}.{node.attr}" if parent else node.attr
    return ""


def _scratch_scan_primary_actions(
    app_source: str,
    ui_sources: Mapping[str, str],
) -> list[str]:
    records: list[tuple[str, str, str, str, str, int]] = []
    for relative, source in [("app.py", app_source), *sorted(ui_sources.items())]:
        tree = ast.parse(source, filename=relative, type_comments=True)
        stack: list[str] = []

        class PrimaryVisitor(ast.NodeVisitor):
            def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
                stack.append(node.name)
                self.generic_visit(node)
                stack.pop()

            visit_AsyncFunctionDef = visit_FunctionDef

            def visit_ClassDef(self, node: ast.ClassDef) -> None:
                stack.append(node.name)
                self.generic_visit(node)
                stack.pop()

            def visit_Call(self, node: ast.Call) -> None:
                call_kind = _scratch_qualname(node.func) or type(node.func).__name__
                primitive = call_kind.rsplit(".", 1)[-1]
                keywords = [item for item in node.keywords if item.arg == "type"]
                if primitive not in _THEME_PRIMARY_PRIMITIVES:
                    _scratch_require(
                        not any(
                            isinstance(item.value, ast.Constant)
                            and item.value.value == "primary"
                            for item in keywords
                        ),
                        "unsupported type='primary' action primitive",
                    )
                    self.generic_visit(node)
                    return
                _scratch_require(
                    not any(item.arg is None for item in node.keywords),
                    "primary action type cannot be hidden in **kwargs",
                )
                if not keywords:
                    self.generic_visit(node)
                    return
                _scratch_require(len(keywords) == 1, "action must have exactly one type keyword")
                type_value = keywords[0].value
                _scratch_require(
                    isinstance(type_value, ast.Constant)
                    and isinstance(type_value.value, str),
                    "action type must be a string literal",
                )
                if type_value.value != "primary":
                    self.generic_visit(node)
                    return
                label = node.args[0] if node.args else next(
                    (item.value for item in node.keywords if item.arg == "label"),
                    None,
                )
                _scratch_require(label is not None, "primary action label is required")
                categories = {
                    ast.BinOp: "binary",
                    ast.Call: "call",
                    ast.Constant: "constant",
                    ast.Dict: "dict",
                    ast.JoinedStr: "f_string",
                    ast.List: "list",
                    ast.Name: "name",
                    ast.Set: "set",
                    ast.Subscript: "subscript",
                    ast.Tuple: "tuple",
                }
                category = next(
                    (
                        label_name
                        for node_type, label_name in categories.items()
                        if isinstance(label, node_type)
                    ),
                    re.sub(r"(?<!^)(?=[A-Z])", "_", type(label).__name__).lower(),
                )
                fingerprint = hashlib.sha256(
                    ast.dump(node, annotate_fields=True, include_attributes=False).encode("utf-8")
                ).hexdigest()
                records.append(
                    (
                        relative,
                        ".".join(stack) if stack else "<module>",
                        call_kind,
                        category,
                        fingerprint,
                        node.lineno,
                    )
                )
                self.generic_visit(node)

        PrimaryVisitor().visit(tree)
    records.sort(key=lambda row: (row[0], row[5], row[1], row[2], row[4]))
    occurrences: dict[tuple[str, ...], int] = {}
    result: list[str] = []
    for relative, function, call_kind, category, fingerprint, _line in records:
        key = (relative, function, call_kind, category, fingerprint)
        occurrences[key] = occurrences.get(key, 0) + 1
        result.append("|".join((*key, str(occurrences[key]))))
    return result


def _scratch_unsafe_calls(tree: ast.Module) -> list[tuple[ast.Call, str, str]]:
    module_calls = {
        id(node.value): node.value
        for node in tree.body
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call)
    }
    rows: list[tuple[ast.Call, str, str]] = []
    for call in ast.walk(tree):
        if not isinstance(call, ast.Call):
            continue
        unsafe = next(
            (item.value for item in call.keywords if item.arg == "unsafe_allow_html"),
            None,
        )
        if not (isinstance(unsafe, ast.Constant) and unsafe.value is True):
            continue
        expression = call.args[0] if call.args else next(
            (
                item.value
                for item in call.keywords
                if item.arg in {"body", "text", "label"}
            ),
            ast.Constant(value=None),
        )
        fingerprint = hashlib.sha256(
            ast.dump(expression, annotate_fields=True, include_attributes=False).encode("utf-8")
        ).hexdigest()
        rows.append(
            (
                call,
                fingerprint,
                "module" if id(call) in module_calls else "nested",
            )
        )
    return rows


def _scratch_verify_paths(context: Mapping[str, Any]) -> None:
    _scratch_require(tuple(context["paths"]) == APPLY_PATHS, "scratch path/order set differs")
    for path in APPLY_PATHS:
        pre_stat = context["preStats"][path]
        post_stat = context["postStats"][path]
        _scratch_require(
            stat.S_ISREG(pre_stat.st_mode)
            and stat.S_ISREG(post_stat.st_mode)
            and pre_stat.st_nlink == post_stat.st_nlink == 1,
            f"{path} scratch image is not a one-link regular file",
        )
        _scratch_require(
            stat.S_IMODE(pre_stat.st_mode) == stat.S_IMODE(post_stat.st_mode) == 0o644,
            f"{path} scratch image mode differs from the exact 0644 set",
        )
        _scratch_require(
            (pre_stat.st_dev, pre_stat.st_ino) != (post_stat.st_dev, post_stat.st_ino),
            f"{path} pre/post scratch images alias",
        )
        _scratch_require(
            context["pre"][path] != context["post"][path],
            f"{path} has no intentional diff",
        )


def _scratch_verify_config(context: Mapping[str, Any]) -> None:
    try:
        try:
            import tomllib
        except ModuleNotFoundError:  # Python 3.10 compatibility.
            import tomli as tomllib  # type: ignore[no-redef,import-not-found]

        before = tomllib.loads(_scratch_decode(context["pre"], APPLY_PATHS[0]))
        after = tomllib.loads(_scratch_decode(context["post"], APPLY_PATHS[0]))
    except (ImportError, TypeError, ValueError) as exc:
        raise ContractViolation("theme config is not valid TOML") from exc
    expected = copy.deepcopy(before)
    theme = expected.get("theme")
    _scratch_require(isinstance(theme, dict), "theme config lacks [theme]")
    theme.update(
        {
            "primaryColor": "#2563eb",
            "linkColor": "#60a5fa",
            "linkUnderline": True,
        }
    )
    _scratch_require(after == expected, "theme config changed outside exact R1B-04 values")


def _scratch_verify_syntax(context: Mapping[str, Any]) -> None:
    for path in ("app.py", "ui/_design.py"):
        source = _scratch_decode(context["post"], path)
        try:
            ast.parse(source, filename=path, type_comments=True)
            ast.parse(
                source,
                filename=path,
                type_comments=True,
                feature_version=(3, 10),
            )
        except SyntaxError as exc:
            raise ContractViolation(f"{path} does not parse with runtime/Python 3.10 grammar") from exc


def _scratch_verify_tokens_css(context: Mapping[str, Any]) -> None:
    from scripts import ui_ux_theme_matrix as theme

    _require_source_module_origin(
        theme,
        "scripts/ui_ux_theme_matrix.py",
    )
    before_tree = ast.parse(_scratch_decode(context["pre"], "ui/_design.py"))
    after_tree = ast.parse(_scratch_decode(context["post"], "ui/_design.py"))
    _scratch_require(
        _scratch_filtered_design_ast(before_tree) == _scratch_filtered_design_ast(after_tree),
        "design code changed outside the semantic token/CSS boundary",
    )
    environment = _scratch_design_environment(after_tree)
    interaction = environment["INTERACTIVE_TOKENS"]
    selected_text = {
        key: environment["TEXT_TOKENS"][key]
        for key in ("text.on-primary", "text.disabled")
    }
    selected_border = {"border.focus": environment["BORDER_TOKENS"]["border.focus"]}
    _scratch_require(
        {**interaction, **selected_text, **selected_border} == _THEME_APPROVED_TOKENS,
        "production semantic theme tokens differ from the exact approved set",
    )
    design_view = type("_ScratchDesign", (), {"COLOR_TOKENS": environment["COLOR_TOKENS"]})
    try:
        theme.validate_design_token_contract(design_view)
        rendered = _scratch_render_theme_builder(after_tree, environment)
        css = theme.extract_theme_css(rendered)
        theme.validate_css_safety(css)
        theme.validate_link_contract(css)
        records = theme.validate_selector_contract(
            css, environment["THEME_SELECTOR_CONTRACT"]
        )
    except theme.ThemeContractError as exc:
        raise ContractViolation(f"theme CSS contract failed: {exc}") from exc
    owned_cases = {
        theme._parse_owner_id(owner)[1]
        for record in records
        for owner in record.owners
    }
    _scratch_require(owned_cases == _THEME_CSS_CASES, "theme CSS owner/case set is incomplete")
    css_lower = css.casefold()
    _scratch_require(
        all(value in css_lower for value in _THEME_APPROVED_TOKENS.values()),
        "theme CSS does not project every approved semantic role",
    )
    _scratch_require(
        "#ef4444" not in css_lower and "#ef553b" not in css_lower,
        "danger/signal red entered interaction CSS",
    )


def _scratch_verify_injection(context: Mapping[str, Any]) -> None:
    before_tree = ast.parse(_scratch_decode(context["pre"], "app.py"))
    after_tree = ast.parse(_scratch_decode(context["post"], "app.py"))
    before_rows = _scratch_unsafe_calls(before_tree)
    after_rows = _scratch_unsafe_calls(after_tree)
    before_fingerprints = sorted(row[1] for row in before_rows)
    new_rows = [
        row
        for row in after_rows
        if row[1] not in before_fingerprints
    ]
    _scratch_require(len(new_rows) == 1, "app must add exactly one unsafe theme injection")
    call, fingerprint, scope = new_rows[0]
    expected_expression = ast.parse("_design.build_global_theme_css()", mode="eval").body
    expression = call.args[0] if call.args else None
    _scratch_require(
        scope == "module"
        and expression is not None
        and ast.dump(expression, include_attributes=False)
        == ast.dump(expected_expression, include_attributes=False),
        "new theme injection is not the one static no-input builder call",
    )
    _scratch_require(
        sorted(row[1] for row in after_rows if row[1] != fingerprint)
        == before_fingerprints,
        "legacy metric/unsafe injections changed",
    )
    stripped = copy.deepcopy(after_tree)
    stripped.body = [
        node
        for node in stripped.body
        if not (
            isinstance(node, ast.Expr)
            and isinstance(node.value, ast.Call)
            and any(
                row_fingerprint == fingerprint
                and ast.dump(row_call, include_attributes=False)
                == ast.dump(node.value, include_attributes=False)
                for row_call, row_fingerprint, _scope in after_rows
            )
        )
    ]
    for node in stripped.body:
        if isinstance(node, ast.ImportFrom) and node.module == "ui":
            node.names = [alias for alias in node.names if alias.name != "_design"]
    _scratch_require(
        ast.dump(stripped, include_attributes=False)
        == ast.dump(before_tree, include_attributes=False),
        "app changed outside the _design import and one theme injection",
    )
    module_calls = [
        node.value
        for node in after_tree.body
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Call)
    ]
    new_index = next(
        index
        for index, module_call in enumerate(module_calls)
        if ast.dump(module_call, include_attributes=False)
        == ast.dump(call, include_attributes=False)
    )
    legacy_metric_indexes = [
        index
        for index, module_call in enumerate(module_calls)
        if any(
            row_fingerprint in before_fingerprints
            and ast.dump(row_call, include_attributes=False)
            == ast.dump(module_call, include_attributes=False)
            for row_call, row_fingerprint, _scope in after_rows
        )
    ]
    _scratch_require(
        legacy_metric_indexes and new_index + 1 == legacy_metric_indexes[0],
        "theme injection is not adjacent to the unchanged legacy metric injection",
    )


def _scratch_verify_version(context: Mapping[str, Any]) -> None:
    before = _scratch_decode(context["pre"], "requirements.txt").splitlines(keepends=True)
    after = _scratch_decode(context["post"], "requirements.txt").splitlines(keepends=True)
    before_streamlit = [line for line in before if line.strip().startswith("streamlit")]
    after_streamlit = [line for line in after if line.strip().startswith("streamlit")]
    _scratch_require(len(before_streamlit) == len(after_streamlit) == 1, "requirements has ambiguous Streamlit rows")
    expected = list(before)
    expected[expected.index(before_streamlit[0])] = "streamlit==1.57.0\n"
    _scratch_require(after == expected, "requirements changed outside the exact Streamlit pin")
    try:
        installed = importlib.metadata.version("streamlit")
    except importlib.metadata.PackageNotFoundError as exc:
        raise ContractViolation("installed Streamlit distribution is unavailable") from exc
    _scratch_require(installed == "1.57.0", "installed Streamlit is not the authorized 1.57.0")


