def _codex_migration_receipt(site_ids: Iterable[str]) -> dict[str, Any]:
    rows = sorted(site_ids)
    if len(rows) != len(set(rows)) or not all(
        isinstance(row, str) and row for row in rows
    ):
        raise ContractViolation("Codex migration site IDs are invalid")
    payload = "".join(f"{row}\n" for row in rows).encode("utf-8")
    return {
        "count": len(rows),
        "bytes": len(payload),
        "sha256": hashlib.sha256(payload).hexdigest(),
    }


def _scratch_verify_classification(context: Mapping[str, Any]) -> None:
    from scripts import ui_ux_inventory as inventory

    _require_source_module_origin(
        inventory,
        "scripts/ui_ux_inventory.py",
    )
    source_root = Path(context["sourceRoot"]).resolve(strict=True)
    try:
        classification = json.loads(
            _scratch_decode(
                context["post"],
                "docs/ui-ux/quant-radar-ui-v2-ux1b-classification.json",
            )
        )
    except (TypeError, ValueError) as exc:
        raise ContractViolation("UX-1B classification is not valid JSON") from exc
    _scratch_require(
        isinstance(classification, dict)
        and set(classification)
        == {
            "accepted_plan",
            "parent",
            "primary_actions",
            "rationales",
            "schema_version",
            "scope",
            "state",
            "unsafe_html",
        },
        "UX-1B classification top-level contract differs",
    )
    _scratch_require(
        classification["schema_version"] == "quant-radar-ui-ux-ux1b-classification/v1"
        and classification["state"] == "accepted",
        "UX-1B classification did not transition pending-to-accepted",
    )
    _scratch_require(
        classification["accepted_plan"]
        == {
            "path": "docs/superpowers/plans/2026-07-16-quant-radar-ui-ux-ux1b.md",
            "sha256": _UX1B_ACCEPTED_PLAN_SHA256,
        },
        "UX-1B accepted-plan binding differs",
    )
    _scratch_require(
        classification["parent"]
        == {
            "ux1a_classification": {
                "path": "docs/ui-ux/quant-radar-ui-v2-ux1a-classification.json",
                "sha256": _UX1A_CLASSIFICATION_SHA256,
            },
            "ux1a_contract": {
                "path": "docs/ui-ux/quant-radar-ui-v2-ux1a-contract.json",
                "sha256": _UX1A_CONTRACT_SHA256,
            },
        },
        "UX-1B parent evidence binding differs",
    )
    protected = {
        "docs/ui-ux/quant-radar-ui-v2-ux1a-classification.json": _UX1A_CLASSIFICATION_SHA256,
        "docs/ui-ux/quant-radar-ui-v2-ux1a-contract.json": _UX1A_CONTRACT_SHA256,
        "ui/_components.py": "c654b1b4a9fd4be93525edb624d0d72d23ba3288df15a6caa59b54c7160d749b",
        "ui/_read_api.py": "defd07518f58f6b8572020e060cc06786ebdb7652c3372dfd7ec7a551b840b1a",
        "ui/_shared.py": "9391c5704356ac2e68547d89a76565890293f7c38ddceb6c364a0b8bcfbff184",
    }
    for relative, expected_digest in protected.items():
        try:
            payload = (source_root / relative).read_bytes()
        except OSError as exc:
            raise ContractViolation(f"protected source is unavailable: {relative}") from exc
        _scratch_require(
            hashlib.sha256(payload).hexdigest() == expected_digest,
            f"protected/fail-soft source hash drifted: {relative}",
        )
    app_source = _scratch_decode(context["post"], "app.py")
    ui_sources = {
        path.relative_to(source_root).as_posix(): path.read_text(encoding="utf-8")
        for path in sorted((source_root / "ui").rglob("*.py"))
    }
    ui_sources["ui/_design.py"] = _scratch_decode(context["post"], "ui/_design.py")
    try:
        current_inventory = inventory.analyze_sources(app_source, ui_sources)
        current_contract = inventory.baseline_contract(current_inventory)
    except (OSError, UnicodeError, inventory.InventoryError) as exc:
        raise ContractViolation(f"UX inventory failed: {exc}") from exc
    ux1a_contract = json.loads(
        (source_root / "docs/ui-ux/quant-radar-ui-v2-ux1a-contract.json").read_text(
            encoding="utf-8"
        )
    )
    parent_current = ux1a_contract["current_contract"]
    compatibility = {
        key: current_contract[key]
        for key in inventory.UX0_COMPATIBILITY_FIELDS
    }
    _scratch_require(
        hashlib.sha256(inventory.canonical_json(compatibility).encode("utf-8")).hexdigest()
        == parent_current["compatibility_sha256"],
        "UX-1A backward compatibility projection drifted",
    )
    current_diagnostic_ids = {
        row["site_id"] for row in current_contract["diagnostics"]
    }
    parent_diagnostic_ids = set(parent_current["diagnostic_site_ids"])
    _scratch_require(
        _codex_migration_receipt(
            current_diagnostic_ids - parent_diagnostic_ids
        )
        == _CODEX_MIGRATION_RECEIPTS["diagnosticAdditions"]
        and _codex_migration_receipt(
            parent_diagnostic_ids - current_diagnostic_ids
        )
        == _CODEX_MIGRATION_RECEIPTS["diagnosticRemovals"],
        "UX-1A diagnostic projection has non-Codex migration drift",
    )
    parent_unsafe = set(parent_current["unsafe_site_ids"])
    current_unsafe = {
        row["site_id"]: row for row in current_contract["unsafe_html"]
    }
    _scratch_require(not (parent_unsafe - set(current_unsafe)), "UX-1A unsafe projection lost a site")
    trusted = classification["unsafe_html"].get("trusted_static_theme_css")
    _scratch_require(isinstance(trusted, list) and len(trusted) == 1, "trusted CSS ledger must contain one site")
    trusted_record = trusted[0]
    _scratch_require(
        isinstance(trusted_record, dict)
        and set(trusted_record)
        == {"builder", "expression_fingerprint", "rationale_code", "site_id"}
        and trusted_record["builder"] == "_design.build_global_theme_css"
        and trusted_record["rationale_code"] == "trusted_static_theme_css",
        "trusted CSS ledger record differs",
    )
    _scratch_require(
        set(current_unsafe) - parent_unsafe == {trusted_record["site_id"]},
        "forward unsafe-HTML delta is not exactly one trusted CSS site",
    )
    trusted_site = current_unsafe.get(trusted_record["site_id"])
    _scratch_require(
        trusted_site is not None
        and trusted_site["file"] == "app.py"
        and trusted_site["function"] == "<module>"
        and trusted_site["call_kind"] == "st.markdown"
        and trusted_site["expression_category"] == "call"
        and trusted_site["static"] is False
        and trusted_site["fingerprint"] == trusted_record["expression_fingerprint"],
        "trusted CSS site does not bind the exact app injection",
    )
    buckets = classification["primary_actions"]
    _scratch_require(
        isinstance(buckets, dict)
        and set(buckets) == {"ordinary_interaction", "danger_destructive"}
        and buckets["danger_destructive"] == []
        and buckets["ordinary_interaction"] == sorted(buckets["ordinary_interaction"]),
        "primary/danger classification union differs",
    )
    current_primary = sorted(_scratch_scan_primary_actions(app_source, ui_sources))
    _scratch_require(
        len(current_primary) == len(set(current_primary)) == 20
        and _codex_migration_receipt(
            set(current_primary) - set(buckets["ordinary_interaction"])
        )
        == _CODEX_MIGRATION_RECEIPTS["primaryAdditions"]
        and _codex_migration_receipt(
            set(buckets["ordinary_interaction"]) - set(current_primary)
        )
        == _CODEX_MIGRATION_RECEIPTS["primaryRemovals"],
        "primary-action ledger has non-Codex migration drift",
    )


_THEME_SCRATCH_VERIFIERS: tuple[
    tuple[str, Callable[[Mapping[str, Any]], None]], ...
] = (
    (THEME_SCRATCH_IDS[0], _scratch_verify_paths),
    (THEME_SCRATCH_IDS[1], _scratch_verify_config),
    (THEME_SCRATCH_IDS[2], _scratch_verify_syntax),
    (THEME_SCRATCH_IDS[3], _scratch_verify_tokens_css),
    (THEME_SCRATCH_IDS[4], _scratch_verify_injection),
    (THEME_SCRATCH_IDS[5], _scratch_verify_version),
    (THEME_SCRATCH_IDS[6], _scratch_verify_classification),
)


def _theme_scratch_internal_result(
    identifier: str,
    *,
    status_value: Literal["passed", "failed"],
    error_code: Literal["assertion_failed", "internal_exception"] | None,
) -> dict[str, Any]:
    empty_digest = hashlib.sha256(b"").hexdigest()
    return {
        "id": identifier,
        "kind": "internal",
        "status": status_value,
        "outcome": "internal",
        "errorCode": error_code,
        "returnCode": None,
        "signal": None,
        "stdoutSha256": empty_digest,
        "stderrSha256": empty_digest,
        "stdoutBytes": 0,
        "stderrBytes": 0,
        "processGroupId": None,
        "processFamily": None,
    }


def _theme_scratch_report(results: Sequence[dict[str, Any]]) -> dict[str, Any]:
    passed = sum(row["status"] == "passed" for row in results)
    failed = len(results) - passed
    body = {
        "schemaVersion": "quant-radar-ui-ux-theme-batch-scratch-tests/v1",
        "status": "passed" if failed == 0 else "failed",
        "commands": [
            {"id": identifier, "kind": "internal", "execution": None}
            for identifier in THEME_SCRATCH_IDS
        ],
        "results": list(results),
        "passed": passed,
        "failed": failed,
    }
    return {
        **body,
        "sha256": hashlib.sha256(_canonical_json_bytes(body)).hexdigest(),
    }


def _run_theme_scratch_verifiers(
    images: Sequence[tuple[str, int, int]],
    *,
    source_root: Path | None = None,
) -> dict[str, Any]:
    """Run the exact seven no-process verifiers over retained pre/post FDs."""

    paths = tuple(path for path, _pre_fd, _post_fd in images)
    pre: dict[str, bytes] = {}
    post: dict[str, bytes] = {}
    pre_stats: dict[str, os.stat_result] = {}
    post_stats: dict[str, os.stat_result] = {}
    try:
        for path, pre_fd, post_fd in images:
            pre_stats[path] = os.fstat(pre_fd)
            post_stats[path] = os.fstat(post_fd)
            pre[path] = _read_fd_bytes(pre_fd)
            post[path] = _read_fd_bytes(post_fd)
    except OSError as exc:
        raise ContractViolation("scratch image descriptor became unavailable") from exc
    context = {
        "paths": paths,
        "pre": pre,
        "post": post,
        "preStats": pre_stats,
        "postStats": post_stats,
        "sourceRoot": SOURCE_WORKSPACE_ROOT if source_root is None else source_root,
    }
    results: list[dict[str, Any]] = []
    for identifier, verifier in _THEME_SCRATCH_VERIFIERS:
        try:
            verifier(context)
        except ContractViolation:
            results.append(
                _theme_scratch_internal_result(
                    identifier,
                    status_value="failed",
                    error_code="assertion_failed",
                )
            )
        except Exception:
            results.append(
                _theme_scratch_internal_result(
                    identifier,
                    status_value="failed",
                    error_code="internal_exception",
                )
            )
        else:
            results.append(
                _theme_scratch_internal_result(
                    identifier,
                    status_value="passed",
                    error_code=None,
                )
            )
    return _theme_scratch_report(results)


def _seal_theme_batch(
    workspace_fd: int,
    batch_id: str,
    theme_run_id: str,
    *,
    fixture: dict[str, Any] | None = None,
    fault_after: str | None = None,
    syscalls: Any | None = None,
) -> dict[str, Any]:
    if type(workspace_fd) is not int or workspace_fd < 0 or not stat.S_ISDIR(os.fstat(workspace_fd).st_mode):
        raise ContractViolation("theme-batch workspace descriptor is invalid")
    if BATCH_ID_PATTERN.fullmatch(batch_id) is None or BATCH_ID_PATTERN.fullmatch(theme_run_id) is None:
        raise ContractViolation("theme-batch identifiers are invalid")
    if not isinstance(fixture, dict):
        raise ContractViolation("theme-batch sealing requires authenticated fixture authority")
    allowed_faults = {
        f"{stage}:{boundary}"
        for stage in ("sealed", "candidate", "packet")
        for boundary in ("precommit", "rename", "parent-fsync", "reopen")
    }
    if fault_after is not None and fault_after not in allowed_faults:
        raise ContractViolation("unknown theme-batch publication boundary")
    root = Path(getattr(syscalls, "root", WORKSPACE_ROOT)).resolve()
    calls = _WorkspaceClaimSyscalls(workspace_fd) if syscalls is None else syscalls
    root_contract = fixture.get("rootContract")
    if not isinstance(root_contract, dict) or set(root_contract) != {"path", "sha256", "size"}:
        raise ContractViolation("theme-batch root contract is invalid")
    root_sha = root_contract["sha256"]
    if not isinstance(root_sha, str) or re.fullmatch(r"[0-9a-f]{64}", root_sha) is None:
        raise ContractViolation("theme-batch root digest is invalid")
    if fixture.get("batchId") != batch_id or fixture.get("themeRunId") != theme_run_id or fixture.get("applyOrder") != list(APPLY_PATHS):
        raise ContractViolation("theme-batch fixture lineage/order mismatch")

    batch_relative = f".claude/ui_snapshots/ux1b/theme-batches/{root_sha}/{batch_id}"
    batch_root = root / batch_relative
    sealed_relative = f"{batch_relative}/sealed"
    sealed_root = root / sealed_relative
    candidate_relative = f"{batch_relative}/candidate.json"
    packet_relative = f"{batch_relative}/review-packet.json"
    candidate_path = root / candidate_relative
    packet_path = root / packet_relative
    publication_trace: list[str] = []
    command_launch_count = 42

    def artifact_ref(record: dict[str, Any]) -> dict[str, Any]:
        return {key: record[key] for key in ("path", "sha256", "size")}

    def source_record(record: dict[str, Any], logical: str) -> dict[str, Any]:
        return {
            "path": logical,
            "sha256": record["sha256"],
            "size": record["size"],
            "mode": record["mode"],
        }

    def write_new(path: Path, payload: bytes, mode: int = 0o600) -> None:
        path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY | os.O_NOFOLLOW, mode)
        try:
            view = memoryview(payload)
            while view:
                written = os.write(fd, view)
                if written <= 0:
                    raise OSError(errno.EIO, "short theme-batch write")
                view = view[written:]
            os.fchmod(fd, mode)
            os.fsync(fd)
        finally:
            os.close(fd)

    def copy_new(source: Path, destination: Path, mode: int | None = None) -> None:
        try:
            source_fd = os.open(source, os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0))
        except OSError as exc:
            raise ContractViolation(f"theme-batch source is unavailable: {source}") from exc
        try:
            source_stat = os.fstat(source_fd)
            if not stat.S_ISREG(source_stat.st_mode) or source_stat.st_nlink != 1:
                raise ContractViolation("theme-batch copy source is not a one-link regular file")
            payload = _read_fd_bytes(source_fd, limit=max(source_stat.st_size, 1) + 1)
        finally:
            os.close(source_fd)
        write_new(destination, payload, stat.S_IMODE(source_stat.st_mode) if mode is None else mode)

    def directory_record(path: Path, logical: str) -> dict[str, Any]:
        observed = os.lstat(path)
        if not stat.S_ISDIR(observed.st_mode) or stat.S_ISLNK(observed.st_mode):
            raise ContractViolation("candidate manifest directory is invalid")
        return {
            "path": logical,
            "mode": f"{stat.S_IMODE(observed.st_mode):04o}",
            "uid": observed.st_uid,
            "gid": observed.st_gid,
            "device": observed.st_dev,
            "inode": observed.st_ino,
        }

    def session_summary(regression: dict[str, Any]) -> dict[str, Any]:
        candidate_root = Path(regression["workspace"]["beforeManifest"]["root"]["path"])
        session_root = candidate_root.parent
        marker_path = session_root / ".quant-radar-candidate-session-owner.json"
        return {
            **directory_record(session_root, str(session_root.relative_to(root))),
            "marker": _file_record_at(root, str(marker_path.relative_to(root))),
        }

    def prefix_result(exit_code: int) -> dict[str, Any]:
        present = [
            name
            for name, path in (
                ("sealed", sealed_root), ("candidate", candidate_path), ("packet", packet_path)
            )
            if path.exists()
        ]
        return {
            "exitCode": exit_code,
            "publicPrefix": present,
            "writesAfterUncertainty": 0,
            "commandLaunchCount": command_launch_count,
            "publicationTrace": list(publication_trace),
        }

    def publish_file(stage: str, destination: str, payload: bytes) -> dict[str, Any] | None:
        destination_path = root / destination
        if destination_path.exists():
            observed = destination_path.read_bytes()
            if observed != payload:
                raise ContractViolation(f"{stage} destination collision")
            return None
        temporary = f"{Path(destination).parent}/.tmp.{Path(destination).name}.{secrets.token_hex(16)}"
        flags = os.O_CREAT | os.O_EXCL | os.O_RDWR | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        fd = calls.open_exclusive(temporary, flags, 0o600)
        try:
            calls.write_all(fd, payload)
            if hasattr(calls, "set_metadata"):
                calls.set_metadata(fd, 0o600, os.getuid(), os.getgid())
            calls.fsync_file(fd)
            if calls.rehash(fd) != hashlib.sha256(payload).hexdigest():
                raise ContractViolation(f"{stage} staged digest mismatch")
        finally:
            calls.close(fd)
        publication_trace.append(f"{stage}-precommit")
        if fault_after == f"{stage}:precommit":
            return prefix_result(EXIT_CONTRACT)
        source_inode, destination_inode = calls.rename_excl(temporary, destination)
        if source_inode != destination_inode:
            raise ContractViolation(f"{stage} publication changed inode")
        publication_trace.append(f"{stage}-rename")
        if fault_after == f"{stage}:rename":
            return prefix_result(EXIT_UNCERTAIN)
        calls.fsync_parent(str(Path(destination).parent))
        publication_trace.append(f"{stage}-parent-fsync")
        if fault_after == f"{stage}:parent-fsync":
            return prefix_result(EXIT_UNCERTAIN)
        reopened = calls.reopen(destination, os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0))
        calls.close(reopened)
        publication_trace.append(f"{stage}-reopen")
        if fault_after == f"{stage}:reopen":
            return prefix_result(EXIT_UNCERTAIN)
        return None

    batch_root.mkdir(parents=True, exist_ok=True, mode=0o700)
    if sealed_root.exists():
        try:
            report = json.loads((sealed_root / "test-report.json").read_bytes())
            bundle_manifest = json.loads((sealed_root / "bundle-manifest.json").read_bytes())
        except (OSError, ValueError, TypeError) as exc:
            raise ContractViolation("sealed theme-batch prefix is unreadable") from exc
        changes = bundle_manifest["changes"]
        regression = report["regression"]
    else:
        staging_relative = f"{batch_relative}/.tmp.sealed.{secrets.token_hex(16)}"
        staging_root = root / staging_relative
        staging_root.mkdir(mode=0o700)
        physical_names = (
            "00-config.toml", "01-app.py", "02-design.py",
            "03-requirements.txt", "04-classification.json",
        )
        pristine_root = root / fixture["pristineRoot"]
        work_root = root / fixture["workRoot"]
        patch_sections: list[bytes] = []
        changes: list[dict[str, Any]] = []
        for index, (logical, physical) in enumerate(zip(APPLY_PATHS, physical_names)):
            pre_staging = staging_root / "pre" / physical
            post_staging = staging_root / "post" / physical
            copy_new(pristine_root / logical, pre_staging)
            copy_new(work_root / logical, post_staging)
            pre_logical = f"{sealed_relative}/pre/{physical}"
            post_logical = f"{sealed_relative}/post/{physical}"
            pre_artifact = _file_record_at(root, str(pre_staging.relative_to(root)), pre_logical)
            post_artifact = _file_record_at(root, str(post_staging.relative_to(root)), post_logical)
            changes.append(
                {
                    "path": logical,
                    "preimage": {"source": source_record(pre_artifact, logical), "artifact": pre_artifact},
                    "postimage": {"source": source_record(post_artifact, logical), "artifact": post_artifact},
                }
            )
            before = (pristine_root / logical).read_text(encoding="utf-8")
            after = (work_root / logical).read_text(encoding="utf-8")
            patch_sections.append(
                "".join(
                    difflib.unified_diff(
                        before.splitlines(keepends=True), after.splitlines(keepends=True),
                        fromfile="a/" + logical, tofile="b/" + logical, lineterm="\n",
                    )
                ).encode("utf-8")
            )
        patch_bytes = b"".join(patch_sections)
        write_new(staging_root / ".quant-radar-theme-batch-owner", _canonical_json_bytes({"schemaVersion": "quant-radar-ui-ux-theme-batch-owner/v1", "batchId": batch_id, "themeRunId": theme_run_id}))
        write_new(staging_root / "theme.patch", patch_bytes)

        candidate_source_root = _candidate_source_root_for_seal(root, fixture)
        scratch_images: list[tuple[str, int, int]] = []
        try:
            for index, logical in enumerate(APPLY_PATHS):
                pre_fd = os.open(
                    staging_root / "pre" / physical_names[index],
                    os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
                )
                try:
                    post_fd = os.open(
                        staging_root / "post" / physical_names[index],
                        os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
                    )
                except Exception:
                    os.close(pre_fd)
                    raise
                scratch_images.append((logical, pre_fd, post_fd))
            scratch = _run_theme_scratch_verifiers(
                scratch_images,
                source_root=candidate_source_root,
            )
        finally:
            for _logical, pre_fd, post_fd in scratch_images:
                os.close(pre_fd)
                os.close(post_fd)
        if scratch["status"] != "passed":
            failed_ids = [
                row["id"] for row in scratch["results"] if row["status"] == "failed"
            ]
            raise ContractViolation(
                "theme scratch verification failed: " + ", ".join(failed_ids)
            )

        runtime_relative = fixture.get("runtimeRoot")
        if (
            not isinstance(runtime_relative, str)
            or not _is_safe_relative_path(runtime_relative)
        ):
            raise ContractViolation(
                "theme-batch runtime root is invalid"
            )
        runtime_root = root / runtime_relative
        runtime_root.mkdir(mode=0o700, exist_ok=True)
        session_nonce = secrets.token_hex(16)
        marker = {
            "schemaVersion": "quant-radar-ui-ux-candidate-session/v1",
            "status": "active",
            "rootContract": copy.deepcopy(root_contract),
            "batchId": batch_id,
            "themeRunId": theme_run_id,
            "sessionNonce": session_nonce,
            "ownerUid": os.getuid(),
            "ownerPid": os.getpid(),
            "createdAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        }
        session_result = _candidate_session_transition(
            workspace_fd,
            {
                "tempParent": runtime_relative, "sessionNonce": session_nonce,
                "batchId": batch_id, "themeRunId": theme_run_id, "marker": marker,
            },
            "create-before-spawn",
            syscalls=calls,
        )
        if session_result["exitCode"] != EXIT_SUCCESS:
            return session_result
        session_root = root / session_result["session"]["path"]
        candidate_root = session_root / "candidate"
        candidate_root.mkdir(mode=0o700)
        candidate_source_fd = os.open(
            candidate_source_root,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
        )
        candidate_fd = os.open(
            candidate_root,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
        )
        overlay_fds: dict[str, int] = {}
        try:
            for index, change in enumerate(changes):
                overlay_fds[change["path"]] = os.open(
                    staging_root / "post" / physical_names[index],
                    os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
                )
            _materialize_candidate_workspace(
                candidate_source_fd,
                candidate_fd,
                venv_target=str(SOURCE_WORKSPACE_ROOT / ".venv"),
                overlay_fds=overlay_fds,
                lifecycle_prefix=batch_relative,
            )
        finally:
            for overlay_fd in overlay_fds.values():
                os.close(overlay_fd)
            os.close(candidate_fd)
            os.close(candidate_source_fd)
        reports_root = candidate_root / "reports"
        reports_root.mkdir(mode=0o700)
        (reports_root / "run_status").mkdir(mode=0o700)
        session_root_fd = os.open(
            session_root,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
        )
        candidate_fd = os.open(
            candidate_root,
            os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
            | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
        )
        try:
            regression_plan = _build_candidate_regression_plan(
                session_root_fd,
                candidate_fd,
            )
            regression_driver = _CandidateRegressionProcessDriver(
                plans=regression_plan,
                session_root=session_root,
                candidate_root=candidate_root,
            )
            regression = _run_candidate_regression(
                candidate_fd,
                regression_plan,
                session_root_fd=session_root_fd,
                probe_driver=regression_driver,
                sealed_overlay={
                    change["path"]: change["postimage"]["artifact"]
                    for change in changes
                },
            )
        finally:
            os.close(candidate_fd)
            os.close(session_root_fd)
        report_body = {
            "schemaVersion": "quant-radar-ui-ux-theme-batch-tests/v1",
            "status": "passed", "scratch": scratch, "regression": regression,
        }
        report = {**report_body, "sha256": hashlib.sha256(_canonical_json_bytes(report_body)).hexdigest()}
        write_new(staging_root / "test-report.json", _canonical_json_bytes(report))
        publication_trace.append("test-report-staged")
        owner_record = _file_record_at(root, f"{staging_relative}/.quant-radar-theme-batch-owner", f"{sealed_relative}/.quant-radar-theme-batch-owner")
        patch_record = _file_record_at(root, f"{staging_relative}/theme.patch", f"{sealed_relative}/theme.patch")
        test_record = _file_record_at(root, f"{staging_relative}/test-report.json", f"{sealed_relative}/test-report.json")
        mirror_comparison = fixture.get("mirrorComparison")
        supplemental_comparison = fixture.get(
            "supplementalComparison"
        )
        if (
            not isinstance(mirror_comparison, dict)
            or not isinstance(supplemental_comparison, dict)
        ):
            comparison = {
                "before": {},
                "after": {},
                "allowedChangedPaths": list(APPLY_PATHS),
                "changes": [],
                "unchangedRecordsSha256": hashlib.sha256(
                    _canonical_json_bytes([])
                ).hexdigest(),
            }
            mirror_comparison = comparison
            supplemental_comparison = copy.deepcopy(comparison)
        bundle_manifest = {
            "schemaVersion": "quant-radar-ui-ux-theme-batch-bundle/v1",
            "status": "sealed", "rootContract": copy.deepcopy(root_contract),
            "batchId": batch_id, "themeRunId": theme_run_id,
            "ownerMarker": owner_record, "changes": changes, "patch": patch_record,
            "testReport": test_record,
            "mirrorComparison": copy.deepcopy(mirror_comparison),
            "supplementalComparison": copy.deepcopy(
                supplemental_comparison
            ),
            "namespaceLeafCount": 14, "selfHash": "omitted-by-contract",
        }
        write_new(staging_root / "bundle-manifest.json", _canonical_json_bytes(bundle_manifest))
        publication_trace.append("bundle-manifest-staged")
        calls.fsync_parent(staging_relative)
        calls.fsync_parent(batch_relative)
        publication_trace.append("sealed-precommit")
        if fault_after == "sealed:precommit":
            return prefix_result(EXIT_CONTRACT)
        source_inode, destination_inode = calls.rename_excl(staging_relative, sealed_relative)
        if source_inode != destination_inode:
            raise ContractViolation("sealed directory publication changed inode")
        publication_trace.append("sealed-rename")
        if fault_after == "sealed:rename":
            return prefix_result(EXIT_UNCERTAIN)
        calls.fsync_parent(batch_relative)
        publication_trace.append("sealed-parent-fsync")
        if fault_after == "sealed:parent-fsync":
            return prefix_result(EXIT_UNCERTAIN)
        sealed_fd = calls.reopen(sealed_relative, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0))
        calls.close(sealed_fd)
        publication_trace.append("sealed-reopen")
        if fault_after == "sealed:reopen":
            return prefix_result(EXIT_UNCERTAIN)

    bundle_record = _file_record_at(root, f"{sealed_relative}/bundle-manifest.json")
    patch_record = bundle_manifest["patch"]
    test_record = bundle_manifest["testReport"]
    candidate_value = {
        "schemaVersion": "quant-radar-ui-ux-theme-batch-candidate/v2",
        "status": "candidate", "rootContract": copy.deepcopy(root_contract),
        "batchId": batch_id, "themeRunId": theme_run_id,
        "prechange": copy.deepcopy(fixture["prechange"]),
        "bundleManifest": artifact_ref(bundle_record),
        "changes": copy.deepcopy(changes), "patch": artifact_ref(patch_record),
        "testReport": artifact_ref(test_record),
        "mirrorComparison": copy.deepcopy(bundle_manifest["mirrorComparison"]),
        "supplementalComparison": copy.deepcopy(bundle_manifest["supplementalComparison"]),
        "runtimeReceipt": copy.deepcopy(fixture["runtimeReceipt"]),
        "changesSha256": hashlib.sha256(_canonical_json_bytes(changes)).hexdigest(),
    }
    _validate_schema(candidate_value["schemaVersion"], candidate_value)
    candidate_bytes = _canonical_json_bytes(candidate_value)
    result = publish_file("candidate", candidate_relative, candidate_bytes)
    if result is not None:
        return result
    candidate_record = _file_record_at(root, candidate_relative)
    candidate_ref = artifact_ref(candidate_record)
    items = []
    patch_sources: dict[str, tuple[bytes, bytes]] = {}
    for change in changes:
        pre_path = root / change["preimage"]["artifact"]["path"]
        post_path = root / change["postimage"]["artifact"]["path"]
        patch_sources[change["path"]] = (
            pre_path.read_bytes(),
            post_path.read_bytes(),
        )
    patch_contract = _build_theme_patch(patch_sources)
    patch_sections = {
        row["path"]: row["sha256"]
        for row in patch_contract["sections"]
    }
    for change in changes:
        items.append(
            {
                "id": change["path"], "path": change["path"],
                "preimage": change["preimage"]["source"],
                "postimage": change["postimage"]["source"],
                "patchSectionSha256": patch_sections[change["path"]],
            }
        )
    packet_value = _build_review_packet(
        "theme-batch",
        root_contract,
        batch_id,
        candidate_ref,
        (
            root_contract,
            fixture["prechange"],
            artifact_ref(bundle_record),
            artifact_ref(patch_record),
            artifact_ref(test_record),
            candidate_ref,
        ),
        items,
        patch_sources=patch_sources,
    )
    _validate_review_packet_value(packet_value)
    result = publish_file("packet", packet_relative, _canonical_json_bytes(packet_value))
    if result is not None:
        return result
    return {
        **prefix_result(EXIT_SUCCESS),
        "namespaceLeafCount": 14,
        "changes": changes,
        "testReport": report,
        "candidateSession": session_summary(regression),
        "publicPrefixes": [[], ["sealed"], ["sealed", "candidate"], ["sealed", "candidate", "packet"]],
    }


