def _historical_stack_authorization_body() -> dict[str, Any]:
    return {
        "schemaVersion": (
            "quant-radar-ui-ux-formal-handoff-"
            "historical-stack-comparator-correction-"
            "authorization/v1"
        ),
        "sequence": 14,
        "status": "AUTHORIZED",
        "correctionId": HISTORICAL_STACK_CORRECTION_ID,
        "tierId": HISTORICAL_STACK_TIER_ID,
        "captureId": HISTORICAL_STACK_CAPTURE_ID,
        "continuationId": HISTORICAL_STACK_CONTINUATION_ID,
        "plan": copy.deepcopy(HISTORICAL_STACK_PLAN_REF),
        "traceability": copy.deepcopy(
            HISTORICAL_STACK_LEDGER_REF
        ),
        "retainedM1": [
            {
                key: row[key]
                for key in ("path", "sha256", "size", "mode")
            }
            for row in SEQUENCE13_M1_REFS
        ],
        "legacyStack": copy.deepcopy(
            LEGACY_HISTORICAL_STACK_REF
        ),
        "currentStack": copy.deepcopy(
            SEQUENCE13_CAPTURE_STACK_REF
        ),
        "evidenceValidator": copy.deepcopy(
            HISTORICAL_STACK_EVIDENCE_REF
        ),
        "sourcePackagePaths": list(
            HISTORICAL_STACK_PACKAGE_PATHS
        ),
        "allowedCommands": list(
            HISTORICAL_STACK_ALLOWED_COMMANDS
        ),
        "formalPause": "H2_PACKET",
        "noCaptureAuthority": True,
        "cardinalities": {
            "logicalRequests": 36,
            "rootCaptures": 44,
            "artifactLeaves": 88,
            "manifestLeaves": 89,
            "pageComparisons": 81,
            "controlRootComparisons": 44,
            "reviewItems": 125,
            "legacySemanticComparisons": 117,
        },
        "precedence": [
            {
                "authority": (
                    "sequence14-historical-stack-"
                    "comparator-correction"
                ),
                "level": 1,
            },
            {
                "authority": "sequence13-retained-m1-history",
                "level": 2,
            },
        ],
    }


def _historical_stack_authorization_document_bytes() -> bytes:
    body = _canonical_json_bytes(
        _historical_stack_authorization_body()
    ).decode("utf-8")
    return (
        "# Quant Radar UX-1B Sequence 14 Historical-Stack "
        "Comparator Correction\n\n"
        "Status: authorization candidate only. This document does not "
        "authorize bootstrap, preflight, migration-report publication, "
        "review-packet publication, external review, root publication, "
        "capture, recapture, retry, or theme changes until the repository "
        "maintainer separately accepts its final whole-document SHA-256, "
        "byte size, and mode.\n\n"
        + HISTORICAL_STACK_AUTH_START.decode("ascii")
        + body
        + HISTORICAL_STACK_AUTH_END.decode("ascii")
        + "\n\nSequence 14 imports the exact retained Sequence 13 "
        "`M1_CAPTURE` without rebuilding its creation-time source "
        "authority. It authenticates the immutable legacy stack only from "
        "its exact whole-file bytes and embedded records, keeps the "
        "Sequence 13 stack live-member bound, publishes only the distinct "
        "81-page plus 44-root migration report and 125-item review packet, "
        "and stops at `H2_PACKET`. No capture command is authorized.\n"
    ).encode("utf-8")


def _parse_historical_stack_authorization_record(
    source_root_fd: int,
) -> dict[str, Any]:
    record, document = _source_file_record(
        source_root_fd,
        HISTORICAL_STACK_AUTHORIZATION_DOCUMENT_PATH,
    )
    if (
        record["mode"] != "0644"
        or record["uid"] != os.getuid()
        or record["gid"] != os.getgid()
        or record["nlink"] != 1
    ):
        raise ContractViolation(
            "Sequence 14 authorization metadata differs"
        )
    if (
        document.count(HISTORICAL_STACK_AUTH_GENERIC) != 2
        or document.count(HISTORICAL_STACK_AUTH_START) != 1
        or document.count(HISTORICAL_STACK_AUTH_END) != 1
    ):
        raise ContractViolation(
            "Sequence 14 authorization markers differ"
        )
    start = document.find(HISTORICAL_STACK_AUTH_START)
    end = document.find(
        HISTORICAL_STACK_AUTH_END,
        start + len(HISTORICAL_STACK_AUTH_START),
    )
    body = document[
        start + len(HISTORICAL_STACK_AUTH_START) : end
    ]
    if (
        start < 0
        or end < start + len(HISTORICAL_STACK_AUTH_START)
        or not body
        or b"\n" in body
        or b"\r" in body
        or body.strip() != body
    ):
        raise ContractViolation(
            "Sequence 14 authorization envelope differs"
        )
    parsed = _strict_json_bytes(body)
    expected = _historical_stack_authorization_body()
    if (
        not isinstance(parsed, dict)
        or parsed != expected
        or set(parsed) != set(expected)
        or isinstance(parsed.get("sequence"), bool)
    ):
        raise ContractViolation(
            "Sequence 14 authorization package differs"
        )
    for expected_ref in (
        HISTORICAL_STACK_PLAN_REF,
        HISTORICAL_STACK_LEDGER_REF,
        SEQUENCE13_CAPTURE_STACK_REF,
        HISTORICAL_STACK_EVIDENCE_REF,
    ):
        observed, _ = _source_file_record(
            source_root_fd,
            expected_ref["path"],
        )
        if {
            key: observed[key]
            for key in ("path", "sha256", "size", "mode")
        } != {
            key: expected_ref[key]
            for key in ("path", "sha256", "size", "mode")
        }:
            raise ContractViolation(
                "Sequence 14 authority drifted: "
                + expected_ref["path"]
            )
    return parsed


def _historical_stack_authorization_binding(
    source_root_fd: int,
) -> dict[str, Any]:
    _parse_historical_stack_authorization_record(
        source_root_fd
    )
    record, document = _source_file_record(
        source_root_fd,
        HISTORICAL_STACK_AUTHORIZATION_DOCUMENT_PATH,
    )
    start = document.find(HISTORICAL_STACK_AUTH_START)
    end = document.find(
        HISTORICAL_STACK_AUTH_END,
        start + len(HISTORICAL_STACK_AUTH_START),
    )
    body = document[
        start + len(HISTORICAL_STACK_AUTH_START) : end
    ]
    return {
        **_artifact_ref(record),
        "bodySha256": hashlib.sha256(body).hexdigest(),
    }


def _build_historical_stack_source_projections(
    source_root_fd: int,
) -> dict[str, Any]:
    base = _build_preflight_source_projections(source_root_fd)
    mirror = base["sourceProjection"]
    mirror_paths = {
        row["path"] for row in mirror["records"]
    }
    records = {
        row["path"]: copy.deepcopy(row)
        for row in base["supplementalProjection"]["records"]
    }
    for relative in HISTORICAL_STACK_PACKAGE_PATHS:
        if relative in mirror_paths:
            continue
        record, _ = _source_file_record(
            source_root_fd,
            relative,
        )
        records[relative] = {
            "path": relative,
            "sha256": record["sha256"],
            "size": record["size"],
            "mode": (
                "0555"
                if int(record["mode"], 8) & 0o111
                else "0444"
            ),
        }
    paths = sorted(records)
    return {
        "sourceProjection": mirror,
        "supplementalProjection": _source_projection_value(
            "quant-radar-ui-ux-supplemental-source/v1",
            paths,
            mirror["policy"]["include"],
            [records[path] for path in paths],
        ),
    }


def _historical_stack_initial_namespace_inventory(
    workspace_fd: int,
    *,
    require_empty: bool = True,
) -> dict[str, Any]:
    intake_directory = posixpath.dirname(
        HISTORICAL_STACK_FORWARD_PATHS[2]
    )
    intake_stat = _relative_leaf_lstat(
        workspace_fd,
        intake_directory,
    )
    if intake_stat is not None and (
        not stat.S_ISDIR(intake_stat.st_mode)
        or stat.S_IMODE(intake_stat.st_mode) != 0o700
        or intake_stat.st_uid != os.getuid()
        or intake_stat.st_gid != os.getgid()
    ):
        raise ContractViolation(
            "Sequence 14 review-intake directory is unsafe"
        )
    if require_empty and any(
        _relative_leaf_lstat(workspace_fd, relative)
        is not None
        for relative in HISTORICAL_STACK_FORWARD_PATHS
    ):
        raise ContractViolation(
            "Sequence 14 initial namespace is not empty"
        )
    return {
        "schemaVersion": (
            "quant-radar-ui-ux-historical-stack-"
            "namespace-inventory/v1"
        ),
        "forwardPaths": list(HISTORICAL_STACK_FORWARD_PATHS),
        "initialState": "H0_READY",
        "reviewIntakeDirectory": {
            "path": intake_directory,
            "exists": intake_stat is not None,
            "safeOwned": True,
        },
    }


def _classify_historical_stack_forward_prefix(
    workspace_fd: int,
) -> dict[str, Any]:
    records: list[dict[str, Any] | None] = []
    values: list[dict[str, Any] | None] = []
    payloads: list[bytes | None] = []
    present: list[bool] = []
    for relative in HISTORICAL_STACK_FORWARD_PATHS:
        if _relative_leaf_lstat(workspace_fd, relative) is None:
            records.append(None)
            values.append(None)
            payloads.append(None)
            present.append(False)
            continue
        record, payload = _relative_regular_record_and_bytes(
            workspace_fd,
            relative,
        )
        if (
            record["mode"] != "0600"
            or record["uid"] != os.getuid()
            or record["gid"] != os.getgid()
            or record["nlink"] != 1
        ):
            raise ContractViolation(
                "Sequence 14 forward leaf is unsafe: "
                + relative
            )
        value = _strict_json_bytes(payload, allow_float=True)
        if (
            not isinstance(value, dict)
            or payload != _canonical_json_bytes(value)
        ):
            raise ContractViolation(
                "Sequence 14 forward leaf is noncanonical: "
                + relative
            )
        records.append(record)
        values.append(value)
        payloads.append(payload)
        present.append(True)
    count = 0
    while count < len(present) and present[count]:
        count += 1
    if present != [True] * count + [False] * (
        len(present) - count
    ):
        raise ContractViolation(
            "Sequence 14 forward namespace is not a prefix"
        )
    return {
        "state": HISTORICAL_STACK_FORWARD_STATES[count],
        "present": present,
        "records": records,
        "values": values,
        "payloads": payloads,
    }


def _historical_stack_make_contract(
    source_root_fd: int,
) -> dict[str, Any]:
    record, payload = _source_file_record(
        source_root_fd,
        "Makefile",
    )
    text = payload.decode("utf-8", errors="strict")
    targets = (
        "ui-ux1b-historical-stack-bootstrap",
        "ui-ux1b-historical-stack-preflight",
        "ui-ux1b-historical-stack-verify",
        "ui-ux1b-historical-stack-compare",
        "ui-ux1b-historical-stack-prepare-review",
    )
    if any(
        text.count(target + ":") != 1 for target in targets
    ):
        raise ContractViolation(
            "Sequence 14 Make contract differs"
        )
    return {
        "artifact": _artifact_ref(record),
        "targets": list(targets),
        "targetsSha256": hashlib.sha256(
            _canonical_json_bytes(list(targets))
        ).hexdigest(),
    }


def _historical_stack_archive_bytes(
    source_root_fd: int,
) -> tuple[bytes, list[dict[str, Any]]]:
    output = io.BytesIO()
    records: list[dict[str, Any]] = []
    with tarfile.open(
        fileobj=output,
        mode="w",
        format=tarfile.PAX_FORMAT,
    ) as archive:
        for relative in HISTORICAL_STACK_PACKAGE_PATHS:
            record, payload = _source_file_record(
                source_root_fd,
                relative,
            )
            records.append(record)
            member = tarfile.TarInfo(relative)
            member.size = len(payload)
            member.mode = stat.S_IMODE(
                int(record["mode"], 8)
            )
            member.uid = 0
            member.gid = 0
            member.uname = ""
            member.gname = ""
            member.mtime = 0
            archive.addfile(member, io.BytesIO(payload))
    return output.getvalue(), records


def _historical_stack_tier_values(
    *,
    lease_record: Mapping[str, Any],
    retained_m1: Mapping[str, Any],
    historical_stack: Mapping[str, Any],
    current_stack: Mapping[str, Any],
    authorization: Mapping[str, Any],
    package_records: Sequence[Mapping[str, Any]],
    prechange_record: Mapping[str, Any] | None = None,
    owner_record: Mapping[str, Any] | None = None,
    archive_record: Mapping[str, Any] | None = None,
    bundle_record: Mapping[str, Any] | None = None,
) -> dict[str, dict[str, Any]]:
    package = [
        _artifact_ref(record)
        for record in sorted(
            package_records,
            key=lambda item: item["path"],
        )
    ]
    if len(package) != len(HISTORICAL_STACK_PACKAGE_PATHS):
        raise ContractViolation(
            "Sequence 14 source package cardinality differs"
        )
    prechange = {
        "schemaVersion": (
            "quant-radar-ui-ux-historical-stack-"
            "correction-prechange/v1"
        ),
        "status": "captured",
        "correctionId": HISTORICAL_STACK_CORRECTION_ID,
        "tierId": HISTORICAL_STACK_TIER_ID,
        "captureId": HISTORICAL_STACK_CAPTURE_ID,
        "continuationId": HISTORICAL_STACK_CONTINUATION_ID,
        "authorizationRecord": copy.deepcopy(
            dict(authorization)
        ),
        "plan": copy.deepcopy(HISTORICAL_STACK_PLAN_REF),
        "traceability": copy.deepcopy(
            HISTORICAL_STACK_LEDGER_REF
        ),
        "retainedM1": copy.deepcopy(dict(retained_m1)),
        "historicalStack": copy.deepcopy(
            dict(historical_stack)
        ),
        "currentStack": copy.deepcopy(dict(current_stack)),
        "package": package,
        "bundlePath": HISTORICAL_STACK_TIER_DESTINATIONS[4],
        "lease": copy.deepcopy(dict(lease_record)),
    }
    owner = {
        "schemaVersion": (
            "quant-radar-ui-ux-historical-stack-"
            "correction-owner/v1"
        ),
        "correctionId": HISTORICAL_STACK_CORRECTION_ID,
        "tierId": HISTORICAL_STACK_TIER_ID,
    }
    values = {"prechange": prechange, "owner": owner}
    if owner_record is not None and archive_record is not None:
        values["bundle"] = {
            "schemaVersion": (
                "quant-radar-ui-ux-historical-stack-"
                "correction-bundle/v1"
            ),
            "status": "sealed",
            "correctionId": HISTORICAL_STACK_CORRECTION_ID,
            "tierId": HISTORICAL_STACK_TIER_ID,
            "ownerMarker": _artifact_ref(owner_record),
            "archive": _artifact_ref(archive_record),
            "archivedPaths": list(
                HISTORICAL_STACK_PACKAGE_PATHS
            ),
            "namespaceLeafCount": 3,
        }
    if prechange_record is not None and bundle_record is not None:
        values["rollback"] = {
            "schemaVersion": (
                "quant-radar-ui-ux-historical-stack-"
                "correction-rollback/v1"
            ),
            "status": "ready",
            "correctionId": HISTORICAL_STACK_CORRECTION_ID,
            "tierId": HISTORICAL_STACK_TIER_ID,
            "prechange": _artifact_ref(prechange_record),
            "bundleManifest": _artifact_ref(bundle_record),
            "entries": [
                {
                    "path": record["path"],
                    "artifact": _artifact_ref(record),
                    "disposition": "restore_whole_if_exact",
                }
                for record in sorted(
                    package_records,
                    key=lambda item: item["path"],
                )
            ],
            "destructiveGitAllowed": False,
        }
    return values


def _validate_historical_stack_tier_complete(
    workspace_fd: int,
    source_root_fd: int,
) -> dict[str, Any]:
    retained_m1 = _import_sequence13_m1_capture(
        workspace_fd,
        source_root_fd=source_root_fd,
    )
    historical = (
        _reauthenticate_legacy_capture_stack_history(
            workspace_fd,
            source_root_fd=source_root_fd,
        )
    )
    current = _import_sequence13_capture_stack_history(
        workspace_fd,
        source_root_fd=source_root_fd,
    )
    authorization = _historical_stack_authorization_binding(
        source_root_fd
    )
    archive_bytes, package_records = (
        _historical_stack_archive_bytes(source_root_fd)
    )
    paths = HISTORICAL_STACK_TIER_DESTINATIONS
    lease_record, lease_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[1],
        )
    )
    prechange_record, prechange_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[2],
        )
    )
    rollback_record, rollback_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[3],
        )
    )
    directory = _open_relative_directory_fd(
        workspace_fd,
        paths[4],
    )
    try:
        metadata = os.fstat(directory)
        if (
            stat.S_IMODE(metadata.st_mode) != 0o700
            or metadata.st_uid != os.getuid()
            or metadata.st_gid != os.getgid()
            or set(os.listdir(directory))
            != {
                PurePosixPath(paths[5]).name,
                PurePosixPath(paths[6]).name,
                PurePosixPath(paths[7]).name,
            }
        ):
            raise ContractViolation(
                "Sequence 14 Tier directory differs"
            )
    finally:
        os.close(directory)
    owner_record, owner_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[5],
        )
    )
    archive_record, observed_archive = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[6],
        )
    )
    bundle_record, bundle_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[7],
        )
    )
    values = _historical_stack_tier_values(
        lease_record=lease_record,
        retained_m1=_sequence13_m1_projection(retained_m1),
        historical_stack=(
            _legacy_historical_stack_projection(historical)
        ),
        current_stack=current,
        authorization=authorization,
        package_records=package_records,
        prechange_record=prechange_record,
        owner_record=owner_record,
        archive_record=archive_record,
        bundle_record=bundle_record,
    )
    if (
        lease_bytes != b""
        or observed_archive != archive_bytes
        or prechange_bytes
        != _canonical_json_bytes(values["prechange"])
        or owner_bytes != _canonical_json_bytes(values["owner"])
        or bundle_bytes != _canonical_json_bytes(values["bundle"])
        or rollback_bytes
        != _canonical_json_bytes(values["rollback"])
    ):
        raise ContractViolation(
            "Sequence 14 Tier bytes differ"
        )
    return {
        "lease": _artifact_ref(lease_record),
        "prechange": _artifact_ref(prechange_record),
        "rollback": _artifact_ref(rollback_record),
        "owner": _artifact_ref(owner_record),
        "archive": _artifact_ref(archive_record),
        "bundle": _artifact_ref(bundle_record),
    }


def _bootstrap_historical_stack_correction(
    workspace_fd: int,
    *,
    source_root_fd: int,
) -> dict[str, Any]:
    _parse_historical_stack_authorization_record(
        source_root_fd
    )
    if (
        _classify_historical_stack_forward_prefix(
            workspace_fd
        )["state"]
        != "H0_READY"
    ):
        raise ContractViolation(
            "Sequence 14 bootstrap requires H0_READY"
        )
    archive_bytes, package_records = (
        _historical_stack_archive_bytes(source_root_fd)
    )
    created_any = False
    paths = HISTORICAL_STACK_TIER_DESTINATIONS
    with _lifecycle_correction_global_lock(workspace_fd):
        retained_m1 = _import_sequence13_m1_capture(
            workspace_fd,
            source_root_fd=source_root_fd,
        )
        historical = (
            _reauthenticate_legacy_capture_stack_history(
                workspace_fd,
                source_root_fd=source_root_fd,
            )
        )
        current = _import_sequence13_capture_stack_history(
            workspace_fd,
            source_root_fd=source_root_fd,
        )
        authorization = (
            _historical_stack_authorization_binding(
                source_root_fd
            )
        )
        lease_record, created = (
            _publish_or_reopen_continuation_file(
                workspace_fd,
                paths[1],
                b"",
            )
        )
        created_any = created_any or created
        initial = _historical_stack_tier_values(
            lease_record=lease_record,
            retained_m1=_sequence13_m1_projection(
                retained_m1
            ),
            historical_stack=(
                _legacy_historical_stack_projection(historical)
            ),
            current_stack=current,
            authorization=authorization,
            package_records=package_records,
        )
        prechange_record, created = (
            _publish_or_reopen_continuation_file(
                workspace_fd,
                paths[2],
                _canonical_json_bytes(initial["prechange"]),
            )
        )
        created_any = created_any or created
        bundle_fd = _ensure_relative_directory_fd(
            workspace_fd,
            paths[4],
        )
        os.close(bundle_fd)
        owner_record, created = (
            _publish_or_reopen_continuation_file(
                workspace_fd,
                paths[5],
                _canonical_json_bytes(initial["owner"]),
            )
        )
        created_any = created_any or created
        archive_record, created = (
            _publish_or_reopen_continuation_file(
                workspace_fd,
                paths[6],
                archive_bytes,
            )
        )
        created_any = created_any or created
        completed = _historical_stack_tier_values(
            lease_record=lease_record,
            retained_m1=_sequence13_m1_projection(
                retained_m1
            ),
            historical_stack=(
                _legacy_historical_stack_projection(historical)
            ),
            current_stack=current,
            authorization=authorization,
            package_records=package_records,
            prechange_record=prechange_record,
            owner_record=owner_record,
            archive_record=archive_record,
        )
        bundle_record, created = (
            _publish_or_reopen_continuation_file(
                workspace_fd,
                paths[7],
                _canonical_json_bytes(completed["bundle"]),
            )
        )
        created_any = created_any or created
        completed = _historical_stack_tier_values(
            lease_record=lease_record,
            retained_m1=_sequence13_m1_projection(
                retained_m1
            ),
            historical_stack=(
                _legacy_historical_stack_projection(historical)
            ),
            current_stack=current,
            authorization=authorization,
            package_records=package_records,
            prechange_record=prechange_record,
            owner_record=owner_record,
            archive_record=archive_record,
            bundle_record=bundle_record,
        )
        rollback_record, created = (
            _publish_or_reopen_continuation_file(
                workspace_fd,
                paths[3],
                _canonical_json_bytes(completed["rollback"]),
            )
        )
        created_any = created_any or created
        _validate_historical_stack_tier_complete(
            workspace_fd,
            source_root_fd,
        )
    return {
        "exitCode": EXIT_SUCCESS,
        "created": created_any,
        "prechange": _artifact_ref(prechange_record),
        "rollback": _artifact_ref(rollback_record),
    }


def _build_historical_stack_preflight_value(
    workspace_fd: int,
    source_root_fd: int,
    *,
    require_ready: bool = True,
) -> dict[str, Any]:
    tier = _validate_historical_stack_tier_complete(
        workspace_fd,
        source_root_fd,
    )
    if require_ready and (
        _classify_historical_stack_forward_prefix(
            workspace_fd
        )["state"]
        != "H0_READY"
    ):
        raise ContractViolation(
            "Sequence 14 preflight requires H0_READY"
        )
    retained_m1 = _import_sequence13_m1_capture(
        workspace_fd,
        source_root_fd=source_root_fd,
    )
    historical = (
        _reauthenticate_legacy_capture_stack_history(
            workspace_fd,
            source_root_fd=source_root_fd,
        )
    )
    current = _import_sequence13_capture_stack_history(
        workspace_fd,
        source_root_fd=source_root_fd,
    )
    projections = _build_historical_stack_source_projections(
        source_root_fd
    )
    return {
        "schemaVersion": (
            "quant-radar-ui-ux-historical-stack-"
            "correction-preflight/v1"
        ),
        "status": "passed",
        "correctionId": HISTORICAL_STACK_CORRECTION_ID,
        "tierId": HISTORICAL_STACK_TIER_ID,
        "captureId": HISTORICAL_STACK_CAPTURE_ID,
        "continuationId": HISTORICAL_STACK_CONTINUATION_ID,
        "authorizationRecord": (
            _historical_stack_authorization_binding(
                source_root_fd
            )
        ),
        "plan": copy.deepcopy(HISTORICAL_STACK_PLAN_REF),
        "traceability": copy.deepcopy(
            HISTORICAL_STACK_LEDGER_REF
        ),
        "retainedM1": _sequence13_m1_projection(
            retained_m1
        ),
        "historicalStack": (
            _legacy_historical_stack_projection(historical)
        ),
        "currentStack": current,
        "sourceProjection": projections["sourceProjection"],
        "supplementalProjection": projections[
            "supplementalProjection"
        ],
        "runtimeReceipt": _import_sequence12_runtime_history(
            workspace_fd
        ),
        "makeContract": _historical_stack_make_contract(
            source_root_fd
        ),
        "namespaceInventory": (
            _historical_stack_initial_namespace_inventory(
                workspace_fd,
                require_empty=require_ready,
            )
        ),
        "descriptorProfile": _build_descriptor_profile(),
        "tier": tier,
    }


def _validate_historical_stack_preflight_complete(
    workspace_fd: int,
    source_root_fd: int,
    value: Mapping[str, Any],
) -> dict[str, Any]:
    expected = _build_historical_stack_preflight_value(
        workspace_fd,
        source_root_fd,
        require_ready=False,
    )
    if (
        not isinstance(value, Mapping)
        or dict(value) != expected
        or set(value) != set(expected)
    ):
        raise ContractViolation(
            "Sequence 14 preflight differs"
        )
    return copy.deepcopy(expected)


def _reauthenticate_historical_stack_preflight(
    workspace_fd: int,
    source_root_fd: int,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    record, payload = _relative_regular_record_and_bytes(
        workspace_fd,
        HISTORICAL_STACK_PREFLIGHT_PATH,
    )
    value = _strict_json_bytes(payload, allow_float=True)
    if (
        not isinstance(value, dict)
        or payload != _canonical_json_bytes(value)
    ):
        raise ContractViolation(
            "Sequence 14 preflight is noncanonical"
        )
    authenticated = (
        _validate_historical_stack_preflight_complete(
            workspace_fd,
            source_root_fd,
            value,
        )
    )
    current = _classify_historical_stack_forward_prefix(
        workspace_fd
    )
    return record, authenticated, current


def _historical_stack_preflight_lifecycle(
    workspace_fd: int,
    *,
    source_root_fd: int,
    verify_only: bool,
) -> dict[str, Any]:
    with _lifecycle_correction_global_lock(workspace_fd):
        if verify_only:
            record, _, current = (
                _reauthenticate_historical_stack_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            return {
                "exitCode": EXIT_SUCCESS,
                "created": False,
                "state": current["state"],
                "preflight": _artifact_ref(record),
            }
        value = _build_historical_stack_preflight_value(
            workspace_fd,
            source_root_fd,
        )
        record, created = (
            _publish_or_reopen_continuation_file(
                workspace_fd,
                HISTORICAL_STACK_PREFLIGHT_PATH,
                _canonical_json_bytes(value),
            )
        )
        reopened, _, current = (
            _reauthenticate_historical_stack_preflight(
                workspace_fd,
                source_root_fd,
            )
        )
        if (
            _artifact_ref(reopened) != _artifact_ref(record)
            or current["state"] != "H0_READY"
        ):
            raise ContractViolation(
                "Sequence 14 preflight postcondition differs"
            )
        return {
            "exitCode": EXIT_SUCCESS,
            "created": created,
            "state": current["state"],
            "preflight": _artifact_ref(record),
        }


def _validate_historical_stack_forward_semantics(
    workspace_fd: int,
    source_root_fd: int,
    *,
    preflight: Mapping[str, Any],
) -> dict[str, Any]:
    retained_m1 = _import_sequence13_m1_capture(
        workspace_fd,
        source_root_fd=source_root_fd,
    )
    if preflight.get("retainedM1") != _sequence13_m1_projection(
        retained_m1
    ):
        raise ContractViolation(
            "Sequence 14 retained M1 preflight binding differs"
        )
    current = _classify_historical_stack_forward_prefix(
        workspace_fd
    )
    state = current["state"]
    if state == "H0_READY":
        return current
    report = current["values"][0]
    expected_exclusion = {
        "classification": "S12_TERMINAL_FAILED",
        "manifest": copy.deepcopy(
            SEQUENCE12_TERMINAL_REFS[9]
        ),
        "partialArtifacts": [
            copy.deepcopy(row)
            for row in SEQUENCE12_TERMINAL_REFS[10:]
        ],
        "usedAsInput": False,
    }
    if (
        not isinstance(report, Mapping)
        or set(report)
        != {
            "schemaVersion",
            "status",
            "kind",
            "coveredProfiles",
            "comparedCaptures",
            "pageComparisons",
            "controlRootComparisons",
            "captureStackTransition",
            "sourceTransition",
            "rootExpansion",
            "allowedBoundaryTranslations",
            "migrationGeometryContract",
            "legacySemanticOracle",
            "screenshotBindingAudit",
            "excludedPredecessorFailure",
        }
        or report.get("schemaVersion")
        != (
            "quant-radar-ui-ux-control-"
            "migration-root-report/v1"
        )
        or report.get("status") != "passed"
        or report.get("kind") != "control-migration"
        or report.get("comparedCaptures") != 125
        or report.get("pageComparisons") != 81
        or report.get("controlRootComparisons") != 44
        or report.get("legacySemanticOracle", {}).get(
            "comparedCaptures"
        )
        != 117
        or report.get("screenshotBindingAudit")
        != {
            "passedRootCaptures": 44,
            "unboundRootCaptures": 0,
            "exactPrePostProjections": 88,
        }
        or report.get("rootExpansion")
        != ROOT_CAPTURE_EXPANSION_REF
        or report.get("excludedPredecessorFailure")
        != expected_exclusion
    ):
        raise ContractViolation(
            "Sequence 14 migration report semantics differ"
        )
    expected_report = _build_historical_stack_migration_report(
        workspace_fd,
        source_root_fd=source_root_fd,
        retained_m1=retained_m1,
    )
    if dict(report) != expected_report:
        raise ContractViolation(
            "Sequence 14 migration report value differs"
        )
    if state == "H1_REPORT":
        return current
    packet = current["values"][1]
    if not isinstance(packet, dict):
        raise ContractViolation(
            "Sequence 14 review packet is invalid"
        )
    _validate_review_packet_value(packet)
    if (
        packet.get("schemaVersion")
        != "quant-radar-ui-ux-review-packet/v2"
        or len(packet.get("items", ())) != 125
        or packet.get("machineReport")
        != _artifact_ref(current["records"][0])
        or len(packet.get("inputs", ())) != 5
        or len(
            {
                item.get("id")
                for item in packet.get("items", ())
                if isinstance(item, Mapping)
            }
        )
        != 125
    ):
        raise ContractViolation(
            "Sequence 14 review packet semantics differ"
        )
    expected_packet = _build_historical_stack_review_packet_value(
        workspace_fd,
        report_record=current["records"][0],
    )
    if packet != expected_packet:
        raise ContractViolation(
            "Sequence 14 review packet value differs"
        )
    if state == "H2_PACKET":
        return current
    raise ContractViolation(
        "Sequence 14 authority is paused at H2_PACKET"
    )


def _build_historical_stack_migration_report(
    workspace_fd: int,
    *,
    source_root_fd: int,
    retained_m1: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    from scripts import ui_ux_evidence

    _reauthenticate_historical_stack_evidence_source(
        source_root_fd
    )
    before_pages = _authenticate_historical_migration_bundle(
        workspace_fd,
        CONTROL_MIGRATION_INPUTS["beforePages"],
    )
    after_pages = _authenticate_historical_migration_bundle(
        workspace_fd,
        CONTROL_MIGRATION_INPUTS["afterPages"],
    )
    before_controls = _authenticate_historical_migration_bundle(
        workspace_fd,
        CONTROL_MIGRATION_INPUTS["beforeControls"],
    )
    imported = (
        _import_sequence13_m1_capture(
            workspace_fd,
            source_root_fd=source_root_fd,
        )
        if retained_m1 is None
        else copy.deepcopy(dict(retained_m1))
    )
    if imported.get("classification") != "S13_M1_CAPTURED":
        raise ContractViolation(
            "Sequence 14 comparator retained M1 differs"
        )
    corrected = _authenticate_sequence13_capture_manifest(
        workspace_fd,
        imported["preflightValue"],
    )
    historical = _reauthenticate_legacy_capture_stack_history(
        workspace_fd,
        source_root_fd=source_root_fd,
    )
    corrected_history = (
        _import_sequence13_capture_stack_history(
            workspace_fd,
            source_root_fd=source_root_fd,
        )
    )
    corrected_catalog = ui_ux_evidence._mint_control_catalog(
        corrected_history["controlCatalog"]
    )
    if (
        ui_ux_evidence._registered_control_catalog(
            corrected_catalog
        )
        != corrected_history["controlCatalog"]
    ):
        raise ContractViolation(
            "Sequence 14 corrected catalog provenance differs"
        )
    if (
        historical["digest"]
        != LEGACY_HISTORICAL_STACK_REF[
            "captureStackDigest"
        ]
        or corrected_history["contract"]["sha256"]
        != SEQUENCE13_CAPTURE_STACK_REF["sha256"]
        or corrected_history["digest"]
        != SEQUENCE13_CAPTURE_STACK_REF[
            "captureStackDigest"
        ]
    ):
        raise ContractViolation(
            "Sequence 14 comparator stack roles differ"
        )
    failed = _import_sequence12_terminal_failed(workspace_fd)
    report = _compare_control_migration_root_geometry_contract(
        ui_ux_evidence,
        source_root_fd=source_root_fd,
        evidence_ref=HISTORICAL_STACK_EVIDENCE_REF,
        before_pages=before_pages,
        after_pages=after_pages,
        before_controls=before_controls,
        after_root_controls=corrected["bundle"],
        historical_catalog=historical["catalog"],
        corrected_catalog=corrected_catalog,
        excluded_artifact=_artifact_ref(
            SEQUENCE12_TERMINAL_REFS[9]
        ),
        legacy_geometry_profile=(
            SEQUENCE13_M1_MIGRATION_GEOMETRY_PROFILE
        ),
        legacy_semantic_volatility_profile=(
            SEQUENCE13_M1_SEMANTIC_VOLATILITY_PROFILE
        ),
    )
    report.pop("excludedArtifacts", None)
    report["excludedPredecessorFailure"] = {
        "classification": failed["classification"],
        "manifest": failed["failedManifest"],
        "partialArtifacts": failed["partialArtifacts"],
        "usedAsInput": False,
    }
    return report


def _build_historical_stack_review_packet_value(
    workspace_fd: int,
    *,
    report_record: Mapping[str, Any] | None,
) -> dict[str, Any]:
    if report_record is None:
        raise ContractViolation(
            "Sequence 14 report reference is unavailable"
        )
    manifest_paths = {
        "beforePages": CONTROL_MIGRATION_INPUTS[
            "beforePages"
        ],
        "afterPages": CONTROL_MIGRATION_INPUTS["afterPages"],
        "beforeControls": CONTROL_MIGRATION_INPUTS[
            "beforeControls"
        ],
        "afterRootControls": SEQUENCE13_FORWARD_PATHS[0],
    }
    values: dict[str, dict[str, Any]] = {}
    refs: list[dict[str, Any]] = []
    roots: dict[str, str] = {}
    for key, relative in manifest_paths.items():
        record, payload = _relative_regular_record_and_bytes(
            workspace_fd,
            relative,
        )
        values[key] = _strict_manifest_json_line(payload)
        refs.append(_artifact_ref(record))
        roots[key] = str(PurePosixPath(relative).parent)
    items = _root_migration_review_items_from_values(
        before_pages=values["beforePages"],
        after_pages=values["afterPages"],
        before_controls=values["beforeControls"],
        after_root_controls=values["afterRootControls"],
        artifact_roots=roots,
    )
    report_ref = _artifact_ref(report_record)
    return _build_root_migration_review_packet(
        lineage_id=AUTHORIZED_RECOVERY_ID,
        machine_report=report_ref,
        inputs=[report_ref, *refs],
        items=items,
    )


def _compare_historical_stack_migration(
    workspace_fd: int,
    *,
    source_root_fd: int,
) -> dict[str, Any]:
    _, preflight, current = (
        _reauthenticate_historical_stack_preflight(
            workspace_fd,
            source_root_fd,
        )
    )
    if current["state"] not in {"H0_READY", "H1_REPORT"}:
        raise ContractViolation(
            "Sequence 14 comparator requires H0_READY"
        )
    if current["state"] == "H1_REPORT":
        validated = _validate_historical_stack_forward_semantics(
            workspace_fd,
            source_root_fd,
            preflight=preflight,
        )
        return {
            "exitCode": EXIT_SUCCESS,
            "created": False,
            "state": validated["state"],
            "report": _artifact_ref(validated["records"][0]),
            "comparedCaptures": 125,
        }
    report = _build_historical_stack_migration_report(
        workspace_fd,
        source_root_fd=source_root_fd,
    )
    report_record, created = (
        _publish_or_reopen_continuation_file(
            workspace_fd,
            HISTORICAL_STACK_FORWARD_PATHS[0],
            _canonical_json_bytes(report),
        )
    )
    validated = _validate_historical_stack_forward_semantics(
        workspace_fd,
        source_root_fd,
        preflight=preflight,
    )
    if validated["state"] != "H1_REPORT":
        raise ContractViolation(
            "Sequence 14 comparator postcondition differs"
        )
    return {
        "exitCode": EXIT_SUCCESS,
        "created": created,
        "state": validated["state"],
        "report": _artifact_ref(report_record),
        "comparedCaptures": 125,
    }


def _prepare_historical_stack_review(
    workspace_fd: int,
    *,
    source_root_fd: int,
) -> dict[str, Any]:
    _, preflight, current = (
        _reauthenticate_historical_stack_preflight(
            workspace_fd,
            source_root_fd,
        )
    )
    if current["state"] not in {"H1_REPORT", "H2_PACKET"}:
        raise ContractViolation(
            "Sequence 14 review requires H1_REPORT"
        )
    if current["state"] == "H2_PACKET":
        validated = _validate_historical_stack_forward_semantics(
            workspace_fd,
            source_root_fd,
            preflight=preflight,
        )
        return {
            "exitCode": EXIT_SUCCESS,
            "created": False,
            "state": validated["state"],
            "packet": _artifact_ref(validated["records"][1]),
            "items": 125,
        }
    report_record = current["records"][0]
    packet = _build_historical_stack_review_packet_value(
        workspace_fd,
        report_record=report_record,
    )
    packet_record, created = (
        _publish_or_reopen_continuation_file(
            workspace_fd,
            HISTORICAL_STACK_FORWARD_PATHS[1],
            _canonical_json_bytes(packet),
        )
    )
    validated = _validate_historical_stack_forward_semantics(
        workspace_fd,
        source_root_fd,
        preflight=preflight,
    )
    if validated["state"] != "H2_PACKET":
        raise ContractViolation(
            "Sequence 14 review packet postcondition differs"
        )
    return {
        "exitCode": EXIT_SUCCESS,
        "created": created,
        "state": validated["state"],
        "packet": _artifact_ref(packet_record),
        "items": 125,
    }


def _external_review_exact_record(
    root_fd: int,
    expected: Mapping[str, Any],
    *,
    source: bool,
) -> tuple[dict[str, Any], bytes]:
    if (
        not isinstance(expected, Mapping)
        or set(expected) != {"path", "sha256", "size", "mode"}
    ):
        raise ContractViolation(
            "Sequence 15 historical reference is invalid"
        )
    record, payload = (
        _source_file_record(root_fd, expected["path"])
        if source
        else _relative_regular_record_and_bytes(
            root_fd,
            expected["path"],
        )
    )
    if (
        {
            key: record[key]
            for key in ("path", "sha256", "size", "mode")
        }
        != dict(expected)
        or record["uid"] != os.getuid()
        or record["gid"] not in {os.getgid(), 0}
        or record["nlink"] != 1
    ):
        raise ContractViolation(
            "Sequence 15 historical artifact differs: "
            + str(expected["path"])
        )
    return record, payload


def _parse_sequence14_historical_authorization(
    payload: bytes,
) -> dict[str, Any]:
    if (
        payload.count(HISTORICAL_STACK_AUTH_GENERIC) != 2
        or payload.count(HISTORICAL_STACK_AUTH_START) != 1
        or payload.count(HISTORICAL_STACK_AUTH_END) != 1
    ):
        raise ContractViolation(
            "Sequence 14 historical authorization markers differ"
        )
    start = payload.find(HISTORICAL_STACK_AUTH_START)
    end = payload.find(
        HISTORICAL_STACK_AUTH_END,
        start + len(HISTORICAL_STACK_AUTH_START),
    )
    body = payload[
        start + len(HISTORICAL_STACK_AUTH_START) : end
    ]
    value = _strict_json_bytes(body)
    expected = _historical_stack_authorization_body()
    if (
        start < 0
        or end < 0
        or not isinstance(value, dict)
        or value != expected
        or body != _canonical_json_bytes(value)
        or value.get("formalPause") != "H2_PACKET"
        or value.get("allowedCommands")
        != list(HISTORICAL_STACK_ALLOWED_COMMANDS)
    ):
        raise ContractViolation(
            "Sequence 14 historical authorization body differs"
        )
    return value


def _import_sequence14_h2_packet(
    workspace_fd: int,
    *,
    source_root_fd: int,
    require_initial: bool = False,
) -> dict[str, Any]:
    """Import immutable Sequence 14 H2 bytes without live source rebuilds."""

    if any(
        type(descriptor) is not int or descriptor < 0
        for descriptor in (workspace_fd, source_root_fd)
    ):
        raise ContractViolation(
            "Sequence 15 historical descriptors are invalid"
        )
    records: list[dict[str, Any]] = []
    payloads: list[bytes] = []
    values: list[dict[str, Any] | None] = []
    for index, expected in enumerate(
        EXTERNAL_REVIEW_PARENT_REFS
    ):
        record, payload = _external_review_exact_record(
            source_root_fd if index < 3 else workspace_fd,
            expected,
            source=index < 3,
        )
        records.append(record)
        payloads.append(payload)
        if index in {0, 1, 2, 3, 7}:
            values.append(None)
            continue
        value = _strict_json_bytes(payload, allow_float=True)
        if (
            not isinstance(value, dict)
            or payload != _canonical_json_bytes(value)
        ):
            raise ContractViolation(
                "Sequence 15 historical JSON is noncanonical: "
                + expected["path"]
            )
        values.append(value)
    authorization = _parse_sequence14_historical_authorization(
        payloads[2]
    )
    prechange = values[4]
    rollback = values[5]
    owner = values[6]
    bundle = values[8]
    preflight = values[9]
    report = values[10]
    packet = values[11]
    assert all(
        value is not None
        for value in (
            prechange,
            rollback,
            owner,
            bundle,
            preflight,
            report,
            packet,
        )
    )
    expected_tier = {
        "lease": _artifact_ref(records[3]),
        "prechange": _artifact_ref(records[4]),
        "rollback": _artifact_ref(records[5]),
        "owner": _artifact_ref(records[6]),
        "archive": _artifact_ref(records[7]),
        "bundle": _artifact_ref(records[8]),
    }
    if (
        prechange.get("authorizationRecord")
        != preflight.get("authorizationRecord")
        or preflight.get("authorizationRecord")
        != {
            "path": EXTERNAL_REVIEW_PARENT_REFS[2]["path"],
            "sha256": EXTERNAL_REVIEW_PARENT_REFS[2]["sha256"],
            "size": EXTERNAL_REVIEW_PARENT_REFS[2]["size"],
            "bodySha256": hashlib.sha256(
                _canonical_json_bytes(authorization)
            ).hexdigest(),
        }
        or preflight.get("plan")
        != dict(HISTORICAL_STACK_PLAN_REF)
        or preflight.get("traceability")
        != dict(HISTORICAL_STACK_LEDGER_REF)
        or preflight.get("tier") != expected_tier
        or preflight.get("schemaVersion")
        != (
            "quant-radar-ui-ux-historical-stack-"
            "correction-preflight/v1"
        )
        or preflight.get("status") != "passed"
        or preflight.get("correctionId")
        != HISTORICAL_STACK_CORRECTION_ID
        or preflight.get("tierId") != HISTORICAL_STACK_TIER_ID
        or preflight.get("captureId")
        != HISTORICAL_STACK_CAPTURE_ID
        or preflight.get("continuationId")
        != HISTORICAL_STACK_CONTINUATION_ID
        or prechange.get("lease") != records[3]
        or bundle.get("archive") != expected_tier["archive"]
        or bundle.get("ownerMarker") != expected_tier["owner"]
        or rollback.get("prechange") != expected_tier["prechange"]
        or rollback.get("bundleManifest")
        != expected_tier["bundle"]
        or owner.get("correctionId")
        != HISTORICAL_STACK_CORRECTION_ID
    ):
        raise ContractViolation(
            "Sequence 14 historical Tier cross-links differ"
        )
    if (
        set(report)
        != {
            "schemaVersion",
            "status",
            "kind",
            "coveredProfiles",
            "comparedCaptures",
            "pageComparisons",
            "controlRootComparisons",
            "captureStackTransition",
            "sourceTransition",
            "rootExpansion",
            "allowedBoundaryTranslations",
            "migrationGeometryContract",
            "legacySemanticOracle",
            "screenshotBindingAudit",
            "excludedPredecessorFailure",
        }
        or report.get("schemaVersion")
        != "quant-radar-ui-ux-control-migration-root-report/v1"
        or report.get("status") != "passed"
        or report.get("kind") != "control-migration"
        or (
            report.get("pageComparisons"),
            report.get("controlRootComparisons"),
            report.get("comparedCaptures"),
        )
        != (81, 44, 125)
        or report.get("legacySemanticOracle", {}).get(
            "comparedCaptures"
        )
        != 117
        or report.get("excludedPredecessorFailure", {}).get(
            "classification"
        )
        != "S12_TERMINAL_FAILED"
        or report.get("excludedPredecessorFailure", {}).get(
            "usedAsInput"
        )
        is not False
    ):
        raise ContractViolation(
            "Sequence 14 historical report semantics differ"
        )
    _validate_review_packet_value(packet)
    kinds = [
        item.get("kind")
        for item in packet.get("items", ())
        if isinstance(item, Mapping)
    ]
    item_ids = [
        item.get("id")
        for item in packet.get("items", ())
        if isinstance(item, Mapping)
    ]
    expected_item_digest = hashlib.sha256(
        _canonical_json_bytes(sorted(item_ids))
    ).hexdigest()
    if (
        packet.get("schemaVersion")
        != "quant-radar-ui-ux-review-packet/v2"
        or packet.get("status") != "review_required"
        or packet.get("kind") != "control-migration"
        or packet.get("lineageId") != AUTHORIZED_RECOVERY_ID
        or packet.get("machineReport")
        != _artifact_ref(records[10])
        or len(packet.get("inputs", ())) != 5
        or _artifact_ref(records[10])
        not in packet.get("inputs", ())
        or len(packet.get("items", ())) != 125
        or len(item_ids) != 125
        or len(set(item_ids)) != 125
        or kinds.count("page") != 81
        or kinds.count("control-root") != 44
        or packet.get("itemSetSha256")
        != expected_item_digest
        or packet.get("promptSha256")
        != hashlib.sha256(
            _canonical_json_bytes(packet.get("prompt"))
        ).hexdigest()
        or packet.get("inputsSha256")
        != hashlib.sha256(
            _canonical_json_bytes(packet.get("inputs"))
        ).hexdigest()
    ):
        raise ContractViolation(
            "Sequence 14 historical packet semantics differ"
        )
    later_present = [
        _relative_leaf_lstat(workspace_fd, relative)
        is not None
        for relative in EXTERNAL_REVIEW_FORWARD_PATHS[2:]
    ]
    if require_initial and any(later_present):
        raise ContractViolation(
            "Sequence 15 parent H2 has a later leaf"
        )
    if any(later_present[2:]):
        raise ContractViolation(
            "Sequence 15 candidate/root authority is forbidden"
        )
    return {
        "classification": "S14_H2_PACKET",
        "authorization": _artifact_ref(records[2]),
        "authorities": [
            _artifact_ref(record) for record in records[:10]
        ],
        "preflight": _artifact_ref(records[9]),
        "report": _artifact_ref(records[10]),
        "packet": _artifact_ref(records[11]),
        "reportValue": copy.deepcopy(report),
        "packetValue": copy.deepcopy(packet),
        "sourceProjection": copy.deepcopy(
            preflight["sourceProjection"]
        ),
        "supplementalProjection": copy.deepcopy(
            preflight["supplementalProjection"]
        ),
        "runtimeReceipt": copy.deepcopy(
            preflight["runtimeReceipt"]
        ),
    }


def _parse_sequence15_historical_authorization(
    payload: bytes,
) -> dict[str, Any]:
    if (
        payload.count(EXTERNAL_REVIEW_AUTH_GENERIC) != 2
        or payload.count(EXTERNAL_REVIEW_AUTH_START) != 1
        or payload.count(EXTERNAL_REVIEW_AUTH_END) != 1
    ):
        raise ContractViolation(
            "Sequence 16 parent authorization markers differ"
        )
    start = payload.find(EXTERNAL_REVIEW_AUTH_START)
    end = payload.find(
        EXTERNAL_REVIEW_AUTH_END,
        start + len(EXTERNAL_REVIEW_AUTH_START),
    )
    body = payload[
        start + len(EXTERNAL_REVIEW_AUTH_START) : end
    ]
    value = _strict_json_bytes(body)
    if (
        start < 0
        or end < 0
        or not isinstance(value, dict)
        or body != _canonical_json_bytes(value)
        or value != _external_review_authorization_body()
        or value.get("sequence") != 15
        or value.get("formalPause") != "E2_REVIEW"
        or value.get("allowedCommands")
        != list(EXTERNAL_REVIEW_ALLOWED_COMMANDS)
    ):
        raise ContractViolation(
            "Sequence 16 parent authorization body differs"
        )
    return value


def _validate_sequence15_historical_archive(
    archive_bytes: bytes,
    package: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    if (
        not isinstance(archive_bytes, bytes)
        or not isinstance(package, Sequence)
        or isinstance(package, (str, bytes))
        or len(package) != len(EXTERNAL_REVIEW_PACKAGE_PATHS)
    ):
        raise ContractViolation(
            "Sequence 16 parent archive inputs differ"
        )
    expected = {
        row.get("path"): dict(row)
        for row in package
        if isinstance(row, Mapping)
    }
    if (
        len(expected) != len(EXTERNAL_REVIEW_PACKAGE_PATHS)
        or set(expected) != set(EXTERNAL_REVIEW_PACKAGE_PATHS)
    ):
        raise ContractViolation(
            "Sequence 16 parent package inventory differs"
        )
    records: list[dict[str, Any]] = []
    try:
        with tarfile.open(
            fileobj=io.BytesIO(archive_bytes),
            mode="r:*",
        ) as archive:
            members = archive.getmembers()
            if [member.name for member in members] != list(
                EXTERNAL_REVIEW_PACKAGE_PATHS
            ):
                raise ContractViolation(
                    "Sequence 16 parent PAX order differs"
                )
            for member in members:
                if (
                    not member.isfile()
                    or member.uid != 0
                    or member.gid != 0
                    or member.uname != ""
                    or member.gname != ""
                    or member.mtime != 0
                    or member.mode != 0o644
                    or member.size != expected[member.name]["size"]
                ):
                    raise ContractViolation(
                        "Sequence 16 parent PAX metadata differs: "
                        + member.name
                    )
                reader = archive.extractfile(member)
                if reader is None:
                    raise ContractViolation(
                        "Sequence 16 parent PAX payload is absent"
                    )
                payload = reader.read()
                digest = hashlib.sha256(payload).hexdigest()
                if (
                    len(payload) != member.size
                    or digest != expected[member.name]["sha256"]
                ):
                    raise ContractViolation(
                        "Sequence 16 parent PAX payload differs: "
                        + member.name
                    )
                records.append(
                    {
                        "path": member.name,
                        "sha256": digest,
                        "size": len(payload),
                        "mode": "0644",
                    }
                )
    except ContractViolation:
        raise
    except (tarfile.TarError, OSError, EOFError) as exc:
        raise ContractViolation(
            "Sequence 16 parent PAX is unreadable"
        ) from exc
    return records


def _classify_sequence15_lifecycle_presence(
    tier_presence: Sequence[bool],
    forward_presence: Sequence[bool],
    *,
    sequence16_active: bool,
) -> str:
    if (
        not isinstance(tier_presence, Sequence)
        or isinstance(tier_presence, (str, bytes))
        or len(tier_presence) != 8
        or any(type(value) is not bool for value in tier_presence)
        or not isinstance(forward_presence, Sequence)
        or isinstance(forward_presence, (str, bytes))
        or len(forward_presence) != 6
        or any(type(value) is not bool for value in forward_presence)
        or type(sequence16_active) is not bool
    ):
        raise ContractViolation(
            "Sequence 16 parent lifecycle presence is invalid"
        )
    tier = tuple(tier_presence)
    forward = tuple(forward_presence)
    initial = (True, True, False, False, False, False)
    if tier == (False,) * 8:
        if forward != initial or sequence16_active:
            raise ContractViolation(
                "Sequence 16 implementation boundary differs"
            )
        return "S15_IMPLEMENTATION_BOUNDARY"
    if tier == (True,) * 7 + (False,):
        if forward != initial or sequence16_active:
            raise ContractViolation(
                "Sequence 16 bootstrap boundary differs"
            )
        return "S15_BOOTSTRAP_BOUNDARY"
    if tier != (True,) * 8:
        raise ContractViolation(
            "Sequence 16 parent Tier is partial"
        )
    if forward[4] or forward[5]:
        raise ContractViolation(
            "Sequence 16 candidate/root authority is forbidden"
        )
    allowed = {
        initial,
        (True, True, True, False, False, False),
        (True, True, True, True, False, False),
    }
    if forward not in allowed or (
        forward != initial and not sequence16_active
    ):
        raise ContractViolation(
            "Sequence 16 parent forward lifecycle differs"
        )
    return "S15_E0_PACKET"


def _import_sequence15_e0_preflight(
    workspace_fd: int,
    *,
    source_root_fd: int,
    require_initial: bool,
) -> dict[str, Any]:
    """Import exact Sequence 15 E0 bytes without rebuilding live source."""

    if (
        any(
            type(descriptor) is not int or descriptor < 0
            for descriptor in (workspace_fd, source_root_fd)
        )
        or type(require_initial) is not bool
    ):
        raise ContractViolation(
            "Sequence 16 parent import arguments are invalid"
        )
    records: list[dict[str, Any]] = []
    payloads: list[bytes] = []
    values: list[dict[str, Any] | None] = []
    for index, expected in enumerate(
        LIFECYCLE_TEST_CORRECTION_PARENT_REFS
    ):
        record, payload = _external_review_exact_record(
            source_root_fd if index < 3 else workspace_fd,
            expected,
            source=index < 3,
        )
        expected_gid = 0 if index == 1 else os.getgid()
        if record["gid"] != expected_gid:
            raise ContractViolation(
                "Sequence 16 parent accepted group differs: "
                + expected["path"]
            )
        records.append(record)
        payloads.append(payload)
        if index in {0, 1, 2, 3, 7}:
            values.append(None)
            continue
        value = _strict_json_bytes(payload, allow_float=True)
        if (
            not isinstance(value, dict)
            or payload != _canonical_json_bytes(value)
        ):
            raise ContractViolation(
                "Sequence 16 parent JSON is noncanonical: "
                + expected["path"]
            )
        values.append(value)
    authorization = _parse_sequence15_historical_authorization(
        payloads[2]
    )
    prechange = values[4]
    rollback = values[5]
    owner = values[6]
    bundle = values[8]
    preflight = values[9]
    report = values[10]
    packet = values[11]
    assert all(
        value is not None
        for value in (
            prechange,
            rollback,
            owner,
            bundle,
            preflight,
            report,
            packet,
        )
    )
    assert isinstance(prechange, dict)
    assert isinstance(rollback, dict)
    assert isinstance(owner, dict)
    assert isinstance(bundle, dict)
    assert isinstance(preflight, dict)
    assert isinstance(report, dict)
    assert isinstance(packet, dict)
    directory_fd = _open_relative_directory_fd(
        workspace_fd,
        EXTERNAL_REVIEW_TIER_DESTINATIONS[4],
    )
    try:
        directory_stat = os.fstat(directory_fd)
        if (
            stat.S_IMODE(directory_stat.st_mode) != 0o700
            or directory_stat.st_uid != os.getuid()
            or directory_stat.st_gid != os.getgid()
            or set(os.listdir(directory_fd))
            != {
                PurePosixPath(
                    EXTERNAL_REVIEW_TIER_DESTINATIONS[index]
                ).name
                for index in (5, 6, 7)
            }
        ):
            raise ContractViolation(
                "Sequence 16 parent Tier directory differs"
            )
    finally:
        os.close(directory_fd)
    parent_h2 = _import_sequence14_h2_packet(
        workspace_fd,
        source_root_fd=source_root_fd,
        require_initial=False,
    )
    parent_projection = {
        key: copy.deepcopy(parent_h2[key])
        for key in (
            "classification",
            "authorization",
            "authorities",
            "preflight",
            "report",
            "packet",
        )
    }
    authorization_record = {
        "path": records[2]["path"],
        "sha256": records[2]["sha256"],
        "size": records[2]["size"],
        "bodySha256": hashlib.sha256(
            _canonical_json_bytes(authorization)
        ).hexdigest(),
    }
    tier = {
        "lease": _artifact_ref(records[3]),
        "prechange": _artifact_ref(records[4]),
        "rollback": _artifact_ref(records[5]),
        "owner": _artifact_ref(records[6]),
        "archive": _artifact_ref(records[7]),
        "bundle": _artifact_ref(records[8]),
    }
    projection_counts = (
        len(preflight.get("sourceProjection", {}).get("records", ())),
        len(
            preflight.get("supplementalProjection", {}).get(
                "records",
                (),
            )
        ),
    )
    expected_namespace = {
        "schemaVersion": (
            "quant-radar-ui-ux-historical-stack-"
            "external-review-namespace/v1"
        ),
        "initialState": "E0_PACKET",
        "forwardPaths": list(EXTERNAL_REVIEW_FORWARD_PATHS),
        "states": {
            "E0_PACKET": [1, 1, 0, 0, 0, 0],
            "E1_INTAKE": [1, 1, 1, 0, 0, 0],
            "E2_REVIEW": [1, 1, 1, 1, 0, 0],
        },
        "candidateForbidden": True,
        "rootForbidden": True,
    }
