def _external_review_authorization_document_bytes() -> bytes:
    body = _canonical_json_bytes(
        _external_review_authorization_body()
    ).decode("utf-8")
    return (
        "# Quant Radar UX-1B Sequence 15 External Review "
        "Continuation\n\n"
        "Status: authorization candidate only. This document does not "
        "authorize bootstrap, preflight, intake submission, manual-review "
        "publication, capture, comparison, candidate, root, or theme work "
        "until the repository maintainer separately accepts its exact "
        "whole-document SHA-256, byte size, and mode.\n\n"
        + EXTERNAL_REVIEW_AUTH_START.decode("ascii")
        + body
        + EXTERNAL_REVIEW_AUTH_END.decode("ascii")
        + "\n\nSequence 15 imports only the exact accepted Sequence 14 "
        "`H2_PACKET`, appoints one fixed independent-review session, "
        "brokers maintainer-accepted reviewer bytes through bounded stdin, "
        "publishes a byte-identical review at a different inode, and stops "
        "at `E2_REVIEW`. It grants no capture, comparison, candidate, or "
        "root authority.\n"
    ).encode("utf-8")


def _parse_external_review_authorization_record(
    source_root_fd: int,
) -> dict[str, Any]:
    record, document = _source_file_record(
        source_root_fd,
        EXTERNAL_REVIEW_AUTHORIZATION_DOCUMENT_PATH,
    )
    if (
        record["mode"] != "0644"
        or record["uid"] != os.getuid()
        or record["gid"] != os.getgid()
        or record["nlink"] != 1
        or document
        != _external_review_authorization_document_bytes()
        or document.count(EXTERNAL_REVIEW_AUTH_GENERIC) != 2
    ):
        raise ContractViolation(
            "Sequence 15 authorization document differs"
        )
    for expected in (
        EXTERNAL_REVIEW_PLAN_REF,
        EXTERNAL_REVIEW_LEDGER_REF,
    ):
        observed, _ = _source_file_record(
            source_root_fd,
            expected["path"],
        )
        if {
            key: observed[key]
            for key in ("path", "sha256", "size", "mode")
        } != expected:
            raise ContractViolation(
                "Sequence 15 authority drifted: "
                + expected["path"]
            )
    return _external_review_authorization_body()


def _external_review_authorization_binding(
    source_root_fd: int,
) -> dict[str, Any]:
    body = _parse_external_review_authorization_record(
        source_root_fd
    )
    record, _ = _source_file_record(
        source_root_fd,
        EXTERNAL_REVIEW_AUTHORIZATION_DOCUMENT_PATH,
    )
    return {
        **_artifact_ref(record),
        "bodySha256": hashlib.sha256(
            _canonical_json_bytes(body)
        ).hexdigest(),
    }


def _build_external_review_source_projections(
    source_root_fd: int,
) -> dict[str, Any]:
    base = _build_preflight_source_projections(source_root_fd)
    mirror = base["sourceProjection"]
    if len(mirror["records"]) != 270:
        raise ContractViolation(
            "Sequence 15 live source projection count differs"
        )
    mirror_paths = {
        row["path"] for row in mirror["records"]
    }
    records = {
        row["path"]: copy.deepcopy(row)
        for row in base["supplementalProjection"]["records"]
    }
    required_paths = (
        *EXTERNAL_REVIEW_PACKAGE_PATHS,
        HISTORICAL_STACK_AUTHORIZATION_DOCUMENT_PATH,
    )
    for relative in required_paths:
        if relative in mirror_paths:
            continue
        record, _ = _source_file_record(
            source_root_fd,
            relative,
        )
        records[relative] = {
            "path": relative,
            "sha256": record["sha256"],
            "size": record["size"],
            "mode": (
                "0555"
                if int(record["mode"], 8) & 0o111
                else "0444"
            ),
        }
    paths = sorted(records)
    return {
        "sourceProjection": mirror,
        "supplementalProjection": _source_projection_value(
            "quant-radar-ui-ux-supplemental-source/v1",
            paths,
            mirror["policy"]["include"],
            [records[path] for path in paths],
        ),
    }


def _external_review_archive_bytes(
    source_root_fd: int,
) -> tuple[bytes, list[dict[str, Any]]]:
    output = io.BytesIO()
    records: list[dict[str, Any]] = []
    with tarfile.open(
        fileobj=output,
        mode="w",
        format=tarfile.PAX_FORMAT,
    ) as archive:
        for relative in EXTERNAL_REVIEW_PACKAGE_PATHS:
            record, payload = _source_file_record(
                source_root_fd,
                relative,
            )
            records.append(record)
            member = tarfile.TarInfo(relative)
            member.size = len(payload)
            member.mode = stat.S_IMODE(
                int(record["mode"], 8)
            )
            member.uid = 0
            member.gid = 0
            member.uname = ""
            member.gname = ""
            member.mtime = 0
            archive.addfile(member, io.BytesIO(payload))
    return output.getvalue(), records


def _external_review_make_contract(
    source_root_fd: int,
) -> dict[str, Any]:
    record, payload = _source_file_record(
        source_root_fd,
        "Makefile",
    )
    targets = (
        "ui-ux1b-external-review-bootstrap",
        "ui-ux1b-external-review-preflight",
        "ui-ux1b-external-review-verify",
        "ui-ux1b-external-review-submit-intake",
        "ui-ux1b-external-review-publish",
    )
    text = payload.decode("utf-8", errors="strict")
    if any(
        text.count(target + ":") != 1 for target in targets
    ):
        raise ContractViolation(
            "Sequence 15 Make contract differs"
        )
    return {
        "artifact": _artifact_ref(record),
        "targets": list(targets),
        "targetsSha256": hashlib.sha256(
            _canonical_json_bytes(list(targets))
        ).hexdigest(),
    }


def _build_external_review_descriptor_profile() -> dict[str, Any]:
    _, hard_limit = resource.getrlimit(resource.RLIMIT_NOFILE)
    value = {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-"
            "descriptor-profile/v1"
        ),
        "hardLimit": hard_limit,
        "worstCaseUniqueRetainedLeaves": (
            EXTERNAL_REVIEW_RETAINED_LEAVES
        ),
        "protocolAdditional": (
            EXTERNAL_REVIEW_PROTOCOL_ALLOWANCE
        ),
        "reserve": EXTERNAL_REVIEW_DESCRIPTOR_RESERVE,
        "requiredSoftFloor": (
            EXTERNAL_REVIEW_REQUIRED_SOFT_FLOOR
        ),
        "raiseCeiling": EXTERNAL_REVIEW_DESCRIPTOR_CEILING,
    }
    return _validate_external_review_descriptor_profile(value)


def _validate_external_review_descriptor_profile(
    value: Any,
) -> dict[str, Any]:
    keys = {
        "schemaVersion",
        "hardLimit",
        "worstCaseUniqueRetainedLeaves",
        "protocolAdditional",
        "reserve",
        "requiredSoftFloor",
        "raiseCeiling",
    }
    if (
        not isinstance(value, dict)
        or set(value) != keys
        or value.get("schemaVersion")
        != (
            "quant-radar-ui-ux-external-review-"
            "descriptor-profile/v1"
        )
        or any(
            type(value[key]) is not int
            for key in keys - {"schemaVersion"}
        )
        or value["requiredSoftFloor"]
        != (
            value["worstCaseUniqueRetainedLeaves"]
            + value["protocolAdditional"]
            + value["reserve"]
        )
        or (
            value["worstCaseUniqueRetainedLeaves"],
            value["protocolAdditional"],
            value["reserve"],
            value["requiredSoftFloor"],
            value["raiseCeiling"],
        )
        not in {
            (
                EXTERNAL_REVIEW_RETAINED_LEAVES,
                EXTERNAL_REVIEW_PROTOCOL_ALLOWANCE,
                EXTERNAL_REVIEW_DESCRIPTOR_RESERVE,
                EXTERNAL_REVIEW_REQUIRED_SOFT_FLOOR,
                EXTERNAL_REVIEW_DESCRIPTOR_CEILING,
            ),
            (
                LIFECYCLE_TEST_CORRECTION_RETAINED_LEAVES,
                LIFECYCLE_TEST_CORRECTION_PROTOCOL_ALLOWANCE,
                LIFECYCLE_TEST_CORRECTION_DESCRIPTOR_RESERVE,
                LIFECYCLE_TEST_CORRECTION_REQUIRED_SOFT_FLOOR,
                LIFECYCLE_TEST_CORRECTION_DESCRIPTOR_CEILING,
            ),
            (
                FORMAL_STATE_ORACLE_CORRECTION_RETAINED_LEAVES,
                FORMAL_STATE_ORACLE_CORRECTION_PROTOCOL_ALLOWANCE,
                FORMAL_STATE_ORACLE_CORRECTION_DESCRIPTOR_RESERVE,
                FORMAL_STATE_ORACLE_CORRECTION_REQUIRED_SOFT_FLOOR,
                FORMAL_STATE_ORACLE_CORRECTION_DESCRIPTOR_CEILING,
            ),
            (
                O1_LIFECYCLE_TEST_CORRECTION_RETAINED_LEAVES,
                O1_LIFECYCLE_TEST_CORRECTION_PROTOCOL_ALLOWANCE,
                O1_LIFECYCLE_TEST_CORRECTION_DESCRIPTOR_RESERVE,
                O1_LIFECYCLE_TEST_CORRECTION_REQUIRED_SOFT_FLOOR,
                O1_LIFECYCLE_TEST_CORRECTION_DESCRIPTOR_CEILING,
            ),
            (
                V1_LIFECYCLE_TEST_CORRECTION_RETAINED_LEAVES,
                V1_LIFECYCLE_TEST_CORRECTION_PROTOCOL_ALLOWANCE,
                V1_LIFECYCLE_TEST_CORRECTION_DESCRIPTOR_RESERVE,
                V1_LIFECYCLE_TEST_CORRECTION_REQUIRED_SOFT_FLOOR,
                V1_LIFECYCLE_TEST_CORRECTION_DESCRIPTOR_CEILING,
            ),
        }
        or value["requiredSoftFloor"] > value["raiseCeiling"]
        or value["hardLimit"] < value["requiredSoftFloor"]
    ):
        raise ContractViolation(
            "Sequence 15 descriptor profile differs"
        )
    return copy.deepcopy(value)


def _classify_external_review_presence(
    presence: Sequence[bool],
) -> str:
    if (
        not isinstance(presence, Sequence)
        or isinstance(presence, (str, bytes))
        or len(presence) != 6
        or any(type(value) is not bool for value in presence)
    ):
        raise ContractViolation(
            "Sequence 15 lifecycle presence is invalid"
        )
    states = {
        (True, True, False, False, False, False): "E0_PACKET",
        (True, True, True, False, False, False): "E1_INTAKE",
        (True, True, True, True, False, False): "E2_REVIEW",
    }
    state = states.get(tuple(presence))
    if state is None:
        raise ContractViolation(
            "Sequence 15 lifecycle is not an exact state"
        )
    return state


def _classify_external_review_forward(
    workspace_fd: int,
) -> dict[str, Any]:
    records: list[dict[str, Any] | None] = []
    payloads: list[bytes | None] = []
    values: list[dict[str, Any] | None] = []
    presence: list[bool] = []
    for relative in EXTERNAL_REVIEW_FORWARD_PATHS:
        if _relative_leaf_lstat(workspace_fd, relative) is None:
            records.append(None)
            payloads.append(None)
            values.append(None)
            presence.append(False)
            continue
        record, payload = _relative_regular_record_and_bytes(
            workspace_fd,
            relative,
        )
        value = _strict_json_bytes(payload, allow_float=True)
        if (
            record["mode"] != "0600"
            or record["uid"] != os.getuid()
            or record["gid"] != os.getgid()
            or record["nlink"] != 1
            or not isinstance(value, dict)
            or payload != _canonical_json_bytes(value)
        ):
            raise ContractViolation(
                "Sequence 15 forward leaf is unsafe: "
                + relative
            )
        records.append(record)
        payloads.append(payload)
        values.append(value)
        presence.append(True)
    return {
        "state": _classify_external_review_presence(presence),
        "present": presence,
        "records": records,
        "payloads": payloads,
        "values": values,
    }


def _external_review_paths() -> tuple[str, str, str]:
    return tuple(EXTERNAL_REVIEW_REVIEW_PATHS)


def _external_review_reviewer_sandbox_contract(
    workspace: Path,
    output: Path,
) -> dict[str, Any]:
    _validate_external_review_reviewer_paths(workspace, output)
    sandbox = Path("/usr/bin/sandbox-exec")
    return {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-sandbox/v1"
        ),
        "sandboxExecutable": str(sandbox),
        "sandboxRequired": True,
        "sandboxAvailable": sandbox.is_file(),
        "workspace": str(workspace.resolve()),
        "workspaceReadOnly": True,
        "runtimeReadOnly": True,
        "allowedWriteRoots": [str(output.resolve())],
        "networkAllowed": False,
        "browserAllowed": False,
        "packageInstallAllowed": False,
        "workspaceWriteSetRequired": [],
    }


def _validate_external_review_reviewer_paths(
    workspace: Path,
    output: Path,
) -> None:
    workspace_path = workspace.resolve()
    output_path = output.resolve()
    runtime_path = (workspace_path / ".venv").resolve()
    if (
        not workspace_path.is_dir()
        or not output_path.is_dir()
        or output_path == workspace_path
        or workspace_path in output_path.parents
        or output_path == runtime_path
        or runtime_path in output_path.parents
    ):
        raise ContractViolation(
            "Sequence 15 reviewer output is not isolated"
        )


def _external_review_tier_values(
    *,
    lease_record: Mapping[str, Any],
    parent_h2: Mapping[str, Any],
    authorization: Mapping[str, Any],
    package_records: Sequence[Mapping[str, Any]],
    prechange_record: Mapping[str, Any] | None = None,
    owner_record: Mapping[str, Any] | None = None,
    archive_record: Mapping[str, Any] | None = None,
    bundle_record: Mapping[str, Any] | None = None,
) -> dict[str, dict[str, Any]]:
    package = [
        _artifact_ref(record)
        for record in sorted(
            package_records,
            key=lambda item: item["path"],
        )
    ]
    if (
        len(package) != len(EXTERNAL_REVIEW_PACKAGE_PATHS)
        or [row["path"] for row in package]
        != sorted(EXTERNAL_REVIEW_PACKAGE_PATHS)
    ):
        raise ContractViolation(
            "Sequence 15 source package differs"
        )
    parent_projection = {
        key: copy.deepcopy(parent_h2[key])
        for key in (
            "classification",
            "authorization",
            "authorities",
            "preflight",
            "report",
            "packet",
        )
    }
    prechange = {
        "schemaVersion": (
            "quant-radar-ui-ux-historical-stack-"
            "external-review-continuation-prechange/v1"
        ),
        "status": "captured",
        "captureId": EXTERNAL_REVIEW_CAPTURE_ID,
        "parentContinuationId": (
            EXTERNAL_REVIEW_PARENT_CONTINUATION_ID
        ),
        "externalReviewCorrectionId": (
            EXTERNAL_REVIEW_CORRECTION_ID
        ),
        "externalReviewTierId": EXTERNAL_REVIEW_TIER_ID,
        "authorizationRecord": copy.deepcopy(
            dict(authorization)
        ),
        "plan": copy.deepcopy(EXTERNAL_REVIEW_PLAN_REF),
        "traceability": copy.deepcopy(
            EXTERNAL_REVIEW_LEDGER_REF
        ),
        "parentH2": parent_projection,
        "package": package,
        "bundlePath": EXTERNAL_REVIEW_TIER_DESTINATIONS[4],
        "lease": copy.deepcopy(dict(lease_record)),
    }
    owner = {
        "schemaVersion": (
            "quant-radar-ui-ux-historical-stack-"
            "external-review-continuation-owner/v1"
        ),
        "externalReviewCorrectionId": (
            EXTERNAL_REVIEW_CORRECTION_ID
        ),
        "externalReviewTierId": EXTERNAL_REVIEW_TIER_ID,
    }
    values = {"prechange": prechange, "owner": owner}
    if owner_record is not None and archive_record is not None:
        values["bundle"] = {
            "schemaVersion": (
                "quant-radar-ui-ux-historical-stack-"
                "external-review-continuation-bundle/v1"
            ),
            "status": "sealed",
            "externalReviewCorrectionId": (
                EXTERNAL_REVIEW_CORRECTION_ID
            ),
            "externalReviewTierId": EXTERNAL_REVIEW_TIER_ID,
            "ownerMarker": _artifact_ref(owner_record),
            "archive": _artifact_ref(archive_record),
            "archivedPaths": list(
                EXTERNAL_REVIEW_PACKAGE_PATHS
            ),
            "namespaceLeafCount": 3,
        }
    if prechange_record is not None and bundle_record is not None:
        values["rollback"] = {
            "schemaVersion": (
                "quant-radar-ui-ux-historical-stack-"
                "external-review-continuation-rollback/v1"
            ),
            "status": "ready",
            "externalReviewCorrectionId": (
                EXTERNAL_REVIEW_CORRECTION_ID
            ),
            "externalReviewTierId": EXTERNAL_REVIEW_TIER_ID,
            "prechange": _artifact_ref(prechange_record),
            "bundleManifest": _artifact_ref(bundle_record),
            "entries": [
                {
                    "path": record["path"],
                    "artifact": _artifact_ref(record),
                    "disposition": "restore_whole_if_exact",
                }
                for record in sorted(
                    package_records,
                    key=lambda item: item["path"],
                )
            ],
            "destructiveGitAllowed": False,
        }
    return values


@contextlib.contextmanager
def _external_review_lease(
    workspace_fd: int,
    *,
    allow_create: bool,
) -> Any:
    relative = EXTERNAL_REVIEW_TIER_DESTINATIONS[1]
    created = False
    if allow_create:
        try:
            lease_fd = _create_relative_file(
                workspace_fd,
                relative,
                b"",
                0o600,
            )
            created = True
            os.fsync(lease_fd)
            _fsync_relative_parent(workspace_fd, relative)
        except NamespaceCollision:
            lease_fd = os.open(
                relative,
                os.O_RDWR
                | os.O_NOFOLLOW
                | getattr(os, "O_CLOEXEC", 0),
                dir_fd=workspace_fd,
            )
    else:
        lease_fd = os.open(
            relative,
            os.O_RDWR
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0),
            dir_fd=workspace_fd,
        )
    try:
        observed = os.fstat(lease_fd)
        if (
            not stat.S_ISREG(observed.st_mode)
            or stat.S_IMODE(observed.st_mode) != 0o600
            or observed.st_uid != os.getuid()
            or observed.st_gid != os.getgid()
            or observed.st_nlink != 1
            or observed.st_size != 0
        ):
            raise ContractViolation(
                "Sequence 15 lease is unsafe"
            )
        try:
            fcntl.flock(
                lease_fd,
                fcntl.LOCK_EX | fcntl.LOCK_NB,
            )
        except BlockingIOError as exc:
            raise BlockingIOError(
                "Sequence 15 lease is busy"
            ) from exc
        yield _file_record_from_fd(relative, lease_fd), created
    finally:
        try:
            fcntl.flock(lease_fd, fcntl.LOCK_UN)
        finally:
            os.close(lease_fd)


def _validate_external_review_tier_complete(
    workspace_fd: int,
    source_root_fd: int,
) -> dict[str, Any]:
    parent_h2 = _import_sequence14_h2_packet(
        workspace_fd,
        source_root_fd=source_root_fd,
    )
    authorization = _external_review_authorization_binding(
        source_root_fd
    )
    archive_bytes, package_records = (
        _external_review_archive_bytes(source_root_fd)
    )
    paths = EXTERNAL_REVIEW_TIER_DESTINATIONS
    lease_record, lease_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[1],
        )
    )
    prechange_record, prechange_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[2],
        )
    )
    rollback_record, rollback_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[3],
        )
    )
    directory = _open_relative_directory_fd(
        workspace_fd,
        paths[4],
    )
    try:
        observed = os.fstat(directory)
        if (
            stat.S_IMODE(observed.st_mode) != 0o700
            or observed.st_uid != os.getuid()
            or observed.st_gid != os.getgid()
            or set(os.listdir(directory))
            != {
                PurePosixPath(paths[5]).name,
                PurePosixPath(paths[6]).name,
                PurePosixPath(paths[7]).name,
            }
        ):
            raise ContractViolation(
                "Sequence 15 Tier directory differs"
            )
    finally:
        os.close(directory)
    owner_record, owner_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[5],
        )
    )
    archive_record, observed_archive = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[6],
        )
    )
    bundle_record, bundle_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[7],
        )
    )
    values = _external_review_tier_values(
        lease_record=lease_record,
        parent_h2=parent_h2,
        authorization=authorization,
        package_records=package_records,
        prechange_record=prechange_record,
        owner_record=owner_record,
        archive_record=archive_record,
        bundle_record=bundle_record,
    )
    if (
        lease_bytes != b""
        or observed_archive != archive_bytes
        or prechange_bytes
        != _canonical_json_bytes(values["prechange"])
        or owner_bytes != _canonical_json_bytes(values["owner"])
        or bundle_bytes != _canonical_json_bytes(values["bundle"])
        or rollback_bytes
        != _canonical_json_bytes(values["rollback"])
    ):
        raise ContractViolation(
            "Sequence 15 Tier bytes differ"
        )
    return {
        "lease": _artifact_ref(lease_record),
        "prechange": _artifact_ref(prechange_record),
        "rollback": _artifact_ref(rollback_record),
        "owner": _artifact_ref(owner_record),
        "archive": _artifact_ref(archive_record),
        "bundle": _artifact_ref(bundle_record),
    }


def _bootstrap_external_review_continuation(
    workspace_fd: int,
    *,
    source_root_fd: int,
) -> dict[str, Any]:
    created_any = False
    paths = EXTERNAL_REVIEW_TIER_DESTINATIONS
    with _lifecycle_correction_global_lock(workspace_fd):
        _parse_external_review_authorization_record(
            source_root_fd
        )
        parent_h2 = _import_sequence14_h2_packet(
            workspace_fd,
            source_root_fd=source_root_fd,
            require_initial=True,
        )
        archive_bytes, package_records = (
            _external_review_archive_bytes(source_root_fd)
        )
        with _external_review_lease(
            workspace_fd,
            allow_create=True,
        ) as (lease_record, created):
            created_any = created_any or created
            authorization = (
                _external_review_authorization_binding(
                    source_root_fd
                )
            )
            initial = _external_review_tier_values(
                lease_record=lease_record,
                parent_h2=parent_h2,
                authorization=authorization,
                package_records=package_records,
            )
            prechange_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[2],
                    _canonical_json_bytes(initial["prechange"]),
                )
            )
            created_any = created_any or created
            directory = _ensure_relative_directory_fd(
                workspace_fd,
                paths[4],
            )
            os.close(directory)
            owner_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[5],
                    _canonical_json_bytes(initial["owner"]),
                )
            )
            created_any = created_any or created
            archive_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[6],
                    archive_bytes,
                )
            )
            created_any = created_any or created
            completed = _external_review_tier_values(
                lease_record=lease_record,
                parent_h2=parent_h2,
                authorization=authorization,
                package_records=package_records,
                prechange_record=prechange_record,
                owner_record=owner_record,
                archive_record=archive_record,
            )
            bundle_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[7],
                    _canonical_json_bytes(completed["bundle"]),
                )
            )
            created_any = created_any or created
            completed = _external_review_tier_values(
                lease_record=lease_record,
                parent_h2=parent_h2,
                authorization=authorization,
                package_records=package_records,
                prechange_record=prechange_record,
                owner_record=owner_record,
                archive_record=archive_record,
                bundle_record=bundle_record,
            )
            rollback_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[3],
                    _canonical_json_bytes(completed["rollback"]),
                )
            )
            created_any = created_any or created
            _validate_external_review_tier_complete(
                workspace_fd,
                source_root_fd,
            )
    return {
        "exitCode": EXIT_SUCCESS,
        "created": created_any,
        "prechange": _artifact_ref(prechange_record),
        "rollback": _artifact_ref(rollback_record),
    }


def _external_review_parse_time(value: Any, label: str) -> int:
    if (
        not isinstance(value, str)
        or re.fullmatch(
            r"[0-9]{4}-[0-9]{2}-[0-9]{2}T"
            r"[0-9]{2}:[0-9]{2}:[0-9]{2}Z",
            value,
        )
        is None
    ):
        raise ContractViolation(
            f"Sequence 15 {label} is not UTC seconds"
        )
    try:
        return calendar.timegm(
            time.strptime(value, "%Y-%m-%dT%H:%M:%SZ")
        )
    except (ValueError, OverflowError) as exc:
        raise ContractViolation(
            f"Sequence 15 {label} is invalid"
        ) from exc


def _external_review_format_time(epoch: int) -> str:
    if type(epoch) is not int or epoch < 0:
        raise ContractViolation(
            "Sequence 15 timestamp epoch is invalid"
        )
    return time.strftime(
        "%Y-%m-%dT%H:%M:%SZ",
        time.gmtime(epoch),
    )


def _external_review_namespace_inventory() -> dict[str, Any]:
    return {
        "schemaVersion": (
            "quant-radar-ui-ux-historical-stack-"
            "external-review-namespace/v1"
        ),
        "initialState": "E0_PACKET",
        "forwardPaths": list(EXTERNAL_REVIEW_FORWARD_PATHS),
        "states": {
            "E0_PACKET": [1, 1, 0, 0, 0, 0],
            "E1_INTAKE": [1, 1, 1, 0, 0, 0],
            "E2_REVIEW": [1, 1, 1, 1, 0, 0],
        },
        "candidateForbidden": True,
        "rootForbidden": True,
    }


def _build_external_review_preflight_value(
    workspace_fd: int,
    source_root_fd: int,
    *,
    created_at: str,
    require_initial: bool,
) -> dict[str, Any]:
    created_epoch = _external_review_parse_time(
        created_at,
        "createdAt",
    )
    parent_h2 = _import_sequence14_h2_packet(
        workspace_fd,
        source_root_fd=source_root_fd,
        require_initial=require_initial,
    )
    current = _classify_external_review_forward(workspace_fd)
    if require_initial and current["state"] != "E0_PACKET":
        raise ContractViolation(
            "Sequence 15 preflight requires E0_PACKET"
        )
    projections = _import_later_source_projections_history(
        source_root_fd,
        "sequence15",
    )
    sandbox = {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-sandbox-policy/v1"
        ),
        "sandboxExecutable": "/usr/bin/sandbox-exec",
        "sandboxRequired": True,
        "workspaceReadOnly": True,
        "isolatedOutputRequired": True,
        "workspaceWriteSetRequired": [],
        "frozenRuntimeWritable": False,
        "networkAllowed": False,
        "browserAllowed": False,
        "packageInstallAllowed": False,
    }
    if not Path(sandbox["sandboxExecutable"]).is_file():
        raise ContractViolation(
            "Sequence 15 reviewer sandbox is unavailable"
        )
    parent_projection = {
        key: copy.deepcopy(parent_h2[key])
        for key in (
            "classification",
            "authorization",
            "authorities",
            "preflight",
            "report",
            "packet",
        )
    }
    return {
        "schemaVersion": (
            "quant-radar-ui-ux-historical-stack-"
            "external-review-preflight/v1"
        ),
        "status": "passed",
        "captureId": EXTERNAL_REVIEW_CAPTURE_ID,
        "parentContinuationId": (
            EXTERNAL_REVIEW_PARENT_CONTINUATION_ID
        ),
        "externalReviewCorrectionId": (
            EXTERNAL_REVIEW_CORRECTION_ID
        ),
        "externalReviewTierId": EXTERNAL_REVIEW_TIER_ID,
        "authorizationRecord": (
            _external_review_authorization_binding(
                source_root_fd
            )
        ),
        "plan": copy.deepcopy(EXTERNAL_REVIEW_PLAN_REF),
        "traceability": copy.deepcopy(
            EXTERNAL_REVIEW_LEDGER_REF
        ),
        "parentH2": parent_projection,
        "initialState": "E0_PACKET",
        "sourceProjection": projections["sourceProjection"],
        "supplementalProjection": projections[
            "supplementalProjection"
        ],
        "runtimeReceipt": _import_sequence12_runtime_history(
            workspace_fd
        ),
        "makeContract": _external_review_make_contract(
            source_root_fd
        ),
        "namespaceInventory": (
            _external_review_namespace_inventory()
        ),
        "reviewerAppointment": (
            _external_review_reviewer_appointment()
        ),
        "reviewerSubmissionCapability": (
            _external_review_submission_capability()
        ),
        "reviewerSandbox": sandbox,
        "descriptorProfile": (
            _build_external_review_descriptor_profile()
        ),
        "tier": _validate_external_review_tier_complete(
            workspace_fd,
            source_root_fd,
        ),
        "createdAt": created_at,
        "reviewDeadline": _external_review_format_time(
            created_epoch
            + EXTERNAL_REVIEW_REVIEW_WINDOW_SECONDS
        ),
        "formalPause": "E2_REVIEW",
        "candidateForbidden": True,
        "rootForbidden": True,
    }


def _validate_external_review_preflight_value(
    workspace_fd: int,
    source_root_fd: int,
    value: Any,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ContractViolation(
            "Sequence 15 preflight is not an object"
        )
    created_at = value.get("createdAt")
    expected = _build_external_review_preflight_value(
        workspace_fd,
        source_root_fd,
        created_at=created_at,
        require_initial=False,
    )
    created_epoch = _external_review_parse_time(
        created_at,
        "createdAt",
    )
    deadline_epoch = _external_review_parse_time(
        value.get("reviewDeadline"),
        "reviewDeadline",
    )
    if (
        deadline_epoch
        != created_epoch + EXTERNAL_REVIEW_REVIEW_WINDOW_SECONDS
        or value != expected
        or set(value) != set(expected)
    ):
        raise ContractViolation(
            "Sequence 15 preflight differs"
        )
    return copy.deepcopy(expected)


def _reauthenticate_external_review_preflight(
    workspace_fd: int,
    source_root_fd: int,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    record, payload = _relative_regular_record_and_bytes(
        workspace_fd,
        EXTERNAL_REVIEW_PREFLIGHT_PATH,
    )
    value = _strict_json_bytes(payload, allow_float=True)
    if (
        record["mode"] != "0600"
        or record["uid"] != os.getuid()
        or record["gid"] != os.getgid()
        or record["nlink"] != 1
        or not isinstance(value, dict)
        or payload != _canonical_json_bytes(value)
    ):
        raise ContractViolation(
            "Sequence 15 preflight is unsafe"
        )
    authenticated = _validate_external_review_preflight_value(
        workspace_fd,
        source_root_fd,
        value,
    )
    current = _classify_external_review_forward(workspace_fd)
    return record, authenticated, current


def _external_review_preflight_lifecycle(
    workspace_fd: int,
    *,
    source_root_fd: int,
    verify_only: bool,
    now: str | None = None,
) -> dict[str, Any]:
    with _lifecycle_correction_global_lock(workspace_fd):
        with _external_review_lease(
            workspace_fd,
            allow_create=False,
        ):
            if verify_only:
                record, _, current = (
                    _reauthenticate_external_review_preflight(
                        workspace_fd,
                        source_root_fd,
                    )
                )
                return {
                    "exitCode": EXIT_SUCCESS,
                    "created": False,
                    "state": current["state"],
                    "preflight": _artifact_ref(record),
                }
            if (
                _relative_leaf_lstat(
                    workspace_fd,
                    EXTERNAL_REVIEW_PREFLIGHT_PATH,
                )
                is not None
            ):
                record, _, current = (
                    _reauthenticate_external_review_preflight(
                        workspace_fd,
                        source_root_fd,
                    )
                )
                return {
                    "exitCode": EXIT_SUCCESS,
                    "created": False,
                    "state": current["state"],
                    "preflight": _artifact_ref(record),
                }
            created_at = (
                _external_review_format_time(
                    int(time.time())
                )
                if now is None
                else now
            )
            value = _build_external_review_preflight_value(
                workspace_fd,
                source_root_fd,
                created_at=created_at,
                require_initial=True,
            )
            record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    EXTERNAL_REVIEW_PREFLIGHT_PATH,
                    _canonical_json_bytes(value),
                )
            )
            reopened, _, current = (
                _reauthenticate_external_review_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            if (
                _artifact_ref(reopened)
                != _artifact_ref(record)
                or current["state"] != "E0_PACKET"
            ):
                raise ContractViolation(
                    "Sequence 15 preflight postcondition differs"
                )
            return {
                "exitCode": EXIT_SUCCESS,
                "created": created,
                "state": current["state"],
                "preflight": _artifact_ref(record),
            }


def _validate_external_review_manual_review_for_authority(
    review: Any,
    packet: dict[str, Any],
    *,
    packet_path: str,
    packet_bytes: bytes,
    preflight: Mapping[str, Any],
    expected_appointment: Mapping[str, Any],
    accepted_sha256: str,
    accepted_size: int,
    broker_now: str | None,
    initial_submission: bool,
    review_window_seconds: int,
    clock_skew_seconds: int,
    max_intake_bytes: int,
    contract_label: str,
) -> dict[str, Any]:
    if (
        not isinstance(contract_label, str)
        or not contract_label
        or packet_path != EXTERNAL_REVIEW_FORWARD_PATHS[1]
        or packet.get("schemaVersion")
        != "quant-radar-ui-ux-review-packet/v2"
        or len(packet.get("inputs", ())) != 5
        or len(packet.get("items", ())) != 125
        or packet_bytes != _canonical_json_bytes(packet)
    ):
        raise ContractViolation(
            contract_label + " packet binding differs"
        )
    if (
        not isinstance(preflight, Mapping)
        or preflight.get("reviewerAppointment")
        != dict(expected_appointment)
        or expected_appointment.get("actorType")
        != "independent-code-reviewer"
        or not isinstance(
            expected_appointment.get("reviewerId"),
            str,
        )
        or not expected_appointment["reviewerId"]
        or not isinstance(
            expected_appointment.get("reviewSessionId"),
            str,
        )
        or not expected_appointment["reviewSessionId"]
    ):
        raise ContractViolation(
            contract_label + " reviewer appointment differs"
        )
    _validate_manual_review_value(
        review,
        packet,
        packet_path,
        packet_bytes,
    )
    assert isinstance(review, dict)
    payload = _canonical_json_bytes(review)
    if (
        not isinstance(accepted_sha256, str)
        or re.fullmatch(r"[0-9a-f]{64}", accepted_sha256)
        is None
        or type(accepted_size) is not int
        or not (1 <= accepted_size <= max_intake_bytes)
        or len(payload) != accepted_size
        or hashlib.sha256(payload).hexdigest()
        != accepted_sha256
        or review.get("reviewer")
        != {
            "type": "independent-code-reviewer",
            "id": expected_appointment["reviewerId"],
        }
    ):
        raise ContractViolation(
            contract_label + " accepted candidate binding differs"
        )
    created_epoch = _external_review_parse_time(
        preflight.get("createdAt"),
        "createdAt",
    )
    deadline_epoch = _external_review_parse_time(
        preflight.get("reviewDeadline"),
        "reviewDeadline",
    )
    reviewed_epoch = _external_review_parse_time(
        review.get("reviewedAt"),
        "reviewedAt",
    )
    if (
        deadline_epoch
        != created_epoch + review_window_seconds
        or reviewed_epoch < created_epoch
        or reviewed_epoch > deadline_epoch
    ):
        raise ContractViolation(
            contract_label
            + " review timestamp is outside authority"
        )
    if initial_submission:
        broker_epoch = _external_review_parse_time(
            broker_now,
            "brokerNow",
        )
        if (
            reviewed_epoch
            > broker_epoch + clock_skew_seconds
            or broker_epoch
            > deadline_epoch + clock_skew_seconds
        ):
            raise ContractViolation(
                contract_label + " initial submission is stale"
            )
    elif broker_now is not None:
        raise ContractViolation(
            contract_label
            + " reconcile cannot consult ambient time"
        )
    item_rejected = False
    for item in review["items"]:
        if not item["explanation"].strip():
            raise ContractViolation(
                contract_label + " item explanation is empty"
            )
        item_rejected = (
            item_rejected or item["verdict"] == "rejected"
        )
    finding_ids: set[str] = set()
    blocking_finding = False
    for finding in review["findings"]:
        if (
            not finding["id"].strip()
            or not finding["summary"].strip()
            or finding["id"] in finding_ids
        ):
            raise ContractViolation(
                contract_label + " finding identity/text differs"
            )
        finding_ids.add(finding["id"])
        blocking_finding = blocking_finding or (
            finding["severity"] in {"High", "Medium"}
            and finding["status"] == "unresolved"
        )
    expected_decision = (
        "rejected"
        if item_rejected or blocking_finding
        else "accepted"
    )
    if (
        review["decision"] != expected_decision
        or review["status"] != expected_decision
    ):
        raise ContractViolation(
            contract_label + " reviewer decision truth differs"
        )
    return {
        "decision": expected_decision,
        "reviewedAt": review["reviewedAt"],
        "candidateSha256": accepted_sha256,
        "candidateSize": accepted_size,
        "rejectedItems": sum(
            item["verdict"] == "rejected"
            for item in review["items"]
        ),
        "blockingFindings": sum(
            finding["severity"] in {"High", "Medium"}
            and finding["status"] == "unresolved"
            for finding in review["findings"]
        ),
    }


def _validate_external_review_manual_review(
    review: Any,
    packet: dict[str, Any],
    *,
    packet_path: str,
    packet_bytes: bytes,
    preflight: Mapping[str, Any],
    accepted_sha256: str,
    accepted_size: int,
    broker_now: str | None,
    initial_submission: bool,
) -> dict[str, Any]:
    return _validate_external_review_manual_review_for_authority(
        review,
        packet,
        packet_path=packet_path,
        packet_bytes=packet_bytes,
        preflight=preflight,
        expected_appointment=(
            _external_review_reviewer_appointment()
        ),
        accepted_sha256=accepted_sha256,
        accepted_size=accepted_size,
        broker_now=broker_now,
        initial_submission=initial_submission,
        review_window_seconds=(
            EXTERNAL_REVIEW_REVIEW_WINDOW_SECONDS
        ),
        clock_skew_seconds=EXTERNAL_REVIEW_CLOCK_SKEW_SECONDS,
        max_intake_bytes=EXTERNAL_REVIEW_MAX_INTAKE_BYTES,
        contract_label="Sequence 15",
    )


def _external_review_material_refs_for_profile(
    packet: Mapping[str, Any],
    source_projection: Mapping[str, Any],
    supplemental_projection: Mapping[str, Any],
    *,
    expected_supplemental_count: int,
    expected_retained_count: int,
    contract_label: str,
) -> dict[str, dict[str, Any]]:
    if (
        not isinstance(packet, Mapping)
        or packet.get("schemaVersion")
        != "quant-radar-ui-ux-review-packet/v2"
        or not isinstance(source_projection, Mapping)
        or not isinstance(supplemental_projection, Mapping)
    ):
        raise ContractViolation(
            contract_label + " material inputs are invalid"
        )
    packet_refs: list[Mapping[str, Any]] = []
    inputs = packet.get("inputs")
    items = packet.get("items")
    if (
        not isinstance(inputs, list)
        or len(inputs) != 5
        or not isinstance(items, list)
        or len(items) != 125
    ):
        raise ContractViolation(
            contract_label + " material cardinality differs"
        )
    packet_refs.extend(inputs)
    for item in items:
        if not isinstance(item, Mapping):
            raise ContractViolation(
                contract_label + " packet item is invalid"
            )
        for key in ("before", "after", "afterSidecar"):
            if key in item:
                packet_refs.append(item[key])

    def merge(
        target: dict[str, dict[str, Any]],
        row: Mapping[str, Any],
        *,
        source: str,
    ) -> None:
        if (
            not isinstance(row, Mapping)
            or set(row) - {"path", "sha256", "size", "mode"}
            or not _is_safe_relative_path(row.get("path"))
            or not isinstance(row.get("sha256"), str)
            or re.fullmatch(r"[0-9a-f]{64}", row["sha256"])
            is None
            or type(row.get("size")) is not int
            or row["size"] < 0
        ):
            raise ContractViolation(
                contract_label + " material reference is invalid"
            )
        normalized = {
            "path": row["path"],
            "sha256": row["sha256"],
            "size": row["size"],
            "source": source,
        }
        if "mode" in row:
            if (
                not isinstance(row["mode"], str)
                or row["mode"] not in {"0444", "0555"}
            ):
                raise ContractViolation(
                    contract_label
                    + " source material mode differs"
                )
            normalized["mode"] = row["mode"]
        existing = target.get(row["path"])
        if existing is not None:
            if (
                existing["sha256"] != normalized["sha256"]
                or existing["size"] != normalized["size"]
                or (
                    "mode" in existing
                    and "mode" in normalized
                    and existing["mode"] != normalized["mode"]
                )
            ):
                raise ContractViolation(
                    contract_label
                    + " material references conflict"
                )
            return
        target[row["path"]] = normalized

    packet_materials: dict[str, dict[str, Any]] = {}
    for row in packet_refs:
        merge(packet_materials, row, source="packet")
    if len(packet_materials) != 291:
        raise ContractViolation(
            contract_label + " packet material count differs"
        )
    source_records = source_projection.get("records")
    supplemental_records = supplemental_projection.get("records")
    if (
        not isinstance(source_records, list)
        or len(source_records) != 270
        or not isinstance(supplemental_records, list)
        or len(supplemental_records)
        != expected_supplemental_count
    ):
        raise ContractViolation(
            contract_label + " source material count differs"
        )
    materials = dict(packet_materials)
    for row in source_records:
        merge(materials, row, source="source")
    for row in supplemental_records:
        merge(materials, row, source="supplemental")
    if len(materials) != expected_retained_count:
        raise ContractViolation(
            contract_label + " retained material set differs"
        )
    return {
        path: materials[path] for path in sorted(materials)
    }


def _external_review_material_refs(
    packet: Mapping[str, Any],
    source_projection: Mapping[str, Any],
    supplemental_projection: Mapping[str, Any],
) -> dict[str, dict[str, Any]]:
    return _external_review_material_refs_for_profile(
        packet,
        source_projection,
        supplemental_projection,
        expected_supplemental_count=61,
        expected_retained_count=EXTERNAL_REVIEW_RETAINED_LEAVES,
        contract_label="Sequence 15",
    )


def _open_external_review_leaf_fd(
    workspace_fd: int,
    relative: str,
) -> int:
    if (
        type(workspace_fd) is not int
        or workspace_fd < 0
        or not _is_safe_relative_path(relative)
    ):
        raise ContractViolation(
            "Sequence 15 material path is invalid"
        )
    parts = relative.split("/")
    current_fd = os.dup(workspace_fd)
    directory_flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | os.O_NOFOLLOW
        | getattr(os, "O_CLOEXEC", 0)
    )
    try:
        for component in parts[:-1]:
            named = os.stat(
                component,
                dir_fd=current_fd,
                follow_symlinks=False,
            )
            next_fd = os.open(
                component,
                directory_flags,
                dir_fd=current_fd,
            )
            try:
                observed = os.fstat(next_fd)
                if (
                    not stat.S_ISDIR(named.st_mode)
                    or not stat.S_ISDIR(observed.st_mode)
                    or (
                        named.st_dev,
                        named.st_ino,
                    )
                    != (
                        observed.st_dev,
                        observed.st_ino,
                    )
                    or observed.st_uid != os.getuid()
                    or observed.st_gid not in {os.getgid(), 0}
                    or stat.S_IMODE(observed.st_mode) & 0o022
                ):
                    raise ContractViolation(
                        "Sequence 15 material ancestor is unsafe: "
                        + component
                    )
            except BaseException:
                os.close(next_fd)
                raise
            os.close(current_fd)
            current_fd = next_fd
        return os.open(
            parts[-1],
            os.O_RDONLY
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0),
            dir_fd=current_fd,
        )
    except OSError as exc:
        raise ContractViolation(
            "Sequence 15 material path is unavailable: "
            + relative
        ) from exc
    finally:
        os.close(current_fd)


def _historical_source_material_receipt(
    source_root_fd: int,
    preflight: Mapping[str, Any],
    sequence: str,
) -> dict[str, Any]:
    imported = _import_later_source_projections_history(
        source_root_fd,
        sequence,
    )
    if (
        not isinstance(preflight, Mapping)
        or preflight.get("sourceProjection")
        != imported["sourceProjection"]
        or preflight.get("supplementalProjection")
        != imported["supplementalProjection"]
    ):
        raise ContractViolation(
            "historical material projection differs"
        )
    references: dict[str, dict[str, Any]] = {}
    for projection_name, projection in imported.items():
        source = (
            "source"
            if projection_name == "sourceProjection"
            else "supplemental"
        )
        for record in projection["records"]:
            path = record["path"]
            declared = {**record, "source": source}
            previous = references.get(path)
            if previous is not None and previous != declared:
                raise ContractViolation(
                    "historical material declaration conflicts: "
                    + path
                )
            references[path] = copy.deepcopy(declared)
    authority = HISTORICAL_SOURCE_PROJECTION_REFS.get(sequence)
    if authority is None:
        raise ContractViolation(
            "historical material authority is unavailable"
        )
    return {
        "authority": {
            key: authority[key]
            for key in ("path", "sha256", "size", "mode")
        },
        "references": references,
    }


@contextlib.contextmanager
def _external_review_material_transaction(
    workspace_fd: int,
    references: Mapping[str, Mapping[str, Any]],
    descriptor_profile: Mapping[str, Any],
    *,
    historical_receipt: Mapping[str, Any] | None = None,
) -> Any:
    if (
        type(workspace_fd) is not int
        or workspace_fd < 0
        or not stat.S_ISDIR(os.fstat(workspace_fd).st_mode)
        or not isinstance(references, Mapping)
    ):
        raise ContractViolation(
            "Sequence 15 material transaction inputs differ"
        )
    profile = _validate_external_review_descriptor_profile(
        copy.deepcopy(dict(descriptor_profile))
    )
    if (
        len(references)
        != profile["worstCaseUniqueRetainedLeaves"]
    ):
        raise ContractViolation(
            "Sequence 15 material transaction count differs"
        )
    historical_references: Mapping[str, Mapping[str, Any]]
    historical_authority: Mapping[str, Any] | None
    if historical_receipt is None:
        historical_references = {}
        historical_authority = None
    else:
        if (
            not isinstance(historical_receipt, Mapping)
            or set(historical_receipt)
            != {"authority", "references"}
            or not isinstance(
                historical_receipt.get("authority"),
                Mapping,
            )
            or not isinstance(
                historical_receipt.get("references"),
                Mapping,
            )
        ):
            raise ContractViolation(
                "Sequence 15 historical material receipt differs"
            )
        historical_authority = historical_receipt["authority"]
        historical_references = historical_receipt["references"]
        if (
            set(historical_authority)
            != {"path", "sha256", "size", "mode"}
            or not set(historical_references).issubset(references)
            or any(
                references.get(path) != expected
                for path, expected in historical_references.items()
            )
        ):
            raise ContractViolation(
                "Sequence 15 historical material binding differs"
            )
    original_soft, original_hard = resource.getrlimit(
        resource.RLIMIT_NOFILE
    )
    if (
        profile["hardLimit"] != original_hard
        or original_hard < profile["requiredSoftFloor"]
    ):
        raise ContractViolation(
            "Sequence 15 descriptor capacity drifted"
        )
    target_soft = max(
        original_soft,
        profile["requiredSoftFloor"],
    )
    if target_soft > profile["raiseCeiling"]:
        if original_soft < profile["requiredSoftFloor"]:
            raise ContractViolation(
                "Sequence 15 descriptor ceiling is unavailable"
            )
        target_soft = original_soft
    raised = target_soft != original_soft
    if raised:
        try:
            resource.setrlimit(
                resource.RLIMIT_NOFILE,
                (target_soft, original_hard),
            )
        except OSError as exc:
            raise ContractViolation(
                "Sequence 15 descriptor floor is unavailable"
            ) from exc
        if resource.getrlimit(resource.RLIMIT_NOFILE) != (
            target_soft,
            original_hard,
        ):
            raise ContractViolation(
                "Sequence 15 descriptor raise did not apply"
            )
    retained: dict[str, dict[str, Any]] = {}

    def authenticate(
        path: str,
        expected: Mapping[str, Any],
        fd: int,
        *,
        require_named: bool,
        require_exact_mode: bool = False,
    ) -> None:
        observed = os.fstat(fd)
        observed_mode = stat.S_IMODE(observed.st_mode)
        expected_mode = expected.get("mode")
        projected_mode = (
            "0555" if observed_mode & 0o111 else "0444"
        )
        if (
            not stat.S_ISREG(observed.st_mode)
            or observed.st_uid != os.getuid()
            or observed.st_gid not in {os.getgid(), 0}
            or observed.st_nlink != 1
            or observed.st_size != expected["size"]
            or observed_mode & 0o022
            or (
                require_exact_mode
                and observed_mode != int(expected_mode, 8)
            )
            or (
                not require_exact_mode
                and expected_mode is not None
                and (
                    expected_mode not in {"0444", "0555"}
                    or projected_mode != expected_mode
                )
            )
        ):
            raise ContractViolation(
                "Sequence 15 material metadata differs: " + path
            )
        os.lseek(fd, 0, os.SEEK_SET)
        digest = hashlib.sha256()
        total = 0
        while chunk := os.read(fd, 1_048_576):
            total += len(chunk)
            if total > expected["size"]:
                raise ContractViolation(
                    "Sequence 15 material grew: " + path
                )
            digest.update(chunk)
        if (
            total != expected["size"]
            or digest.hexdigest() != expected["sha256"]
        ):
            raise ContractViolation(
                "Sequence 15 material bytes differ: " + path
            )
        if require_named:
            named_fd = _open_external_review_leaf_fd(
                workspace_fd,
                path,
            )
            try:
                named = os.fstat(named_fd)
                if (
                    named.st_dev,
                    named.st_ino,
                ) != (
                    observed.st_dev,
                    observed.st_ino,
                ):
                    raise ContractViolation(
                        "Sequence 15 material name changed: "
                        + path
                    )
            finally:
                os.close(named_fd)

    def reauthenticate() -> None:
        for path, row in retained.items():
            authenticate(
                row["authenticatedPath"],
                row["authenticatedExpected"],
                row["fd"],
                require_named=True,
                require_exact_mode=row["historical"],
            )

    def read_retained(path: str) -> bytes:
        row = retained.get(path)
        if row is None:
            raise ContractViolation(
                "Sequence 15 retained material is absent: " + path
            )
        if row["historical"]:
            raise ContractViolation(
                "Sequence 15 historical declaration is not readable: "
                + path
            )
        authenticate(
            row["authenticatedPath"],
            row["authenticatedExpected"],
            row["fd"],
            require_named=True,
            require_exact_mode=False,
        )
        os.lseek(row["fd"], 0, os.SEEK_SET)
        chunks: list[bytes] = []
        total = 0
        while chunk := os.read(row["fd"], 1_048_576):
            total += len(chunk)
            if total > row["expected"]["size"]:
                raise ContractViolation(
                    "Sequence 15 retained material grew: " + path
                )
            chunks.append(chunk)
        payload = b"".join(chunks)
        if (
            len(payload) != row["expected"]["size"]
            or hashlib.sha256(payload).hexdigest()
            != row["expected"]["sha256"]
        ):
            raise ContractViolation(
                "Sequence 15 retained read differs: " + path
            )
        return payload

    try:
        for path in sorted(references):
            expected = references[path]
            if (
                not isinstance(expected, Mapping)
                or expected.get("path") != path
            ):
                raise ContractViolation(
                    "Sequence 15 material map differs"
                )
            historical = path in historical_references
            authenticated_path = (
                historical_authority["path"]
                if historical and historical_authority is not None
                else path
            )
            authenticated_expected = (
                historical_authority
                if historical and historical_authority is not None
                else expected
            )
            fd = _open_external_review_leaf_fd(
                workspace_fd,
                authenticated_path,
            )
            try:
                authenticate(
                    authenticated_path,
                    authenticated_expected,
                    fd,
                    require_named=True,
                    require_exact_mode=historical,
                )
            except BaseException:
                os.close(fd)
                raise
            retained[path] = {
                "fd": fd,
                "expected": copy.deepcopy(dict(expected)),
                "authenticatedPath": authenticated_path,
                "authenticatedExpected": copy.deepcopy(
                    dict(authenticated_expected)
                ),
                "historical": historical,
            }
        reauthenticate()
        yield {
            "count": len(retained),
            "paths": list(retained),
            "reauthenticate": reauthenticate,
            "read": read_retained,
        }
        reauthenticate()
    finally:
        for row in retained.values():
            os.close(row["fd"])
        if raised:
            try:
                resource.setrlimit(
                    resource.RLIMIT_NOFILE,
                    (original_soft, original_hard),
                )
            except OSError as exc:
                raise ContractViolation(
                    "Sequence 15 descriptor limit was not restored"
                ) from exc
        if resource.getrlimit(resource.RLIMIT_NOFILE) != (
            original_soft,
            original_hard,
        ):
            raise ContractViolation(
                "Sequence 15 descriptor restore differs"
            )


@contextlib.contextmanager
def _historical_external_review_material_transaction(
    workspace_fd: int,
    source_root_fd: int,
    references: Mapping[str, Mapping[str, Any]],
    descriptor_profile: Mapping[str, Any],
    preflight: Mapping[str, Any],
    sequence: str,
) -> Any:
    receipt = _historical_source_material_receipt(
        source_root_fd,
        preflight,
        sequence,
    )
    with _external_review_material_transaction(
        workspace_fd,
        references,
        descriptor_profile,
        historical_receipt=receipt,
    ) as retained:
        yield retained


def _publish_external_review_payload(
    workspace_fd: int,
    relative: str,
    payload: bytes,
    *,
    fault_after: str | None = None,
    syscalls: Any | None = None,
    precommit: Callable[[], None] | None = None,
    postrename_prefsync: Callable[[], None] | None = None,
    postfsync: Callable[[], None] | None = None,
    postcommit: Callable[[], None] | None = None,
) -> dict[str, Any]:
    if (
        not _is_safe_relative_path(relative)
        or not isinstance(payload, bytes)
        or not payload
        or len(payload) > EXTERNAL_REVIEW_MAX_INTAKE_BYTES
    ):
        raise ContractViolation(
            "Sequence 15 publication input differs"
        )
    parent, name = relative.rsplit("/", 1)
    parent_fd = _open_relative_directory_fd(
        workspace_fd,
        parent,
    )
    try:
        published = _publish_regular_exact(
            parent_fd,
            name,
            payload,
            fault_after=fault_after,
            syscalls=syscalls,
            precommit=precommit,
            postrename_prefsync=postrename_prefsync,
            postfsync=postfsync,
            postcommit=postcommit,
        )
    finally:
        os.close(parent_fd)
    if published.get("exitCode") != EXIT_SUCCESS:
        return {
            "exitCode": published["exitCode"],
            "created": bool(published.get("created")),
            "record": None,
        }
    record = dict(published["published"])
    record["path"] = relative
    return {
        "exitCode": EXIT_SUCCESS,
        "created": bool(published["created"]),
        "record": record,
    }


def _read_external_review_stdin(stream: Any) -> bytes:
    if not hasattr(stream, "read"):
        raise ContractViolation(
            "Sequence 15 intake stream is invalid"
        )
    chunks: list[bytes] = []
    total = 0
    while True:
        chunk = stream.read(
            min(
                131_072,
                EXTERNAL_REVIEW_MAX_INTAKE_BYTES + 1 - total,
            )
        )
        if not isinstance(chunk, bytes):
            raise ContractViolation(
                "Sequence 15 intake stream is not binary"
            )
        if not chunk:
            break
        chunks.append(chunk)
        total += len(chunk)
        if total > EXTERNAL_REVIEW_MAX_INTAKE_BYTES:
            raise ContractViolation(
                "Sequence 15 intake exceeds the byte bound"
            )
    payload = b"".join(chunks)
    if not payload:
        raise ContractViolation(
            "Sequence 15 intake is empty"
        )
    return payload


def _external_review_runtime_boundary(
    workspace_fd: int,
    preflight: Mapping[str, Any],
) -> None:
    if (
        not isinstance(preflight, Mapping)
        or _import_sequence12_runtime_history(workspace_fd)
        != preflight.get("runtimeReceipt")
    ):
        raise ContractViolation(
            "Sequence 15 runtime receipt drifted"
        )


def _validate_external_review_forward_semantics(
    workspace_fd: int,
    source_root_fd: int,
    *,
    preflight: Mapping[str, Any],
    broker_now: str | None = None,
    initial_submission: bool = False,
) -> dict[str, Any]:
    parent_h2 = _import_sequence14_h2_packet(
        workspace_fd,
        source_root_fd=source_root_fd,
    )
    current = _classify_external_review_forward(workspace_fd)
    records = current["records"]
    payloads = current["payloads"]
    values = current["values"]
    for index, expected in enumerate(
        EXTERNAL_REVIEW_PARENT_REFS[-2:]
    ):
        observed = records[index]
        if (
            observed is None
            or {
                key: observed[key]
                for key in ("path", "sha256", "size", "mode")
            }
            != expected
        ):
            raise ContractViolation(
                "Sequence 15 parent H2 forward leaf differs"
            )
    if (
        values[0] != parent_h2["reportValue"]
        or values[1] != parent_h2["packetValue"]
    ):
        raise ContractViolation(
            "Sequence 15 parent H2 values differ"
        )
    if current["state"] == "E0_PACKET":
        if initial_submission:
            return current
        return current
    intake_record = records[2]
    intake_payload = payloads[2]
    intake_value = values[2]
    assert (
        intake_record is not None
        and intake_payload is not None
        and isinstance(intake_value, dict)
    )
    intake_validation = _validate_external_review_manual_review(
        intake_value,
        parent_h2["packetValue"],
        packet_path=EXTERNAL_REVIEW_FORWARD_PATHS[1],
        packet_bytes=payloads[1],
        preflight=preflight,
        accepted_sha256=intake_record["sha256"],
        accepted_size=intake_record["size"],
        broker_now=broker_now,
        initial_submission=initial_submission,
    )
    current["decision"] = intake_validation["decision"]
    current["intakeValidation"] = intake_validation
    if current["state"] == "E1_INTAKE":
        return current
    review_record = records[3]
    review_payload = payloads[3]
    review_value = values[3]
    assert (
        review_record is not None
        and review_payload is not None
        and isinstance(review_value, dict)
    )
    _validate_external_review_manual_review(
        review_value,
        parent_h2["packetValue"],
        packet_path=EXTERNAL_REVIEW_FORWARD_PATHS[1],
        packet_bytes=payloads[1],
        preflight=preflight,
        accepted_sha256=review_record["sha256"],
        accepted_size=review_record["size"],
        broker_now=None,
        initial_submission=False,
    )
    if (
        review_payload != intake_payload
        or review_value != intake_value
        or review_record["inode"] == intake_record["inode"]
    ):
        raise ContractViolation(
            "Sequence 15 review is not an exact different-inode copy"
        )
    return current


def _external_review_materials_from_preflight(
    packet: Mapping[str, Any],
    preflight: Mapping[str, Any],
) -> dict[str, dict[str, Any]]:
    return _external_review_material_refs(
        packet,
        preflight.get("sourceProjection", {}),
        preflight.get("supplementalProjection", {}),
    )


def _submit_external_review_intake(
    workspace_fd: int,
    *,
    source_root_fd: int,
    payload: bytes,
    accepted_sha256: str,
    accepted_size: int,
    broker_now: str | None = None,
    fault_after: str | None = None,
    syscalls: Any | None = None,
) -> dict[str, Any]:
    if (
        not isinstance(payload, bytes)
        or not payload
        or len(payload) > EXTERNAL_REVIEW_MAX_INTAKE_BYTES
        or not isinstance(accepted_sha256, str)
        or re.fullmatch(r"[0-9a-f]{64}", accepted_sha256)
        is None
        or type(accepted_size) is not int
        or len(payload) != accepted_size
        or hashlib.sha256(payload).hexdigest()
        != accepted_sha256
    ):
        raise ContractViolation(
            "Sequence 15 submitted candidate digest differs"
        )
    value = _strict_json_bytes(payload)
    if (
        not isinstance(value, dict)
        or payload != _canonical_json_bytes(value)
    ):
        raise ContractViolation(
            "Sequence 15 submitted candidate is noncanonical"
        )
    now_text = (
        _external_review_format_time(int(time.time()))
        if broker_now is None
        else broker_now
    )
    with _lifecycle_correction_global_lock(workspace_fd):
        with _external_review_lease(
            workspace_fd,
            allow_create=False,
        ):
            _, preflight, _ = (
                _reauthenticate_external_review_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            current = _validate_external_review_forward_semantics(
                workspace_fd,
                source_root_fd,
                preflight=preflight,
            )
            state = current["state"]
            if state in {"E1_INTAKE", "E2_REVIEW"}:
                retained_payload = current["payloads"][2]
                if retained_payload != payload:
                    raise ContractViolation(
                        "Sequence 15 consumed session bytes differ"
                    )
                validation = (
                    _validate_external_review_manual_review(
                        value,
                        current["values"][1],
                        packet_path=(
                            EXTERNAL_REVIEW_FORWARD_PATHS[1]
                        ),
                        packet_bytes=current["payloads"][1],
                        preflight=preflight,
                        accepted_sha256=accepted_sha256,
                        accepted_size=accepted_size,
                        broker_now=None,
                        initial_submission=False,
                    )
                )
                materials = (
                    _external_review_materials_from_preflight(
                        current["values"][1],
                        preflight,
                    )
                )
                _external_review_runtime_boundary(
                    workspace_fd,
                    preflight,
                )
                with _historical_external_review_material_transaction(
                    workspace_fd,
                    source_root_fd,
                    materials,
                    preflight["descriptorProfile"],
                    preflight,
                    "sequence15",
                ):
                    _external_review_runtime_boundary(
                        workspace_fd,
                        preflight,
                    )
                _, reopened_preflight, _ = (
                    _reauthenticate_external_review_preflight(
                        workspace_fd,
                        source_root_fd,
                    )
                )
                reopened = (
                    _validate_external_review_forward_semantics(
                        workspace_fd,
                        source_root_fd,
                        preflight=reopened_preflight,
                    )
                )
                if (
                    reopened["state"] != state
                    or reopened["payloads"][2] != payload
                ):
                    raise ContractViolation(
                        "Sequence 15 reconcile state drifted"
                    )
                return {
                    "exitCode": EXIT_SUCCESS,
                    "created": False,
                    "state": state,
                    "decision": validation["decision"],
                    "intake": _artifact_ref(
                        reopened["records"][2]
                    ),
                }
            if state != "E0_PACKET":
                raise ContractViolation(
                    "Sequence 15 submit requires E0_PACKET"
                )
            validation = _validate_external_review_manual_review(
                value,
                current["values"][1],
                packet_path=EXTERNAL_REVIEW_FORWARD_PATHS[1],
                packet_bytes=current["payloads"][1],
                preflight=preflight,
                accepted_sha256=accepted_sha256,
                accepted_size=accepted_size,
                broker_now=now_text,
                initial_submission=True,
            )
            materials = _external_review_materials_from_preflight(
                current["values"][1],
                preflight,
            )
            _external_review_runtime_boundary(
                workspace_fd,
                preflight,
            )
            with _historical_external_review_material_transaction(
                workspace_fd,
                source_root_fd,
                materials,
                preflight["descriptorProfile"],
                preflight,
                "sequence15",
            ) as retained:

                def boundary() -> None:
                    retained["reauthenticate"]()
                    _external_review_runtime_boundary(
                        workspace_fd,
                        preflight,
                    )

                published = _publish_external_review_payload(
                    workspace_fd,
                    EXTERNAL_REVIEW_FORWARD_PATHS[2],
                    payload,
                    fault_after=fault_after,
                    syscalls=syscalls,
                    precommit=boundary,
                    postcommit=boundary,
                )
                if published["exitCode"] != EXIT_SUCCESS:
                    return {
                        "exitCode": published["exitCode"],
                        "created": published["created"],
                    }
                boundary()
            _, reopened_preflight, _ = (
                _reauthenticate_external_review_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            reopened = _validate_external_review_forward_semantics(
                workspace_fd,
                source_root_fd,
                preflight=reopened_preflight,
            )
            if (
                reopened["state"] != "E1_INTAKE"
                or reopened["payloads"][2] != payload
            ):
                raise ContractViolation(
                    "Sequence 15 intake postcondition differs"
                )
            return {
                "exitCode": EXIT_SUCCESS,
                "created": published["created"],
                "state": reopened["state"],
                "decision": validation["decision"],
                "intake": _artifact_ref(reopened["records"][2]),
            }


def _publish_external_review(
    workspace_fd: int,
    *,
    source_root_fd: int,
    fault_after: str | None = None,
    syscalls: Any | None = None,
) -> dict[str, Any]:
    with _lifecycle_correction_global_lock(workspace_fd):
        with _external_review_lease(
            workspace_fd,
            allow_create=False,
        ):
            _, preflight, _ = (
                _reauthenticate_external_review_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            current = _validate_external_review_forward_semantics(
                workspace_fd,
                source_root_fd,
                preflight=preflight,
            )
            if current["state"] == "E0_PACKET":
                raise ContractViolation(
                    "Sequence 15 review requires E1_INTAKE"
                )
            packet = current["values"][1]
            assert isinstance(packet, dict)
            materials = _external_review_materials_from_preflight(
                packet,
                preflight,
            )
            intake_payload = current["payloads"][2]
            intake_record = current["records"][2]
            assert (
                isinstance(intake_payload, bytes)
                and intake_record is not None
            )
            _external_review_runtime_boundary(
                workspace_fd,
                preflight,
            )
            with _historical_external_review_material_transaction(
                workspace_fd,
                source_root_fd,
                materials,
                preflight["descriptorProfile"],
                preflight,
                "sequence15",
            ) as retained:

                def boundary() -> None:
                    retained["reauthenticate"]()
                    _external_review_runtime_boundary(
                        workspace_fd,
                        preflight,
                    )

                if current["state"] == "E2_REVIEW":
                    boundary()
                    reopened = (
                        _validate_external_review_forward_semantics(
                            workspace_fd,
                            source_root_fd,
                            preflight=preflight,
                        )
                    )
                    if reopened["state"] != "E2_REVIEW":
                        raise ContractViolation(
                            "Sequence 15 review reconcile drifted"
                        )
                    return {
                        "exitCode": EXIT_SUCCESS,
                        "created": False,
                        "state": "E2_REVIEW",
                        "decision": reopened["decision"],
                        "review": _artifact_ref(
                            reopened["records"][3]
                        ),
                    }
                published = _publish_external_review_payload(
                    workspace_fd,
                    EXTERNAL_REVIEW_FORWARD_PATHS[3],
                    intake_payload,
                    fault_after=fault_after,
                    syscalls=syscalls,
                    precommit=boundary,
                    postcommit=boundary,
                )
                if published["exitCode"] != EXIT_SUCCESS:
                    return {
                        "exitCode": published["exitCode"],
                        "created": published["created"],
                    }
                if (
                    published["record"]["inode"]
                    == intake_record["inode"]
                ):
                    raise ContractViolation(
                        "Sequence 15 review aliases intake inode"
                    )
                boundary()
            _, reopened_preflight, _ = (
                _reauthenticate_external_review_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            reopened = _validate_external_review_forward_semantics(
                workspace_fd,
                source_root_fd,
                preflight=reopened_preflight,
            )
            if reopened["state"] != "E2_REVIEW":
                raise ContractViolation(
                    "Sequence 15 review postcondition differs"
                )
            return {
                "exitCode": EXIT_SUCCESS,
                "created": published["created"],
                "state": reopened["state"],
                "decision": reopened["decision"],
                "review": _artifact_ref(reopened["records"][3]),
            }


