def _lifecycle_test_correction_authorization_document_bytes(
) -> bytes:
    body = _canonical_json_bytes(
        _lifecycle_test_correction_authorization_body()
    ).decode("utf-8")
    return (
        "# Quant Radar UX-1B Sequence 16 Lifecycle-Test "
        "Correction\n\n"
        "Status: authorization candidate only. This document does not "
        "authorize bootstrap, preflight, intake submission, manual-review "
        "publication, capture, comparison, candidate, root, or theme work "
        "until the repository maintainer separately accepts its exact "
        "whole-document SHA-256, byte size, and mode.\n\n"
        + LIFECYCLE_TEST_CORRECTION_AUTH_START.decode("ascii")
        + body
        + LIFECYCLE_TEST_CORRECTION_AUTH_END.decode("ascii")
        + "\n\nSequence 16 imports the exact retained Sequence 15 "
        "`E0_PACKET` as immutable history, freezes corrected current "
        "source under a distinct authority, owns only the still-absent "
        "shared intake and review leaves, and stops at `C2_REVIEW`. "
        "It grants no capture, comparison, candidate, or root authority.\n"
    ).encode("utf-8")


def _parse_lifecycle_test_correction_authorization_record(
    source_root_fd: int,
) -> dict[str, Any]:
    record, document = _source_file_record(
        source_root_fd,
        LIFECYCLE_TEST_CORRECTION_AUTHORIZATION_DOCUMENT_PATH,
    )
    if (
        record["mode"] != "0644"
        or record["uid"] != os.getuid()
        or record["gid"] != os.getgid()
        or record["nlink"] != 1
        or document
        != (
            _lifecycle_test_correction_authorization_document_bytes()
        )
        or document.count(
            LIFECYCLE_TEST_CORRECTION_AUTH_GENERIC
        )
        != 2
    ):
        raise ContractViolation(
            "Sequence 16 authorization document differs"
        )
    for expected in (
        LIFECYCLE_TEST_CORRECTION_PLAN_REF,
        LIFECYCLE_TEST_CORRECTION_LEDGER_REF,
    ):
        observed, _ = _source_file_record(
            source_root_fd,
            expected["path"],
        )
        if {
            key: observed[key]
            for key in ("path", "sha256", "size", "mode")
        } != expected:
            raise ContractViolation(
                "Sequence 16 authority drifted: "
                + expected["path"]
            )
    return _lifecycle_test_correction_authorization_body()


def _lifecycle_test_correction_authorization_binding(
    source_root_fd: int,
) -> dict[str, Any]:
    body = (
        _parse_lifecycle_test_correction_authorization_record(
            source_root_fd
        )
    )
    record, _ = _source_file_record(
        source_root_fd,
        LIFECYCLE_TEST_CORRECTION_AUTHORIZATION_DOCUMENT_PATH,
    )
    return {
        **_artifact_ref(record),
        "bodySha256": hashlib.sha256(
            _canonical_json_bytes(body)
        ).hexdigest(),
    }


def _build_lifecycle_test_correction_source_projections(
    source_root_fd: int,
) -> dict[str, Any]:
    base = _build_external_review_source_projections(
        source_root_fd
    )
    mirror = base["sourceProjection"]
    mirror_paths = {
        row["path"] for row in mirror["records"]
    }
    records = {
        row["path"]: copy.deepcopy(row)
        for row in base["supplementalProjection"]["records"]
    }
    for relative in LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS:
        if relative in mirror_paths:
            continue
        record, _ = _source_file_record(
            source_root_fd,
            relative,
        )
        records[relative] = {
            "path": relative,
            "sha256": record["sha256"],
            "size": record["size"],
            "mode": (
                "0555"
                if int(record["mode"], 8) & 0o111
                else "0444"
            ),
        }
    paths = sorted(records)
    projection = _source_projection_value(
        "quant-radar-ui-ux-supplemental-source/v1",
        paths,
        mirror["policy"]["include"],
        [records[path] for path in paths],
    )
    if (
        len(mirror["records"]) != 270
        or len(projection["records"]) != 64
    ):
        raise ContractViolation(
            "Sequence 16 source projection counts differ"
        )
    return {
        "sourceProjection": mirror,
        "supplementalProjection": projection,
    }


def _lifecycle_test_correction_archive_bytes(
    source_root_fd: int,
) -> tuple[bytes, list[dict[str, Any]]]:
    output = io.BytesIO()
    records: list[dict[str, Any]] = []
    with tarfile.open(
        fileobj=output,
        mode="w",
        format=tarfile.PAX_FORMAT,
    ) as archive:
        for relative in LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS:
            record, payload = _source_file_record(
                source_root_fd,
                relative,
            )
            records.append(record)
            member = tarfile.TarInfo(relative)
            member.size = len(payload)
            member.mode = stat.S_IMODE(
                int(record["mode"], 8)
            )
            member.uid = 0
            member.gid = 0
            member.uname = ""
            member.gname = ""
            member.mtime = 0
            archive.addfile(member, io.BytesIO(payload))
    return output.getvalue(), records


def _lifecycle_test_correction_make_contract(
    source_root_fd: int,
) -> dict[str, Any]:
    record, payload = _source_file_record(
        source_root_fd,
        "Makefile",
    )
    targets = (
        "ui-ux1b-external-review-lifecycle-test-bootstrap",
        "ui-ux1b-external-review-lifecycle-test-preflight",
        "ui-ux1b-external-review-lifecycle-test-verify",
        (
            "ui-ux1b-external-review-lifecycle-test-"
            "submit-intake"
        ),
        "ui-ux1b-external-review-lifecycle-test-publish",
    )
    text = payload.decode("utf-8", errors="strict")
    if any(
        text.count(target + ":") != 1 for target in targets
    ):
        raise ContractViolation(
            "Sequence 16 Make contract differs"
        )
    return {
        "artifact": _artifact_ref(record),
        "targets": list(targets),
        "targetsSha256": hashlib.sha256(
            _canonical_json_bytes(list(targets))
        ).hexdigest(),
    }


def _build_lifecycle_test_correction_descriptor_profile(
) -> dict[str, Any]:
    _, hard_limit = resource.getrlimit(resource.RLIMIT_NOFILE)
    return _validate_external_review_descriptor_profile(
        {
            "schemaVersion": (
                "quant-radar-ui-ux-external-review-"
                "descriptor-profile/v1"
            ),
            "hardLimit": hard_limit,
            "worstCaseUniqueRetainedLeaves": (
                LIFECYCLE_TEST_CORRECTION_RETAINED_LEAVES
            ),
            "protocolAdditional": (
                LIFECYCLE_TEST_CORRECTION_PROTOCOL_ALLOWANCE
            ),
            "reserve": (
                LIFECYCLE_TEST_CORRECTION_DESCRIPTOR_RESERVE
            ),
            "requiredSoftFloor": (
                LIFECYCLE_TEST_CORRECTION_REQUIRED_SOFT_FLOOR
            ),
            "raiseCeiling": (
                LIFECYCLE_TEST_CORRECTION_DESCRIPTOR_CEILING
            ),
        }
    )


def _classify_lifecycle_test_correction_presence(
    presence: Sequence[bool],
) -> str:
    if (
        not isinstance(presence, Sequence)
        or isinstance(presence, (str, bytes))
        or len(presence) != 6
        or any(type(value) is not bool for value in presence)
    ):
        raise ContractViolation(
            "Sequence 16 lifecycle presence is invalid"
        )
    states = {
        (
            True,
            True,
            False,
            False,
            False,
            False,
        ): "C0_PACKET",
        (
            True,
            True,
            True,
            False,
            False,
            False,
        ): "C1_INTAKE",
        (
            True,
            True,
            True,
            True,
            False,
            False,
        ): "C2_REVIEW",
    }
    state = states.get(tuple(presence))
    if state is None:
        raise ContractViolation(
            "Sequence 16 lifecycle is not an exact state"
        )
    return state


def _classify_lifecycle_test_correction_forward(
    workspace_fd: int,
) -> dict[str, Any]:
    records: list[dict[str, Any] | None] = []
    payloads: list[bytes | None] = []
    values: list[dict[str, Any] | None] = []
    presence: list[bool] = []
    for relative in LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS:
        if _relative_leaf_lstat(workspace_fd, relative) is None:
            records.append(None)
            payloads.append(None)
            values.append(None)
            presence.append(False)
            continue
        record, payload = _relative_regular_record_and_bytes(
            workspace_fd,
            relative,
        )
        value = _strict_json_bytes(payload, allow_float=True)
        if (
            record["mode"] != "0600"
            or record["uid"] != os.getuid()
            or record["gid"] != os.getgid()
            or record["nlink"] != 1
            or not isinstance(value, dict)
            or payload != _canonical_json_bytes(value)
        ):
            raise ContractViolation(
                "Sequence 16 forward leaf is unsafe: "
                + relative
            )
        records.append(record)
        payloads.append(payload)
        values.append(value)
        presence.append(True)
    return {
        "state": (
            _classify_lifecycle_test_correction_presence(
                presence
            )
        ),
        "present": presence,
        "records": records,
        "payloads": payloads,
        "values": values,
    }


def _lifecycle_test_correction_review_paths(
) -> tuple[str, str, str]:
    return tuple(LIFECYCLE_TEST_CORRECTION_REVIEW_PATHS)


def _lifecycle_test_correction_tier_values(
    *,
    lease_record: Mapping[str, Any],
    parent_e0: Mapping[str, Any],
    authorization: Mapping[str, Any],
    package_records: Sequence[Mapping[str, Any]],
    prechange_record: Mapping[str, Any] | None = None,
    owner_record: Mapping[str, Any] | None = None,
    archive_record: Mapping[str, Any] | None = None,
    bundle_record: Mapping[str, Any] | None = None,
) -> dict[str, dict[str, Any]]:
    package = [
        _artifact_ref(record)
        for record in sorted(
            package_records,
            key=lambda item: item["path"],
        )
    ]
    if (
        len(package)
        != len(LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS)
        or [row["path"] for row in package]
        != sorted(LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS)
    ):
        raise ContractViolation(
            "Sequence 16 source package differs"
        )
    parent_projection = {
        key: copy.deepcopy(parent_e0[key])
        for key in (
            "classification",
            "authorization",
            "authorities",
            "preflight",
            "archive",
            "report",
            "packet",
        )
    }
    prechange = {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-lifecycle-"
            "test-correction-prechange/v1"
        ),
        "status": "captured",
        "captureId": LIFECYCLE_TEST_CORRECTION_CAPTURE_ID,
        "packetContinuationId": (
            LIFECYCLE_TEST_CORRECTION_PARENT_CONTINUATION_ID
        ),
        "parentExternalReviewCorrectionId": (
            LIFECYCLE_TEST_CORRECTION_PARENT_REVIEW_ID
        ),
        "lifecycleTestCorrectionId": (
            LIFECYCLE_TEST_CORRECTION_ID
        ),
        "lifecycleTestTierId": (
            LIFECYCLE_TEST_CORRECTION_TIER_ID
        ),
        "authorizationRecord": copy.deepcopy(
            dict(authorization)
        ),
        "plan": copy.deepcopy(
            LIFECYCLE_TEST_CORRECTION_PLAN_REF
        ),
        "traceability": copy.deepcopy(
            LIFECYCLE_TEST_CORRECTION_LEDGER_REF
        ),
        "parentE0": parent_projection,
        "package": package,
        "bundlePath": (
            LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[4]
        ),
        "lease": copy.deepcopy(dict(lease_record)),
    }
    owner = {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-lifecycle-"
            "test-correction-owner/v1"
        ),
        "lifecycleTestCorrectionId": (
            LIFECYCLE_TEST_CORRECTION_ID
        ),
        "lifecycleTestTierId": (
            LIFECYCLE_TEST_CORRECTION_TIER_ID
        ),
    }
    values = {"prechange": prechange, "owner": owner}
    if owner_record is not None and archive_record is not None:
        values["bundle"] = {
            "schemaVersion": (
                "quant-radar-ui-ux-external-review-lifecycle-"
                "test-correction-bundle/v1"
            ),
            "status": "sealed",
            "lifecycleTestCorrectionId": (
                LIFECYCLE_TEST_CORRECTION_ID
            ),
            "lifecycleTestTierId": (
                LIFECYCLE_TEST_CORRECTION_TIER_ID
            ),
            "ownerMarker": _artifact_ref(owner_record),
            "archive": _artifact_ref(archive_record),
            "archivedPaths": list(
                LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS
            ),
            "namespaceLeafCount": 3,
        }
    if prechange_record is not None and bundle_record is not None:
        values["rollback"] = {
            "schemaVersion": (
                "quant-radar-ui-ux-external-review-lifecycle-"
                "test-correction-rollback/v1"
            ),
            "status": "ready",
            "lifecycleTestCorrectionId": (
                LIFECYCLE_TEST_CORRECTION_ID
            ),
            "lifecycleTestTierId": (
                LIFECYCLE_TEST_CORRECTION_TIER_ID
            ),
            "prechange": _artifact_ref(prechange_record),
            "bundleManifest": _artifact_ref(bundle_record),
            "entries": [
                {
                    "path": record["path"],
                    "artifact": _artifact_ref(record),
                    "disposition": "restore_whole_if_exact",
                }
                for record in sorted(
                    package_records,
                    key=lambda item: item["path"],
                )
            ],
            "destructiveGitAllowed": False,
        }
    return values


@contextlib.contextmanager
def _lifecycle_test_correction_lease(
    workspace_fd: int,
    *,
    allow_create: bool,
) -> Any:
    relative = LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[1]
    created = False
    if allow_create:
        try:
            lease_fd = _create_relative_file(
                workspace_fd,
                relative,
                b"",
                0o600,
            )
            created = True
            os.fsync(lease_fd)
            _fsync_relative_parent(workspace_fd, relative)
        except NamespaceCollision:
            lease_fd = os.open(
                relative,
                os.O_RDWR
                | os.O_NOFOLLOW
                | getattr(os, "O_CLOEXEC", 0),
                dir_fd=workspace_fd,
            )
    else:
        lease_fd = os.open(
            relative,
            os.O_RDWR
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0),
            dir_fd=workspace_fd,
        )
    try:
        observed = os.fstat(lease_fd)
        if (
            not stat.S_ISREG(observed.st_mode)
            or stat.S_IMODE(observed.st_mode) != 0o600
            or observed.st_uid != os.getuid()
            or observed.st_gid != os.getgid()
            or observed.st_nlink != 1
            or observed.st_size != 0
        ):
            raise ContractViolation(
                "Sequence 16 lease is unsafe"
            )
        try:
            fcntl.flock(
                lease_fd,
                fcntl.LOCK_EX | fcntl.LOCK_NB,
            )
        except BlockingIOError as exc:
            raise BlockingIOError(
                "Sequence 16 lease is busy"
            ) from exc
        yield _file_record_from_fd(relative, lease_fd), created
    finally:
        try:
            fcntl.flock(lease_fd, fcntl.LOCK_UN)
        finally:
            os.close(lease_fd)


def _validate_lifecycle_test_correction_tier_complete(
    workspace_fd: int,
    source_root_fd: int,
) -> dict[str, Any]:
    parent_e0 = _import_sequence15_e0_preflight(
        workspace_fd,
        source_root_fd=source_root_fd,
        require_initial=False,
    )
    authorization = (
        _lifecycle_test_correction_authorization_binding(
            source_root_fd
        )
    )
    archive_bytes, package_records = (
        _lifecycle_test_correction_archive_bytes(
            source_root_fd
        )
    )
    paths = LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS
    lease_record, lease_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[1],
        )
    )
    prechange_record, prechange_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[2],
        )
    )
    rollback_record, rollback_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[3],
        )
    )
    directory = _open_relative_directory_fd(
        workspace_fd,
        paths[4],
    )
    try:
        observed = os.fstat(directory)
        if (
            stat.S_IMODE(observed.st_mode) != 0o700
            or observed.st_uid != os.getuid()
            or observed.st_gid != os.getgid()
            or set(os.listdir(directory))
            != {
                PurePosixPath(paths[5]).name,
                PurePosixPath(paths[6]).name,
                PurePosixPath(paths[7]).name,
            }
        ):
            raise ContractViolation(
                "Sequence 16 Tier directory differs"
            )
    finally:
        os.close(directory)
    owner_record, owner_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[5],
        )
    )
    archive_record, observed_archive = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[6],
        )
    )
    bundle_record, bundle_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[7],
        )
    )
    values = _lifecycle_test_correction_tier_values(
        lease_record=lease_record,
        parent_e0=parent_e0,
        authorization=authorization,
        package_records=package_records,
        prechange_record=prechange_record,
        owner_record=owner_record,
        archive_record=archive_record,
        bundle_record=bundle_record,
    )
    if (
        lease_bytes != b""
        or observed_archive != archive_bytes
        or prechange_bytes
        != _canonical_json_bytes(values["prechange"])
        or owner_bytes != _canonical_json_bytes(values["owner"])
        or bundle_bytes != _canonical_json_bytes(values["bundle"])
        or rollback_bytes
        != _canonical_json_bytes(values["rollback"])
    ):
        raise ContractViolation(
            "Sequence 16 Tier bytes differ"
        )
    return {
        "lease": _artifact_ref(lease_record),
        "prechange": _artifact_ref(prechange_record),
        "rollback": _artifact_ref(rollback_record),
        "owner": _artifact_ref(owner_record),
        "archive": _artifact_ref(archive_record),
        "bundle": _artifact_ref(bundle_record),
    }


def _bootstrap_lifecycle_test_correction(
    workspace_fd: int,
    *,
    source_root_fd: int,
) -> dict[str, Any]:
    created_any = False
    paths = LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS
    with _lifecycle_correction_global_lock(workspace_fd):
        _parse_lifecycle_test_correction_authorization_record(
            source_root_fd
        )
        parent_e0 = _import_sequence15_e0_preflight(
            workspace_fd,
            source_root_fd=source_root_fd,
            require_initial=True,
        )
        archive_bytes, package_records = (
            _lifecycle_test_correction_archive_bytes(
                source_root_fd
            )
        )
        with _lifecycle_test_correction_lease(
            workspace_fd,
            allow_create=True,
        ) as (lease_record, created):
            created_any = created_any or created
            authorization = (
                _lifecycle_test_correction_authorization_binding(
                    source_root_fd
                )
            )
            initial = _lifecycle_test_correction_tier_values(
                lease_record=lease_record,
                parent_e0=parent_e0,
                authorization=authorization,
                package_records=package_records,
            )
            prechange_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[2],
                    _canonical_json_bytes(initial["prechange"]),
                )
            )
            created_any = created_any or created
            directory = _ensure_relative_directory_fd(
                workspace_fd,
                paths[4],
            )
            os.close(directory)
            owner_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[5],
                    _canonical_json_bytes(initial["owner"]),
                )
            )
            created_any = created_any or created
            archive_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[6],
                    archive_bytes,
                )
            )
            created_any = created_any or created
            completed = _lifecycle_test_correction_tier_values(
                lease_record=lease_record,
                parent_e0=parent_e0,
                authorization=authorization,
                package_records=package_records,
                prechange_record=prechange_record,
                owner_record=owner_record,
                archive_record=archive_record,
            )
            bundle_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[7],
                    _canonical_json_bytes(completed["bundle"]),
                )
            )
            created_any = created_any or created
            completed = _lifecycle_test_correction_tier_values(
                lease_record=lease_record,
                parent_e0=parent_e0,
                authorization=authorization,
                package_records=package_records,
                prechange_record=prechange_record,
                owner_record=owner_record,
                archive_record=archive_record,
                bundle_record=bundle_record,
            )
            rollback_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[3],
                    _canonical_json_bytes(completed["rollback"]),
                )
            )
            created_any = created_any or created
            _validate_lifecycle_test_correction_tier_complete(
                workspace_fd,
                source_root_fd,
            )
    return {
        "exitCode": EXIT_SUCCESS,
        "created": created_any,
        "prechange": _artifact_ref(prechange_record),
        "rollback": _artifact_ref(rollback_record),
    }


def _lifecycle_test_correction_namespace_inventory(
) -> dict[str, Any]:
    return {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-lifecycle-"
            "test-correction-namespace/v1"
        ),
        "initialState": "C0_PACKET",
        "forwardPaths": list(
            LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS
        ),
        "states": {
            "C0_PACKET": [1, 1, 0, 0, 0, 0],
            "C1_INTAKE": [1, 1, 1, 0, 0, 0],
            "C2_REVIEW": [1, 1, 1, 1, 0, 0],
        },
        "candidateForbidden": True,
        "rootForbidden": True,
    }


def _build_lifecycle_test_correction_preflight_value(
    workspace_fd: int,
    source_root_fd: int,
    *,
    created_at: str,
    require_initial: bool,
) -> dict[str, Any]:
    created_epoch = _external_review_parse_time(
        created_at,
        "createdAt",
    )
    parent_e0 = _import_sequence15_e0_preflight(
        workspace_fd,
        source_root_fd=source_root_fd,
        require_initial=require_initial,
    )
    current = _classify_lifecycle_test_correction_forward(
        workspace_fd
    )
    if require_initial and current["state"] != "C0_PACKET":
        raise ContractViolation(
            "Sequence 16 preflight requires C0_PACKET"
        )
    projections = _import_later_source_projections_history(
        source_root_fd,
        "sequence16",
    )
    sandbox = {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-sandbox-policy/v1"
        ),
        "sandboxExecutable": "/usr/bin/sandbox-exec",
        "sandboxRequired": True,
        "workspaceReadOnly": True,
        "isolatedOutputRequired": True,
        "workspaceWriteSetRequired": [],
        "frozenRuntimeWritable": False,
        "networkAllowed": False,
        "browserAllowed": False,
        "packageInstallAllowed": False,
    }
    if not Path(sandbox["sandboxExecutable"]).is_file():
        raise ContractViolation(
            "Sequence 16 reviewer sandbox is unavailable"
        )
    parent_projection = {
        key: copy.deepcopy(parent_e0[key])
        for key in (
            "classification",
            "authorization",
            "authorities",
            "preflight",
            "archive",
            "report",
            "packet",
        )
    }
    return {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-lifecycle-"
            "test-correction-preflight/v1"
        ),
        "status": "passed",
        "captureId": LIFECYCLE_TEST_CORRECTION_CAPTURE_ID,
        "packetContinuationId": (
            LIFECYCLE_TEST_CORRECTION_PARENT_CONTINUATION_ID
        ),
        "parentExternalReviewCorrectionId": (
            LIFECYCLE_TEST_CORRECTION_PARENT_REVIEW_ID
        ),
        "lifecycleTestCorrectionId": (
            LIFECYCLE_TEST_CORRECTION_ID
        ),
        "lifecycleTestTierId": (
            LIFECYCLE_TEST_CORRECTION_TIER_ID
        ),
        "authorizationRecord": (
            _lifecycle_test_correction_authorization_binding(
                source_root_fd
            )
        ),
        "plan": copy.deepcopy(
            LIFECYCLE_TEST_CORRECTION_PLAN_REF
        ),
        "traceability": copy.deepcopy(
            LIFECYCLE_TEST_CORRECTION_LEDGER_REF
        ),
        "parentE0": parent_projection,
        "initialState": "C0_PACKET",
        "sourceProjection": projections["sourceProjection"],
        "supplementalProjection": projections[
            "supplementalProjection"
        ],
        "runtimeReceipt": _import_sequence12_runtime_history(
            workspace_fd
        ),
        "makeContract": (
            _lifecycle_test_correction_make_contract(
                source_root_fd
            )
        ),
        "namespaceInventory": (
            _lifecycle_test_correction_namespace_inventory()
        ),
        "reviewerAppointment": (
            _lifecycle_test_correction_reviewer_appointment()
        ),
        "reviewerSubmissionCapability": (
            _lifecycle_test_correction_submission_capability()
        ),
        "reviewerSandbox": sandbox,
        "descriptorProfile": (
            _build_lifecycle_test_correction_descriptor_profile()
        ),
        "tier": (
            _validate_lifecycle_test_correction_tier_complete(
                workspace_fd,
                source_root_fd,
            )
        ),
        "createdAt": created_at,
        "reviewDeadline": _external_review_format_time(
            created_epoch
            + LIFECYCLE_TEST_CORRECTION_REVIEW_WINDOW_SECONDS
        ),
        "formalPause": "C2_REVIEW",
        "candidateForbidden": True,
        "rootForbidden": True,
    }


def _validate_lifecycle_test_correction_preflight_value(
    workspace_fd: int,
    source_root_fd: int,
    value: Any,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ContractViolation(
            "Sequence 16 preflight is not an object"
        )
    created_at = value.get("createdAt")
    expected = _build_lifecycle_test_correction_preflight_value(
        workspace_fd,
        source_root_fd,
        created_at=created_at,
        require_initial=False,
    )
    created_epoch = _external_review_parse_time(
        created_at,
        "createdAt",
    )
    deadline_epoch = _external_review_parse_time(
        value.get("reviewDeadline"),
        "reviewDeadline",
    )
    if (
        deadline_epoch
        != (
            created_epoch
            + LIFECYCLE_TEST_CORRECTION_REVIEW_WINDOW_SECONDS
        )
        or value != expected
        or set(value) != set(expected)
    ):
        raise ContractViolation(
            "Sequence 16 preflight differs"
        )
    return copy.deepcopy(expected)


def _reauthenticate_lifecycle_test_correction_preflight(
    workspace_fd: int,
    source_root_fd: int,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    record, payload = _relative_regular_record_and_bytes(
        workspace_fd,
        LIFECYCLE_TEST_CORRECTION_PREFLIGHT_PATH,
    )
    value = _strict_json_bytes(payload, allow_float=True)
    if (
        record["mode"] != "0600"
        or record["uid"] != os.getuid()
        or record["gid"] != os.getgid()
        or record["nlink"] != 1
        or not isinstance(value, dict)
        or payload != _canonical_json_bytes(value)
    ):
        raise ContractViolation(
            "Sequence 16 preflight is unsafe"
        )
    authenticated = (
        _validate_lifecycle_test_correction_preflight_value(
            workspace_fd,
            source_root_fd,
            value,
        )
    )
    current = _classify_lifecycle_test_correction_forward(
        workspace_fd
    )
    return record, authenticated, current


def _lifecycle_test_correction_preflight_lifecycle(
    workspace_fd: int,
    *,
    source_root_fd: int,
    verify_only: bool,
    now: str | None = None,
) -> dict[str, Any]:
    with _lifecycle_correction_global_lock(workspace_fd):
        with _lifecycle_test_correction_lease(
            workspace_fd,
            allow_create=False,
        ):
            if verify_only:
                record, _, current = (
                    _reauthenticate_lifecycle_test_correction_preflight(
                        workspace_fd,
                        source_root_fd,
                    )
                )
                return {
                    "exitCode": EXIT_SUCCESS,
                    "created": False,
                    "state": current["state"],
                    "preflight": _artifact_ref(record),
                }
            if (
                _relative_leaf_lstat(
                    workspace_fd,
                    LIFECYCLE_TEST_CORRECTION_PREFLIGHT_PATH,
                )
                is not None
            ):
                record, _, current = (
                    _reauthenticate_lifecycle_test_correction_preflight(
                        workspace_fd,
                        source_root_fd,
                    )
                )
                return {
                    "exitCode": EXIT_SUCCESS,
                    "created": False,
                    "state": current["state"],
                    "preflight": _artifact_ref(record),
                }
            created_at = (
                _external_review_format_time(int(time.time()))
                if now is None
                else now
            )
            value = (
                _build_lifecycle_test_correction_preflight_value(
                    workspace_fd,
                    source_root_fd,
                    created_at=created_at,
                    require_initial=True,
                )
            )
            record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    LIFECYCLE_TEST_CORRECTION_PREFLIGHT_PATH,
                    _canonical_json_bytes(value),
                )
            )
            reopened, _, current = (
                _reauthenticate_lifecycle_test_correction_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            if (
                _artifact_ref(reopened) != _artifact_ref(record)
                or current["state"] != "C0_PACKET"
            ):
                raise ContractViolation(
                    "Sequence 16 preflight postcondition differs"
                )
            return {
                "exitCode": EXIT_SUCCESS,
                "created": created,
                "state": current["state"],
                "preflight": _artifact_ref(record),
            }


def _lifecycle_test_correction_material_refs(
    packet: Mapping[str, Any],
    source_projection: Mapping[str, Any],
    supplemental_projection: Mapping[str, Any],
) -> dict[str, dict[str, Any]]:
    return _external_review_material_refs_for_profile(
        packet,
        source_projection,
        supplemental_projection,
        expected_supplemental_count=64,
        expected_retained_count=(
            LIFECYCLE_TEST_CORRECTION_RETAINED_LEAVES
        ),
        contract_label="Sequence 16",
    )


def _lifecycle_test_correction_runtime_boundary(
    workspace_fd: int,
    preflight: Mapping[str, Any],
) -> None:
    if (
        not isinstance(preflight, Mapping)
        or _import_sequence12_runtime_history(workspace_fd)
        != preflight.get("runtimeReceipt")
    ):
        raise ContractViolation(
            "Sequence 16 runtime receipt drifted"
        )


def _validate_lifecycle_test_correction_forward_semantics(
    workspace_fd: int,
    source_root_fd: int,
    *,
    preflight: Mapping[str, Any],
    broker_now: str | None = None,
    initial_submission: bool = False,
) -> dict[str, Any]:
    parent_e0 = _import_sequence15_e0_preflight(
        workspace_fd,
        source_root_fd=source_root_fd,
        require_initial=False,
    )
    current = _classify_lifecycle_test_correction_forward(
        workspace_fd
    )
    records = current["records"]
    payloads = current["payloads"]
    values = current["values"]
    for index, expected in enumerate(
        LIFECYCLE_TEST_CORRECTION_PARENT_REFS[-2:]
    ):
        observed = records[index]
        if (
            observed is None
            or {
                key: observed[key]
                for key in ("path", "sha256", "size", "mode")
            }
            != expected
        ):
            raise ContractViolation(
                "Sequence 16 parent forward leaf differs"
            )
    if (
        values[0] != parent_e0["reportValue"]
        or values[1] != parent_e0["packetValue"]
    ):
        raise ContractViolation(
            "Sequence 16 parent forward values differ"
        )
    if current["state"] == "C0_PACKET":
        return current
    intake_record = records[2]
    intake_payload = payloads[2]
    intake_value = values[2]
    assert (
        intake_record is not None
        and intake_payload is not None
        and isinstance(intake_value, dict)
    )
    validation = (
        _validate_external_review_manual_review_for_authority(
            intake_value,
            parent_e0["packetValue"],
            packet_path=(
                LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[1]
            ),
            packet_bytes=payloads[1],
            preflight=preflight,
            expected_appointment=(
                _lifecycle_test_correction_reviewer_appointment()
            ),
            accepted_sha256=intake_record["sha256"],
            accepted_size=intake_record["size"],
            broker_now=broker_now,
            initial_submission=initial_submission,
            review_window_seconds=(
                LIFECYCLE_TEST_CORRECTION_REVIEW_WINDOW_SECONDS
            ),
            clock_skew_seconds=(
                LIFECYCLE_TEST_CORRECTION_CLOCK_SKEW_SECONDS
            ),
            max_intake_bytes=(
                LIFECYCLE_TEST_CORRECTION_MAX_INTAKE_BYTES
            ),
            contract_label="Sequence 16",
        )
    )
    current["decision"] = validation["decision"]
    current["intakeValidation"] = validation
    if current["state"] == "C1_INTAKE":
        return current
    review_record = records[3]
    review_payload = payloads[3]
    review_value = values[3]
    assert (
        review_record is not None
        and review_payload is not None
        and isinstance(review_value, dict)
    )
    _validate_external_review_manual_review_for_authority(
        review_value,
        parent_e0["packetValue"],
        packet_path=(
            LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[1]
        ),
        packet_bytes=payloads[1],
        preflight=preflight,
        expected_appointment=(
            _lifecycle_test_correction_reviewer_appointment()
        ),
        accepted_sha256=review_record["sha256"],
        accepted_size=review_record["size"],
        broker_now=None,
        initial_submission=False,
        review_window_seconds=(
            LIFECYCLE_TEST_CORRECTION_REVIEW_WINDOW_SECONDS
        ),
        clock_skew_seconds=(
            LIFECYCLE_TEST_CORRECTION_CLOCK_SKEW_SECONDS
        ),
        max_intake_bytes=(
            LIFECYCLE_TEST_CORRECTION_MAX_INTAKE_BYTES
        ),
        contract_label="Sequence 16",
    )
    if (
        review_payload != intake_payload
        or review_value != intake_value
        or review_record["inode"] == intake_record["inode"]
    ):
        raise ContractViolation(
            "Sequence 16 review is not an exact different-inode copy"
        )
    return current


def _lifecycle_test_correction_materials_from_preflight(
    packet: Mapping[str, Any],
    preflight: Mapping[str, Any],
) -> dict[str, dict[str, Any]]:
    return _lifecycle_test_correction_material_refs(
        packet,
        preflight.get("sourceProjection", {}),
        preflight.get("supplementalProjection", {}),
    )


def _submit_lifecycle_test_corrected_review_intake(
    workspace_fd: int,
    *,
    source_root_fd: int,
    payload: bytes,
    accepted_sha256: str,
    accepted_size: int,
    broker_now: str | None = None,
    fault_after: str | None = None,
    syscalls: Any | None = None,
) -> dict[str, Any]:
    if (
        not isinstance(payload, bytes)
        or not payload
        or len(payload)
        > LIFECYCLE_TEST_CORRECTION_MAX_INTAKE_BYTES
        or not isinstance(accepted_sha256, str)
        or re.fullmatch(r"[0-9a-f]{64}", accepted_sha256)
        is None
        or type(accepted_size) is not int
        or len(payload) != accepted_size
        or hashlib.sha256(payload).hexdigest()
        != accepted_sha256
    ):
        raise ContractViolation(
            "Sequence 16 submitted candidate digest differs"
        )
    value = _strict_json_bytes(payload)
    if (
        not isinstance(value, dict)
        or payload != _canonical_json_bytes(value)
    ):
        raise ContractViolation(
            "Sequence 16 submitted candidate is noncanonical"
        )
    now_text = (
        _external_review_format_time(int(time.time()))
        if broker_now is None
        else broker_now
    )
    with _lifecycle_correction_global_lock(workspace_fd):
        with _lifecycle_test_correction_lease(
            workspace_fd,
            allow_create=False,
        ):
            _, preflight, _ = (
                _reauthenticate_lifecycle_test_correction_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            current = (
                _validate_lifecycle_test_correction_forward_semantics(
                    workspace_fd,
                    source_root_fd,
                    preflight=preflight,
                )
            )
            state = current["state"]
            if state in {"C1_INTAKE", "C2_REVIEW"}:
                if current["payloads"][2] != payload:
                    raise ContractViolation(
                        "Sequence 16 consumed session bytes differ"
                    )
                validation = (
                    _validate_external_review_manual_review_for_authority(
                        value,
                        current["values"][1],
                        packet_path=(
                            LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[
                                1
                            ]
                        ),
                        packet_bytes=current["payloads"][1],
                        preflight=preflight,
                        expected_appointment=(
                            _lifecycle_test_correction_reviewer_appointment()
                        ),
                        accepted_sha256=accepted_sha256,
                        accepted_size=accepted_size,
                        broker_now=None,
                        initial_submission=False,
                        review_window_seconds=(
                            LIFECYCLE_TEST_CORRECTION_REVIEW_WINDOW_SECONDS
                        ),
                        clock_skew_seconds=(
                            LIFECYCLE_TEST_CORRECTION_CLOCK_SKEW_SECONDS
                        ),
                        max_intake_bytes=(
                            LIFECYCLE_TEST_CORRECTION_MAX_INTAKE_BYTES
                        ),
                        contract_label="Sequence 16",
                    )
                )
                materials = (
                    _lifecycle_test_correction_materials_from_preflight(
                        current["values"][1],
                        preflight,
                    )
                )
                _lifecycle_test_correction_runtime_boundary(
                    workspace_fd,
                    preflight
                )
                with _historical_external_review_material_transaction(
                    workspace_fd,
                    source_root_fd,
                    materials,
                    preflight["descriptorProfile"],
                    preflight,
                    "sequence16",
                ):
                    _lifecycle_test_correction_runtime_boundary(
                        workspace_fd,
                        preflight
                    )
                _, reopened_preflight, _ = (
                    _reauthenticate_lifecycle_test_correction_preflight(
                        workspace_fd,
                        source_root_fd,
                    )
                )
                reopened = (
                    _validate_lifecycle_test_correction_forward_semantics(
                        workspace_fd,
                        source_root_fd,
                        preflight=reopened_preflight,
                    )
                )
                if (
                    reopened["state"] != state
                    or reopened["payloads"][2] != payload
                ):
                    raise ContractViolation(
                        "Sequence 16 reconcile state drifted"
                    )
                return {
                    "exitCode": EXIT_SUCCESS,
                    "created": False,
                    "state": state,
                    "decision": validation["decision"],
                    "intake": _artifact_ref(
                        reopened["records"][2]
                    ),
                }
            if state != "C0_PACKET":
                raise ContractViolation(
                    "Sequence 16 submit requires C0_PACKET"
                )
            validation = (
                _validate_external_review_manual_review_for_authority(
                    value,
                    current["values"][1],
                    packet_path=(
                        LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[1]
                    ),
                    packet_bytes=current["payloads"][1],
                    preflight=preflight,
                    expected_appointment=(
                        _lifecycle_test_correction_reviewer_appointment()
                    ),
                    accepted_sha256=accepted_sha256,
                    accepted_size=accepted_size,
                    broker_now=now_text,
                    initial_submission=True,
                    review_window_seconds=(
                        LIFECYCLE_TEST_CORRECTION_REVIEW_WINDOW_SECONDS
                    ),
                    clock_skew_seconds=(
                        LIFECYCLE_TEST_CORRECTION_CLOCK_SKEW_SECONDS
                    ),
                    max_intake_bytes=(
                        LIFECYCLE_TEST_CORRECTION_MAX_INTAKE_BYTES
                    ),
                    contract_label="Sequence 16",
                )
            )
            materials = (
                _lifecycle_test_correction_materials_from_preflight(
                    current["values"][1],
                    preflight,
                )
            )
            _lifecycle_test_correction_runtime_boundary(
                workspace_fd,
                preflight,
            )
            with _historical_external_review_material_transaction(
                workspace_fd,
                source_root_fd,
                materials,
                preflight["descriptorProfile"],
                preflight,
                "sequence16",
            ) as retained:

                def boundary() -> None:
                    retained["reauthenticate"]()
                    _lifecycle_test_correction_runtime_boundary(
                        workspace_fd,
                        preflight
                    )

                published = _publish_external_review_payload(
                    workspace_fd,
                    LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[2],
                    payload,
                    fault_after=fault_after,
                    syscalls=syscalls,
                    precommit=boundary,
                    postcommit=boundary,
                )
                if published["exitCode"] != EXIT_SUCCESS:
                    return {
                        "exitCode": published["exitCode"],
                        "created": published["created"],
                    }
                boundary()
            _, reopened_preflight, _ = (
                _reauthenticate_lifecycle_test_correction_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            reopened = (
                _validate_lifecycle_test_correction_forward_semantics(
                    workspace_fd,
                    source_root_fd,
                    preflight=reopened_preflight,
                )
            )
            if (
                reopened["state"] != "C1_INTAKE"
                or reopened["payloads"][2] != payload
            ):
                raise ContractViolation(
                    "Sequence 16 intake postcondition differs"
                )
            return {
                "exitCode": EXIT_SUCCESS,
                "created": published["created"],
                "state": reopened["state"],
                "decision": validation["decision"],
                "intake": _artifact_ref(reopened["records"][2]),
            }


def _publish_lifecycle_test_corrected_review(
    workspace_fd: int,
    *,
    source_root_fd: int,
    fault_after: str | None = None,
    syscalls: Any | None = None,
) -> dict[str, Any]:
    with _lifecycle_correction_global_lock(workspace_fd):
        with _lifecycle_test_correction_lease(
            workspace_fd,
            allow_create=False,
        ):
            _, preflight, _ = (
                _reauthenticate_lifecycle_test_correction_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            current = (
                _validate_lifecycle_test_correction_forward_semantics(
                    workspace_fd,
                    source_root_fd,
                    preflight=preflight,
                )
            )
            if current["state"] == "C0_PACKET":
                raise ContractViolation(
                    "Sequence 16 review requires C1_INTAKE"
                )
            packet = current["values"][1]
            assert isinstance(packet, dict)
            materials = (
                _lifecycle_test_correction_materials_from_preflight(
                    packet,
                    preflight,
                )
            )
            intake_payload = current["payloads"][2]
            intake_record = current["records"][2]
            assert (
                isinstance(intake_payload, bytes)
                and intake_record is not None
            )
            _lifecycle_test_correction_runtime_boundary(
                workspace_fd,
                preflight,
            )
            with _historical_external_review_material_transaction(
                workspace_fd,
                source_root_fd,
                materials,
                preflight["descriptorProfile"],
                preflight,
                "sequence16",
            ) as retained:

                def boundary() -> None:
                    retained["reauthenticate"]()
                    _lifecycle_test_correction_runtime_boundary(
                        workspace_fd,
                        preflight
                    )

                if current["state"] == "C2_REVIEW":
                    boundary()
                    reopened = (
                        _validate_lifecycle_test_correction_forward_semantics(
                            workspace_fd,
                            source_root_fd,
                            preflight=preflight,
                        )
                    )
                    if reopened["state"] != "C2_REVIEW":
                        raise ContractViolation(
                            "Sequence 16 review reconcile drifted"
                        )
                    return {
                        "exitCode": EXIT_SUCCESS,
                        "created": False,
                        "state": "C2_REVIEW",
                        "decision": reopened["decision"],
                        "review": _artifact_ref(
                            reopened["records"][3]
                        ),
                    }
                published = _publish_external_review_payload(
                    workspace_fd,
                    LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[3],
                    intake_payload,
                    fault_after=fault_after,
                    syscalls=syscalls,
                    precommit=boundary,
                    postcommit=boundary,
                )
                if published["exitCode"] != EXIT_SUCCESS:
                    return {
                        "exitCode": published["exitCode"],
                        "created": published["created"],
                    }
                if (
                    published["record"]["inode"]
                    == intake_record["inode"]
                ):
                    raise ContractViolation(
                        "Sequence 16 review aliases intake inode"
                    )
                boundary()
            _, reopened_preflight, _ = (
                _reauthenticate_lifecycle_test_correction_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            reopened = (
                _validate_lifecycle_test_correction_forward_semantics(
                    workspace_fd,
                    source_root_fd,
                    preflight=reopened_preflight,
                )
            )
            if reopened["state"] != "C2_REVIEW":
                raise ContractViolation(
                    "Sequence 16 review postcondition differs"
                )
            return {
                "exitCode": EXIT_SUCCESS,
                "created": published["created"],
                "state": reopened["state"],
                "decision": reopened["decision"],
                "review": _artifact_ref(reopened["records"][3]),
            }


