def _formal_state_oracle_correction_authorization_document_bytes(
) -> bytes:
    body = _canonical_json_bytes(
        _formal_state_oracle_correction_authorization_body()
    ).decode("utf-8")
    return (
        "# Quant Radar UX-1B Sequence 17 Formal-State Oracle "
        "Correction\n\n"
        "Status: authorization candidate only. This document does not "
        "authorize bootstrap, preflight, intake submission, manual-review "
        "publication, capture, comparison, candidate, root, or theme work "
        "until the repository maintainer separately accepts its exact "
        "whole-document SHA-256, byte size, and mode.\n\n"
        + FORMAL_STATE_ORACLE_CORRECTION_AUTH_START.decode("ascii")
        + body
        + FORMAL_STATE_ORACLE_CORRECTION_AUTH_END.decode("ascii")
        + "\n\nSequence 17 imports the exact retained Sequence 16 "
        "`C0_PACKET` as immutable history, freezes corrected current "
        "source under a distinct authority, owns only the still-absent "
        "shared intake and review leaves, and stops at `O2_REVIEW`. "
        "It grants no capture, comparison, candidate, or root authority.\n"
    ).encode("utf-8")


def _parse_formal_state_oracle_correction_authorization_record(
    source_root_fd: int,
) -> dict[str, Any]:
    record, document = _source_file_record(
        source_root_fd,
        FORMAL_STATE_ORACLE_CORRECTION_AUTHORIZATION_DOCUMENT_PATH,
    )
    if (
        record["mode"] != "0644"
        or record["uid"] != os.getuid()
        or record["gid"] != os.getgid()
        or record["nlink"] != 1
        or document
        != (
            _formal_state_oracle_correction_authorization_document_bytes()
        )
        or document.count(
            FORMAL_STATE_ORACLE_CORRECTION_AUTH_GENERIC
        )
        != 2
    ):
        raise ContractViolation(
            "Sequence 17 authorization document differs"
        )
    for expected in (
        FORMAL_STATE_ORACLE_CORRECTION_PLAN_REF,
        FORMAL_STATE_ORACLE_CORRECTION_LEDGER_REF,
    ):
        observed, _ = _source_file_record(
            source_root_fd,
            expected["path"],
        )
        if {
            key: observed[key]
            for key in ("path", "sha256", "size", "mode")
        } != expected:
            raise ContractViolation(
                "Sequence 17 authority drifted: "
                + expected["path"]
            )
    return _formal_state_oracle_correction_authorization_body()


def _formal_state_oracle_correction_authorization_binding(
    source_root_fd: int,
) -> dict[str, Any]:
    body = (
        _parse_formal_state_oracle_correction_authorization_record(
            source_root_fd
        )
    )
    record, _ = _source_file_record(
        source_root_fd,
        FORMAL_STATE_ORACLE_CORRECTION_AUTHORIZATION_DOCUMENT_PATH,
    )
    return {
        **_artifact_ref(record),
        "bodySha256": hashlib.sha256(
            _canonical_json_bytes(body)
        ).hexdigest(),
    }


def _build_formal_state_oracle_correction_source_projections(
    source_root_fd: int,
) -> dict[str, Any]:
    base = _build_lifecycle_test_correction_source_projections(
        source_root_fd
    )
    mirror = base["sourceProjection"]
    mirror_paths = {
        row["path"] for row in mirror["records"]
    }
    records = {
        row["path"]: copy.deepcopy(row)
        for row in base["supplementalProjection"]["records"]
    }
    for relative in FORMAL_STATE_ORACLE_CORRECTION_PACKAGE_PATHS:
        if relative in mirror_paths:
            continue
        record, _ = _source_file_record(
            source_root_fd,
            relative,
        )
        records[relative] = {
            "path": relative,
            "sha256": record["sha256"],
            "size": record["size"],
            "mode": (
                "0555"
                if int(record["mode"], 8) & 0o111
                else "0444"
            ),
        }
    paths = sorted(records)
    projection = _source_projection_value(
        "quant-radar-ui-ux-supplemental-source/v1",
        paths,
        mirror["policy"]["include"],
        [records[path] for path in paths],
    )
    if (
        len(mirror["records"]) != 270
        or len(projection["records"]) != 67
    ):
        raise ContractViolation(
            "Sequence 17 source projection counts differ"
        )
    return {
        "sourceProjection": mirror,
        "supplementalProjection": projection,
    }


def _formal_state_oracle_correction_archive_bytes(
    source_root_fd: int,
) -> tuple[bytes, list[dict[str, Any]]]:
    output = io.BytesIO()
    records: list[dict[str, Any]] = []
    with tarfile.open(
        fileobj=output,
        mode="w",
        format=tarfile.PAX_FORMAT,
    ) as archive:
        for relative in FORMAL_STATE_ORACLE_CORRECTION_PACKAGE_PATHS:
            record, payload = _source_file_record(
                source_root_fd,
                relative,
            )
            records.append(record)
            member = tarfile.TarInfo(relative)
            member.size = len(payload)
            member.mode = stat.S_IMODE(
                int(record["mode"], 8)
            )
            member.uid = 0
            member.gid = 0
            member.uname = ""
            member.gname = ""
            member.mtime = 0
            archive.addfile(member, io.BytesIO(payload))
    return output.getvalue(), records


def _formal_state_oracle_correction_make_contract(
    source_root_fd: int,
) -> dict[str, Any]:
    record, payload = _source_file_record(
        source_root_fd,
        "Makefile",
    )
    targets = (
        "ui-ux1b-external-review-formal-state-oracle-bootstrap",
        "ui-ux1b-external-review-formal-state-oracle-preflight",
        "ui-ux1b-external-review-formal-state-oracle-verify",
        (
            "ui-ux1b-external-review-formal-state-oracle-"
            "submit-intake"
        ),
        "ui-ux1b-external-review-formal-state-oracle-publish",
    )
    text = payload.decode("utf-8", errors="strict")
    if any(
        text.count(target + ":") != 1 for target in targets
    ):
        raise ContractViolation(
            "Sequence 17 Make contract differs"
        )
    return {
        "artifact": _artifact_ref(record),
        "targets": list(targets),
        "targetsSha256": hashlib.sha256(
            _canonical_json_bytes(list(targets))
        ).hexdigest(),
    }


def _build_formal_state_oracle_correction_descriptor_profile(
) -> dict[str, Any]:
    _, hard_limit = resource.getrlimit(resource.RLIMIT_NOFILE)
    return _validate_external_review_descriptor_profile(
        {
            "schemaVersion": (
                "quant-radar-ui-ux-external-review-"
                "descriptor-profile/v1"
            ),
            "hardLimit": hard_limit,
            "worstCaseUniqueRetainedLeaves": (
                FORMAL_STATE_ORACLE_CORRECTION_RETAINED_LEAVES
            ),
            "protocolAdditional": (
                FORMAL_STATE_ORACLE_CORRECTION_PROTOCOL_ALLOWANCE
            ),
            "reserve": (
                FORMAL_STATE_ORACLE_CORRECTION_DESCRIPTOR_RESERVE
            ),
            "requiredSoftFloor": (
                FORMAL_STATE_ORACLE_CORRECTION_REQUIRED_SOFT_FLOOR
            ),
            "raiseCeiling": (
                FORMAL_STATE_ORACLE_CORRECTION_DESCRIPTOR_CEILING
            ),
        }
    )


def _classify_formal_state_oracle_correction_presence(
    presence: Sequence[bool],
) -> str:
    if (
        not isinstance(presence, Sequence)
        or isinstance(presence, (str, bytes))
        or len(presence) != 6
        or any(type(value) is not bool for value in presence)
    ):
        raise ContractViolation(
            "Sequence 17 lifecycle presence is invalid"
        )
    states = {
        (
            True,
            True,
            False,
            False,
            False,
            False,
        ): "O0_PACKET",
        (
            True,
            True,
            True,
            False,
            False,
            False,
        ): "O1_INTAKE",
        (
            True,
            True,
            True,
            True,
            False,
            False,
        ): "O2_REVIEW",
    }
    state = states.get(tuple(presence))
    if state is None:
        raise ContractViolation(
            "Sequence 17 lifecycle is not an exact state"
        )
    return state


def _classify_formal_state_oracle_correction_forward(
    workspace_fd: int,
) -> dict[str, Any]:
    records: list[dict[str, Any] | None] = []
    payloads: list[bytes | None] = []
    values: list[dict[str, Any] | None] = []
    presence: list[bool] = []
    for relative in FORMAL_STATE_ORACLE_CORRECTION_FORWARD_PATHS:
        if _relative_leaf_lstat(workspace_fd, relative) is None:
            records.append(None)
            payloads.append(None)
            values.append(None)
            presence.append(False)
            continue
        record, payload = _relative_regular_record_and_bytes(
            workspace_fd,
            relative,
        )
        value = _strict_json_bytes(payload, allow_float=True)
        if (
            record["mode"] != "0600"
            or record["uid"] != os.getuid()
            or record["gid"] != os.getgid()
            or record["nlink"] != 1
            or not isinstance(value, dict)
            or payload != _canonical_json_bytes(value)
        ):
            raise ContractViolation(
                "Sequence 17 forward leaf is unsafe: "
                + relative
            )
        records.append(record)
        payloads.append(payload)
        values.append(value)
        presence.append(True)
    return {
        "state": (
            _classify_formal_state_oracle_correction_presence(
                presence
            )
        ),
        "present": presence,
        "records": records,
        "payloads": payloads,
        "values": values,
    }


def _formal_state_oracle_correction_review_paths(
) -> tuple[str, str, str]:
    return tuple(FORMAL_STATE_ORACLE_CORRECTION_REVIEW_PATHS)


def _formal_state_oracle_correction_tier_values(
    *,
    lease_record: Mapping[str, Any],
    parent_c0: Mapping[str, Any],
    authorization: Mapping[str, Any],
    package_records: Sequence[Mapping[str, Any]],
    prechange_record: Mapping[str, Any] | None = None,
    owner_record: Mapping[str, Any] | None = None,
    archive_record: Mapping[str, Any] | None = None,
    bundle_record: Mapping[str, Any] | None = None,
) -> dict[str, dict[str, Any]]:
    package = [
        _artifact_ref(record)
        for record in sorted(
            package_records,
            key=lambda item: item["path"],
        )
    ]
    if (
        len(package)
        != len(FORMAL_STATE_ORACLE_CORRECTION_PACKAGE_PATHS)
        or [row["path"] for row in package]
        != sorted(FORMAL_STATE_ORACLE_CORRECTION_PACKAGE_PATHS)
    ):
        raise ContractViolation(
            "Sequence 17 source package differs"
        )
    parent_projection = {
        key: copy.deepcopy(parent_c0[key])
        for key in (
            "classification",
            "authorization",
            "authorities",
            "preflight",
            "archive",
            "report",
            "packet",
        )
    }
    prechange = {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-formal-state-oracle-"
            "correction-prechange/v1"
        ),
        "status": "captured",
        "captureId": FORMAL_STATE_ORACLE_CORRECTION_CAPTURE_ID,
        "packetContinuationId": (
            FORMAL_STATE_ORACLE_CORRECTION_PARENT_CONTINUATION_ID
        ),
        "parentLifecycleCorrectionId": (
            FORMAL_STATE_ORACLE_CORRECTION_PARENT_REVIEW_ID
        ),
        "formalStateOracleCorrectionId": (
            FORMAL_STATE_ORACLE_CORRECTION_ID
        ),
        "formalStateOracleTierId": (
            FORMAL_STATE_ORACLE_CORRECTION_TIER_ID
        ),
        "authorizationRecord": copy.deepcopy(
            dict(authorization)
        ),
        "plan": copy.deepcopy(
            FORMAL_STATE_ORACLE_CORRECTION_PLAN_REF
        ),
        "traceability": copy.deepcopy(
            FORMAL_STATE_ORACLE_CORRECTION_LEDGER_REF
        ),
        "parentC0": parent_projection,
        "package": package,
        "bundlePath": (
            FORMAL_STATE_ORACLE_CORRECTION_TIER_DESTINATIONS[4]
        ),
        "lease": copy.deepcopy(dict(lease_record)),
    }
    owner = {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-formal-state-oracle-"
            "correction-owner/v1"
        ),
        "formalStateOracleCorrectionId": (
            FORMAL_STATE_ORACLE_CORRECTION_ID
        ),
        "formalStateOracleTierId": (
            FORMAL_STATE_ORACLE_CORRECTION_TIER_ID
        ),
    }
    values = {"prechange": prechange, "owner": owner}
    if owner_record is not None and archive_record is not None:
        values["bundle"] = {
            "schemaVersion": (
                "quant-radar-ui-ux-external-review-formal-state-oracle-"
                "correction-bundle/v1"
            ),
            "status": "sealed",
            "formalStateOracleCorrectionId": (
                FORMAL_STATE_ORACLE_CORRECTION_ID
            ),
            "formalStateOracleTierId": (
                FORMAL_STATE_ORACLE_CORRECTION_TIER_ID
            ),
            "ownerMarker": _artifact_ref(owner_record),
            "archive": _artifact_ref(archive_record),
            "archivedPaths": list(
                FORMAL_STATE_ORACLE_CORRECTION_PACKAGE_PATHS
            ),
            "namespaceLeafCount": 3,
        }
    if prechange_record is not None and bundle_record is not None:
        values["rollback"] = {
            "schemaVersion": (
                "quant-radar-ui-ux-external-review-formal-state-oracle-"
                "correction-rollback/v1"
            ),
            "status": "ready",
            "formalStateOracleCorrectionId": (
                FORMAL_STATE_ORACLE_CORRECTION_ID
            ),
            "formalStateOracleTierId": (
                FORMAL_STATE_ORACLE_CORRECTION_TIER_ID
            ),
            "prechange": _artifact_ref(prechange_record),
            "bundleManifest": _artifact_ref(bundle_record),
            "entries": [
                {
                    "path": record["path"],
                    "artifact": _artifact_ref(record),
                    "disposition": "restore_whole_if_exact",
                }
                for record in sorted(
                    package_records,
                    key=lambda item: item["path"],
                )
            ],
            "destructiveGitAllowed": False,
        }
    return values


@contextlib.contextmanager
def _formal_state_oracle_correction_lease(
    workspace_fd: int,
    *,
    allow_create: bool,
) -> Any:
    relative = FORMAL_STATE_ORACLE_CORRECTION_TIER_DESTINATIONS[1]
    created = False
    if allow_create:
        try:
            lease_fd = _create_relative_file(
                workspace_fd,
                relative,
                b"",
                0o600,
            )
            created = True
            os.fsync(lease_fd)
            _fsync_relative_parent(workspace_fd, relative)
        except NamespaceCollision:
            lease_fd = os.open(
                relative,
                os.O_RDWR
                | os.O_NOFOLLOW
                | getattr(os, "O_CLOEXEC", 0),
                dir_fd=workspace_fd,
            )
    else:
        lease_fd = os.open(
            relative,
            os.O_RDWR
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0),
            dir_fd=workspace_fd,
        )
    try:
        observed = os.fstat(lease_fd)
        if (
            not stat.S_ISREG(observed.st_mode)
            or stat.S_IMODE(observed.st_mode) != 0o600
            or observed.st_uid != os.getuid()
            or observed.st_gid != os.getgid()
            or observed.st_nlink != 1
            or observed.st_size != 0
        ):
            raise ContractViolation(
                "Sequence 17 lease is unsafe"
            )
        try:
            fcntl.flock(
                lease_fd,
                fcntl.LOCK_EX | fcntl.LOCK_NB,
            )
        except BlockingIOError as exc:
            raise BlockingIOError(
                "Sequence 17 lease is busy"
            ) from exc
        yield _file_record_from_fd(relative, lease_fd), created
    finally:
        try:
            fcntl.flock(lease_fd, fcntl.LOCK_UN)
        finally:
            os.close(lease_fd)


def _validate_formal_state_oracle_correction_tier_complete(
    workspace_fd: int,
    source_root_fd: int,
) -> dict[str, Any]:
    parent_c0 = _import_sequence16_c0_preflight(
        workspace_fd,
        source_root_fd=source_root_fd,
        require_initial=False,
    )
    authorization = (
        _formal_state_oracle_correction_authorization_binding(
            source_root_fd
        )
    )
    archive_bytes, package_records = (
        _formal_state_oracle_correction_archive_bytes(
            source_root_fd
        )
    )
    paths = FORMAL_STATE_ORACLE_CORRECTION_TIER_DESTINATIONS
    lease_record, lease_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[1],
        )
    )
    prechange_record, prechange_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[2],
        )
    )
    rollback_record, rollback_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[3],
        )
    )
    directory = _open_relative_directory_fd(
        workspace_fd,
        paths[4],
    )
    try:
        observed = os.fstat(directory)
        if (
            stat.S_IMODE(observed.st_mode) != 0o700
            or observed.st_uid != os.getuid()
            or observed.st_gid != os.getgid()
            or set(os.listdir(directory))
            != {
                PurePosixPath(paths[5]).name,
                PurePosixPath(paths[6]).name,
                PurePosixPath(paths[7]).name,
            }
        ):
            raise ContractViolation(
                "Sequence 17 Tier directory differs"
            )
    finally:
        os.close(directory)
    owner_record, owner_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[5],
        )
    )
    archive_record, observed_archive = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[6],
        )
    )
    bundle_record, bundle_bytes = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            paths[7],
        )
    )
    values = _formal_state_oracle_correction_tier_values(
        lease_record=lease_record,
        parent_c0=parent_c0,
        authorization=authorization,
        package_records=package_records,
        prechange_record=prechange_record,
        owner_record=owner_record,
        archive_record=archive_record,
        bundle_record=bundle_record,
    )
    if (
        lease_bytes != b""
        or observed_archive != archive_bytes
        or prechange_bytes
        != _canonical_json_bytes(values["prechange"])
        or owner_bytes != _canonical_json_bytes(values["owner"])
        or bundle_bytes != _canonical_json_bytes(values["bundle"])
        or rollback_bytes
        != _canonical_json_bytes(values["rollback"])
    ):
        raise ContractViolation(
            "Sequence 17 Tier bytes differ"
        )
    return {
        "lease": _artifact_ref(lease_record),
        "prechange": _artifact_ref(prechange_record),
        "rollback": _artifact_ref(rollback_record),
        "owner": _artifact_ref(owner_record),
        "archive": _artifact_ref(archive_record),
        "bundle": _artifact_ref(bundle_record),
    }


def _bootstrap_formal_state_oracle_correction(
    workspace_fd: int,
    *,
    source_root_fd: int,
) -> dict[str, Any]:
    created_any = False
    paths = FORMAL_STATE_ORACLE_CORRECTION_TIER_DESTINATIONS
    with _lifecycle_correction_global_lock(workspace_fd):
        _parse_formal_state_oracle_correction_authorization_record(
            source_root_fd
        )
        parent_c0 = _import_sequence16_c0_preflight(
            workspace_fd,
            source_root_fd=source_root_fd,
            require_initial=True,
        )
        archive_bytes, package_records = (
            _formal_state_oracle_correction_archive_bytes(
                source_root_fd
            )
        )
        with _formal_state_oracle_correction_lease(
            workspace_fd,
            allow_create=True,
        ) as (lease_record, created):
            created_any = created_any or created
            authorization = (
                _formal_state_oracle_correction_authorization_binding(
                    source_root_fd
                )
            )
            initial = _formal_state_oracle_correction_tier_values(
                lease_record=lease_record,
                parent_c0=parent_c0,
                authorization=authorization,
                package_records=package_records,
            )
            prechange_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[2],
                    _canonical_json_bytes(initial["prechange"]),
                )
            )
            created_any = created_any or created
            directory = _ensure_relative_directory_fd(
                workspace_fd,
                paths[4],
            )
            os.close(directory)
            owner_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[5],
                    _canonical_json_bytes(initial["owner"]),
                )
            )
            created_any = created_any or created
            archive_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[6],
                    archive_bytes,
                )
            )
            created_any = created_any or created
            completed = _formal_state_oracle_correction_tier_values(
                lease_record=lease_record,
                parent_c0=parent_c0,
                authorization=authorization,
                package_records=package_records,
                prechange_record=prechange_record,
                owner_record=owner_record,
                archive_record=archive_record,
            )
            bundle_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[7],
                    _canonical_json_bytes(completed["bundle"]),
                )
            )
            created_any = created_any or created
            completed = _formal_state_oracle_correction_tier_values(
                lease_record=lease_record,
                parent_c0=parent_c0,
                authorization=authorization,
                package_records=package_records,
                prechange_record=prechange_record,
                owner_record=owner_record,
                archive_record=archive_record,
                bundle_record=bundle_record,
            )
            rollback_record, created = (
                _publish_or_reopen_continuation_file(
                    workspace_fd,
                    paths[3],
                    _canonical_json_bytes(completed["rollback"]),
                )
            )
            created_any = created_any or created
            _validate_formal_state_oracle_correction_tier_complete(
                workspace_fd,
                source_root_fd,
            )
    return {
        "exitCode": EXIT_SUCCESS,
        "created": created_any,
        "prechange": _artifact_ref(prechange_record),
        "rollback": _artifact_ref(rollback_record),
    }


