def _o1_lifecycle_test_correction_authorization_document_bytes(
) -> bytes:
    body = _canonical_json_bytes(
        _o1_lifecycle_test_correction_authorization_body()
    ).decode("utf-8")
    return (
        "# Quant Radar UX-1B Sequence 18 Component-Name "
        "Amendment Authorization\n\n"
        "Status: authorization candidate only. This document does not "
        "authorize bootstrap, preflight, manual-review publication, "
        "capture, comparison, candidate, root, or theme work until the "
        "repository maintainer separately accepts its exact whole-"
        "document SHA-256, byte size, and mode.\n\n"
        + O1_LIFECYCLE_TEST_CORRECTION_AUTH_START.decode("ascii")
        + body
        + O1_LIFECYCLE_TEST_CORRECTION_AUTH_END.decode("ascii")
        + "\n\nThe Sequence 18 component-name amendment imports the "
        "exact retained Sequence 17 "
        "`O1_INTAKE` as immutable history, freezes corrected current "
        "source under a distinct authority, may publish only the exact "
        "accepted intake bytes, and stops at `V2_REVIEW`. It grants no "
        "reviewer-intake, capture, comparison, candidate, root, or theme "
        "authority.\n"
    ).encode("utf-8")


def _parse_o1_lifecycle_test_correction_authorization_record(
    source_root_fd: int,
) -> dict[str, Any]:
    record, document = _source_file_record(
        source_root_fd,
        O1_LIFECYCLE_TEST_CORRECTION_AUTHORIZATION_DOCUMENT_PATH,
    )
    if (
        record["mode"] != "0644"
        or record["uid"] != os.getuid()
        or record["gid"] != os.getgid()
        or record["nlink"] != 1
        or document
        != _o1_lifecycle_test_correction_authorization_document_bytes()
        or document.count(
            O1_LIFECYCLE_TEST_CORRECTION_AUTH_GENERIC
        )
        != 2
    ):
        raise ContractViolation(
            "Sequence 18 authorization document differs"
        )
    for expected in (
        O1_LIFECYCLE_TEST_CORRECTION_PLAN_REF,
        O1_LIFECYCLE_TEST_CORRECTION_LEDGER_REF,
        O1_LIFECYCLE_TEST_CORRECTION_AMENDMENT_REF,
        O1_LIFECYCLE_TEST_CORRECTION_AMENDMENT_LEDGER_REF,
        O1_LIFECYCLE_TEST_CORRECTION_SUPERSEDED_AUTHORIZATION_REF,
    ):
        observed, _ = _source_file_record(
            source_root_fd,
            expected["path"],
        )
        if {
            key: observed[key]
            for key in ("path", "sha256", "size", "mode")
        } != expected:
            raise ContractViolation(
                "Sequence 18 authority drifted: "
                + expected["path"]
            )
    return _o1_lifecycle_test_correction_authorization_body()


def _o1_lifecycle_test_correction_authorization_binding(
    source_root_fd: int,
) -> dict[str, Any]:
    body = (
        _parse_o1_lifecycle_test_correction_authorization_record(
            source_root_fd
        )
    )
    record, _ = _source_file_record(
        source_root_fd,
        O1_LIFECYCLE_TEST_CORRECTION_AUTHORIZATION_DOCUMENT_PATH,
    )
    return {
        **_artifact_ref(record),
        "bodySha256": hashlib.sha256(
            _canonical_json_bytes(body)
        ).hexdigest(),
    }


def _build_o1_lifecycle_test_correction_source_projections(
    source_root_fd: int,
) -> dict[str, Any]:
    base = (
        _build_formal_state_oracle_correction_source_projections(
            source_root_fd
        )
    )
    mirror = base["sourceProjection"]
    mirror_paths = {
        row["path"] for row in mirror["records"]
    }
    records = {
        row["path"]: copy.deepcopy(row)
        for row in base["supplementalProjection"]["records"]
    }
    for relative in O1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS:
        if relative in mirror_paths:
            continue
        record, _ = _source_file_record(
            source_root_fd,
            relative,
        )
        records[relative] = {
            "path": relative,
            "sha256": record["sha256"],
            "size": record["size"],
            "mode": (
                "0555"
                if int(record["mode"], 8) & 0o111
                else "0444"
            ),
        }
    paths = sorted(records)
    projection = _source_projection_value(
        "quant-radar-ui-ux-supplemental-source/v1",
        paths,
        mirror["policy"]["include"],
        [records[path] for path in paths],
    )
    if (
        len(mirror["records"])
        != O1_LIFECYCLE_TEST_CORRECTION_SOURCE_COUNT
        or len(projection["records"])
        != O1_LIFECYCLE_TEST_CORRECTION_SUPPLEMENTAL_COUNT
    ):
        raise ContractViolation(
            "Sequence 18 source projection counts differ"
        )
    return {
        "sourceProjection": mirror,
        "supplementalProjection": projection,
    }


def _o1_lifecycle_test_correction_archive_bytes(
    source_root_fd: int,
) -> tuple[bytes, list[dict[str, Any]]]:
    output = io.BytesIO()
    records: list[dict[str, Any]] = []
    with tarfile.open(
        fileobj=output,
        mode="w",
        format=tarfile.PAX_FORMAT,
    ) as archive:
        for relative in O1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS:
            record, payload = _source_file_record(
                source_root_fd,
                relative,
            )
            records.append(record)
            member = tarfile.TarInfo(relative)
            member.size = len(payload)
            member.mode = stat.S_IMODE(int(record["mode"], 8))
            member.uid = 0
            member.gid = 0
            member.uname = ""
            member.gname = ""
            member.mtime = 0
            archive.addfile(member, io.BytesIO(payload))
    return output.getvalue(), records


def _o1_lifecycle_test_correction_make_contract(
    source_root_fd: int,
) -> dict[str, Any]:
    record, payload = _source_file_record(
        source_root_fd,
        "Makefile",
    )
    targets = (
        "ui-ux1b-external-review-o1-lifecycle-test-bootstrap",
        "ui-ux1b-external-review-o1-lifecycle-test-preflight",
        "ui-ux1b-external-review-o1-lifecycle-test-verify",
        "ui-ux1b-external-review-o1-lifecycle-test-publish",
    )
    text = payload.decode("utf-8", errors="strict")
    if any(
        text.count(target + ":") != 1 for target in targets
    ):
        raise ContractViolation(
            "Sequence 18 Make contract differs"
        )
    return {
        "artifact": _artifact_ref(record),
        "targets": list(targets),
        "targetsSha256": hashlib.sha256(
            _canonical_json_bytes(list(targets))
        ).hexdigest(),
    }


