def _o1_lifecycle_expected_artifact(
    relative: str,
    payload: bytes,
) -> dict[str, Any]:
    if not _is_safe_relative_path(relative) or not isinstance(
        payload,
        bytes,
    ):
        raise ContractViolation(
            "Sequence 18 expected artifact is invalid"
        )
    return {
        "path": relative,
        "sha256": hashlib.sha256(payload).hexdigest(),
        "size": len(payload),
    }


def _o1_lifecycle_test_correction_tier_values(
    *,
    lease_record: Mapping[str, Any],
    parent_o1: Mapping[str, Any],
    authorization: Mapping[str, Any],
    package_records: Sequence[Mapping[str, Any]],
    archive_bytes: bytes,
) -> dict[str, Any]:
    package = [
        _artifact_ref(record)
        for record in sorted(
            package_records,
            key=lambda item: item["path"],
        )
    ]
    if (
        len(package)
        != len(O1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS)
        or [row["path"] for row in package]
        != sorted(O1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS)
    ):
        raise ContractViolation(
            "Sequence 18 source package differs"
        )
    parent_projection = {
        key: copy.deepcopy(parent_o1[key])
        for key in (
            "classification",
            "authorization",
            "authorities",
            "preflight",
            "archive",
            "report",
            "packet",
            "intake",
            "decision",
        )
    }
    paths = O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS
    owner = {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-o1-lifecycle-"
            "test-correction-owner/v1"
        ),
        "o1LifecycleTestCorrectionId": (
            O1_LIFECYCLE_TEST_CORRECTION_ID
        ),
        "o1LifecycleTestTierId": (
            O1_LIFECYCLE_TEST_CORRECTION_TIER_ID
        ),
    }
    owner_bytes = _canonical_json_bytes(owner)
    owner_ref = _o1_lifecycle_expected_artifact(
        paths[5],
        owner_bytes,
    )
    archive_ref = _o1_lifecycle_expected_artifact(
        paths[6],
        archive_bytes,
    )
    bundle = {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-o1-lifecycle-"
            "test-correction-bundle/v1"
        ),
        "status": "sealed",
        "o1LifecycleTestCorrectionId": (
            O1_LIFECYCLE_TEST_CORRECTION_ID
        ),
        "o1LifecycleTestTierId": (
            O1_LIFECYCLE_TEST_CORRECTION_TIER_ID
        ),
        "ownerMarker": owner_ref,
        "archive": archive_ref,
        "archivedPaths": list(
            O1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS
        ),
        "namespaceLeafCount": 3,
    }
    bundle_bytes = _canonical_json_bytes(bundle)
    bundle_ref = _o1_lifecycle_expected_artifact(
        paths[7],
        bundle_bytes,
    )
    prechange = {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-o1-lifecycle-"
            "test-correction-prechange/v1"
        ),
        "status": "captured",
        "captureId": O1_LIFECYCLE_TEST_CORRECTION_CAPTURE_ID,
        "packetContinuationId": (
            O1_LIFECYCLE_TEST_CORRECTION_PACKET_CONTINUATION_ID
        ),
        "parentFormalStateOracleCorrectionId": (
            O1_LIFECYCLE_TEST_CORRECTION_PARENT_CORRECTION_ID
        ),
        "o1LifecycleTestCorrectionId": (
            O1_LIFECYCLE_TEST_CORRECTION_ID
        ),
        "o1LifecycleTestTierId": (
            O1_LIFECYCLE_TEST_CORRECTION_TIER_ID
        ),
        "authorizationRecord": copy.deepcopy(
            dict(authorization)
        ),
        "plan": copy.deepcopy(
            O1_LIFECYCLE_TEST_CORRECTION_PLAN_REF
        ),
        "traceability": copy.deepcopy(
            O1_LIFECYCLE_TEST_CORRECTION_LEDGER_REF
        ),
        "parentO1": parent_projection,
        "package": package,
        "bundlePath": paths[4],
        "lease": copy.deepcopy(dict(lease_record)),
    }
    prechange_bytes = _canonical_json_bytes(prechange)
    prechange_ref = _o1_lifecycle_expected_artifact(
        paths[2],
        prechange_bytes,
    )
    rollback = {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-o1-lifecycle-"
            "test-correction-rollback/v1"
        ),
        "status": "ready",
        "o1LifecycleTestCorrectionId": (
            O1_LIFECYCLE_TEST_CORRECTION_ID
        ),
        "o1LifecycleTestTierId": (
            O1_LIFECYCLE_TEST_CORRECTION_TIER_ID
        ),
        "prechange": prechange_ref,
        "bundleManifest": bundle_ref,
        "entries": [
            {
                "path": record["path"],
                "artifact": _artifact_ref(record),
                "disposition": "restore_whole_if_exact",
            }
            for record in sorted(
                package_records,
                key=lambda item: item["path"],
            )
        ],
        "destructiveGitAllowed": False,
    }
    rollback_bytes = _canonical_json_bytes(rollback)
    payloads = {
        paths[1]: b"",
        paths[2]: prechange_bytes,
        paths[3]: rollback_bytes,
        paths[5]: owner_bytes,
        paths[6]: archive_bytes,
        paths[7]: bundle_bytes,
    }
    return {
        "prechange": prechange,
        "rollback": rollback,
        "owner": owner,
        "bundle": bundle,
        "payloads": payloads,
        "expectedTier": {
            "lease": _artifact_ref(dict(lease_record)),
            "prechange": prechange_ref,
            "rollback": _o1_lifecycle_expected_artifact(
                paths[3],
                rollback_bytes,
            ),
            "owner": owner_ref,
            "archive": archive_ref,
            "bundle": bundle_ref,
        },
    }


def _o1_lifecycle_test_correction_prefix_presence(
    workspace_fd: int,
) -> tuple[bool, ...]:
    return tuple(
        _relative_leaf_lstat(workspace_fd, relative) is not None
        for relative in (
            O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[1:]
        )
    )


def _validate_o1_lifecycle_test_correction_component_contract(
) -> None:
    destinations = (
        O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[1:]
    )
    if (
        len(destinations) != 8
        or any(
            not _is_normalized_publisher_component(
                PurePosixPath(relative).name
            )
            for relative in destinations
        )
    ):
        raise ContractViolation(
            "Sequence 18 destination component contract differs"
        )


def _validate_o1_lifecycle_test_correction_rejected_paths_absent(
    workspace_fd: int,
) -> None:
    if (
        type(workspace_fd) is not int
        or workspace_fd < 0
        or not stat.S_ISDIR(os.fstat(workspace_fd).st_mode)
    ):
        raise ContractViolation(
            "Sequence 18 rejected-path check requires a workspace "
            "directory descriptor"
        )
    for relative in O1_LIFECYCLE_TEST_CORRECTION_REJECTED_PATHS:
        if _relative_leaf_lstat(workspace_fd, relative) is not None:
            raise ContractViolation(
                "Sequence 18 superseded component exists: "
                + relative
            )


def _validate_o1_lifecycle_test_correction_prefix(
    workspace_fd: int,
    values: Mapping[str, Any] | None,
    *,
    allow_preflight: bool = False,
) -> int:
    if type(allow_preflight) is not bool:
        raise ContractViolation(
            "Sequence 18 preflight-prefix mode is invalid"
        )
    paths = O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS
    presence = _o1_lifecycle_test_correction_prefix_presence(
        workspace_fd
    )
    if presence[7] and not allow_preflight:
        raise ContractViolation(
            "Sequence 18 bootstrap prefix includes preflight"
        )
    seven = presence[:7]
    prefix_length = 0
    absent_seen = False
    for present in seven:
        if present and absent_seen:
            raise ContractViolation(
                "Sequence 18 bootstrap Tier is not a prefix"
            )
        if present:
            prefix_length += 1
        else:
            absent_seen = True
    if prefix_length == 0:
        if values is not None:
            raise ContractViolation(
                "Sequence 18 empty prefix has unexpected values"
            )
        return 0
    if not isinstance(values, Mapping):
        raise ContractViolation(
            "Sequence 18 prefix values are absent"
        )
    payloads = values.get("payloads")
    if not isinstance(payloads, Mapping):
        raise ContractViolation(
            "Sequence 18 prefix payload map is invalid"
        )
    step_paths = (
        paths[1],
        paths[2],
        paths[3],
        paths[4],
        paths[5],
        paths[6],
        paths[7],
    )
    for index, relative in enumerate(step_paths):
        if index >= prefix_length:
            break
        if index == 3:
            directory_fd = _open_relative_directory_fd(
                workspace_fd,
                relative,
            )
            try:
                observed = os.fstat(directory_fd)
                expected_names = {
                    PurePosixPath(step_paths[item]).name
                    for item in range(4, prefix_length)
                }
                if (
                    stat.S_IMODE(observed.st_mode) != 0o700
                    or observed.st_uid != os.getuid()
                    or observed.st_gid != os.getgid()
                    or set(os.listdir(directory_fd))
                    != expected_names
                ):
                    raise ContractViolation(
                        "Sequence 18 prefix Tier directory differs"
                    )
            finally:
                os.close(directory_fd)
            continue
        expected_payload = payloads.get(relative)
        if not isinstance(expected_payload, bytes):
            raise ContractViolation(
                "Sequence 18 prefix payload is absent"
            )
        record, payload = _relative_regular_record_and_bytes(
            workspace_fd,
            relative,
        )
        if (
            payload != expected_payload
            or record["mode"] != "0600"
            or record["uid"] != os.getuid()
            or record["gid"] != os.getgid()
            or record["nlink"] != 1
        ):
            raise ContractViolation(
                "Sequence 18 bootstrap prefix differs: "
                + relative
            )
    return prefix_length


def _publish_o1_lifecycle_test_correction_file(
    workspace_fd: int,
    relative: str,
    payload: bytes,
    *,
    fault_after: str | None = None,
    syscalls: Any | None = None,
) -> dict[str, Any]:
    parent, name = relative.rsplit("/", 1)
    parent_fd = _open_relative_directory_fd(
        workspace_fd,
        parent,
    )
    try:
        published = _publish_regular_exact(
            parent_fd,
            name,
            payload,
            fault_after=fault_after,
            syscalls=syscalls,
        )
    finally:
        os.close(parent_fd)
    if published.get("exitCode") != EXIT_SUCCESS:
        return {
            "exitCode": published["exitCode"],
            "created": bool(published.get("created")),
            "record": None,
        }
    record = dict(published["published"])
    record["path"] = relative
    return {
        "exitCode": EXIT_SUCCESS,
        "created": bool(published["created"]),
        "record": record,
    }


def _create_o1_lifecycle_test_correction_directory(
    workspace_fd: int,
    relative: str,
    *,
    fault_after: str | None,
) -> dict[str, Any]:
    if fault_after not in {
        None,
        "before-mkdir",
        "after-mkdir",
        "after-parent-fsync",
    }:
        raise ContractViolation(
            "Sequence 18 directory fault boundary is invalid"
        )
    parent, name = relative.rsplit("/", 1)
    parent_fd = _open_relative_directory_fd(
        workspace_fd,
        parent,
    )
    created = False
    try:
        if fault_after == "before-mkdir":
            return {
                "exitCode": EXIT_CONTRACT,
                "created": False,
            }
        try:
            os.mkdir(name, 0o700, dir_fd=parent_fd)
            created = True
        except FileExistsError:
            pass
        directory_fd = os.open(
            name,
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | os.O_NOFOLLOW
            | getattr(os, "O_CLOEXEC", 0),
            dir_fd=parent_fd,
        )
        try:
            observed = os.fstat(directory_fd)
            if (
                stat.S_IMODE(observed.st_mode) != 0o700
                or observed.st_uid != os.getuid()
                or observed.st_gid != os.getgid()
                or os.listdir(directory_fd)
            ):
                raise ContractViolation(
                    "Sequence 18 Tier directory collision"
                )
        finally:
            os.close(directory_fd)
        if fault_after == "after-mkdir":
            return {
                "exitCode": EXIT_UNCERTAIN,
                "created": created,
            }
        os.fsync(parent_fd)
        if fault_after == "after-parent-fsync":
            return {
                "exitCode": EXIT_UNCERTAIN,
                "created": created,
            }
        return {
            "exitCode": EXIT_SUCCESS,
            "created": created,
        }
    finally:
        os.close(parent_fd)


@contextlib.contextmanager
def _o1_lifecycle_test_correction_lease(
    workspace_fd: int,
) -> Any:
    relative = O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[1]
    lease_fd = os.open(
        relative,
        os.O_RDWR
        | os.O_NOFOLLOW
        | getattr(os, "O_CLOEXEC", 0),
        dir_fd=workspace_fd,
    )
    try:
        observed = os.fstat(lease_fd)
        if (
            not stat.S_ISREG(observed.st_mode)
            or stat.S_IMODE(observed.st_mode) != 0o600
            or observed.st_uid != os.getuid()
            or observed.st_gid != os.getgid()
            or observed.st_nlink != 1
            or observed.st_size != 0
        ):
            raise ContractViolation(
                "Sequence 18 lease is unsafe"
            )
        try:
            fcntl.flock(
                lease_fd,
                fcntl.LOCK_EX | fcntl.LOCK_NB,
            )
        except BlockingIOError as exc:
            raise BlockingIOError(
                "Sequence 18 lease is busy"
            ) from exc
        yield _file_record_from_fd(relative, lease_fd)
    finally:
        try:
            fcntl.flock(lease_fd, fcntl.LOCK_UN)
        finally:
            os.close(lease_fd)


def _o1_lifecycle_fault_for_step(
    fault_after: str | None,
    step: str,
) -> str | None:
    if fault_after is None:
        return None
    prefix = step + ":"
    if not fault_after.startswith(prefix):
        return None
    return fault_after[len(prefix) :]


def _bootstrap_o1_lifecycle_test_correction(
    workspace_fd: int,
    *,
    source_root_fd: int,
    fault_after: str | None = None,
    syscalls: Any | None = None,
) -> dict[str, Any]:
    allowed_steps = {
        "lease",
        "prechange",
        "rollback",
        "tier-directory",
        "owner",
        "archive",
        "bundle",
    }
    if fault_after is not None and (
        ":" not in fault_after
        or fault_after.split(":", 1)[0] not in allowed_steps
    ):
        raise ContractViolation(
            "Sequence 18 bootstrap fault boundary is invalid"
        )
    created_any = False
    paths = O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS
    with _lifecycle_correction_global_lock(workspace_fd):
        _validate_o1_lifecycle_test_correction_rejected_paths_absent(
            workspace_fd
        )
        _validate_o1_lifecycle_test_correction_component_contract()
        _parse_o1_lifecycle_test_correction_authorization_record(
            source_root_fd
        )
        parent_o1 = _import_sequence17_o1_intake(
            workspace_fd,
            source_root_fd=source_root_fd,
            require_initial=True,
        )
        initial_prefix = (
            _validate_o1_lifecycle_test_correction_prefix(
                workspace_fd,
                None,
            )
            if not _o1_lifecycle_test_correction_prefix_presence(
                workspace_fd
            )[0]
            else None
        )
        if initial_prefix == 0:
            published = (
                _publish_o1_lifecycle_test_correction_file(
                    workspace_fd,
                    paths[1],
                    b"",
                    fault_after=_o1_lifecycle_fault_for_step(
                        fault_after,
                        "lease",
                    ),
                    syscalls=syscalls,
                )
            )
            created_any = created_any or published["created"]
            if published["exitCode"] != EXIT_SUCCESS:
                return {
                    "exitCode": published["exitCode"],
                    "created": created_any,
                }
        with _o1_lifecycle_test_correction_lease(
            workspace_fd
        ) as lease_record:
            authorization = (
                _o1_lifecycle_test_correction_authorization_binding(
                    source_root_fd
                )
            )
            archive_bytes, package_records = (
                _o1_lifecycle_test_correction_archive_bytes(
                    source_root_fd
                )
            )
            values = _o1_lifecycle_test_correction_tier_values(
                lease_record=lease_record,
                parent_o1=parent_o1,
                authorization=authorization,
                package_records=package_records,
                archive_bytes=archive_bytes,
            )
            prefix_length = (
                _validate_o1_lifecycle_test_correction_prefix(
                    workspace_fd,
                    values,
                )
            )
            steps = (
                ("prechange", paths[2]),
                ("rollback", paths[3]),
                ("tier-directory", paths[4]),
                ("owner", paths[5]),
                ("archive", paths[6]),
                ("bundle", paths[7]),
            )
            for step_index, (step, relative) in enumerate(
                steps,
                start=2,
            ):
                if prefix_length >= step_index:
                    continue
                _import_sequence17_o1_intake(
                    workspace_fd,
                    source_root_fd=source_root_fd,
                    require_initial=True,
                )
                if step == "tier-directory":
                    result = (
                        _create_o1_lifecycle_test_correction_directory(
                            workspace_fd,
                            relative,
                            fault_after=(
                                _o1_lifecycle_fault_for_step(
                                    fault_after,
                                    step,
                                )
                            ),
                        )
                    )
                else:
                    payload = values["payloads"].get(relative)
                    if not isinstance(payload, bytes):
                        raise ContractViolation(
                            "Sequence 18 bootstrap payload is absent"
                        )
                    result = (
                        _publish_o1_lifecycle_test_correction_file(
                            workspace_fd,
                            relative,
                            payload,
                            fault_after=(
                                _o1_lifecycle_fault_for_step(
                                    fault_after,
                                    step,
                                )
                            ),
                            syscalls=syscalls,
                        )
                    )
                created_any = created_any or result["created"]
                if result["exitCode"] != EXIT_SUCCESS:
                    return {
                        "exitCode": result["exitCode"],
                        "created": created_any,
                    }
                prefix_length = (
                    _validate_o1_lifecycle_test_correction_prefix(
                        workspace_fd,
                        values,
                    )
                )
                if prefix_length != step_index:
                    raise ContractViolation(
                        "Sequence 18 bootstrap prefix did not advance"
                    )
            if prefix_length != 7:
                raise ContractViolation(
                    "Sequence 18 bootstrap did not reach V0"
                )
    return {
        "exitCode": EXIT_SUCCESS,
        "created": created_any,
        "state": "V0_BOOTSTRAPPED",
        "prechange": copy.deepcopy(
            values["expectedTier"]["prechange"]
        ),
        "rollback": copy.deepcopy(
            values["expectedTier"]["rollback"]
        ),
    }


def _validate_o1_lifecycle_test_correction_tier_complete(
    workspace_fd: int,
    source_root_fd: int,
    *,
    require_initial: bool,
) -> dict[str, Any]:
    parent_o1 = _import_sequence17_o1_intake(
        workspace_fd,
        source_root_fd=source_root_fd,
        require_initial=require_initial,
    )
    authorization = (
        _o1_lifecycle_test_correction_authorization_binding(
            source_root_fd
        )
    )
    archive_bytes, package_records = (
        _o1_lifecycle_test_correction_archive_bytes(
            source_root_fd
        )
    )
    lease_record, lease_payload = (
        _relative_regular_record_and_bytes(
            workspace_fd,
            O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[1],
        )
    )
    values = _o1_lifecycle_test_correction_tier_values(
        lease_record=lease_record,
        parent_o1=parent_o1,
        authorization=authorization,
        package_records=package_records,
        archive_bytes=archive_bytes,
    )
    if (
        lease_payload != b""
        or _validate_o1_lifecycle_test_correction_prefix(
            workspace_fd,
            values,
            allow_preflight=True,
        )
        != 7
    ):
        raise ContractViolation(
            "Sequence 18 Tier is not complete"
        )
    result: dict[str, Any] = {}
    expected_tier = values["expectedTier"]
    for key, index in (
        ("lease", 1),
        ("prechange", 2),
        ("rollback", 3),
        ("owner", 5),
        ("archive", 6),
        ("bundle", 7),
    ):
        record, _ = _relative_regular_record_and_bytes(
            workspace_fd,
            O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[index],
        )
        ref = _artifact_ref(record)
        if ref != expected_tier[key]:
            raise ContractViolation(
                "Sequence 18 Tier artifact differs: " + key
            )
        result[key] = ref
    return result


def _classify_o1_lifecycle_test_correction_forward(
    workspace_fd: int,
) -> dict[str, Any]:
    records: list[dict[str, Any] | None] = []
    payloads: list[bytes | None] = []
    values: list[dict[str, Any] | None] = []
    presence: list[bool] = []
    for relative in O1_LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS:
        if _relative_leaf_lstat(workspace_fd, relative) is None:
            records.append(None)
            payloads.append(None)
            values.append(None)
            presence.append(False)
            continue
        record, payload = _relative_regular_record_and_bytes(
            workspace_fd,
            relative,
        )
        value = _strict_json_bytes(payload, allow_float=True)
        if (
            record["mode"] != "0600"
            or record["uid"] != os.getuid()
            or record["gid"] != os.getgid()
            or record["nlink"] != 1
            or not isinstance(value, dict)
            or payload != _canonical_json_bytes(value)
        ):
            raise ContractViolation(
                "Sequence 18 forward leaf is unsafe: "
                + relative
            )
        records.append(record)
        payloads.append(payload)
        values.append(value)
        presence.append(True)
    states = {
        (
            True,
            True,
            True,
            False,
            False,
            False,
        ): "V1_INTAKE",
        (
            True,
            True,
            True,
            True,
            False,
            False,
        ): "V2_REVIEW",
    }
    state = states.get(tuple(presence))
    if state is None:
        raise ContractViolation(
            "Sequence 18 forward lifecycle is not exact"
        )
    return {
        "state": state,
        "present": presence,
        "records": records,
        "payloads": payloads,
        "values": values,
    }


def _validate_o1_lifecycle_test_correction_forward_semantics(
    workspace_fd: int,
    source_root_fd: int,
    *,
    preflight: Mapping[str, Any],
) -> dict[str, Any]:
    parent_o1 = _import_sequence17_o1_intake(
        workspace_fd,
        source_root_fd=source_root_fd,
        require_initial=False,
    )
    current = _classify_o1_lifecycle_test_correction_forward(
        workspace_fd
    )
    records = current["records"]
    payloads = current["payloads"]
    values = current["values"]
    for index, expected in enumerate(
        O1_LIFECYCLE_TEST_CORRECTION_PARENT_REFS[-3:]
    ):
        observed = records[index]
        if (
            observed is None
            or {
                key: observed[key]
                for key in ("path", "sha256", "size", "mode")
            }
            != expected
        ):
            raise ContractViolation(
                "Sequence 18 parent forward leaf differs"
            )
    if (
        values[0] != parent_o1["reportValue"]
        or values[1] != parent_o1["packetValue"]
        or values[2] != parent_o1["intakeValue"]
        or payloads[2] != parent_o1["intakeBytes"]
    ):
        raise ContractViolation(
            "Sequence 18 parent forward values differ"
        )
    _validate_external_review_manual_review_for_authority(
        parent_o1["intakeValue"],
        parent_o1["packetValue"],
        packet_path=(
            O1_LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[1]
        ),
        packet_bytes=payloads[1],
        preflight=parent_o1["preflightValue"],
        expected_appointment=(
            _formal_state_oracle_correction_reviewer_appointment()
        ),
        accepted_sha256=records[2]["sha256"],
        accepted_size=records[2]["size"],
        broker_now=None,
        initial_submission=False,
        review_window_seconds=(
            FORMAL_STATE_ORACLE_CORRECTION_REVIEW_WINDOW_SECONDS
        ),
        clock_skew_seconds=(
            FORMAL_STATE_ORACLE_CORRECTION_CLOCK_SKEW_SECONDS
        ),
        max_intake_bytes=(
            FORMAL_STATE_ORACLE_CORRECTION_MAX_INTAKE_BYTES
        ),
        contract_label="Sequence 18 frozen O1",
    )
    if current["state"] == "V1_INTAKE":
        current["decision"] = "accepted"
        return current
    review_record = records[3]
    review_payload = payloads[3]
    review_value = values[3]
    intake_record = records[2]
    assert (
        review_record is not None
        and review_payload is not None
        and isinstance(review_value, dict)
        and intake_record is not None
    )
    if (
        review_payload != parent_o1["intakeBytes"]
        or review_value != parent_o1["intakeValue"]
        or review_record["inode"] == intake_record["inode"]
    ):
        raise ContractViolation(
            "Sequence 18 review is not an exact different-inode copy"
        )
    current["decision"] = "accepted"
    return current


def _build_o1_lifecycle_test_correction_preflight_value(
    workspace_fd: int,
    source_root_fd: int,
    *,
    require_initial: bool,
) -> dict[str, Any]:
    parent_o1 = _import_sequence17_o1_intake(
        workspace_fd,
        source_root_fd=source_root_fd,
        require_initial=require_initial,
    )
    tier = _validate_o1_lifecycle_test_correction_tier_complete(
        workspace_fd,
        source_root_fd,
        require_initial=require_initial,
    )
    projections = _import_later_source_projections_history(
        source_root_fd,
        "sequence18",
    )
    parent_created_at = parent_o1["preflightValue"].get(
        "createdAt"
    )
    parent_review_deadline = parent_o1[
        "preflightValue"
    ].get("reviewDeadline")
    reviewed_at = parent_o1["intakeValue"].get("reviewedAt")
    reviewed_epoch = _external_review_parse_time(
        reviewed_at,
        "Sequence 18 frozen reviewedAt",
    )
    created_epoch = _external_review_parse_time(
        parent_created_at,
        "Sequence 18 frozen parent createdAt",
    )
    deadline_epoch = _external_review_parse_time(
        parent_review_deadline,
        "Sequence 18 frozen parent reviewDeadline",
    )
    if (
        reviewed_epoch
        < (
            created_epoch
            - FORMAL_STATE_ORACLE_CORRECTION_CLOCK_SKEW_SECONDS
        )
        or reviewed_epoch > deadline_epoch
    ):
        raise ContractViolation(
            "Sequence 18 frozen review timing differs"
        )
    parent_projection = {
        key: copy.deepcopy(parent_o1[key])
        for key in (
            "classification",
            "authorization",
            "authorities",
            "preflight",
            "archive",
            "report",
            "packet",
            "intake",
            "decision",
        )
    }
    content_materials = (
        _o1_lifecycle_test_correction_content_material_refs(
            parent_o1["packetValue"],
            projections["sourceProjection"],
            projections["supplementalProjection"],
        )
    )
    if (
        len(content_materials)
        != O1_LIFECYCLE_TEST_CORRECTION_CONTENT_LEAVES
    ):
        raise ContractViolation(
            "Sequence 18 preflight content geometry differs"
        )
    return {
        "schemaVersion": (
            "quant-radar-ui-ux-external-review-o1-lifecycle-"
            "test-correction-preflight/v1"
        ),
        "status": "passed",
        "captureId": O1_LIFECYCLE_TEST_CORRECTION_CAPTURE_ID,
        "packetContinuationId": (
            O1_LIFECYCLE_TEST_CORRECTION_PACKET_CONTINUATION_ID
        ),
        "parentFormalStateOracleCorrectionId": (
            O1_LIFECYCLE_TEST_CORRECTION_PARENT_CORRECTION_ID
        ),
        "o1LifecycleTestCorrectionId": (
            O1_LIFECYCLE_TEST_CORRECTION_ID
        ),
        "o1LifecycleTestTierId": (
            O1_LIFECYCLE_TEST_CORRECTION_TIER_ID
        ),
        "authorizationRecord": (
            _o1_lifecycle_test_correction_authorization_binding(
                source_root_fd
            )
        ),
        "plan": copy.deepcopy(
            O1_LIFECYCLE_TEST_CORRECTION_PLAN_REF
        ),
        "traceability": copy.deepcopy(
            O1_LIFECYCLE_TEST_CORRECTION_LEDGER_REF
        ),
        "parentO1": parent_projection,
        "initialState": "V1_INTAKE",
        "sourceProjection": projections["sourceProjection"],
        "supplementalProjection": projections[
            "supplementalProjection"
        ],
        "runtimeReceipt": _import_sequence12_runtime_history(
            workspace_fd
        ),
        "makeContract": (
            _o1_lifecycle_test_correction_make_contract(
                source_root_fd
            )
        ),
        "namespaceInventory": (
            _o1_lifecycle_test_correction_namespace_inventory()
        ),
        "descriptorProfile": (
            _build_o1_lifecycle_test_correction_descriptor_profile()
        ),
        "materialGeometry": {
            "sourceProjection": (
                O1_LIFECYCLE_TEST_CORRECTION_SOURCE_COUNT
            ),
            "supplementalProjection": (
                O1_LIFECYCLE_TEST_CORRECTION_SUPPLEMENTAL_COUNT
            ),
            "contentMaterials": len(content_materials),
            "authorityMaterials": (
                O1_LIFECYCLE_TEST_CORRECTION_AUTHORITY_LEAVES
            ),
            "retainedMaterials": (
                O1_LIFECYCLE_TEST_CORRECTION_RETAINED_LEAVES
            ),
            "requiredSoftFloor": (
                O1_LIFECYCLE_TEST_CORRECTION_REQUIRED_SOFT_FLOOR
            ),
        },
        "tier": tier,
        "createdAt": reviewed_at,
        "parentCreatedAt": parent_created_at,
        "parentReviewDeadline": parent_review_deadline,
        "acceptedIntake": copy.deepcopy(parent_o1["intake"]),
        "decision": "accepted",
        "formalPause": "V2_REVIEW",
        "candidateForbidden": True,
        "rootForbidden": True,
    }


def _validate_o1_lifecycle_test_correction_preflight_value(
    workspace_fd: int,
    source_root_fd: int,
    value: Any,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ContractViolation(
            "Sequence 18 preflight is not an object"
        )
    expected = _build_o1_lifecycle_test_correction_preflight_value(
        workspace_fd,
        source_root_fd,
        require_initial=False,
    )
    if value != expected or set(value) != set(expected):
        raise ContractViolation(
            "Sequence 18 preflight differs"
        )
    return copy.deepcopy(expected)


def _reauthenticate_o1_lifecycle_test_correction_preflight(
    workspace_fd: int,
    source_root_fd: int,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    record, payload = _relative_regular_record_and_bytes(
        workspace_fd,
        O1_LIFECYCLE_TEST_CORRECTION_PREFLIGHT_PATH,
    )
    value = _strict_json_bytes(payload, allow_float=True)
    if (
        record["mode"] != "0600"
        or record["uid"] != os.getuid()
        or record["gid"] != os.getgid()
        or record["nlink"] != 1
        or not isinstance(value, dict)
        or payload != _canonical_json_bytes(value)
    ):
        raise ContractViolation(
            "Sequence 18 preflight is unsafe"
        )
    authenticated = (
        _validate_o1_lifecycle_test_correction_preflight_value(
            workspace_fd,
            source_root_fd,
            value,
        )
    )
    current = (
        _validate_o1_lifecycle_test_correction_forward_semantics(
            workspace_fd,
            source_root_fd,
            preflight=authenticated,
        )
    )
    return record, authenticated, current


def _classify_o1_lifecycle_test_correction_workspace(
    workspace_fd: int,
    source_root_fd: int,
) -> dict[str, Any]:
    if any(
        type(descriptor) is not int or descriptor < 0
        for descriptor in (workspace_fd, source_root_fd)
    ):
        raise ContractViolation(
            "Sequence 18 workspace descriptors are invalid"
        )
    _validate_o1_lifecycle_test_correction_rejected_paths_absent(
        workspace_fd
    )
    _validate_o1_lifecycle_test_correction_component_contract()
    presence = (
        _o1_lifecycle_test_correction_prefix_presence(
            workspace_fd
        )
    )
    if presence == (False,) * 8:
        parent = _import_sequence17_o1_intake(
            workspace_fd,
            source_root_fd=source_root_fd,
            require_initial=True,
        )
        return {
            "state": "IMPLEMENTATION_BOUNDARY",
            "tierPresence": list(presence),
            "parent": parent,
        }
    if presence == (True,) * 7 + (False,):
        tier = _validate_o1_lifecycle_test_correction_tier_complete(
            workspace_fd,
            source_root_fd,
            require_initial=True,
        )
        return {
            "state": "V0_BOOTSTRAPPED",
            "tierPresence": list(presence),
            "tier": tier,
        }
    if presence != (True,) * 8:
        raise ContractViolation(
            "Sequence 18 permanent workspace Tier is partial"
        )
    try:
        preflight_record, _, current = (
            _reauthenticate_o1_lifecycle_test_correction_preflight(
                workspace_fd,
                source_root_fd,
            )
        )
    except ContractViolation:
        return _classify_sequence18_historical_v1_workspace(
            workspace_fd,
            source_root_fd,
        )
    if current["state"] not in (
        O1_LIFECYCLE_TEST_CORRECTION_FORWARD_STATES
    ):
        raise ContractViolation(
            "Sequence 18 permanent workspace state differs"
        )
    return {
        "state": current["state"],
        "tierPresence": list(presence),
        "preflight": _artifact_ref(preflight_record),
        "forward": current,
    }


def _o1_lifecycle_test_correction_preflight_lifecycle(
    workspace_fd: int,
    *,
    source_root_fd: int,
    verify_only: bool,
    fault_after: str | None = None,
    syscalls: Any | None = None,
) -> dict[str, Any]:
    if type(verify_only) is not bool:
        raise ContractViolation(
            "Sequence 18 preflight mode is invalid"
        )
    with _lifecycle_correction_global_lock(workspace_fd):
        _validate_o1_lifecycle_test_correction_rejected_paths_absent(
            workspace_fd
        )
        _validate_o1_lifecycle_test_correction_component_contract()
        _parse_o1_lifecycle_test_correction_authorization_record(
            source_root_fd
        )
        with _o1_lifecycle_test_correction_lease(
            workspace_fd
        ):
            classified = (
                _classify_o1_lifecycle_test_correction_workspace(
                    workspace_fd,
                    source_root_fd,
                )
            )
            if verify_only:
                if classified["state"] not in {
                    "V1_INTAKE",
                    "V2_REVIEW",
                }:
                    raise ContractViolation(
                        "Sequence 18 verify requires V1 or V2"
                    )
                return {
                    "exitCode": EXIT_SUCCESS,
                    "created": False,
                    "state": classified["state"],
                    "preflight": copy.deepcopy(
                        classified["preflight"]
                    ),
                }
            if classified["state"] in {
                "V1_INTAKE",
                "V2_REVIEW",
            }:
                return {
                    "exitCode": EXIT_SUCCESS,
                    "created": False,
                    "state": classified["state"],
                    "preflight": copy.deepcopy(
                        classified["preflight"]
                    ),
                }
            if classified["state"] != "V0_BOOTSTRAPPED":
                raise ContractViolation(
                    "Sequence 18 preflight requires V0"
                )
            value = (
                _build_o1_lifecycle_test_correction_preflight_value(
                    workspace_fd,
                    source_root_fd,
                    require_initial=True,
                )
            )
            published = (
                _publish_o1_lifecycle_test_correction_file(
                    workspace_fd,
                    O1_LIFECYCLE_TEST_CORRECTION_PREFLIGHT_PATH,
                    _canonical_json_bytes(value),
                    fault_after=fault_after,
                    syscalls=syscalls,
                )
            )
            if published["exitCode"] != EXIT_SUCCESS:
                return {
                    "exitCode": published["exitCode"],
                    "created": published["created"],
                }
            reopened = (
                _classify_o1_lifecycle_test_correction_workspace(
                    workspace_fd,
                    source_root_fd,
                )
            )
            if reopened["state"] != "V1_INTAKE":
                raise ContractViolation(
                    "Sequence 18 preflight postcondition differs"
                )
            return {
                "exitCode": EXIT_SUCCESS,
                "created": published["created"],
                "state": "V1_INTAKE",
                "preflight": copy.deepcopy(
                    reopened["preflight"]
                ),
            }


def _o1_lifecycle_test_correction_content_material_refs(
    packet: Mapping[str, Any],
    source_projection: Mapping[str, Any],
    supplemental_projection: Mapping[str, Any],
) -> dict[str, dict[str, Any]]:
    return _external_review_material_refs_for_profile(
        packet,
        source_projection,
        supplemental_projection,
        expected_supplemental_count=(
            O1_LIFECYCLE_TEST_CORRECTION_SUPPLEMENTAL_COUNT
        ),
        expected_retained_count=(
            O1_LIFECYCLE_TEST_CORRECTION_CONTENT_LEAVES
        ),
        contract_label="Sequence 18 content",
    )


def _o1_lifecycle_test_correction_material_refs(
    packet: Mapping[str, Any],
    preflight: Mapping[str, Any],
    preflight_record: Mapping[str, Any],
) -> dict[str, Any]:
    content = (
        _o1_lifecycle_test_correction_content_material_refs(
            packet,
            preflight.get("sourceProjection", {}),
            preflight.get("supplementalProjection", {}),
        )
    )
    parent_indexes = (3, 4, 5, 6, 7, 8, 9, 11, 12)
    parent_authority = [
        copy.deepcopy(
            dict(O1_LIFECYCLE_TEST_CORRECTION_PARENT_REFS[index])
        )
        for index in parent_indexes
    ]
    tier = preflight.get("tier")
    if not isinstance(tier, Mapping):
        raise ContractViolation(
            "Sequence 18 preflight Tier is invalid"
        )
    current_authority = [
        copy.deepcopy(dict(tier[key]))
        for key in (
            "lease",
            "prechange",
            "rollback",
            "owner",
            "archive",
            "bundle",
        )
    ]
    current_authority.append(
        _artifact_ref(dict(preflight_record))
    )
    if (
        len(content)
        != O1_LIFECYCLE_TEST_CORRECTION_CONTENT_LEAVES
        or len(parent_authority)
        != O1_LIFECYCLE_TEST_CORRECTION_PARENT_AUTHORITY_LEAVES
        or len(current_authority)
        != O1_LIFECYCLE_TEST_CORRECTION_CURRENT_AUTHORITY_LEAVES
    ):
        raise ContractViolation(
            "Sequence 18 material partition count differs"
        )

    def normalize(
        row: Mapping[str, Any],
        source: str,
    ) -> dict[str, Any]:
        if (
            not isinstance(row, Mapping)
            or not _is_safe_relative_path(row.get("path"))
            or not isinstance(row.get("sha256"), str)
            or re.fullmatch(r"[0-9a-f]{64}", row["sha256"])
            is None
            or type(row.get("size")) is not int
            or row["size"] < 0
        ):
            raise ContractViolation(
                "Sequence 18 authority material is invalid"
            )
        return {
            "path": row["path"],
            "sha256": row["sha256"],
            "size": row["size"],
            "source": source,
        }

    references = {
        path: copy.deepcopy(dict(row))
        for path, row in content.items()
    }
    content_paths = set(references)
    authority_paths: set[str] = set()
    for row, source in (
        *((row, "parent-authority") for row in parent_authority),
        *((row, "current-authority") for row in current_authority),
    ):
        normalized = normalize(row, source)
        path = normalized["path"]
        if path in content_paths or path in authority_paths:
            raise ContractViolation(
                "Sequence 18 material partitions overlap: " + path
            )
        authority_paths.add(path)
        references[path] = normalized
    if (
        len(authority_paths)
        != O1_LIFECYCLE_TEST_CORRECTION_AUTHORITY_LEAVES
        or len(references)
        != O1_LIFECYCLE_TEST_CORRECTION_RETAINED_LEAVES
    ):
        raise ContractViolation(
            "Sequence 18 retained material union differs"
        )
    expected_floor = (
        len(references)
        + O1_LIFECYCLE_TEST_CORRECTION_PROTOCOL_ALLOWANCE
        + O1_LIFECYCLE_TEST_CORRECTION_DESCRIPTOR_RESERVE
    )
    if (
        expected_floor
        != O1_LIFECYCLE_TEST_CORRECTION_REQUIRED_SOFT_FLOOR
    ):
        raise ContractViolation(
            "Sequence 18 descriptor floor arithmetic differs"
        )
    return {
        "references": {
            path: references[path] for path in sorted(references)
        },
        "contentPaths": sorted(content_paths),
        "authorityPaths": sorted(authority_paths),
        "contentCount": len(content_paths),
        "authorityCount": len(authority_paths),
        "retainedCount": len(references),
        "requiredSoftFloor": expected_floor,
    }


def _o1_lifecycle_test_correction_runtime_boundary(
    workspace_fd: int,
    preflight: Mapping[str, Any],
) -> None:
    if (
        not isinstance(preflight, Mapping)
        or _import_sequence12_runtime_history(workspace_fd)
        != preflight.get("runtimeReceipt")
    ):
        raise ContractViolation(
            "Sequence 18 runtime receipt drifted"
        )


def _publish_o1_lifecycle_test_corrected_review(
    workspace_fd: int,
    *,
    source_root_fd: int,
    fault_after: str | None = None,
    syscalls: Any | None = None,
) -> dict[str, Any]:
    with _lifecycle_correction_global_lock(workspace_fd):
        _validate_o1_lifecycle_test_correction_rejected_paths_absent(
            workspace_fd
        )
        _validate_o1_lifecycle_test_correction_component_contract()
        _parse_o1_lifecycle_test_correction_authorization_record(
            source_root_fd
        )
        with _o1_lifecycle_test_correction_lease(
            workspace_fd
        ):
            preflight_record, preflight, current = (
                _reauthenticate_o1_lifecycle_test_correction_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            if current["state"] not in {
                "V1_INTAKE",
                "V2_REVIEW",
            }:
                raise ContractViolation(
                    "Sequence 18 publish requires V1 or V2"
                )
            packet = current["values"][1]
            intake_record = current["records"][2]
            assert isinstance(packet, dict)
            assert intake_record is not None
            material_set = (
                _o1_lifecycle_test_correction_material_refs(
                    packet,
                    preflight,
                    preflight_record,
                )
            )
            profile = preflight.get("descriptorProfile")
            _o1_lifecycle_test_correction_runtime_boundary(
                workspace_fd,
                preflight
            )
            with _historical_external_review_material_transaction(
                workspace_fd,
                source_root_fd,
                material_set["references"],
                profile,
                preflight,
                "sequence18",
            ) as retained:

                def boundary() -> None:
                    retained["reauthenticate"]()
                    _o1_lifecycle_test_correction_runtime_boundary(
                        workspace_fd,
                        preflight
                    )

                intake_payload = retained["read"](
                    O1_LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[2]
                )
                if (
                    hashlib.sha256(intake_payload).hexdigest()
                    != intake_record["sha256"]
                    or len(intake_payload) != intake_record["size"]
                ):
                    raise ContractViolation(
                        "Sequence 18 retained intake differs"
                    )
                if current["state"] == "V2_REVIEW":
                    boundary()
                    review_record = current["records"][3]
                    review_payload = current["payloads"][3]
                    assert review_record is not None
                    if (
                        review_payload != intake_payload
                        or review_record["inode"]
                        == intake_record["inode"]
                    ):
                        raise ContractViolation(
                            "Sequence 18 V2 reconcile differs"
                        )
                    boundary()
                    return {
                        "exitCode": EXIT_SUCCESS,
                        "created": False,
                        "state": "V2_REVIEW",
                        "decision": "accepted",
                        "review": _artifact_ref(review_record),
                    }
                published = _publish_external_review_payload(
                    workspace_fd,
                    O1_LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[3],
                    intake_payload,
                    fault_after=fault_after,
                    syscalls=syscalls,
                    precommit=boundary,
                    postrename_prefsync=boundary,
                    postfsync=boundary,
                    postcommit=boundary,
                )
                if published["exitCode"] != EXIT_SUCCESS:
                    return {
                        "exitCode": published["exitCode"],
                        "created": published["created"],
                    }
                if (
                    published["record"]["inode"]
                    == intake_record["inode"]
                ):
                    raise ContractViolation(
                        "Sequence 18 review aliases intake inode"
                    )
                boundary()
            reopened = (
                _classify_o1_lifecycle_test_correction_workspace(
                    workspace_fd,
                    source_root_fd,
                )
            )
            if reopened["state"] != "V2_REVIEW":
                raise ContractViolation(
                    "Sequence 18 review postcondition differs"
                )
            return {
                "exitCode": EXIT_SUCCESS,
                "created": published["created"],
                "state": "V2_REVIEW",
                "decision": "accepted",
                "review": _artifact_ref(
                    reopened["forward"]["records"][3]
                ),
            }


def _ensure_o1_lifecycle_test_correction_not_superseded() -> None:
    raise ContractViolation(
        "Sequence 18 live authority is superseded by Sequence 19"
    )


def _validate_sequence18_v1_historical_archive(
    archive_bytes: bytes,
    package: Sequence[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    if (
        not isinstance(archive_bytes, bytes)
        or not isinstance(package, Sequence)
        or isinstance(package, (str, bytes))
        or len(package)
        != len(O1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS)
    ):
        raise ContractViolation(
            "Sequence 19 parent archive inputs differ"
        )
    expected = {
        row.get("path"): dict(row)
        for row in package
        if isinstance(row, Mapping)
    }
    if (
        len(expected)
        != len(O1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS)
        or set(expected)
        != set(O1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS)
    ):
        raise ContractViolation(
            "Sequence 19 parent package inventory differs"
        )
    records: list[dict[str, Any]] = []
    try:
        with tarfile.open(
            fileobj=io.BytesIO(archive_bytes),
            mode="r:*",
        ) as archive:
            members = archive.getmembers()
            if [member.name for member in members] != list(
                O1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS
            ):
                raise ContractViolation(
                    "Sequence 19 parent PAX order differs"
                )
            for member in members:
                row = expected.get(member.name)
                if (
                    row is None
                    or not member.isfile()
                    or member.uid != 0
                    or member.gid != 0
                    or member.uname != ""
                    or member.gname != ""
                    or member.mtime != 0
                    or member.mode != 0o644
                    or member.size != row.get("size")
                ):
                    raise ContractViolation(
                        "Sequence 19 parent PAX metadata differs: "
                        + member.name
                    )
                reader = archive.extractfile(member)
                if reader is None:
                    raise ContractViolation(
                        "Sequence 19 parent PAX member is absent"
                    )
                payload = reader.read()
                digest = hashlib.sha256(payload).hexdigest()
                if (
                    len(payload) != member.size
                    or digest != row.get("sha256")
                ):
                    raise ContractViolation(
                        "Sequence 19 parent PAX payload differs: "
                        + member.name
                    )
                records.append(
                    {
                        "path": member.name,
                        "sha256": digest,
                        "size": len(payload),
                        "mode": "0644",
                    }
                )
    except ContractViolation:
        raise
    except (tarfile.TarError, OSError, EOFError) as exc:
        raise ContractViolation(
            "Sequence 19 parent PAX is unreadable"
        ) from exc
    return records


def _import_sequence18_v1_intake(
    workspace_fd: int,
    *,
    source_root_fd: int,
    require_initial: bool,
) -> dict[str, Any]:
    """Authenticate permanent Sequence 18 V1 without live rebuilding."""

    if (
        any(
            type(descriptor) is not int or descriptor < 0
            for descriptor in (workspace_fd, source_root_fd)
        )
        or type(require_initial) is not bool
    ):
        raise ContractViolation(
            "Sequence 19 parent import arguments are invalid"
        )
    records: list[dict[str, Any]] = []
    payloads: list[bytes] = []
    for index, expected in enumerate(
        V1_LIFECYCLE_TEST_CORRECTION_PARENT_REFS
    ):
        record, payload = _external_review_exact_record(
            source_root_fd if index < 6 else workspace_fd,
            expected,
            source=index < 6,
        )
        if (
            record["sha256"]
            != V1_LIFECYCLE_TEST_CORRECTION_PARENT_SHA256[index]
        ):
            raise ContractViolation(
                "Sequence 19 parent exact pin differs: "
                + expected["path"]
            )
        records.append(record)
        payloads.append(payload)
    _parse_o1_lifecycle_test_correction_authorization_record(
        source_root_fd
    )
    values: dict[int, dict[str, Any]] = {}
    for index in (7, 8, 9, 11, 12, 13, 14, 15):
        value = _strict_json_bytes(
            payloads[index],
            allow_float=True,
        )
        if (
            not isinstance(value, dict)
            or payloads[index] != _canonical_json_bytes(value)
        ):
            raise ContractViolation(
                "Sequence 19 parent JSON is noncanonical: "
                + records[index]["path"]
            )
        values[index] = value
    prechange = values[7]
    rollback = values[8]
    owner = values[9]
    bundle = values[11]
    preflight = values[12]
    report = values[13]
    packet = values[14]
    intake = values[15]
    directory_fd = _open_relative_directory_fd(
        workspace_fd,
        O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[4],
    )
    try:
        observed = os.fstat(directory_fd)
        expected_names = {
            PurePosixPath(
                O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[index]
            ).name
            for index in (5, 6, 7)
        }
        if (
            stat.S_IMODE(observed.st_mode) != 0o700
            or observed.st_uid != os.getuid()
            or observed.st_gid != os.getgid()
            or set(os.listdir(directory_fd)) != expected_names
        ):
            raise ContractViolation(
                "Sequence 19 parent Tier directory differs"
            )
    finally:
        os.close(directory_fd)
    package = prechange.get("package")
    if not isinstance(package, list):
        raise ContractViolation(
            "Sequence 19 parent package is invalid"
        )
    archive_members = _validate_sequence18_v1_historical_archive(
        payloads[10],
        package,
    )
    tier = {
        "lease": _artifact_ref(records[6]),
        "prechange": _artifact_ref(records[7]),
        "rollback": _artifact_ref(records[8]),
        "owner": _artifact_ref(records[9]),
        "archive": _artifact_ref(records[10]),
        "bundle": _artifact_ref(records[11]),
    }
    if (
        prechange.get("schemaVersion")
        != (
            "quant-radar-ui-ux-external-review-o1-lifecycle-"
            "test-correction-prechange/v1"
        )
        or prechange.get("status") != "captured"
        or prechange.get("o1LifecycleTestCorrectionId")
        != O1_LIFECYCLE_TEST_CORRECTION_ID
        or prechange.get("o1LifecycleTestTierId")
        != O1_LIFECYCLE_TEST_CORRECTION_TIER_ID
        or [row.get("path") for row in package]
        != sorted(O1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS)
        or [
            {
                key: row[key]
                for key in ("path", "sha256", "size")
            }
            for row in sorted(
                archive_members,
                key=lambda item: item["path"],
            )
        ]
        != package
        or rollback.get("status") != "ready"
        or rollback.get("prechange") != tier["prechange"]
        or rollback.get("bundleManifest") != tier["bundle"]
        or rollback.get("destructiveGitAllowed") is not False
        or owner.get("o1LifecycleTestCorrectionId")
        != O1_LIFECYCLE_TEST_CORRECTION_ID
        or bundle.get("status") != "sealed"
        or bundle.get("archive") != tier["archive"]
    ):
        raise ContractViolation(
            "Sequence 19 parent Tier semantics differ"
        )
    source_projection = _source_projection_value(
        preflight.get("sourceProjection", {}).get(
            "schemaVersion",
            "",
        ),
        preflight.get("sourceProjection", {}).get(
            "policy",
            {},
        ).get("include", ()),
        preflight.get("sourceProjection", {}).get(
            "policy",
            {},
        ).get("exclude", ()),
        preflight.get("sourceProjection", {}).get(
            "records",
            (),
        ),
        digest=preflight.get("sourceProjection", {}).get("digest"),
    )
    supplemental_projection = _source_projection_value(
        preflight.get("supplementalProjection", {}).get(
            "schemaVersion",
            "",
        ),
        preflight.get("supplementalProjection", {}).get(
            "policy",
            {},
        ).get("include", ()),
        preflight.get("supplementalProjection", {}).get(
            "policy",
            {},
        ).get("exclude", ()),
        preflight.get("supplementalProjection", {}).get(
            "records",
            (),
        ),
        digest=preflight.get("supplementalProjection", {}).get(
            "digest"
        ),
    )
    if (
        preflight.get("schemaVersion")
        != (
            "quant-radar-ui-ux-external-review-o1-lifecycle-"
            "test-correction-preflight/v1"
        )
        or preflight.get("status") != "passed"
        or preflight.get("o1LifecycleTestCorrectionId")
        != O1_LIFECYCLE_TEST_CORRECTION_ID
        or preflight.get("o1LifecycleTestTierId")
        != O1_LIFECYCLE_TEST_CORRECTION_TIER_ID
        or preflight.get("tier") != tier
        or preflight.get("initialState") != "V1_INTAKE"
        or preflight.get("formalPause") != "V2_REVIEW"
        or preflight.get("candidateForbidden") is not True
        or preflight.get("rootForbidden") is not True
        or len(source_projection["records"]) != 270
        or len(supplemental_projection["records"]) != 73
        or intake.get("status") != "accepted"
        or intake.get("decision") != "accepted"
    ):
        raise ContractViolation(
            "Sequence 19 parent V1 semantics differ"
        )
    _validate_review_packet_value(packet)
    parent_o1 = _import_sequence17_o1_intake(
        workspace_fd,
        source_root_fd=source_root_fd,
        require_initial=False,
    )
    parent_authority_indexes = (3, 4, 5, 6, 7, 8, 9, 11, 12)
    parent_authorities = [
        copy.deepcopy(
            dict(O1_LIFECYCLE_TEST_CORRECTION_PARENT_REFS[index])
        )
        for index in parent_authority_indexes
    ]
    current_authorities = [
        copy.deepcopy(dict(records[index]))
        for index in (6, 7, 8, 9, 10, 11, 12)
    ]
    authority_refs = [
        _artifact_ref(record)
        for record in (*parent_authorities, *current_authorities)
    ]
    if len(authority_refs) != 16:
        raise ContractViolation(
            "Sequence 19 parent authority count differs"
        )
    if require_initial:
        if _relative_leaf_lstat(
            workspace_fd,
            O1_LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[3],
        ) is not None:
            raise ContractViolation(
                "Sequence 19 parent manual review must initially be absent"
            )
        for relative in V1_LIFECYCLE_TEST_CORRECTION_FORMAL_PATHS:
            if _relative_leaf_lstat(
                workspace_fd,
                relative,
            ) is not None:
                raise ContractViolation(
                    "Sequence 19 formal path must initially be absent: "
                    + relative
                )
    for relative in O1_LIFECYCLE_TEST_CORRECTION_FORWARD_PATHS[4:]:
        if _relative_leaf_lstat(workspace_fd, relative) is not None:
            raise ContractViolation(
                "Sequence 19 candidate/root authority is forbidden"
            )
    return {
        "classification": "S18_V1_INTAKE",
        "authorization": _artifact_ref(records[4]),
        "authorities": authority_refs,
        "preflight": _artifact_ref(records[12]),
        "archive": _artifact_ref(records[10]),
        "report": _artifact_ref(records[13]),
        "packet": _artifact_ref(records[14]),
        "intake": _artifact_ref(records[15]),
        "reportValue": copy.deepcopy(report),
        "packetValue": copy.deepcopy(packet),
        "intakeValue": copy.deepcopy(intake),
        "intakeBytes": payloads[15],
        "decision": "accepted",
        "preflightValue": copy.deepcopy(preflight),
        "sourceProjection": copy.deepcopy(source_projection),
        "supplementalProjection": copy.deepcopy(
            supplemental_projection
        ),
        "runtimeReceipt": copy.deepcopy(preflight["runtimeReceipt"]),
        "parentO1": parent_o1,
    }


def _classify_sequence18_historical_v1_workspace(
    workspace_fd: int,
    source_root_fd: int,
) -> dict[str, Any]:
    """Read the exact permanent V1 after its live source was superseded."""

    parent_v1 = _import_sequence18_v1_intake(
        workspace_fd,
        source_root_fd=source_root_fd,
        require_initial=False,
    )
    expected_tier = (
        V1_LIFECYCLE_TEST_CORRECTION_PARENT_REFS[6:13]
    )
    tier_paths = (
        O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[1],
        O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[2],
        O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[3],
        O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[5],
        O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[6],
        O1_LIFECYCLE_TEST_CORRECTION_TIER_DESTINATIONS[7],
        O1_LIFECYCLE_TEST_CORRECTION_PREFLIGHT_PATH,
    )
    if tuple(row["path"] for row in expected_tier) != tier_paths:
        raise ContractViolation(
            "Sequence 18 historical Tier paths differ"
        )
    for expected in expected_tier:
        _external_review_exact_record(
            workspace_fd,
            expected,
            source=False,
        )
    forward = _classify_v1_lifecycle_test_correction_forward(
        workspace_fd,
        parent_v1,
    )
    state = {
        "W1_READY": "V1_INTAKE",
        "W2_REVIEW": "V2_REVIEW",
    }.get(forward["state"])
    if state is None:
        raise ContractViolation(
            "Sequence 18 historical forward state differs"
        )
    return {
        "state": state,
        "tierPresence": [True] * 8,
        "preflight": copy.deepcopy(parent_v1["preflight"]),
        "forward": {
            **forward,
            "state": state,
        },
        "historicalImport": "S18_V1_INTAKE",
    }


