def _v1_lifecycle_test_correction_authorization_document_bytes(
) -> bytes:
    body = _canonical_json_bytes(
        _v1_lifecycle_test_correction_authorization_body()
    ).decode("utf-8")
    return (
        "# Quant Radar UX-1B Sequence 19 Post-V1 Lifecycle-Test "
        "Correction Continuation Authorization\n\n"
        + V1_LIFECYCLE_TEST_CORRECTION_AUTH_START.decode("ascii")
        + body
        + V1_LIFECYCLE_TEST_CORRECTION_AUTH_END.decode("ascii")
        + "\n"
    ).encode("utf-8")


def _v1_lifecycle_source_file_record(
    source_root_fd: int,
    relative: str,
) -> tuple[dict[str, Any], bytes]:
    if (
        relative
        == V1_LIFECYCLE_TEST_CORRECTION_AUTHORIZATION_DOCUMENT_PATH
        and _relative_leaf_lstat(source_root_fd, relative) is None
    ):
        payload = (
            _v1_lifecycle_test_correction_authorization_document_bytes()
        )
        return (
            {
                "path": relative,
                "sha256": hashlib.sha256(payload).hexdigest(),
                "size": len(payload),
                "mode": "0644",
                "uid": os.getuid(),
                "gid": os.getgid(),
                "nlink": 1,
            },
            payload,
        )
    return _source_file_record(source_root_fd, relative)


def _parse_v1_lifecycle_test_correction_authorization_record(
    source_root_fd: int,
) -> dict[str, Any]:
    record, document = _source_file_record(
        source_root_fd,
        V1_LIFECYCLE_TEST_CORRECTION_AUTHORIZATION_DOCUMENT_PATH,
    )
    if (
        record["mode"] != "0644"
        or record["uid"] != os.getuid()
        or record["gid"] != os.getgid()
        or record["nlink"] != 1
        or document
        != _v1_lifecycle_test_correction_authorization_document_bytes()
        or document.count(
            V1_LIFECYCLE_TEST_CORRECTION_AUTH_GENERIC
        )
        != 3
    ):
        raise ContractViolation(
            "Sequence 19 authorization document differs"
        )
    for expected in (
        V1_LIFECYCLE_TEST_CORRECTION_PLAN_REF,
        V1_LIFECYCLE_TEST_CORRECTION_LEDGER_REF,
        *V1_LIFECYCLE_TEST_CORRECTION_RETAINED_REFS,
    ):
        observed, _ = _source_file_record(
            source_root_fd,
            expected["path"],
        )
        if {
            key: observed[key]
            for key in ("path", "sha256", "size", "mode")
        } != expected:
            raise ContractViolation(
                "Sequence 19 authority drifted: "
                + expected["path"]
            )
    return _v1_lifecycle_test_correction_authorization_body()


def _v1_lifecycle_test_correction_authorization_binding(
    source_root_fd: int,
) -> dict[str, Any]:
    body = _parse_v1_lifecycle_test_correction_authorization_record(
        source_root_fd
    )
    record, _ = _source_file_record(
        source_root_fd,
        V1_LIFECYCLE_TEST_CORRECTION_AUTHORIZATION_DOCUMENT_PATH,
    )
    return {
        **_artifact_ref(record),
        "bodySha256": hashlib.sha256(
            _canonical_json_bytes(body)
        ).hexdigest(),
    }


def _build_v1_lifecycle_test_correction_source_projections(
    source_root_fd: int,
) -> dict[str, Any]:
    base = _build_o1_lifecycle_test_correction_source_projections(
        source_root_fd
    )
    return _build_v1_lifecycle_test_correction_source_projections_from_base(
        source_root_fd,
        base,
    )


def _build_v1_lifecycle_test_correction_source_projections_history(
    source_root_fd: int,
) -> dict[str, Any]:
    base = _import_later_source_projections_history(
        source_root_fd,
        "sequence18",
    )
    return _build_v1_lifecycle_test_correction_source_projections_from_base(
        source_root_fd,
        base,
    )


def _build_v1_lifecycle_test_correction_source_projections_from_base(
    source_root_fd: int,
    base: Mapping[str, Any],
) -> dict[str, Any]:
    mirror = base["sourceProjection"]
    mirror_paths = {row["path"] for row in mirror["records"]}
    records = {
        row["path"]: copy.deepcopy(row)
        for row in base["supplementalProjection"]["records"]
    }
    for relative in V1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS:
        if relative in mirror_paths:
            continue
        record, _ = _v1_lifecycle_source_file_record(
            source_root_fd,
            relative,
        )
        records[relative] = {
            "path": relative,
            "sha256": record["sha256"],
            "size": record["size"],
            "mode": (
                "0555"
                if int(record["mode"], 8) & 0o111
                else "0444"
            ),
        }
    paths = sorted(records)
    projection = _source_projection_value(
        "quant-radar-ui-ux-supplemental-source/v1",
        paths,
        mirror["policy"]["include"],
        [records[path] for path in paths],
    )
    if (
        len(mirror["records"])
        != V1_LIFECYCLE_TEST_CORRECTION_SOURCE_COUNT
        or len(projection["records"])
        != V1_LIFECYCLE_TEST_CORRECTION_SUPPLEMENTAL_COUNT
    ):
        raise ContractViolation(
            "Sequence 19 source projection counts differ"
        )
    return {
        "sourceProjection": mirror,
        "supplementalProjection": projection,
    }


def _v1_lifecycle_test_correction_archive_bytes(
    source_root_fd: int,
) -> tuple[bytes, list[dict[str, Any]]]:
    output = io.BytesIO()
    records: list[dict[str, Any]] = []
    with tarfile.open(
        fileobj=output,
        mode="w",
        format=tarfile.PAX_FORMAT,
    ) as archive:
        for relative in V1_LIFECYCLE_TEST_CORRECTION_PACKAGE_PATHS:
            record, payload = _v1_lifecycle_source_file_record(
                source_root_fd,
                relative,
            )
            records.append(record)
            member = tarfile.TarInfo(relative)
            member.size = len(payload)
            member.mode = 0o644
            member.uid = 0
            member.gid = 0
            member.uname = ""
            member.gname = ""
            member.mtime = 0
            archive.addfile(member, io.BytesIO(payload))
    return output.getvalue(), records


def _v1_lifecycle_test_correction_make_contract(
    source_root_fd: int,
) -> dict[str, Any]:
    record, payload = _source_file_record(source_root_fd, "Makefile")
    targets = (
        "ui-ux1b-external-review-v1-lifecycle-test-bootstrap",
        "ui-ux1b-external-review-v1-lifecycle-test-preflight",
        "ui-ux1b-external-review-v1-lifecycle-test-verify",
        "ui-ux1b-external-review-v1-lifecycle-test-publish",
    )
    text = payload.decode("utf-8", errors="strict")
    if any(text.count(target + ":") != 1 for target in targets):
        raise ContractViolation(
            "Sequence 19 Make contract differs"
        )
    return {
        "artifact": _artifact_ref(record),
        "targets": list(targets),
        "targetsSha256": hashlib.sha256(
            _canonical_json_bytes(list(targets))
        ).hexdigest(),
    }


