def _verify_frozen_authority_contract(
    workspace_fd: int,
    *,
    source_root_fd: int,
    authority_contract: dict[str, Any],
) -> dict[str, Any]:
    if any(type(fd) is not int or fd < 0 for fd in (workspace_fd, source_root_fd)):
        raise ContractViolation("frozen authority descriptors are invalid")
    workspace_stat = os.fstat(workspace_fd)
    named_workspace = os.lstat(WORKSPACE_ROOT)
    if (
        not stat.S_ISDIR(workspace_stat.st_mode)
        or (workspace_stat.st_dev, workspace_stat.st_ino)
        != (named_workspace.st_dev, named_workspace.st_ino)
        or not stat.S_ISDIR(os.fstat(source_root_fd).st_mode)
    ):
        raise ContractViolation("frozen authority descriptor binding is invalid")
    if not isinstance(authority_contract, dict) or set(authority_contract) != {"relative", "absolute"}:
        raise ContractViolation("frozen authority contract keys are not closed")
    relative = authority_contract["relative"]
    absolute = authority_contract["absolute"]
    if not isinstance(relative, list) or len(relative) != 5 or not isinstance(absolute, list) or len(absolute) != 5:
        raise ContractViolation("frozen authority contract cardinality mismatch")

    def validate_contract_row(row: Any, path_key: str, label: str) -> None:
        if not isinstance(row, dict) or set(row) != {path_key, "sha256", "size", "mode"}:
            raise ContractViolation(f"{label} keys are not closed")
        path = row[path_key]
        if (
            not isinstance(path, str)
            or (path_key == "path" and not _is_safe_relative_path(path))
            or (path_key == "absolutePath" and (not path.startswith("/") or "\0" in path))
            or not isinstance(row["sha256"], str)
            or re.fullmatch(r"[0-9a-f]{64}", row["sha256"]) is None
            or type(row["size"]) is not int
            or row["size"] < 0
            or not isinstance(row["mode"], str)
            or re.fullmatch(r"[0-7]{4}", row["mode"]) is None
        ):
            raise ContractViolation(f"{label} is invalid")

    def stream_record(row: dict[str, Any], *, relative_path: bool) -> tuple[dict[str, Any], bytes | None]:
        path_key = "path" if relative_path else "absolutePath"
        validate_contract_row(row, path_key, "relative authority" if relative_path else "absolute authority")
        flags = os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0)
        try:
            fd = (
                os.open(row[path_key], flags, dir_fd=source_root_fd)
                if relative_path
                else os.open(row[path_key], flags)
            )
        except OSError as exc:
            raise ContractViolation(f"frozen authority unavailable: {row[path_key]}") from exc
        try:
            observed = os.fstat(fd)
            if (
                not stat.S_ISREG(observed.st_mode)
                or observed.st_nlink != 1
                or observed.st_size != row["size"]
                or f"{stat.S_IMODE(observed.st_mode):04o}" != row["mode"]
            ):
                raise ContractViolation(f"frozen authority metadata mismatch: {row[path_key]}")
            digest = hashlib.sha256()
            retained: list[bytes] | None = [] if row["size"] <= 1_048_576 else None
            total = 0
            while chunk := os.read(fd, 1_048_576):
                total += len(chunk)
                digest.update(chunk)
                if retained is not None:
                    retained.append(chunk)
            if total != row["size"] or digest.hexdigest() != row["sha256"]:
                raise ContractViolation(f"frozen authority content mismatch: {row[path_key]}")
            record = {
                path_key: row[path_key],
                "sha256": digest.hexdigest(),
                "size": total,
                "mode": f"{stat.S_IMODE(observed.st_mode):04o}",
                "uid": observed.st_uid,
                "gid": observed.st_gid,
                "device": observed.st_dev,
                "inode": observed.st_ino,
                "nlink": observed.st_nlink,
            }
            return record, None if retained is None else b"".join(retained)
        finally:
            os.close(fd)

    relative_records: list[dict[str, Any]] = []
    retained_relative: dict[str, bytes] = {}
    for row in relative:
        record, payload = stream_record(row, relative_path=True)
        relative_records.append(record)
        if payload is not None:
            retained_relative[row["path"]] = payload
    absolute_records = [stream_record(row, relative_path=False)[0] for row in absolute]

    manifest_keys = {
        "attestations", "captureStackContract", "captureStackDigest",
        "capturedCount", "captures", "childrenQuiescent", "expectedCaptureCount",
        "fixtureEntrypoint", "mode", "mutatorCounters", "network", "phase",
        "processes", "prohibitedCounters", "providerCounters", "runId",
        "schemaVersion", "sourceDigestEnd", "sourceDigestStart", "status",
    }
    process_row_keys = {
        "launchIdentitySha256", "processId", "quiescent", "returnCode",
        "role", "sessionId", "signal",
    }

    def valid_digest(value: Any) -> bool:
        return (
            isinstance(value, str)
            and re.fullmatch(r"[0-9a-f]{64}", value) is not None
            and value != "0" * 64
        )

    def manifest_binding(row: dict[str, Any], kind: str) -> dict[str, Any]:
        raw = retained_relative.get(row["path"])
        if raw is None:
            raise ContractViolation("frozen manifest was not retained")
        try:
            manifest = json.loads(raw)
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise ContractViolation("frozen manifest JSON is invalid") from exc
        canonical = _canonical_json_bytes(manifest)
        if raw not in {canonical, canonical + b"\n"} or not isinstance(manifest, dict) or set(manifest) != manifest_keys:
            raise ContractViolation("frozen manifest encoding/keys mismatch")
        expected_mode, expected_fixture, expected_count = (
            ("ux1b-full-pages", "scripts/ui_ux_fixture_app.py", 81)
            if kind == "pages"
            else ("ux1b-selection-controls", "scripts/ui_ux_selection_fixture_app.py", 36)
        )
        if (
            manifest.get("schemaVersion") != "quant-radar-ui-ux-evidence/v1"
            or manifest.get("status") != "passed"
            or manifest.get("mode") != expected_mode
            or manifest.get("fixtureEntrypoint") != expected_fixture
            or manifest.get("phase") != "precontrol"
            or manifest.get("childrenQuiescent") is not True
            or manifest.get("sourceDigestStart") != HISTORICAL_SOURCE_SHA256
            or manifest.get("sourceDigestEnd") != HISTORICAL_SOURCE_SHA256
            or manifest.get("expectedCaptureCount") != expected_count
            or manifest.get("capturedCount") != expected_count
        ):
            raise ContractViolation("frozen manifest lifecycle fields mismatch")
        captures = manifest.get("captures")
        if not isinstance(captures, list):
            raise ContractViolation("frozen manifest captures are invalid")
        capture_ids = [capture.get("id") for capture in captures if isinstance(capture, dict)]
        if (
            len(capture_ids) != expected_count
            or capture_ids != sorted(capture_ids)
            or len(set(capture_ids)) != expected_count
        ):
            raise ContractViolation("frozen manifest capture order/set mismatch")
        artifact_claims: list[dict[str, Any]] = []
        for capture in captures:
            if (
                not isinstance(capture, dict)
                or set(capture) != {"id", "status", "artifacts"}
                or capture["status"] != "passed"
                or not isinstance(capture["artifacts"], dict)
                or set(capture["artifacts"]) != {"png", "renderSidecar"}
            ):
                raise ContractViolation("frozen capture row is invalid")
            artifact_claims.append(
                {"id": capture["id"], "artifacts": copy.deepcopy(capture["artifacts"])}
            )
        processes = manifest.get("processes")
        if not isinstance(processes, dict) or set(processes) != {"app", "browsers", "attestationDigests"}:
            raise ContractViolation("frozen process receipt keys mismatch")
        app = processes["app"]
        if (
            not isinstance(app, dict)
            or set(app) != process_row_keys
            or app.get("role") != "app"
            or app.get("sessionId") != manifest.get("runId")
            or app.get("processId")
            != {
                "scripts/ui_ux_fixture_app.py": "app/full-pages",
                "scripts/ui_ux_selection_fixture_app.py": "app/selection-controls",
            }[expected_fixture]
            or not valid_digest(app.get("launchIdentitySha256"))
            or app.get("quiescent") is not True
            or app.get("returnCode") != 0
            or app.get("signal") is not None
        ):
            raise ContractViolation("frozen app process receipt is invalid")
        browsers = processes["browsers"]
        attestations = processes["attestationDigests"]
        if (
            not isinstance(browsers, dict)
            or list(browsers) != capture_ids
            or not isinstance(attestations, dict)
            or set(attestations) != {"app", "browsers"}
            or not valid_digest(attestations.get("app"))
            or not isinstance(attestations.get("browsers"), dict)
            or set(attestations["browsers"]) != set(capture_ids)
        ):
            raise ContractViolation("frozen browser attestation set is invalid")
        for capture_id in capture_ids:
            browser = browsers[capture_id]
            if (
                not isinstance(browser, dict)
                or set(browser) != process_row_keys
                or browser.get("processId") != capture_id
                or browser.get("role") != "browser"
                or browser.get("sessionId") != manifest.get("runId")
                or not valid_digest(browser.get("launchIdentitySha256"))
                or browser.get("quiescent") is not True
                or browser.get("returnCode") != 0
                or browser.get("signal") is not None
                or not valid_digest(attestations["browsers"].get(capture_id))
            ):
                raise ContractViolation("frozen browser process receipt is invalid")
        return {
            "manifest": relative_records[relative.index(row)],
            "captureCount": len(capture_ids),
            "artifactCount": sum(len(capture["artifacts"]) for capture in captures),
            "namespaceLeafCount": sum(len(capture["artifacts"]) for capture in captures) + 1,
            "childrenQuiescent": True,
            "captureIdsSha256": hashlib.sha256(
                b"quant-radar-ui-ux-frozen-capture-ids/v1\0"
                + _canonical_json_bytes(capture_ids)
            ).hexdigest(),
            "artifactClaimsSha256": hashlib.sha256(
                b"quant-radar-ui-ux-frozen-artifact-claims/v1\0"
                + _canonical_json_bytes(artifact_claims)
            ).hexdigest(),
            "processReceiptsSha256": hashlib.sha256(
                b"quant-radar-ui-ux-frozen-process-receipts/v1\0"
                + _canonical_json_bytes(processes)
            ).hexdigest(),
            "attestationDigestsSha256": hashlib.sha256(
                b"quant-radar-ui-ux-frozen-attestation-digests/v1\0"
                + _canonical_json_bytes(attestations)
            ).hexdigest(),
        }

    if "precontrol-pages-" not in relative[1]["path"] or "precontrol-controls-" not in relative[2]["path"]:
        raise ContractViolation("frozen manifest roles are not in the closed order")
    inner_manifests = {
        "pages": manifest_binding(relative[1], "pages"),
        "controls": manifest_binding(relative[2], "controls"),
    }
    stack_raw = retained_relative.get(relative[0]["path"])
    if stack_raw is None:
        raise ContractViolation("capture-stack contract was not retained")
    try:
        stack = json.loads(stack_raw)
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ContractViolation("capture-stack contract JSON is invalid") from exc
    if not isinstance(stack, dict) or not isinstance(stack.get("members"), list):
        raise ContractViolation("capture-stack contract members are invalid")
    authority_payload = {
        "relativeAuthorities": relative_records,
        "absoluteAuthorities": absolute_records,
        "innerManifests": inner_manifests,
    }
    return {
        "captureStackMembers": len(stack["members"]),
        "pageCaptures": inner_manifests["pages"]["captureCount"],
        "pageArtifacts": inner_manifests["pages"]["artifactCount"],
        "controlCaptures": inner_manifests["controls"]["captureCount"],
        "controlArtifacts": inner_manifests["controls"]["artifactCount"],
        "protectedBehaviorChanged": False,
        "processesQuiescent": True,
        "captureProcessFamily": "outer_pgid",
        "candidateProcessFamily": "token_pgid",
        "candidateHeadlessShellInCaptureRuntime": False,
        **authority_payload,
        "authoritySetSha256": hashlib.sha256(
            b"quant-radar-ui-ux-frozen-authority-set/v1\0"
            + _canonical_json_bytes(authority_payload)
        ).hexdigest(),
    }


def _classify_abnormal_capture(
    workspace_fd: int,
    state: dict[str, Any],
) -> dict[str, Any]:
    if type(workspace_fd) is not int or workspace_fd < 0 or not stat.S_ISDIR(os.fstat(workspace_fd).st_mode):
        raise ContractViolation("abnormal capture workspace descriptor is invalid")
    if not isinstance(state, dict) or set(state) != {"outcome", "ownerInterrupted", "cleanupReceipt"}:
        raise ContractViolation("abnormal capture state keys are not closed")
    allowed = {
        "signaled": (True, True, EXIT_INTERRUPTED),
        "timed_out": (False, True, EXIT_MANUAL),
        "output_overflow": (False, True, EXIT_MANUAL),
        "owner_lost": (False, False, EXIT_MANUAL),
    }
    outcome = state.get("outcome")
    if outcome not in allowed:
        raise ContractViolation("abnormal capture outcome is invalid")
    interrupted, cleanup, exit_code = allowed[outcome]
    if state.get("ownerInterrupted") is not interrupted or state.get("cleanupReceipt") is not cleanup:
        raise ContractViolation("abnormal capture state combination is invalid")
    return {
        "exitCode": exit_code,
        "lineageBurned": True,
        "freshGrant": False,
        "runnerReceipt": None,
        "claimsInnerQuiescence": False,
        "manualAuditRequired": True,
    }


def _validate_traceability_v3_ledger(
    ledger_bytes: bytes,
    plan_bytes: bytes,
    *,
    plan_ref: Mapping[str, Any],
    ledger_ref: Mapping[str, Any],
    expected_ids: Mapping[str, set[str]],
) -> dict[str, Any]:
    """Validate one exact v3 ledger and its bidirectional graph."""

    if (
        not isinstance(ledger_bytes, bytes)
        or not isinstance(plan_bytes, bytes)
        or set(plan_ref) != {"path", "sha256", "size"}
        or set(ledger_ref) != {"path", "sha256", "size"}
        or set(expected_ids)
        != {"requirements", "acceptance", "implementation", "tests"}
    ):
        raise ContractViolation("traceability inputs must be bytes")
    if (
        len(plan_bytes) != plan_ref["size"]
        or hashlib.sha256(plan_bytes).hexdigest()
        != plan_ref["sha256"]
        or not ledger_bytes.endswith(b"\n")
        or ledger_bytes.endswith(b"\n\n")
        or len(ledger_bytes) != ledger_ref["size"]
        or hashlib.sha256(ledger_bytes).hexdigest()
        != ledger_ref["sha256"]
    ):
        raise ContractViolation(
            "traceability bytes differ from the authorized package"
        )
    ledger = _strict_json_bytes(ledger_bytes[:-1])
    if (
        not isinstance(ledger, dict)
        or _canonical_json_bytes(ledger) + b"\n" != ledger_bytes
        or set(ledger)
        != {
            "schemaVersion",
            "status",
            "implementationStatus",
            "testExecution",
            "plan",
            "requirements",
            "acceptance",
            "implementation",
            "tests",
            "coverageBasisPoints",
            "gaps",
            "orphans",
        }
        or ledger.get("schemaVersion")
        != "quant-radar-ui-ux-traceability/v3"
        or ledger.get("status") != "NOT_TESTED"
        or ledger.get("implementationStatus") != "NOT_STARTED"
        or ledger.get("testExecution")
        != {"executedAt": None, "results": [], "status": "NOT_RUN"}
        or ledger.get("plan") != plan_ref
        or ledger.get("coverageBasisPoints") != 10_000
        or ledger.get("gaps") != []
        or ledger.get("orphans") != []
    ):
        raise ContractViolation("traceability v3 envelope differs")

    collections = {
        "requirements": ("acceptance", "implementation", "tests"),
        "acceptance": ("requirements", "implementation", "tests"),
        "implementation": ("requirements", "acceptance", "tests"),
        "tests": ("requirements", "acceptance", "implementation"),
    }
    indexed: dict[str, dict[str, dict[str, Any]]] = {}
    for collection, edge_fields in collections.items():
        rows = ledger.get(collection)
        if (
            not isinstance(rows, list)
            or len(rows) != len(expected_ids[collection])
        ):
            raise ContractViolation(
                f"traceability {collection} cardinality differs"
            )
        by_id: dict[str, dict[str, Any]] = {}
        for row in rows:
            if (
                not isinstance(row, dict)
                or set(row) != {"id", *edge_fields}
                or row.get("id") in by_id
            ):
                raise ContractViolation(
                    f"traceability {collection} row differs"
                )
            for field in edge_fields:
                values = row.get(field)
                if (
                    not isinstance(values, list)
                    or values != sorted(set(values))
                    or any(
                        not isinstance(value, str)
                        for value in values
                    )
                ):
                    raise ContractViolation(
                        f"traceability {collection}.{field} differs"
                    )
            by_id[row["id"]] = row
        if set(by_id) != expected_ids[collection]:
            raise ContractViolation(
                f"traceability {collection} identity set differs"
            )
        indexed[collection] = by_id

    for source_collection, edge_fields in collections.items():
        for source_id, row in indexed[source_collection].items():
            for target_collection in edge_fields:
                for target_id in row[target_collection]:
                    target = indexed[target_collection].get(target_id)
                    if (
                        target is None
                        or source_id not in target[source_collection]
                    ):
                        raise ContractViolation(
                            "traceability graph is not bidirectional"
                        )
    return {
        "requirements": len(expected_ids["requirements"]),
        "acceptance": len(expected_ids["acceptance"]),
        "implementation": len(expected_ids["implementation"]),
        "tests": len(expected_ids["tests"]),
        "edgeFamilies": 12,
        "coverageBasisPoints": 10_000,
        "gaps": [],
        "orphans": [],
    }


def _validate_traceability_ledger(
    ledger_bytes: bytes,
    plan_bytes: bytes,
) -> dict[str, Any]:
    """Validate the exact Sequence 8 ledger."""

    return _validate_traceability_v3_ledger(
        ledger_bytes,
        plan_bytes,
        plan_ref=AUTHORIZED_PLAN_REF,
        ledger_ref=AUTHORIZED_LEDGER_REF,
        expected_ids={
            "requirements": {
                "REQ-008",
                "CFR-021",
                "CFR-022",
                "CFR-023",
                "CFR-024",
                "CFR-025",
            },
            "acceptance": {
                f"AC-SEQ8-{index:03d}" for index in range(1, 8)
            },
            "implementation": {
                f"IMPL-{index:03d}" for index in range(40, 48)
            },
            "tests": {
                f"TEST-{index:03d}" for index in range(58, 67)
            },
        },
    )


