def _validate_sequence2_traceability_ledger(
    ledger_bytes: bytes,
    plan_bytes: bytes,
) -> dict[str, Any]:
    if not isinstance(ledger_bytes, bytes) or not isinstance(plan_bytes, bytes):
        raise ContractViolation("traceability inputs must be bytes")
    if (
        len(plan_bytes) != SEQUENCE2_PLAN_REF["size"]
        or hashlib.sha256(plan_bytes).hexdigest()
        != SEQUENCE2_PLAN_REF["sha256"]
    ):
        raise ContractViolation("traceability amendment binding mismatch")
    if not ledger_bytes.endswith(b"\n") or ledger_bytes.endswith(b"\n\n"):
        raise ContractViolation("traceability ledger requires exactly one final LF")
    body = ledger_bytes[:-1]
    ledger = _strict_json_bytes(body)
    if (
        not isinstance(ledger, dict)
        or _canonical_json_bytes(ledger) + b"\n" != ledger_bytes
        or len(ledger_bytes) != SEQUENCE2_LEDGER_REF["size"]
        or hashlib.sha256(ledger_bytes).hexdigest()
        != SEQUENCE2_LEDGER_REF["sha256"]
    ):
        raise ContractViolation(
            "traceability ledger bytes differ from the authorized package"
        )

    acceptance_source = (
        (
            "AC-COMPAT-001",
            ("REQ-001",),
            ("IMPL-002", "IMPL-003"),
            ("TEST-001", "TEST-002"),
        ),
        (
            "AC-COMPAT-002",
            ("CFR-001", "REQ-001"),
            ("IMPL-002", "IMPL-004"),
            ("TEST-002",),
        ),
        (
            "AC-COMPAT-003",
            ("CFR-001",),
            ("IMPL-004",),
            ("TEST-003",),
        ),
        (
            "AC-COMPAT-004",
            ("CFR-002",),
            ("IMPL-003", "IMPL-005"),
            ("TEST-004", "TEST-006"),
        ),
        (
            "AC-COMPAT-005",
            ("CFR-003",),
            ("IMPL-005", "IMPL-006"),
            ("TEST-005", "TEST-006"),
        ),
        (
            "AC-COMPAT-006",
            ("CFR-002",),
            ("IMPL-001", "IMPL-003", "IMPL-005"),
            ("TEST-001", "TEST-006"),
        ),
    )
    acceptance = [
        {
            "id": identifier,
            "requirements": list(requirements),
            "implementation": list(implementation),
            "tests": list(tests),
        }
        for identifier, requirements, implementation, tests in acceptance_source
    ]

    def derive(
        collection: str,
        identifier: str,
        fields: tuple[str, ...],
    ) -> dict[str, Any]:
        selected = [
            row for row in acceptance if identifier in row[collection]
        ]
        result: dict[str, Any] = {
            "id": identifier,
            "acceptance": [row["id"] for row in selected],
        }
        for field in fields:
            result[field] = sorted(
                {value for row in selected for value in row[field]}
            )
        return result

    requirement_ids = ("CFR-001", "CFR-002", "CFR-003", "REQ-001")
    implementation_ids = tuple(
        f"IMPL-{index:03d}" for index in range(1, 7)
    )
    test_ids = tuple(f"TEST-{index:03d}" for index in range(1, 7))
    requirements = [
        derive("requirements", identifier, ("implementation", "tests"))
        for identifier in requirement_ids
    ]
    implementation = [
        derive("implementation", identifier, ("requirements", "tests"))
        for identifier in implementation_ids
    ]
    tests: list[dict[str, Any]] = []
    for identifier in test_ids:
        selected = [
            row for row in acceptance if identifier in row["tests"]
        ]
        tests.append(
            {
                "id": identifier,
                "requirements": sorted(
                    {
                        value
                        for row in selected
                        for value in row["requirements"]
                    }
                ),
                "acceptance": [row["id"] for row in selected],
                "implementation": sorted(
                    {
                        value
                        for row in selected
                        for value in row["implementation"]
                    }
                ),
            }
        )
    expected = {
        "schemaVersion": "quant-radar-ui-ux-traceability/v3",
        "status": "NOT_TESTED",
        "implementationStatus": "NOT_STARTED",
        "testExecution": {
            "executedAt": None,
            "results": [],
            "status": "NOT_RUN",
        },
        "plan": dict(SEQUENCE2_PLAN_REF),
        "requirements": requirements,
        "acceptance": acceptance,
        "implementation": implementation,
        "tests": tests,
        "coverageBasisPoints": 10_000,
        "gaps": [],
        "orphans": [],
    }
    if ledger != expected:
        raise ContractViolation("traceability v3 graph differs")
    return {
        "requirements": 4,
        "acceptance": 6,
        "implementation": 6,
        "tests": 6,
        "edgeFamilies": 6,
        "coverageBasisPoints": 10_000,
        "gaps": [],
        "orphans": [],
    }


def _validate_parent_traceability_ledger(
    ledger_bytes: bytes,
    plan_bytes: bytes,
) -> dict[str, Any]:
    if not isinstance(ledger_bytes, bytes) or not isinstance(plan_bytes, bytes):
        raise ContractViolation("traceability inputs must be bytes")
    if (
        len(plan_bytes) != PARENT_PLAN_REF["size"]
        or hashlib.sha256(plan_bytes).hexdigest() != PARENT_PLAN_REF["sha256"]
    ):
        raise ContractViolation("traceability plan binding mismatch")
    if not ledger_bytes.endswith(b"\n") or ledger_bytes.endswith(b"\n\n"):
        raise ContractViolation("traceability ledger requires exactly one final LF")
    body = ledger_bytes[:-1]
    ledger = _strict_json_bytes(body)
    if not isinstance(ledger, dict) or _canonical_json_bytes(ledger) + b"\n" != ledger_bytes:
        raise ContractViolation("traceability ledger is not canonical JSON plus LF")
    if (
        len(ledger_bytes) != PARENT_LEDGER_REF["size"]
        or hashlib.sha256(ledger_bytes).hexdigest() != PARENT_LEDGER_REF["sha256"]
    ):
        raise ContractViolation("traceability ledger bytes differ from the authorized package")

    top_keys = {
        "schemaVersion", "status", "implementationStatus", "testExecution",
        "plan", "requirements", "acceptance", "implementation", "tests",
        "coverageBasisPoints", "gaps", "orphans",
    }
    if set(ledger) != top_keys:
        raise ContractViolation("traceability ledger top-level keys are not closed")
    if ledger.get("schemaVersion") != "quant-radar-ui-ux-traceability/v2":
        raise ContractViolation("traceability schema mismatch")
    if ledger.get("status") != "NOT_TESTED" or ledger.get("implementationStatus") != "NOT_STARTED":
        raise ContractViolation("traceability preimplementation status mismatch")
    if ledger.get("testExecution") != {"executedAt": None, "results": [], "status": "NOT_RUN"}:
        raise ContractViolation("traceability test-execution state mismatch")
    if ledger.get("plan") != PARENT_PLAN_REF:
        raise ContractViolation("traceability plan reference mismatch")
    if ledger.get("coverageBasisPoints") != 10_000 or isinstance(ledger.get("coverageBasisPoints"), bool):
        raise ContractViolation("traceability coverage is not complete")
    if ledger.get("gaps") != [] or ledger.get("orphans") != []:
        raise ContractViolation("traceability gaps and orphans must be empty")

    expected_ids = {
        "requirements": tuple(
            [f"CFR-{index:03d}" for index in range(1, 14)]
            + [f"REQ-{index:03d}" for index in range(1, 5)]
        ),
        "acceptance": tuple(f"AC-HANDOFF-{index:03d}" for index in range(1, 14)),
        "implementation": tuple(f"IMPL-{index:03d}" for index in range(1, 11)),
        "tests": tuple(f"TEST-{index:03d}" for index in range(1, 30)),
    }
    relation_fields = {
        "requirements": ("acceptance", "implementation", "tests"),
        "acceptance": ("requirements", "implementation", "tests"),
        "implementation": ("requirements", "acceptance", "tests"),
        "tests": ("requirements", "acceptance", "implementation"),
    }
    maps: dict[str, dict[str, dict[str, Any]]] = {}
    for collection, identifiers in expected_ids.items():
        rows = ledger.get(collection)
        if not isinstance(rows, list) or tuple(row.get("id") for row in rows if isinstance(row, dict)) != identifiers:
            raise ContractViolation(f"traceability {collection} declaration set/order mismatch")
        row_map: dict[str, dict[str, Any]] = {}
        for row in rows:
            if not isinstance(row, dict) or set(row) != {"id", *relation_fields[collection]}:
                raise ContractViolation(f"traceability {collection} row keys are not closed")
            identifier = row["id"]
            for field in relation_fields[collection]:
                edges = row.get(field)
                if (
                    not isinstance(edges, list)
                    or not edges
                    or edges != sorted(edges)
                    or len(edges) != len(set(edges))
                ):
                    raise ContractViolation(f"traceability {collection}.{field} edges are invalid")
                if any(edge not in expected_ids[field] for edge in edges):
                    raise ContractViolation(f"traceability {collection}.{field} has an undeclared edge")
            row_map[identifier] = row
        maps[collection] = row_map

    edge_families = (
        ("requirements", "acceptance"),
        ("requirements", "implementation"),
        ("requirements", "tests"),
        ("acceptance", "implementation"),
        ("acceptance", "tests"),
        ("implementation", "tests"),
    )
    for left, right in edge_families:
        for left_id, row in maps[left].items():
            for right_id in row[right]:
                if left_id not in maps[right][right_id][left]:
                    raise ContractViolation(f"traceability {left}<->{right} edge is asymmetric")
        for right_id, row in maps[right].items():
            for left_id in row[left]:
                if right_id not in maps[left][left_id][right]:
                    raise ContractViolation(f"traceability {left}<->{right} reverse edge is asymmetric")

    for requirement_id, requirement in maps["requirements"].items():
        acceptance_rows = [maps["acceptance"][item] for item in requirement["acceptance"]]
        expected_implementation = sorted({item for row in acceptance_rows for item in row["implementation"]})
        expected_tests = sorted({item for row in acceptance_rows for item in row["tests"]})
        if requirement["implementation"] != expected_implementation or requirement["tests"] != expected_tests:
            raise ContractViolation(f"traceability {requirement_id} edges differ from its acceptance-chain union")

    for implementation_id, implementation in maps["implementation"].items():
        for test_id in implementation["tests"]:
            if not (set(implementation["acceptance"]) & set(maps["tests"][test_id]["acceptance"])):
                raise ContractViolation("implementation/test edge lacks an acceptance co-occurrence")

    return {
        "requirements": len(maps["requirements"]),
        "acceptance": len(maps["acceptance"]),
        "implementation": len(maps["implementation"]),
        "tests": len(maps["tests"]),
        "edgeFamilies": len(edge_families),
        "coverageBasisPoints": ledger["coverageBasisPoints"],
        "gaps": [],
        "orphans": [],
    }


