def _reject_duplicate_flags(argv: Sequence[str]) -> None:
    seen: set[str] = set()
    for value in argv:
        if not value.startswith("--") or value == "--":
            continue
        flag = value.split("=", 1)[0]
        if flag in seen:
            raise ContractViolation(f"duplicate flag: {flag}")
        seen.add(flag)


def _validate_publish_review_args(args: argparse.Namespace) -> None:
    present = {
        "recovery": args.recovery_id is not None,
        "continuation": args.continuation_id is not None,
        "correction": args.correction_id is not None,
        "lifecycleCorrection": (
            args.lifecycle_correction_id is not None
        ),
        "batch": args.batch_id is not None,
        "theme": args.theme_run_id is not None,
    }
    expected = {
        "control-migration": {
            "recovery": True,
            "continuation": True,
            "correction": True,
            "lifecycleCorrection": True,
            "batch": False,
            "theme": False,
        },
        "theme-batch": {
            "recovery": False,
            "continuation": False,
            "correction": False,
            "lifecycleCorrection": False,
            "batch": True,
            "theme": True,
        },
        "theme-states": {
            "recovery": False,
            "continuation": False,
            "correction": False,
            "lifecycleCorrection": False,
            "batch": False,
            "theme": True,
        },
        "posttheme": {
            "recovery": False,
            "continuation": False,
            "correction": False,
            "lifecycleCorrection": False,
            "batch": False,
            "theme": True,
        },
    }[args.kind]
    if present != expected:
        raise ContractViolation("publish-review identifiers do not match kind")


def _parse_private_child(argv: Sequence[str]) -> argparse.Namespace:
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument(PRIVATE_CHILD_COMMAND)
    parser.add_argument("--workspace-fd", required=True, type=int)
    parser.add_argument("--stage-fd", required=True, type=int)
    parser.add_argument("--receipt-fd", required=True, type=int)
    parser.add_argument("--nonce", required=True, type=_id_type(NONCE_PATTERN, "nonce"))
    args = parser.parse_args(list(argv))
    if min(args.workspace_fd, args.stage_fd, args.receipt_fd) < 0:
        parser.error("inherited descriptors must be nonnegative")
    if len({args.workspace_fd, args.stage_fd, args.receipt_fd}) != 3:
        parser.error("inherited descriptors must be distinct")
    return args


@contextlib.contextmanager
def _production_workspace_fd() -> Any:
    flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_CLOEXEC", 0)
    workspace_fd = os.open(WORKSPACE_ROOT, flags)
    try:
        observed = os.fstat(workspace_fd)
        named = os.lstat(WORKSPACE_ROOT)
        if (
            not stat.S_ISDIR(observed.st_mode)
            or (observed.st_dev, observed.st_ino) != (named.st_dev, named.st_ino)
        ):
            raise ContractViolation("production workspace descriptor/path mismatch")
        yield workspace_fd
    finally:
        os.close(workspace_fd)


def _public_success(
    command: str,
    relative: str,
    *,
    status_value: str,
) -> dict[str, Any]:
    record = _file_record_at(WORKSPACE_ROOT, relative)
    return {
        "exitCode": EXIT_SUCCESS,
        "kind": command,
        "path": relative,
        "sha256": record["sha256"],
        "status": status_value,
    }


def _handle_verify_python_syntax(args: argparse.Namespace) -> dict[str, Any]:
    if args.command != "verify-python-syntax" or args.json is not True:
        raise ContractViolation("verify-python-syntax arguments mismatch")
    checked = (
        "scripts/ui_ux_theme_handoff.py",
        "scripts/test_ui_ux_theme_handoff.py",
    )
    for relative in checked:
        source_fd = os.open(
            WORKSPACE_ROOT / relative,
            os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_CLOEXEC", 0),
        )
        try:
            source = _read_fd_bytes(source_fd, limit=CANDIDATE_FILE_LIMIT_BYTES)
        finally:
            os.close(source_fd)
        try:
            text = source.decode("utf-8", errors="strict")
            compile(text, relative, "exec", dont_inherit=True, optimize=0)
            ast.parse(text, filename=relative, mode="exec", feature_version=(3, 10))
        except (SyntaxError, UnicodeError, ValueError) as exc:
            raise ContractViolation(f"Python syntax verification failed: {relative}") from exc
    return _public_success(
        args.command,
        "scripts/ui_ux_theme_handoff.py",
        status_value="verified",
    )


def _handle_bootstrap(args: argparse.Namespace) -> dict[str, Any]:
    if (
        args.command != "bootstrap"
        or args.json is not True
        or args.recovery_id != AUTHORIZED_RECOVERY_ID
    ):
        raise ContractViolation("bootstrap arguments mismatch")
    source_flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
    )
    with _production_workspace_fd() as workspace_fd:
        source_root_fd = os.open(SOURCE_WORKSPACE_ROOT, source_flags)
        try:
            result = _bootstrap_tier0(
                workspace_fd,
                args.recovery_id,
                source_root_fd=source_root_fd,
            )
        finally:
            os.close(source_root_fd)
        if result.get("exitCode") != EXIT_SUCCESS:
            exit_code = result.get("exitCode")
            if type(exit_code) is not int:
                raise ContractViolation("bootstrap returned an invalid exit code")
            return {"exitCode": exit_code}
        _validate_tier0_complete(workspace_fd, result)
    return _public_success(
        args.command,
        TIER0_DESTINATIONS[5],
        status_value=(
            "reconciled" if result.get("readOnlyReconciled") is True else "created"
        ),
    )


def _handle_preflight(args: argparse.Namespace) -> dict[str, Any]:
    if (
        args.command != "preflight"
        or args.json is not True
        or args.recovery_id != AUTHORIZED_RECOVERY_ID
        or args.authorization_record_sha != AUTH_BODY_SHA256
    ):
        raise ContractViolation("preflight arguments mismatch")
    source_flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
    )
    with _production_workspace_fd() as workspace_fd:
        source_root_fd = os.open(SOURCE_WORKSPACE_ROOT, source_flags)
        try:
            result = _preflight_lifecycle(
                workspace_fd,
                args.recovery_id,
                args.authorization_record_sha,
                source_root_fd=source_root_fd,
            )
        finally:
            os.close(source_root_fd)
    if result.get("exitCode") != EXIT_SUCCESS:
        exit_code = result.get("exitCode")
        if type(exit_code) is not int:
            raise ContractViolation("preflight returned an invalid exit code")
        return {"exitCode": exit_code}
    return _public_success(
        args.command,
        TIER0_DESTINATIONS[10],
        status_value=(
            "created" if result.get("created") is True else "reconciled"
        ),
    )


def _handle_verify_preflight(args: argparse.Namespace) -> dict[str, Any]:
    if (
        args.command != "verify-preflight"
        or args.json is not True
        or args.recovery_id != AUTHORIZED_RECOVERY_ID
    ):
        raise ContractViolation("verify-preflight arguments mismatch")
    source_flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
    )
    with _production_workspace_fd() as workspace_fd:
        source_root_fd = os.open(SOURCE_WORKSPACE_ROOT, source_flags)
        try:
            result = _preflight_lifecycle(
                workspace_fd,
                args.recovery_id,
                None,
                source_root_fd=source_root_fd,
                verify_only=True,
            )
        finally:
            os.close(source_root_fd)
    if result.get("exitCode") != EXIT_SUCCESS:
        exit_code = result.get("exitCode")
        if type(exit_code) is not int:
            raise ContractViolation(
                "verify-preflight returned an invalid exit code"
            )
        return {"exitCode": exit_code}
    return _public_success(
        args.command,
        TIER0_DESTINATIONS[10],
        status_value="verified",
    )


def _run_task9_with_descriptors(
    workspace_fd: int,
    source_root_fd: int,
    event: str,
) -> dict[str, Any]:
    if (
        event not in {"capture", "reconcile"}
        or type(workspace_fd) is not int
        or workspace_fd < 0
        or type(source_root_fd) is not int
        or source_root_fd < 0
    ):
        raise ContractViolation(
            "Task 9 descriptor execution inputs differ"
        )
    context = _build_task9_production_context(
        workspace_fd,
        source_root_fd,
        TIER0_DESTINATIONS[10],
        event=event,
    )
    budget = _validate_descriptor_budget(
        context["preflight"]["descriptorBudget"]
    )
    driver = _Task9ProductionDriver(
        workspace_fd,
        source_root_fd,
        context,
    )
    with _apply_preflight_descriptor_budget(budget):
        result = _task9_transition(
            workspace_fd,
            AUTHORIZED_RECOVERY_ID,
            event,
            driver=driver,
        )
    exit_code = result.get("exitCode")
    if type(exit_code) is not int:
        raise ContractViolation(
            "Task 9 returned an invalid exit code"
        )
    if exit_code != EXIT_SUCCESS:
        return {"exitCode": exit_code}
    if result.get("status") != "passed":
        raise ContractViolation(
            "Task 9 success lacks a passed terminal"
        )
    return {"exitCode": EXIT_SUCCESS}


def _run_task9_public_handler(
    args: argparse.Namespace,
    event: str,
) -> dict[str, Any]:
    if (
        event not in {"capture", "reconcile"}
        or args.json is not True
        or args.recovery_id != AUTHORIZED_RECOVERY_ID
        or args.command
        != (
            "capture-task9"
            if event == "capture"
            else "reconcile-task9"
        )
        or (
            event == "capture"
            and args.preflight != TIER0_DESTINATIONS[10]
        )
        or (
            event == "reconcile"
            and hasattr(args, "preflight")
            and args.preflight is not None
        )
    ):
        raise ContractViolation("Task 9 public arguments mismatch")
    source_flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
    )
    try:
        with _production_workspace_fd() as workspace_fd:
            source_root_fd = os.open(
                SOURCE_WORKSPACE_ROOT,
                source_flags,
            )
            try:
                result = _run_task9_with_descriptors(
                    workspace_fd,
                    source_root_fd,
                    event,
                )
            finally:
                os.close(source_root_fd)
    except _Task9RunnerFailure as exc:
        return {"exitCode": exc.exit_code}
    except NamespaceCollision:
        return {"exitCode": EXIT_COLLISION}
    except PrimitiveUnavailable:
        return {"exitCode": EXIT_UNAVAILABLE}
    except OSError:
        return {"exitCode": EXIT_UNAVAILABLE}
    exit_code = result["exitCode"]
    if exit_code != EXIT_SUCCESS:
        return {"exitCode": exit_code}
    return _public_success(
        args.command,
        TASK9_LIFECYCLE[4][0],
        status_value=(
            "captured" if event == "capture" else "reconciled"
        ),
    )


def _handle_capture_task9(
    args: argparse.Namespace,
) -> dict[str, Any]:
    return _run_task9_public_handler(args, "capture")


def _handle_reconcile_task9(
    args: argparse.Namespace,
) -> dict[str, Any]:
    return _run_task9_public_handler(args, "reconcile")


