def _run_correction_descriptor_command(
    operation: Callable[[int, int], dict[str, Any]],
) -> dict[str, Any]:
    source_flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
    )
    try:
        with _production_workspace_fd() as workspace_fd:
            source_root_fd = os.open(
                SOURCE_WORKSPACE_ROOT,
                source_flags,
            )
            try:
                descriptor_profile = _build_descriptor_profile()
                with _runtime_descriptor_budget(
                    descriptor_profile
                ):
                    return operation(workspace_fd, source_root_fd)
            finally:
                os.close(source_root_fd)
    except BlockingIOError:
        return {"exitCode": EXIT_BUSY}
    except NamespaceCollision:
        return {"exitCode": EXIT_COLLISION}
    except PrimitiveUnavailable:
        return {"exitCode": EXIT_UNAVAILABLE}
    except OSError:
        return {"exitCode": EXIT_UNAVAILABLE}


def _run_continuation_descriptor_command(
    operation: Callable[[int, int], dict[str, Any]],
) -> dict[str, Any]:
    """Compatibility name; all active work uses Sequence 10 capacity."""

    return _run_correction_descriptor_command(operation)


