def _handle_verify_historical_stack_preflight(
    args: argparse.Namespace,
) -> dict[str, Any]:
    _validate_historical_stack_public_args(
        args,
        (
            "verify-historical-stack-comparator-"
            "correction-preflight"
        ),
    )

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        record, preflight, _ = (
            _reauthenticate_historical_stack_preflight(
                workspace_fd,
                source_root_fd,
            )
        )
        current = _validate_historical_stack_forward_semantics(
            workspace_fd,
            source_root_fd,
            preflight=preflight,
        )
        return {
            "exitCode": EXIT_SUCCESS,
            "preflight": _artifact_ref(record),
            "state": current["state"],
        }

    result = _run_correction_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        HISTORICAL_STACK_PREFLIGHT_PATH,
        status_value="verified-" + result["state"],
    )


