def _validate_external_review_public_args(
    args: argparse.Namespace,
    command: str,
) -> None:
    submit = command == "submit-historical-stack-review-intake"
    if (
        args.command != command
        or command not in EXTERNAL_REVIEW_ALLOWED_COMMANDS
        or args.json is not True
        or args.capture_id != EXTERNAL_REVIEW_CAPTURE_ID
        or args.parent_continuation_id
        != EXTERNAL_REVIEW_PARENT_CONTINUATION_ID
        or args.external_review_correction_id
        != EXTERNAL_REVIEW_CORRECTION_ID
        or args.external_review_tier_id
        != EXTERNAL_REVIEW_TIER_ID
        or (
            submit
            and (
                getattr(args, "intake_stdin", None) is not True
                or not isinstance(
                    getattr(
                        args,
                        "accepted_intake_sha256",
                        None,
                    ),
                    str,
                )
                or re.fullmatch(
                    r"[0-9a-f]{64}",
                    args.accepted_intake_sha256,
                )
                is None
                or type(args.accepted_intake_size) is not int
                or not (
                    1
                    <= args.accepted_intake_size
                    <= EXTERNAL_REVIEW_MAX_INTAKE_BYTES
                )
            )
        )
        or (
            not submit
            and any(
                hasattr(args, name)
                for name in (
                    "intake_stdin",
                    "accepted_intake_sha256",
                    "accepted_intake_size",
                )
            )
        )
    ):
        raise ContractViolation(
            f"{command} arguments mismatch"
        )


