def _read_workspace_schema(
    workspace_fd: int,
    relative: str,
    schema_version: str | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    record, data = _relative_regular_record_and_bytes(
        workspace_fd,
        relative,
    )
    value = _strict_json_bytes(data, allow_float=True)
    if not isinstance(value, dict):
        raise ContractViolation(
            "workspace JSON authority is not an object: " + relative
        )
    if schema_version is not None:
        _validate_schema(schema_version, value)
    return record, value


def _migration_review_items(
    workspace_fd: int,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    expected_by_path = {
        row["path"]: row for row in CONTINUATION_PREDECESSOR_REFS
    }
    inputs: list[dict[str, Any]] = []
    manifests: dict[str, dict[str, Any]] = {}
    for key, relative in CONTROL_MIGRATION_INPUTS.items():
        record, data = _expected_continuation_ref(
            workspace_fd,
            expected_by_path[relative],
        )
        payload = (
            data[:-1]
            if data.endswith(b"\n") and not data.endswith(b"\n\n")
            else data
        )
        value = _strict_json_bytes(payload, allow_float=True)
        if not isinstance(value, dict):
            raise ContractViolation("migration manifest is not an object")
        manifests[key] = value
        inputs.append(_artifact_ref(record))

    def rows(
        before_key: str,
        after_key: str,
        before_root: str,
        after_root: str,
    ) -> list[dict[str, Any]]:
        before = {
            row["id"]: row
            for row in manifests[before_key]["captures"]
        }
        after = {
            row["id"]: row
            for row in manifests[after_key]["captures"]
        }
        if set(before) != set(after):
            raise ContractViolation(
                "migration review capture IDs differ"
            )
        result: list[dict[str, Any]] = []
        for identifier in sorted(before):
            before_png = before[identifier]["artifacts"]["png"]
            after_png = after[identifier]["artifacts"]["png"]
            dimensions = {
                "width": before_png["width"],
                "height": before_png["height"],
            }
            if dimensions != {
                "width": after_png["width"],
                "height": after_png["height"],
            }:
                raise ContractViolation(
                    "migration review dimensions differ"
                )
            before_ref = {
                "path": f"{before_root}/{before_png['path']}",
                "sha256": before_png["sha256"],
                "size": before_png["size"],
            }
            after_ref = {
                "path": f"{after_root}/{after_png['path']}",
                "sha256": after_png["sha256"],
                "size": after_png["size"],
            }
            result.append(
                {
                    "id": identifier,
                    "before": before_ref,
                    "after": after_ref,
                    "dimensions": dimensions,
                    "changed": (
                        before_ref["sha256"] != after_ref["sha256"]
                    ),
                }
            )
        return result

    items = [
        *rows(
            "beforePages",
            "afterPages",
            str(
                PurePosixPath(
                    CONTROL_MIGRATION_INPUTS["beforePages"]
                ).parent
            ),
            str(
                PurePosixPath(
                    CONTROL_MIGRATION_INPUTS["afterPages"]
                ).parent
            ),
        ),
        *rows(
            "beforeControls",
            "afterControls",
            str(
                PurePosixPath(
                    CONTROL_MIGRATION_INPUTS["beforeControls"]
                ).parent
            ),
            str(
                PurePosixPath(
                    CONTROL_MIGRATION_INPUTS["afterControls"]
                ).parent
            ),
        ),
    ]
    if len(items) != 117:
        raise ContractViolation(
            "migration review item cardinality differs"
        )
    _validate_review_items("control-migration", items)
    return inputs, items


def _root_migration_review_items_from_values(
    *,
    before_pages: Mapping[str, Any],
    after_pages: Mapping[str, Any],
    before_controls: Mapping[str, Any],
    after_root_controls: Mapping[str, Any],
    artifact_roots: Mapping[str, str],
) -> list[dict[str, Any]]:
    from scripts import ui_ux_evidence

    if set(artifact_roots) != {
        "beforePages",
        "afterPages",
        "beforeControls",
        "afterRootControls",
    } or any(
        not isinstance(value, str) or not value
        for value in artifact_roots.values()
    ):
        raise ContractViolation(
            "root migration artifact roots differ"
        )

    def capture_map(
        manifest: Mapping[str, Any],
        *,
        label: str,
    ) -> dict[str, Mapping[str, Any]]:
        captures = manifest.get("captures")
        if not isinstance(captures, list):
            raise ContractViolation(
                f"{label} captures are invalid"
            )
        result = {
            row.get("id"): row
            for row in captures
            if isinstance(row, Mapping)
            and isinstance(row.get("id"), str)
        }
        if len(result) != len(captures):
            raise ContractViolation(
                f"{label} capture IDs are invalid"
            )
        return result

    page_before = capture_map(before_pages, label="before pages")
    page_after = capture_map(after_pages, label="after pages")
    control_before = capture_map(
        before_controls,
        label="before controls",
    )
    root_after = capture_map(
        after_root_controls,
        label="after root controls",
    )
    if len(page_before) != 81 or set(page_before) != set(page_after):
        raise ContractViolation(
            "root migration page capture IDs differ"
        )
    expected_roots = ui_ux_evidence.root_capture_expansion_rows()
    expected_logical = {
        row["logicalCaptureId"] for row in expected_roots
    }
    if (
        len(control_before) != 36
        or set(control_before) != expected_logical
        or len(root_after) != 44
        or set(root_after)
        != {row["rootCaptureId"] for row in expected_roots}
    ):
        raise ContractViolation(
            "root migration control capture IDs differ"
        )

    def artifact_ref(
        root_key: str,
        artifact: Mapping[str, Any],
        *,
        label: str,
    ) -> dict[str, Any]:
        path = artifact.get("path")
        if not isinstance(path, str) or not path:
            raise ContractViolation(f"{label} path is invalid")
        value = {
            "path": str(
                PurePosixPath(artifact_roots[root_key]) / path
            ),
            "sha256": artifact.get("sha256"),
            "size": artifact.get("size"),
        }
        _validate_artifact_ref_value(value, label)
        return value

    page_items: list[dict[str, Any]] = []
    for capture_id in sorted(page_before):
        before_png = page_before[capture_id]["artifacts"]["png"]
        after_png = page_after[capture_id]["artifacts"]["png"]
        dimensions = {
            "width": before_png.get("width"),
            "height": before_png.get("height"),
        }
        if dimensions != {
            "width": after_png.get("width"),
            "height": after_png.get("height"),
        }:
            raise ContractViolation(
                "root migration page dimensions differ"
            )
        _validate_review_dimensions(dimensions)
        before_ref = artifact_ref(
            "beforePages",
            before_png,
            label="root migration page before",
        )
        after_ref = artifact_ref(
            "afterPages",
            after_png,
            label="root migration page after",
        )
        page_items.append(
            {
                "kind": "page",
                "id": capture_id,
                "before": before_ref,
                "after": after_ref,
                "dimensions": dimensions,
                "changed": (
                    before_ref["sha256"] != after_ref["sha256"]
                ),
            }
        )

    root_items: list[dict[str, Any]] = []
    for expected in expected_roots:
        logical_id = expected["logicalCaptureId"]
        root_id = expected["rootCaptureId"]
        before_png = control_before[logical_id]["artifacts"]["png"]
        after_artifacts = root_after[root_id]["artifacts"]
        after_png = after_artifacts["png"]
        after_sidecar = after_artifacts["renderSidecar"]
        dimensions = {
            "width": expected["viewport"]["width"],
            "height": expected["viewport"]["height"],
        }
        if any(
            artifact.get("width") != dimensions["width"]
            or artifact.get("height") != dimensions["height"]
            for artifact in (before_png, after_png)
        ):
            raise ContractViolation(
                "root migration control dimensions differ"
            )
        before_ref = artifact_ref(
            "beforeControls",
            before_png,
            label="root migration control before",
        )
        after_ref = artifact_ref(
            "afterRootControls",
            after_png,
            label="root migration control after",
        )
        root_items.append(
            {
                "kind": "control-root",
                "id": root_id,
                "logicalCaptureId": logical_id,
                "rootCaptureId": root_id,
                "rootOrdinal": expected["rootOrdinal"],
                "rootSelector": expected["rootSelector"],
                "before": before_ref,
                "after": after_ref,
                "afterSidecar": artifact_ref(
                    "afterRootControls",
                    after_sidecar,
                    label="root migration control sidecar",
                ),
                "dimensions": dimensions,
                "changed": (
                    before_ref["sha256"] != after_ref["sha256"]
                ),
            }
        )
    items = [*page_items, *root_items]
    _validate_root_migration_review_items(items)
    return items


def _prepare_control_migration_review(
    workspace_fd: int,
    source_root_fd: int,
) -> dict[str, Any]:
    _, _, current = _reauthenticate_lifecycle_correction_preflight(
        workspace_fd,
        source_root_fd,
    )
    if current["state"] not in {"F0_REPORT", "F1_PACKET"}:
        raise ContractViolation(
            "prepare-review requires report or packet state"
        )
    report_record = current["records"][0]
    report = current["values"][0]
    if report_record is None or report is None:
        raise ContractViolation("migration report is unavailable")
    if (
        report.get("status") != "passed"
        or report.get("kind") != "control-migration"
        or report.get("comparedCaptures") != 117
    ):
        raise ContractViolation("migration machine report differs")
    inputs, items = _migration_review_items(workspace_fd)
    report_ref = _artifact_ref(report_record)
    packet = _build_review_packet(
        "control-migration",
        None,
        AUTHORIZED_RECOVERY_ID,
        report_ref,
        [report_ref, *inputs],
        items,
    )
    _validate_review_packet_value(packet)
    packet_record, created = _publish_or_reopen_continuation_file(
        workspace_fd,
        CONTINUATION_FORWARD_PATHS[1],
        _canonical_json_bytes(packet),
    )
    _, _, post = _reauthenticate_lifecycle_correction_preflight(
        workspace_fd,
        source_root_fd,
    )
    if post["state"] != "F1_PACKET":
        raise ContractViolation(
            "prepare-review postcondition differs"
        )
    return {
        "exitCode": EXIT_SUCCESS,
        "created": created,
        "packet": _artifact_ref(packet_record),
        "items": len(items),
    }


def _publish_review_from_external_intake(
    workspace_fd: int,
    *,
    kind: str,
    root_sha256: str | None,
    lineage_id: str,
) -> dict[str, Any]:
    packet_path, intake_path, _ = _review_paths(
        kind,
        root_sha256,
        lineage_id,
    )
    _, packet = _read_workspace_schema(
        workspace_fd,
        packet_path,
        "quant-radar-ui-ux-review-packet/v1",
    )
    intake_fd = os.open(
        intake_path,
        os.O_RDONLY
        | os.O_NOFOLLOW
        | getattr(os, "O_CLOEXEC", 0),
        dir_fd=workspace_fd,
    )
    decision: dict[str, str] = {}
    try:
        intake_record = _file_record_from_fd(intake_path, intake_fd)
        published = _publish_review_exact(
            workspace_fd,
            packet,
            intake_fd,
            intake_record,
            decision_out=decision,
        )
    finally:
        os.close(intake_fd)
    if decision.get("decision") not in {"accepted", "rejected"}:
        raise ContractViolation(
            "published review decision is unavailable"
        )
    return {
        "exitCode": EXIT_SUCCESS,
        "review": _artifact_ref(published),
        "decision": decision["decision"],
    }


def _handle_prepare_review(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "prepare-review"
        or args.json is not True
        or args.kind != "control-migration"
        or args.recovery_id != AUTHORIZED_RECOVERY_ID
        or args.continuation_id != CONTINUATION_ID
        or args.correction_id != CORRECTION_ID
        or args.lifecycle_correction_id
        != LIFECYCLE_CORRECTION_ID
    ):
        raise ContractViolation("prepare-review arguments mismatch")
    result = _run_correction_descriptor_command(
        lambda workspace_fd, source_root_fd: (
            _prepare_control_migration_review(
                workspace_fd,
                source_root_fd,
            )
        )
    )
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        CONTINUATION_FORWARD_PATHS[1],
        status_value=(
            "created" if result.get("created") else "reconciled"
        ),
    )


def _handle_publish_review(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if args.command != "publish-review" or args.json is not True:
        raise ContractViolation("publish-review arguments mismatch")
    _validate_publish_review_args(args)
    if args.kind == "control-migration":
        if (
            args.recovery_id != AUTHORIZED_RECOVERY_ID
            or args.continuation_id != CONTINUATION_ID
            or args.correction_id != CORRECTION_ID
            or args.lifecycle_correction_id
            != LIFECYCLE_CORRECTION_ID
        ):
            raise ContractViolation(
                "control-migration review lineage mismatch"
            )

        def operation(
            workspace_fd: int,
            source_root_fd: int,
        ) -> dict[str, Any]:
            _, _, current = (
                _reauthenticate_lifecycle_correction_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            if current["state"] != "F2_INTAKE":
                raise ContractViolation(
                    "publish-review requires external intake state"
                )
            published = _publish_review_from_external_intake(
                workspace_fd,
                kind="control-migration",
                root_sha256=None,
                lineage_id=AUTHORIZED_RECOVERY_ID,
            )
            _, _, post = (
                _reauthenticate_lifecycle_correction_preflight(
                    workspace_fd,
                    source_root_fd,
                )
            )
            if post["state"] != "F3_REVIEW":
                raise ContractViolation(
                    "publish-review postcondition differs"
                )
            return published

        result = _run_correction_descriptor_command(operation)
    else:
        result = _publish_downstream_review(args)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    review = result.get("review")
    if (
        not isinstance(review, Mapping)
        or not isinstance(review.get("path"), str)
    ):
        raise ContractViolation(
            "published review artifact is missing"
        )
    destination = result["review"]["path"]
    decision = (
        result.get("decision")
        if args.kind == "control-migration"
        else "accepted"
    )
    if decision not in {"accepted", "rejected"}:
        raise ContractViolation(
            "published review decision is invalid"
        )
    return _public_success(
        args.command,
        destination,
        status_value=decision,
    )


def _source_record_from_file_record(
    record: Mapping[str, Any],
) -> dict[str, Any]:
    return {
        key: record[key]
        for key in ("path", "sha256", "size", "mode")
    }


def _root_theme_boundary(
    preflight: Mapping[str, Any],
) -> dict[str, Any]:
    projected: dict[str, dict[str, Any]] = {}
    for projection_name in (
        "sourceProjection",
        "supplementalProjection",
    ):
        projection = preflight.get(projection_name)
        if not isinstance(projection, Mapping) or not isinstance(
            projection.get("records"),
            list,
        ):
            raise ContractViolation(
                "root source projection is invalid"
            )
        for record in projection["records"]:
            projected[record["path"]] = copy.deepcopy(record)
    try:
        preimages = [
            projected[relative] for relative in APPLY_PATHS
        ]
    except KeyError as exc:
        raise ContractViolation(
            "root theme boundary lacks a preimage"
        ) from exc
    if [item["path"] for item in preimages] != list(APPLY_PATHS):
        raise ContractViolation("root theme boundary order differs")
    return {
        "paths": list(APPLY_PATHS),
        "preimages": preimages,
    }


def _build_correction_root_candidate(
    workspace_fd: int,
    source_root_fd: int,
) -> dict[str, Any]:
    preflight_record, preflight = (
        _reauthenticate_correction_preflight(
            workspace_fd,
            source_root_fd,
        )
    )
    predecessor = _reauthenticate_sequence8_predecessor(workspace_fd)
    report_record, report = _read_workspace_schema(
        workspace_fd,
        CONTINUATION_FORWARD_PATHS[0],
    )
    packet_record, packet = _read_workspace_schema(
        workspace_fd,
        CONTINUATION_FORWARD_PATHS[1],
        "quant-radar-ui-ux-review-packet/v1",
    )
    review_record, review = _read_workspace_schema(
        workspace_fd,
        CONTINUATION_FORWARD_PATHS[3],
        "quant-radar-ui-ux-manual-review/v2",
    )
    if (
        report.get("comparedCaptures") != 117
        or packet.get("machineReport") != _artifact_ref(report_record)
        or review.get("packet") != _artifact_ref(packet_record)
        or review.get("status") != "accepted"
        or review.get("decision") != "accepted"
    ):
        raise ContractViolation(
            "accepted migration review chain differs"
        )
    base_record, _ = _read_continuation_authority(
        source_root_fd,
        BASE_DRAFT_PATH,
    )
    authority_records: dict[str, dict[str, Any]] = {}
    for relative in (
        CORRECTION_AUTHORIZATION_DOCUMENT_PATH,
        CORRECTION_PLAN_REF["path"],
        CORRECTION_LEDGER_REF["path"],
    ):
        record, _ = _read_continuation_authority(
            source_root_fd,
            relative,
        )
        authority_records[relative] = record
    for index, expected in enumerate(CORRECTION_PREDECESSOR_REFS):
        record, _ = _read_exact_correction_predecessor(
            source_root_fd if index == 0 else workspace_fd,
            expected,
        )
        authority_records[record["path"]] = record
    task9 = {
        key: copy.deepcopy(predecessor[key])
        for key in (
            "intent",
            "controlCheckpoint",
            "prethemeGate",
            "prethemeCheckpoint",
            "terminal",
            "postcontrol",
            "pretheme",
        )
    }
    migration = {
        "machineReport": _artifact_ref(report_record),
        "reviewPacket": _artifact_ref(packet_record),
        "manualReview": _artifact_ref(review_record),
        "comparedCaptures": 117,
    }
    root = {
        "schemaVersion": (
            "quant-radar-ui-ux-formal-theme-handoff/v2"
        ),
        "status": "passed",
        "recoveryId": AUTHORIZED_RECOVERY_ID,
        "authorizationRecord": _correction_authorization_binding(),
        "baseDraft": _artifact_ref(base_record),
        "replacementPlan": dict(CORRECTION_PLAN_REF),
        "traceability": dict(CORRECTION_LEDGER_REF),
        "authorities": [
            authority_records[path]
            for path in sorted(authority_records)
        ],
        "preflight": _artifact_ref(preflight_record),
        "captureStack": _artifact_ref(
            preflight["predecessor"]["preflightValue"][
                "captureStack"
            ]["contract"]
        ),
        "task6": copy.deepcopy(
            preflight["predecessor"]["preflightValue"]["task6"]
        ),
        "task9": task9,
        "migration": migration,
        "historicalSelectorModes": copy.deepcopy(
            preflight["predecessor"]["preflightValue"][
                "historicalSelectorModes"
            ]
        ),
        "sourceProjection": copy.deepcopy(
            preflight["sourceProjection"]
        ),
        "supplementalProjection": copy.deepcopy(
            preflight["supplementalProjection"]
        ),
        "runtimeReceipt": copy.deepcopy(
            preflight["runtimeReceipt"]
        ),
        "themeBatchBoundary": _root_theme_boundary(preflight),
        "allowedChanges": {
            "production": list(APPLY_PATHS[:4]),
            "evidence": [APPLY_PATHS[4]],
        },
    }
    _validate_schema(root["schemaVersion"], root)
    candidate = {
        "schemaVersion": (
            "quant-radar-ui-ux-formal-handoff-candidate/v2"
        ),
        "status": "candidate",
        "recoveryId": AUTHORIZED_RECOVERY_ID,
        "authorizationRecord": copy.deepcopy(
            root["authorizationRecord"]
        ),
        "baseDraft": copy.deepcopy(root["baseDraft"]),
        "replacementPlan": copy.deepcopy(root["replacementPlan"]),
        "traceability": copy.deepcopy(root["traceability"]),
        "preflight": copy.deepcopy(root["preflight"]),
        "task6": copy.deepcopy(root["task6"]),
        "task9": copy.deepcopy(root["task9"]),
        "migration": copy.deepcopy(root["migration"]),
        "historicalSelectorModes": copy.deepcopy(
            root["historicalSelectorModes"]
        ),
        "sourceProjection": copy.deepcopy(
            root["sourceProjection"]
        ),
        "supplementalProjection": copy.deepcopy(
            root["supplementalProjection"]
        ),
        "runtimeReceipt": copy.deepcopy(root["runtimeReceipt"]),
        "proposedContract": root,
        "proposedContractSha256": hashlib.sha256(
            _canonical_json_bytes(root)
        ).hexdigest(),
    }
    _validate_schema(candidate["schemaVersion"], candidate)
    return candidate


def _build_lifecycle_correction_root_candidate(
    workspace_fd: int,
    source_root_fd: int,
    *,
    preflight_record: Mapping[str, Any],
    preflight: Mapping[str, Any],
    classified: Mapping[str, Any],
) -> dict[str, Any]:
    """Pure Sequence 11 candidate reconstruction over authenticated inputs."""

    if (
        classified.get("state")
        not in {"F3_REVIEW", "F4_CANDIDATE", "F5_ROOT"}
        or not isinstance(classified.get("records"), list)
        or not isinstance(classified.get("values"), list)
    ):
        raise ContractViolation(
            "candidate requires an authenticated review prefix"
        )
    records = classified["records"]
    values = classified["values"]
    report_record = records[0]
    packet_record = records[1]
    review_record = records[3]
    report = values[0]
    packet = values[1]
    review = values[3]
    if (
        report_record is None
        or packet_record is None
        or review_record is None
        or report.get("comparedCaptures") != 117
        or packet.get("machineReport")
        != _artifact_ref(report_record)
        or review.get("packet") != _artifact_ref(packet_record)
        or review.get("status") != "accepted"
        or review.get("decision") != "accepted"
    ):
        raise ContractViolation(
            "accepted Sequence 11 migration review chain differs"
        )
    predecessor = _reauthenticate_sequence8_predecessor(
        workspace_fd
    )
    sequence10 = preflight.get("predecessor")
    if not isinstance(sequence10, Mapping):
        raise ContractViolation(
            "Sequence 11 preflight lacks Sequence 10 predecessor"
        )
    sequence9 = sequence10.get("preflightValue", {}).get(
        "predecessor"
    )
    if not isinstance(sequence9, Mapping):
        raise ContractViolation(
            "Sequence 10 predecessor lacks Sequence 9 history"
        )
    sequence9_preflight = sequence9.get("preflightValue")
    if not isinstance(sequence9_preflight, Mapping):
        raise ContractViolation(
            "Sequence 9 historical preflight is unavailable"
        )
    base_record, _ = _read_continuation_authority(
        source_root_fd,
        BASE_DRAFT_PATH,
    )
    authority_records: dict[str, dict[str, Any]] = {}
    for relative in (
        LIFECYCLE_CORRECTION_AUTHORIZATION_DOCUMENT_PATH,
        LIFECYCLE_CORRECTION_PLAN_REF["path"],
        LIFECYCLE_CORRECTION_LEDGER_REF["path"],
        CORRECTION_PLAN_REF["path"],
        CORRECTION_LEDGER_REF["path"],
    ):
        record, _ = _read_continuation_authority(
            source_root_fd,
            relative,
        )
        authority_records[relative] = record
    for index, expected in enumerate(
        LIFECYCLE_CORRECTION_PREDECESSOR_REFS
    ):
        root_fd = source_root_fd if index == 0 else workspace_fd
        record, _ = _read_exact_correction_predecessor(
            root_fd,
            expected,
        )
        authority_records[record["path"]] = record
    task9 = {
        key: copy.deepcopy(predecessor[key])
        for key in (
            "intent",
            "controlCheckpoint",
            "prethemeGate",
            "prethemeCheckpoint",
            "terminal",
            "postcontrol",
            "pretheme",
        )
    }
    migration = {
        "machineReport": _artifact_ref(report_record),
        "reviewPacket": _artifact_ref(packet_record),
        "manualReview": _artifact_ref(review_record),
        "comparedCaptures": 117,
    }
    root = {
        "schemaVersion": (
            "quant-radar-ui-ux-formal-theme-handoff/v2"
        ),
        "status": "passed",
        "recoveryId": AUTHORIZED_RECOVERY_ID,
        "authorizationRecord": (
            _lifecycle_correction_authorization_binding()
        ),
        "baseDraft": _artifact_ref(base_record),
        "replacementPlan": dict(LIFECYCLE_CORRECTION_PLAN_REF),
        "traceability": dict(LIFECYCLE_CORRECTION_LEDGER_REF),
        "authorities": [
            authority_records[path]
            for path in sorted(authority_records)
        ],
        "preflight": _artifact_ref(preflight_record),
        "captureStack": _artifact_ref(
            sequence9_preflight["captureStack"]["contract"]
        ),
        "task6": copy.deepcopy(sequence9_preflight["task6"]),
        "task9": task9,
        "migration": migration,
        "historicalSelectorModes": copy.deepcopy(
            sequence9_preflight["historicalSelectorModes"]
        ),
        "sourceProjection": copy.deepcopy(
            preflight["sourceProjection"]
        ),
        "supplementalProjection": copy.deepcopy(
            preflight["supplementalProjection"]
        ),
        "runtimeReceipt": copy.deepcopy(
            preflight["runtimeReceipt"]
        ),
        "themeBatchBoundary": _root_theme_boundary(preflight),
        "allowedChanges": {
            "production": list(APPLY_PATHS[:4]),
            "evidence": [APPLY_PATHS[4]],
        },
    }
    _validate_schema(root["schemaVersion"], root)
    candidate = {
        "schemaVersion": (
            "quant-radar-ui-ux-formal-handoff-candidate/v2"
        ),
        "status": "candidate",
        "recoveryId": AUTHORIZED_RECOVERY_ID,
        "authorizationRecord": copy.deepcopy(
            root["authorizationRecord"]
        ),
        "baseDraft": copy.deepcopy(root["baseDraft"]),
        "replacementPlan": copy.deepcopy(root["replacementPlan"]),
        "traceability": copy.deepcopy(root["traceability"]),
        "preflight": copy.deepcopy(root["preflight"]),
        "task6": copy.deepcopy(root["task6"]),
        "task9": copy.deepcopy(root["task9"]),
        "migration": copy.deepcopy(root["migration"]),
        "historicalSelectorModes": copy.deepcopy(
            root["historicalSelectorModes"]
        ),
        "sourceProjection": copy.deepcopy(
            root["sourceProjection"]
        ),
        "supplementalProjection": copy.deepcopy(
            root["supplementalProjection"]
        ),
        "runtimeReceipt": copy.deepcopy(root["runtimeReceipt"]),
        "proposedContract": root,
        "proposedContractSha256": hashlib.sha256(
            _canonical_json_bytes(root)
        ).hexdigest(),
    }
    _validate_schema(candidate["schemaVersion"], candidate)
    return candidate


def _validate_root_pristine_source(
    source_root_fd: int,
    root: Mapping[str, Any],
) -> None:
    boundary = root.get("themeBatchBoundary")
    if (
        not isinstance(boundary, Mapping)
        or boundary.get("paths") != list(APPLY_PATHS)
        or not isinstance(boundary.get("preimages"), list)
    ):
        raise ContractViolation(
            "root pristine source boundary is invalid"
        )
    for preimage in boundary["preimages"]:
        live_record, _ = _source_file_record(
            source_root_fd,
            preimage["path"],
        )
        try:
            live_mode = int(live_record["mode"], 8)
        except (KeyError, TypeError, ValueError) as exc:
            raise ContractViolation(
                "root pristine source metadata is invalid: "
                + preimage["path"]
            ) from exc
        if (
            live_record.get("uid") != os.getuid()
            or live_record.get("gid") not in {os.getgid(), 0}
            or live_record.get("nlink") != 1
            or live_mode & 0o022
        ):
            raise ContractViolation(
                "root pristine source metadata differs: "
                + preimage["path"]
            )
        normalized = {
            "path": live_record["path"],
            "sha256": live_record["sha256"],
            "size": live_record["size"],
            "mode": (
                "0555"
                if live_mode & 0o111
                else "0444"
            ),
        }
        if normalized != preimage and not (
            preimage
            == THEME_BATCH_REQUIREMENTS_LIFECYCLE["historical"]
            and normalized
            == THEME_BATCH_REQUIREMENTS_LIFECYCLE["current"]
        ):
            raise ContractViolation(
                "root pristine source boundary drifted: "
                + preimage["path"]
            )


def _prepare_handoff_candidate_transition(
    workspace_fd: int,
    source_root_fd: int,
) -> dict[str, Any]:
    preflight_record, preflight, current = (
        _reauthenticate_lifecycle_correction_preflight(
            workspace_fd,
            source_root_fd,
        )
    )
    if current["state"] not in {"F3_REVIEW", "F4_CANDIDATE"}:
        raise ContractViolation(
            "prepare-handoff requires review or candidate state"
        )
    candidate = _build_lifecycle_correction_root_candidate(
        workspace_fd,
        source_root_fd,
        preflight_record=preflight_record,
        preflight=preflight,
        classified=current,
    )
    record, created = _publish_or_reopen_continuation_file(
        workspace_fd,
        CONTINUATION_FORWARD_PATHS[4],
        _canonical_json_bytes(candidate),
    )
    _, _, post = _reauthenticate_lifecycle_correction_preflight(
        workspace_fd,
        source_root_fd,
    )
    if post["state"] != "F4_CANDIDATE":
        raise ContractViolation(
            "prepare-handoff postcondition differs"
        )
    return {
        "exitCode": EXIT_SUCCESS,
        "created": created,
        "candidate": _artifact_ref(record),
    }


def _verify_handoff_candidate_transition(
    workspace_fd: int,
    source_root_fd: int,
) -> tuple[dict[str, Any], dict[str, Any]]:
    _, _, current = (
        _reauthenticate_lifecycle_correction_preflight(
            workspace_fd,
            source_root_fd,
        )
    )
    if current["state"] not in {"F4_CANDIDATE", "F5_ROOT"}:
        raise ContractViolation(
            "candidate verification requires candidate or root state"
        )
    record = current["records"][4]
    candidate = current["values"][4]
    if record is None or candidate is None:
        raise ContractViolation("handoff candidate is unavailable")
    return record, candidate


def _verify_root_lifecycle_correction_chain(
    workspace_fd: int,
    source_root_fd: int,
    *,
    require_pristine: bool = True,
) -> tuple[dict[str, Any], dict[str, Any]]:
    preflight_record, preflight, current = (
        _reauthenticate_lifecycle_correction_preflight(
            workspace_fd,
            source_root_fd,
            require_pristine_root=require_pristine,
        )
    )
    if current["state"] != "F5_ROOT":
        raise ContractViolation(
            "root verification requires complete forward state"
        )
    record = current["records"][5]
    root = current["values"][5]
    if record is None or root is None:
        raise ContractViolation("root is unavailable")
    if (
        root["recoveryId"] != AUTHORIZED_RECOVERY_ID
        or root["authorizationRecord"]
        != _lifecycle_correction_authorization_binding()
        or root["replacementPlan"]
        != LIFECYCLE_CORRECTION_PLAN_REF
        or root["traceability"]
        != LIFECYCLE_CORRECTION_LEDGER_REF
        or root["preflight"] != _artifact_ref(preflight_record)
        or root["sourceProjection"]
        != preflight["sourceProjection"]
        or root["supplementalProjection"]
        != preflight["supplementalProjection"]
        or root["themeBatchBoundary"]
        != _root_theme_boundary(preflight)
    ):
        raise ContractViolation(
            "root lifecycle-correction chain differs"
        )
    if require_pristine:
        _validate_root_pristine_source(source_root_fd, root)
    return record, root


def _build_lifecycle_candidate_for_current_prefix(
    workspace_fd: int,
    source_root_fd: int,
) -> dict[str, Any]:
    preflight_record, preflight, current = (
        _reauthenticate_lifecycle_correction_preflight(
            workspace_fd,
            source_root_fd,
        )
    )
    return _build_lifecycle_correction_root_candidate(
        workspace_fd,
        source_root_fd,
        preflight_record=preflight_record,
        preflight=preflight,
        classified=current,
    )


def _verify_root_correction_chain(
    workspace_fd: int,
    source_root_fd: int,
    *,
    require_pristine: bool = True,
) -> tuple[dict[str, Any], dict[str, Any]]:
    record, root = _read_workspace_schema(
        workspace_fd,
        CONTINUATION_ROOT_PATH,
        "quant-radar-ui-ux-formal-theme-handoff/v2",
    )
    preflight_record, preflight = (
        _reauthenticate_correction_preflight(
            workspace_fd,
            source_root_fd,
        )
    )
    if (
        root["recoveryId"] != AUTHORIZED_RECOVERY_ID
        or root["authorizationRecord"]
        != _correction_authorization_binding()
        or root["replacementPlan"] != CORRECTION_PLAN_REF
        or root["traceability"] != CORRECTION_LEDGER_REF
        or root["preflight"] != _artifact_ref(preflight_record)
        or root["sourceProjection"] != preflight["sourceProjection"]
        or root["supplementalProjection"]
        != preflight["supplementalProjection"]
        or root["themeBatchBoundary"]
        != _root_theme_boundary(preflight)
    ):
        raise ContractViolation("root correction chain differs")
    if require_pristine:
        for preimage in root["themeBatchBoundary"]["preimages"]:
            live_record, _ = _source_file_record(
                source_root_fd,
                preimage["path"],
            )
            if _source_record_from_file_record(live_record) != preimage:
                raise ContractViolation(
                    "root pristine source boundary drifted: "
                    + preimage["path"]
                )
    return record, root


def _handle_prepare_handoff(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "prepare-handoff"
        or args.json is not True
        or args.recovery_id != AUTHORIZED_RECOVERY_ID
        or args.continuation_id != CONTINUATION_ID
        or args.correction_id != CORRECTION_ID
        or args.lifecycle_correction_id
        != LIFECYCLE_CORRECTION_ID
    ):
        raise ContractViolation("prepare-handoff arguments mismatch")
    result = _run_correction_descriptor_command(
        _prepare_handoff_candidate_transition
    )
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        CONTINUATION_FORWARD_PATHS[4],
        status_value=(
            "created" if result.get("created") else "reconciled"
        ),
    )


def _handle_verify_handoff_candidate(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "verify-handoff-candidate"
        or args.json is not True
        or args.recovery_id != AUTHORIZED_RECOVERY_ID
        or args.continuation_id != CONTINUATION_ID
        or args.correction_id != CORRECTION_ID
        or args.lifecycle_correction_id
        != LIFECYCLE_CORRECTION_ID
    ):
        raise ContractViolation(
            "verify-handoff-candidate arguments mismatch"
        )

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        record, _ = _verify_handoff_candidate_transition(
            workspace_fd,
            source_root_fd,
        )
        return {
            "exitCode": EXIT_SUCCESS,
            "candidate": _artifact_ref(record),
        }

    result = _run_correction_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        CONTINUATION_FORWARD_PATHS[4],
        status_value="verified",
    )


def _handle_publish_handoff(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "publish-handoff"
        or args.json is not True
        or args.recovery_id != AUTHORIZED_RECOVERY_ID
        or args.continuation_id != CONTINUATION_ID
        or args.correction_id != CORRECTION_ID
        or args.lifecycle_correction_id
        != LIFECYCLE_CORRECTION_ID
    ):
        raise ContractViolation("publish-handoff arguments mismatch")

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        _, candidate = _verify_handoff_candidate_transition(
            workspace_fd,
            source_root_fd,
        )
        root = candidate["proposedContract"]
        record, created = _publish_or_reopen_continuation_file(
            workspace_fd,
            CONTINUATION_ROOT_PATH,
            _canonical_json_bytes(root),
        )
        _verify_root_lifecycle_correction_chain(
            workspace_fd,
            source_root_fd,
        )
        return {
            "exitCode": EXIT_SUCCESS,
            "created": created,
            "root": _artifact_ref(record),
        }

    result = _run_correction_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        CONTINUATION_ROOT_PATH,
        status_value=(
            "published" if result.get("created") else "verified"
        ),
    )


def _handle_verify_handoff(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "verify-handoff"
        or args.json is not True
        or args.require_pristine is not True
    ):
        raise ContractViolation("verify-handoff arguments mismatch")

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        record, _ = _verify_root_lifecycle_correction_chain(
            workspace_fd,
            source_root_fd,
        )
        return {
            "exitCode": EXIT_SUCCESS,
            "root": _artifact_ref(record),
        }

    result = _run_correction_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        CONTINUATION_ROOT_PATH,
        status_value="verified",
    )


def _theme_batch_paths(
    root_sha256: str,
    batch_id: str,
    theme_run_id: str,
) -> dict[str, str]:
    if (
        re.fullmatch(r"[0-9a-f]{64}", root_sha256) is None
        or BATCH_ID_PATTERN.fullmatch(batch_id) is None
        or BATCH_ID_PATTERN.fullmatch(theme_run_id) is None
    ):
        raise ContractViolation("theme-batch path identity is invalid")
    base = (
        ".claude/ui_snapshots/ux1b/theme-batches/"
        f"{root_sha256}/{batch_id}"
    )
    return {
        "lineage": (
            ".claude/ui_snapshots/ux1b/"
            f"theme-lineage-prechange-{root_sha256}.json"
        ),
        "prechange": f"{base}/prechange.json",
        "pristine": f"{base}/pristine",
        "work": f"{base}/work",
        "candidate": f"{base}/candidate.json",
        "packet": f"{base}/review-packet.json",
        "review": f"{base}/review.json",
        "runtime": ".claude/ui_snapshots/ux1b/runtime",
    }


def _theme_projection(
    schema_version: str,
    records: Sequence[dict[str, Any]],
) -> dict[str, Any]:
    ordered = sorted(
        (copy.deepcopy(record) for record in records),
        key=lambda item: item["path"],
    )
    return {
        "schemaVersion": schema_version,
        "policy": {"include": ["**"], "exclude": [".git/**"]},
        "records": ordered,
        "digest": hashlib.sha256(
            _canonical_json_bytes(ordered)
        ).hexdigest(),
    }


def _theme_projection_comparison(
    schema_version: str,
    rows: Sequence[tuple[dict[str, Any], dict[str, Any]]],
) -> dict[str, Any]:
    before = [copy.deepcopy(row[0]) for row in rows]
    after = [copy.deepcopy(row[1]) for row in rows]
    paths = [record["path"] for record in before]
    return {
        "before": _theme_projection(schema_version, before),
        "after": _theme_projection(schema_version, after),
        "allowedChangedPaths": paths,
        "changes": [
            {
                "path": path,
                "before": copy.deepcopy(left),
                "after": copy.deepcopy(right),
            }
            for path, left, right in zip(paths, before, after)
        ],
        "unchangedRecordsSha256": hashlib.sha256(
            _canonical_json_bytes([])
        ).hexdigest(),
    }


def _theme_init_transition(
    workspace_fd: int,
    source_root_fd: int,
    batch_id: str,
    theme_run_id: str,
) -> dict[str, Any]:
    root_record, root_value = _verify_root_lifecycle_correction_chain(
        workspace_fd,
        source_root_fd,
    )
    root_ref = _artifact_ref(root_record)
    paths = _theme_batch_paths(
        root_record["sha256"],
        batch_id,
        theme_run_id,
    )
    root_fd = os.open(
        CONTINUATION_ROOT_PATH,
        os.O_RDONLY
        | os.O_NOFOLLOW
        | getattr(os, "O_CLOEXEC", 0),
        dir_fd=workspace_fd,
    )
    try:
        try:
            fcntl.flock(
                root_fd,
                fcntl.LOCK_EX | fcntl.LOCK_NB,
            )
        except BlockingIOError as exc:
            raise BlockingIOError(
                "theme root lock is busy"
            ) from exc
        if _relative_leaf_lstat(
            workspace_fd,
            paths["prechange"],
        ) is not None:
            record, value = _read_workspace_schema(
                workspace_fd,
                paths["prechange"],
                "quant-radar-ui-ux-theme-batch-prechange/v1",
            )
            if (
                value["rootContract"] != root_ref
                or value["batchId"] != batch_id
                or value["themeRunId"] != theme_run_id
            ):
                raise ContractViolation(
                    "existing theme-batch prechange differs"
                )
            return {
                "exitCode": EXIT_SUCCESS,
                "created": False,
                "prechange": _artifact_ref(record),
            }

        lineage_value = {
            "schemaVersion": (
                "quant-radar-ui-ux-theme-lineage-prechange/v1"
            ),
            "status": "passed",
            "rootContract": root_ref,
            "themeRunId": theme_run_id,
            "eligibleDestinations": [
                {"path": path.rstrip("/"), "exists": False}
                for path in _theme_shared_lineage_paths(
                    root_record["sha256"],
                    theme_run_id,
                )
            ],
            "runtimeReceipt": copy.deepcopy(
                root_value["runtimeReceipt"]
            ),
        }
        _validate_schema(
            lineage_value["schemaVersion"],
            lineage_value,
        )
        lineage_record, _ = (
            _publish_or_reopen_continuation_file(
                workspace_fd,
                paths["lineage"],
                _canonical_json_bytes(lineage_value),
            )
        )

        live_preimages: list[dict[str, Any]] = []
        for relative in APPLY_PATHS:
            source_record, data = _source_file_record(
                source_root_fd,
                relative,
            )
            live_preimages.append(
                {
                    "source": _source_record_from_file_record(
                        source_record
                    ),
                    "artifact": source_record,
                }
            )
            for role in ("pristine", "work"):
                destination = f"{paths[role]}/{relative}"
                (WORKSPACE_ROOT / destination).parent.mkdir(
                    parents=True,
                    exist_ok=True,
                    mode=0o700,
                )
                fd = _create_relative_file(
                    workspace_fd,
                    destination,
                    data,
                    int(source_record["mode"], 8),
                )
                try:
                    os.fsync(fd)
                finally:
                    os.close(fd)
                _fsync_relative_parent(
                    workspace_fd,
                    destination,
                )

        prechange_value = {
            "schemaVersion": (
                "quant-radar-ui-ux-theme-batch-prechange/v1"
            ),
            "status": "passed",
            "rootContract": root_ref,
            "lineagePrechange": _artifact_ref(lineage_record),
            "batchId": batch_id,
            "themeRunId": theme_run_id,
            "livePreimages": live_preimages,
            "eligibleDestinations": [
                {"path": paths[key], "exists": False}
                for key in ("candidate", "packet", "review")
            ],
            "runtimeReceipt": copy.deepcopy(
                root_value["runtimeReceipt"]
            ),
        }
        _validate_schema(
            prechange_value["schemaVersion"],
            prechange_value,
        )
        prechange_record, created = (
            _publish_or_reopen_continuation_file(
                workspace_fd,
                paths["prechange"],
                _canonical_json_bytes(prechange_value),
            )
        )
        return {
            "exitCode": EXIT_SUCCESS,
            "created": created,
            "prechange": _artifact_ref(prechange_record),
        }
    finally:
        try:
            fcntl.flock(root_fd, fcntl.LOCK_UN)
        finally:
            os.close(root_fd)


def _theme_batch_fixture(
    workspace_fd: int,
    source_root_fd: int,
    batch_id: str,
    theme_run_id: str,
    *,
    require_pristine: bool = True,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, str]]:
    root_record, root_value = _verify_root_lifecycle_correction_chain(
        workspace_fd,
        source_root_fd,
        require_pristine=require_pristine,
    )
    paths = _theme_batch_paths(
        root_record["sha256"],
        batch_id,
        theme_run_id,
    )
    prechange_record, prechange = _read_workspace_schema(
        workspace_fd,
        paths["prechange"],
        "quant-radar-ui-ux-theme-batch-prechange/v1",
    )
    if (
        prechange["rootContract"] != _artifact_ref(root_record)
        or prechange["batchId"] != batch_id
        or prechange["themeRunId"] != theme_run_id
        or prechange["runtimeReceipt"] != root_value["runtimeReceipt"]
    ):
        raise ContractViolation("theme-batch prechange chain differs")
    source_pairs: list[
        tuple[dict[str, Any], dict[str, Any]]
    ] = []
    for relative in APPLY_PATHS:
        pristine_record = _file_record_at(
            WORKSPACE_ROOT,
            f"{paths['pristine']}/{relative}",
            relative,
        )
        work_record = _file_record_at(
            WORKSPACE_ROOT,
            f"{paths['work']}/{relative}",
            relative,
        )
        source_pairs.append(
            (
                _source_record_from_file_record(pristine_record),
                _source_record_from_file_record(work_record),
            )
        )
    fixture = {
        "rootContract": _artifact_ref(root_record),
        "batchId": batch_id,
        "themeRunId": theme_run_id,
        "prechange": _artifact_ref(prechange_record),
        "runtimeReceipt": copy.deepcopy(
            root_value["runtimeReceipt"]
        ),
        "runtimeRoot": paths["runtime"],
        "pristineRoot": paths["pristine"],
        "workRoot": paths["work"],
        "candidateSourceRoot": ".",
        "livePreimages": copy.deepcopy(
            prechange["livePreimages"]
        ),
        "applyOrder": list(APPLY_PATHS),
        "mirrorComparison": _theme_projection_comparison(
            "quant-radar-ui-ux-ux1b-source-mirror/v1",
            source_pairs[:3],
        ),
        "supplementalComparison": (
            _theme_projection_comparison(
                "quant-radar-ui-ux-supplemental-source/v1",
                source_pairs[3:],
            )
        ),
    }
    return fixture, root_value, paths


def _handle_init_theme_batch(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "init-theme-batch"
        or args.json is not True
    ):
        raise ContractViolation("init-theme-batch arguments mismatch")
    result = _run_correction_descriptor_command(
        lambda workspace_fd, source_root_fd: (
            _theme_init_transition(
                workspace_fd,
                source_root_fd,
                args.batch_id,
                args.theme_run_id,
            )
        )
    )
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    prechange = result.get("prechange")
    if (
        not isinstance(prechange, Mapping)
        or not isinstance(prechange.get("path"), str)
    ):
        raise ContractViolation(
            "theme initialization prechange artifact is missing"
        )
    destination = result["prechange"]["path"]
    return _public_success(
        args.command,
        destination,
        status_value=(
            "created" if result.get("created") else "verified"
        ),
    )


def _handle_seal_theme_batch(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "seal-theme-batch"
        or args.json is not True
    ):
        raise ContractViolation("seal-theme-batch arguments mismatch")

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        fixture, _, paths = _theme_batch_fixture(
            workspace_fd,
            source_root_fd,
            args.batch_id,
            args.theme_run_id,
        )
        result = _seal_theme_batch(
            workspace_fd,
            args.batch_id,
            args.theme_run_id,
            fixture=fixture,
        )
        return {**result, "destination": paths["candidate"]}

    result = _run_continuation_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        result["destination"],
        status_value="sealed",
    )


def _theme_batch_ready(
    workspace_fd: int,
    source_root_fd: int,
    batch_id: str,
    theme_run_id: str,
    *,
    require_pristine: bool = True,
) -> dict[str, Any]:
    fixture, root_value, paths = _theme_batch_fixture(
        workspace_fd,
        source_root_fd,
        batch_id,
        theme_run_id,
        require_pristine=require_pristine,
    )
    candidate_record, candidate = _read_workspace_schema(
        workspace_fd,
        paths["candidate"],
        "quant-radar-ui-ux-theme-batch-candidate/v2",
    )
    packet_record, packet = _read_workspace_schema(
        workspace_fd,
        paths["packet"],
        "quant-radar-ui-ux-review-packet/v1",
    )
    review_record, review = _read_workspace_schema(
        workspace_fd,
        paths["review"],
        "quant-radar-ui-ux-manual-review/v2",
    )
    if (
        candidate["rootContract"] != fixture["rootContract"]
        or candidate["batchId"] != batch_id
        or candidate["themeRunId"] != theme_run_id
        or packet["machineReport"] != _artifact_ref(candidate_record)
        or review["packet"] != _artifact_ref(packet_record)
        or review["status"] != "accepted"
        or review["decision"] != "accepted"
        or candidate["runtimeReceipt"]
        != root_value["runtimeReceipt"]
    ):
        raise ContractViolation("theme-batch review chain differs")
    return {
        "fixture": fixture,
        "rootValue": root_value,
        "paths": paths,
        "candidateRecord": candidate_record,
        "candidate": candidate,
        "packetRecord": packet_record,
        "reviewRecord": review_record,
    }


def _handle_verify_theme_batch_ready(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "verify-theme-batch-ready"
        or args.json is not True
    ):
        raise ContractViolation(
            "verify-theme-batch-ready arguments mismatch"
        )
    holder: dict[str, Any] = {}

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        state = _theme_batch_ready(
            workspace_fd,
            source_root_fd,
            args.batch_id,
            args.theme_run_id,
        )
        holder["path"] = state["paths"]["review"]
        return {"exitCode": EXIT_SUCCESS}

    result = _run_continuation_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        holder["path"],
        status_value="ready",
    )


def _theme_apply_snapshot(
    state: Mapping[str, Any],
    *,
    actor: str,
) -> dict[str, Any]:
    candidate = state["candidate"]
    changes = candidate["changes"]
    return {
        "actor": actor,
        "rootContract": {
            "artifact": {
                **state["fixture"]["rootContract"],
                **{
                    key: state["rootRecord"][key]
                    for key in (
                        "mode",
                        "uid",
                        "gid",
                        "device",
                        "inode",
                        "nlink",
                    )
                },
            },
            "value": copy.deepcopy(state["rootValue"]),
        },
        "batchId": candidate["batchId"],
        "themeRunId": candidate["themeRunId"],
        "candidate": _artifact_ref(state["candidateRecord"]),
        "reviewPacket": _artifact_ref(state["packetRecord"]),
        "manualReview": _artifact_ref(state["reviewRecord"]),
        "runtimeReceipt": copy.deepcopy(
            candidate["runtimeReceipt"]
        ),
        "livePreimages": copy.deepcopy(
            state["fixture"]["livePreimages"]
        ),
        "sealedPreimages": [
            copy.deepcopy(change["preimage"])
            for change in changes
        ],
        "sealedPostimages": [
            copy.deepcopy(change["postimage"])
            for change in changes
        ],
        "applyOrder": list(APPLY_PATHS),
        "changesSha256": candidate["changesSha256"],
        "mirrorComparison": copy.deepcopy(
            candidate["mirrorComparison"]
        ),
        "supplementalComparison": copy.deepcopy(
            candidate["supplementalComparison"]
        ),
    }


def _handle_apply_theme_batch(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "apply-theme-batch"
        or args.json is not True
    ):
        raise ContractViolation("apply-theme-batch arguments mismatch")
    holder: dict[str, Any] = {}

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        state = _theme_batch_ready(
            workspace_fd,
            source_root_fd,
            args.batch_id,
            args.theme_run_id,
        )
        root_record, _ = _verify_root_lifecycle_correction_chain(
            workspace_fd,
            source_root_fd,
            require_pristine=False,
        )
        state["rootRecord"] = root_record
        snapshot = _theme_apply_snapshot(
            state,
            actor="original",
        )
        result = _apply_theme_batch_forward(
            workspace_fd,
            root_record,
            args.batch_id,
            args.theme_run_id,
            fixture=snapshot,
        )
        holder["path"] = _theme_shared_lineage_paths(
            root_record["sha256"],
            args.theme_run_id,
        )[5]
        return result

    result = _run_continuation_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        holder["path"],
        status_value="applied",
    )


def _reconciliation_snapshot(
    workspace_fd: int,
    source_root_fd: int,
) -> tuple[dict[str, Any], str]:
    root_record, root_value = _verify_root_lifecycle_correction_chain(
        workspace_fd,
        source_root_fd,
        require_pristine=False,
    )
    attempt_path = _theme_shared_lineage_paths(
        root_record["sha256"],
        "placeholder",
    )[1]
    _, attempt = _read_workspace_schema(
        workspace_fd,
        attempt_path,
        "quant-radar-ui-ux-theme-batch-attempt/v1",
    )
    batch_id = attempt["batchId"]
    theme_run_id = attempt["themeRunId"]
    state = _theme_batch_ready(
        workspace_fd,
        source_root_fd,
        batch_id,
        theme_run_id,
        require_pristine=False,
    )
    state["rootRecord"] = root_record
    state["rootValue"] = root_value
    return (
        _theme_apply_snapshot(state, actor="reconciler"),
        theme_run_id,
    )


def _handle_reconcile_theme_batch(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "reconcile-theme-batch"
        or args.json is not True
    ):
        raise ContractViolation(
            "reconcile-theme-batch arguments mismatch"
        )
    holder: dict[str, Any] = {}

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        snapshot, theme_run_id = _reconciliation_snapshot(
            workspace_fd,
            source_root_fd,
        )
        result = _reconcile_theme_batch(
            workspace_fd,
            snapshot,
        )
        root_sha = snapshot["rootContract"]["artifact"]["sha256"]
        holder["path"] = _theme_shared_lineage_paths(
            root_sha,
            theme_run_id,
        )[4]
        return result

    result = _run_continuation_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        holder["path"],
        status_value=str(result.get("action", "reconciled")),
    )


def _handle_verify_theme_batch_applied(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "verify-theme-batch-applied"
        or args.json is not True
    ):
        raise ContractViolation(
            "verify-theme-batch-applied arguments mismatch"
        )
    holder: dict[str, Any] = {}

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        root_record, _ = _verify_root_lifecycle_correction_chain(
            workspace_fd,
            source_root_fd,
            require_pristine=False,
        )
        attempt_path = _theme_shared_lineage_paths(
            root_record["sha256"],
            "placeholder",
        )[1]
        _, attempt = _read_workspace_schema(
            workspace_fd,
            attempt_path,
            "quant-radar-ui-ux-theme-batch-attempt/v1",
        )
        applied_path = _theme_shared_lineage_paths(
            root_record["sha256"],
            attempt["themeRunId"],
        )[5]
        applied_record, _ = _read_workspace_schema(
            workspace_fd,
            applied_path,
            "quant-radar-ui-ux-theme-batch-applied/v1",
        )
        _verify_applied_receipt(
            _artifact_ref(applied_record),
            workspace_fd=workspace_fd,
        )
        holder["path"] = applied_path
        return {"exitCode": EXIT_SUCCESS}

    result = _run_continuation_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        holder["path"],
        status_value="verified",
    )


def _publish_downstream_review(
    args: argparse.Namespace,
) -> dict[str, Any]:
    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        root_record, _ = _verify_root_lifecycle_correction_chain(
            workspace_fd,
            source_root_fd,
            require_pristine=(args.kind == "theme-batch"),
        )
        lineage = (
            args.batch_id
            if args.kind == "theme-batch"
            else args.theme_run_id
        )
        return _publish_review_from_external_intake(
            workspace_fd,
            kind=args.kind,
            root_sha256=root_record["sha256"],
            lineage_id=str(lineage),
        )

    return _run_continuation_descriptor_command(operation)


class _ThemeCaptureProductionDriver:
    requires_lease_fd = True

    def __init__(
        self,
        root: Path,
        runtime_receipt: Mapping[str, Any],
    ) -> None:
        self.root = root.resolve()
        self.runtime_receipt = copy.deepcopy(
            dict(runtime_receipt)
        )

    @staticmethod
    def _timestamp() -> str:
        return time.strftime(
            "%Y-%m-%dT%H:%M:%SZ",
            time.gmtime(),
        )

    def run_capture(
        self,
        kind: str,
        destination: str,
        *,
        lease_fd: int | None = None,
    ) -> dict[str, Any]:
        plan = _capture_runner_plan_value(
            self.runtime_receipt,
            kind,
            destination,
        )
        execution = plan["execution"]
        if type(lease_fd) is not int or lease_fd < 0:
            raise ContractViolation(
                "theme capture lease descriptor is invalid"
            )
        lease = os.fstat(lease_fd)
        destination_prefix = (
            ".claude/ui_snapshots/ux1b/theme-states-"
            if kind == "theme-states"
            else ".claude/ui_snapshots/ux1b/posttheme-"
        )
        theme_run_id = destination.removeprefix(
            destination_prefix
        )
        if (
            not theme_run_id
            or destination
            != destination_prefix + theme_run_id
        ):
            raise ContractViolation(
                "theme capture destination lineage differs"
            )
        lease_relative = _theme_capture_paths(
            kind,
            theme_run_id,
        )["lease"]
        lease_record = _file_record_at(
            self.root,
            lease_relative,
        )
        if (
            lease.st_dev,
            lease.st_ino,
        ) != (
            lease_record["device"],
            lease_record["inode"],
        ):
            raise ContractViolation(
                "theme capture lease identity differs"
            )
        environment = dict(execution["environment"])
        for key in (
            "HOME",
            "TMPDIR",
            "XDG_CACHE_HOME",
            "XDG_CONFIG_HOME",
            "XDG_DATA_HOME",
        ):
            Path(environment[key]).mkdir(
                parents=True,
                exist_ok=True,
                mode=0o700,
            )
        started_at = self._timestamp()
        try:
            process = subprocess.Popen(
                execution["argv"],
                cwd=self.root,
                env=environment,
                stdin=subprocess.DEVNULL,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                pass_fds=(lease_fd,),
                close_fds=True,
                start_new_session=True,
            )
        except OSError as exc:
            raise PrimitiveUnavailable(
                "theme capture runner is unavailable"
            ) from exc
        if process.stdout is None or process.stderr is None:
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            process.wait()
            raise PrimitiveUnavailable(
                "theme capture runner streams are unavailable"
            )
        streams = {
            process.stdout.fileno(): ("stdout", process.stdout),
            process.stderr.fileno(): ("stderr", process.stderr),
        }
        buffers = {"stdout": bytearray(), "stderr": bytearray()}
        selector = selectors.DefaultSelector()
        deadline = time.monotonic() + execution["timeoutSeconds"]
        overflow = False
        try:
            for fd in streams:
                os.set_blocking(fd, False)
                selector.register(fd, selectors.EVENT_READ)
            while streams:
                now = time.monotonic()
                if now >= deadline:
                    raise TimeoutError
                for key, _ in selector.select(
                    min(0.05, max(0.0, deadline - now))
                ):
                    fd = key.fd
                    role, stream = streams[fd]
                    try:
                        chunk = os.read(fd, 65_536)
                    except BlockingIOError:
                        continue
                    if not chunk:
                        selector.unregister(fd)
                        stream.close()
                        del streams[fd]
                        continue
                    buffers[role].extend(chunk)
                    if len(buffers[role]) > execution[
                        f"{role}LimitBytes"
                    ]:
                        overflow = True
                        raise TimeoutError
        except (TimeoutError, KeyboardInterrupt) as exc:
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            process.wait()
            if isinstance(exc, KeyboardInterrupt):
                raise
            raise ContractViolation(
                "theme capture runner output overflowed"
                if overflow
                else "theme capture runner timed out"
            ) from exc
        finally:
            selector.close()
            for _, stream in streams.values():
                if not stream.closed:
                    stream.close()
        pre_reap: dict[str, Any] | None = None
        quiescence_deadline = time.monotonic() + 25
        while time.monotonic() < quiescence_deadline:
            sample = _Task9ProductionDriver._observe_outer_family(
                process.pid,
                "pre_reap",
            )
            leader_rows = [
                row
                for row in sample["rows"]
                if row["pid"] == process.pid
            ]
            if (
                len(sample["rows"]) == 1
                and len(leader_rows) == 1
                and leader_rows[0]["state"].startswith("Z")
            ):
                pre_reap = sample
                break
            time.sleep(0.05)
        if pre_reap is None:
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            process.wait()
            raise ContractViolation(
                "theme capture process family did not quiesce"
            )
        waited_pid, wait_status = os.waitpid(process.pid, 0)
        if waited_pid != process.pid:
            raise ContractViolation(
                "theme capture reaped the wrong runner"
            )
        process.returncode = os.waitstatus_to_exitcode(wait_status)
        post_reap = _Task9ProductionDriver._observe_outer_family(
            process.pid,
            "post_reap",
        )
        if post_reap["rows"]:
            raise ContractViolation(
                "theme capture family remained after reap"
            )
        stdout = bytes(buffers["stdout"])
        stderr = bytes(buffers["stderr"])
        if (
            process.returncode != 0
            or stderr
        ):
            raise ContractViolation(
                "theme capture runner did not exit cleanly"
            )
        process_family = (
            _CandidateRegressionProcessDriver._family_receipt(
                process_family_plan=copy.deepcopy(
                    execution["processFamily"]
                ),
                process_group_id=process.pid,
                exit_watch_result={
                    "registration": "esrch",
                    "outcome": "owned_zombie",
                    "eventCount": 0,
                },
                samples=(pre_reap, post_reap),
                return_code=0,
                signal_number=None,
                wait_status=wait_status,
            )
        )
        runner_receipt = {
            "plan": plan,
            "startedAt": started_at,
            "finishedAt": self._timestamp(),
            "outcome": "exited",
            "returnCode": 0,
            "signal": None,
            "stdoutSha256": hashlib.sha256(stdout).hexdigest(),
            "stderrSha256": hashlib.sha256(stderr).hexdigest(),
            "stdoutBytes": len(stdout),
            "stderrBytes": len(stderr),
            "processGroupId": process.pid,
            "processFamily": process_family,
        }
        _validate_schema("RunnerReceipt", runner_receipt)
        manifest_record = _file_record_at(
            self.root,
            f"{destination}/manifest.json",
        )
        manifest_bytes = (
            self.root / destination / "manifest.json"
        ).read_bytes()
        manifest = _strict_json_bytes(
            manifest_bytes,
            allow_float=True,
        )
        if (
            not isinstance(manifest, dict)
            or manifest_bytes != _canonical_json_bytes(manifest)
            or not isinstance(manifest.get("captures"), list)
        ):
            raise ContractViolation(
                "theme capture manifest is not canonical"
            )
        captures = copy.deepcopy(manifest["captures"])
        visual_items: list[dict[str, Any]] = []
        artifact_count = 0
        for capture in captures:
            capture_id = capture["id"]
            artifacts = capture["artifacts"]
            png = artifacts["png"]
            artifact_count += 2
            if kind == "theme-states":
                visual_items.append(
                    {
                        "id": capture_id,
                        "artifact": _artifact_ref(
                            _file_record_at(
                                self.root,
                                f"{destination}/{png['path']}",
                            )
                        ),
                        "dimensions": {
                            "width": png["width"],
                            "height": png["height"],
                        },
                    }
                )
                for supplemental in artifacts[
                    "supplementalArtifacts"
                ]:
                    artifact_count += 1
                    visual_items.append(
                        {
                            "id": (
                                f"{capture_id}::"
                                f"{supplemental['id']}"
                            ),
                            "artifact": _artifact_ref(
                                _file_record_at(
                                    self.root,
                                    (
                                        f"{destination}/"
                                        f"{supplemental['path']}"
                                    ),
                                )
                            ),
                            "dimensions": {
                                "width": supplemental["width"],
                                "height": supplemental["height"],
                            },
                        }
                    )
        capture_ids = [row["id"] for row in captures]
        manifest_ref = _artifact_ref(manifest_record)
        bundle = {
            "manifest": manifest_ref,
            "mode": (
                "ux1b-theme"
                if kind == "theme-states"
                else "ux1b-full-pages"
            ),
            "phase": "posttheme",
            "expectedCaptureCount": len(captures),
            "capturedCount": len(captures),
            "artifactCount": artifact_count,
            "namespaceLeafCount": artifact_count + 1,
            "captureIdsSha256": hashlib.sha256(
                _canonical_json_bytes(capture_ids)
            ).hexdigest(),
            "sourceDigest": HISTORICAL_SOURCE_SHA256,
            "captureStackDigest": (
                "69eeec0dcdffdab16d5696896cb4fc5ddb27071591953d04b4c907ea5b78055e"
            ),
        }
        return {
            "returnCode": 0,
            "signal": None,
            "childrenQuiescent": True,
            "manifest": manifest_ref,
            "captureCount": len(captures),
            "artifactCount": artifact_count,
            "namespaceLeafCount": artifact_count + 1,
            "runnerReceipt": runner_receipt,
            "bundle": bundle,
            "captures": captures,
            "visualItems": sorted(
                visual_items,
                key=lambda item: item["id"],
            ),
        }


def _theme_capture_paths(
    kind: str,
    theme_run_id: str,
) -> dict[str, str]:
    if BATCH_ID_PATTERN.fullmatch(theme_run_id) is None:
        raise ContractViolation("theme capture run ID is invalid")
    base = ".claude/ui_snapshots/ux1b"
    if kind == "theme-states":
        return {
            "lease": f"{base}/.theme-states-{theme_run_id}.lease",
            "intent": (
                f"{base}/theme-state-capture-intent-"
                f"{theme_run_id}.json"
            ),
            "checkpoint": (
                f"{base}/theme-state-capture-checkpoint-"
                f"{theme_run_id}.json"
            ),
            "destination": f"{base}/theme-states-{theme_run_id}",
            "candidate": (
                f"{base}/theme-state-candidate-{theme_run_id}.json"
            ),
            "packet": (
                f"{base}/review-packet-theme-states-"
                f"{theme_run_id}.json"
            ),
        }
    if kind == "posttheme":
        return {
            "lease": f"{base}/.posttheme-{theme_run_id}.lease",
            "intent": (
                f"{base}/posttheme-capture-intent-"
                f"{theme_run_id}.json"
            ),
            "checkpoint": (
                f"{base}/posttheme-capture-checkpoint-"
                f"{theme_run_id}.json"
            ),
            "destination": f"{base}/posttheme-{theme_run_id}",
            "candidate": (
                f"{base}/posttheme-comparison-candidate-"
                f"{theme_run_id}.json"
            ),
            "packet": (
                f"{base}/review-packet-posttheme-"
                f"{theme_run_id}.json"
            ),
        }
    raise ContractViolation("unknown theme capture kind")


def _theme_capture_state(
    workspace_fd: int,
    source_root_fd: int,
    kind: str,
    theme_run_id: str,
) -> dict[str, Any]:
    root_record, root_value = _verify_root_lifecycle_correction_chain(
        workspace_fd,
        source_root_fd,
        require_pristine=False,
    )
    applied_path = _theme_shared_lineage_paths(
        root_record["sha256"],
        theme_run_id,
    )[5]
    applied_record, applied_value = _read_workspace_schema(
        workspace_fd,
        applied_path,
        "quant-radar-ui-ux-theme-batch-applied/v1",
    )
    _verify_applied_receipt(
        _artifact_ref(applied_record),
        workspace_fd=workspace_fd,
    )
    attestation_record: dict[str, Any] | None = None
    attestation_value: dict[str, Any] | None = None
    pretheme_record: dict[str, Any] | None = None
    pretheme_value: dict[str, Any] | None = None
    pretheme_rows: list[dict[str, Any]] = []
    if kind == "posttheme":
        attestation_path = _theme_shared_lineage_paths(
            root_record["sha256"],
            theme_run_id,
        )[14]
        attestation_record, attestation_value = (
            _read_workspace_schema(
                workspace_fd,
                attestation_path,
                "quant-radar-ui-ux-theme-state-attestation/v2",
            )
        )
        pretheme_ref = root_value["task9"]["pretheme"]
        pretheme_record, pretheme_data = (
            _relative_regular_record_and_bytes(
                workspace_fd,
                pretheme_ref["path"],
            )
        )
        if _artifact_ref(pretheme_record) != pretheme_ref:
            raise ContractViolation(
                "posttheme pretheme authority drifted"
            )
        pretheme_value = _strict_json_bytes(
            pretheme_data,
            allow_float=True,
        )
        if (
            not isinstance(pretheme_value, dict)
            or not isinstance(
                pretheme_value.get("captures"),
                list,
            )
        ):
            raise ContractViolation(
                "posttheme pretheme manifest is invalid"
            )
        destination = str(Path(pretheme_ref["path"]).parent)
        for capture in pretheme_value["captures"]:
            png = capture["artifacts"]["png"]
            pretheme_rows.append(
                {
                    "id": capture["id"],
                    "artifact": _artifact_ref(
                        _file_record_at(
                            WORKSPACE_ROOT,
                            f"{destination}/{png['path']}",
                        )
                    ),
                    "dimensions": {
                        "width": png["width"],
                        "height": png["height"],
                    },
                }
            )
    return {
        "themeRunId": theme_run_id,
        "rootContract": _artifact_ref(root_record),
        "rootValue": root_value,
        "appliedBatch": _artifact_ref(applied_record),
        "appliedValue": applied_value,
        "stateAttestation": (
            None
            if attestation_record is None
            else _artifact_ref(attestation_record)
        ),
        "stateAttestationValue": attestation_value,
        "pretheme": (
            None
            if pretheme_record is None
            else _artifact_ref(pretheme_record)
        ),
        "prethemeManifest": pretheme_value,
        "prethemeRows": pretheme_rows,
        "sourceComparisons": {
            "mirror": copy.deepcopy(
                applied_value["mirrorProjection"]
            ),
            "supplemental": copy.deepcopy(
                applied_value["supplementalProjection"]
            ),
        },
        "paths": _theme_capture_paths(kind, theme_run_id),
        "runtimeReceipt": copy.deepcopy(
            applied_value["runtimeReceipt"]
        ),
    }


def _handle_theme_capture(
    args: argparse.Namespace,
    kind: str,
    event: str,
) -> dict[str, Any]:
    command = (
        ("capture-" if event == "capture" else "reconcile-")
        + ("theme-states" if kind == "theme-states" else "posttheme")
    )
    if (
        args.command != command
        or args.json is not True
    ):
        raise ContractViolation(f"{command} arguments mismatch")
    holder: dict[str, Any] = {}

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        state = _theme_capture_state(
            workspace_fd,
            source_root_fd,
            kind,
            args.theme_run_id,
        )
        driver = _ThemeCaptureProductionDriver(
            WORKSPACE_ROOT,
            state["runtimeReceipt"],
        )
        result = _capture_transition(
            workspace_fd,
            kind,
            state,
            event,
            driver=driver,
        )
        holder["path"] = state["paths"]["candidate"]
        return result

    result = _run_continuation_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        holder["path"],
        status_value=(
            "captured" if event == "capture" else "reconciled"
        ),
    )


def _handle_capture_theme_states(
    args: argparse.Namespace,
) -> dict[str, Any]:
    return _handle_theme_capture(
        args,
        "theme-states",
        "capture",
    )


