def _handle_close_theme_states(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "close-theme-states"
        or args.json is not True
    ):
        raise ContractViolation(
            "close-theme-states arguments mismatch"
        )
    holder: dict[str, Any] = {}

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        state = _theme_capture_state(
            workspace_fd,
            source_root_fd,
            "theme-states",
            args.theme_run_id,
        )
        paths = state["paths"]
        candidate_record, candidate = _read_workspace_schema(
            workspace_fd,
            paths["candidate"],
            "quant-radar-ui-ux-theme-state-candidate/v2",
        )
        packet_record, packet = _read_workspace_schema(
            workspace_fd,
            paths["packet"],
            "quant-radar-ui-ux-review-packet/v1",
        )
        _, _, review_path = _review_paths(
            "theme-states",
            state["rootContract"]["sha256"],
            args.theme_run_id,
        )
        review_record, review = _read_workspace_schema(
            workspace_fd,
            review_path,
            "quant-radar-ui-ux-manual-review/v2",
        )
        if (
            packet["machineReport"]
            != _artifact_ref(candidate_record)
            or review["packet"] != _artifact_ref(packet_record)
            or review["status"] != "accepted"
            or review["decision"] != "accepted"
        ):
            raise ContractViolation(
                "theme-state review chain differs"
            )
        attestation = {
            "schemaVersion": (
                "quant-radar-ui-ux-theme-state-attestation/v2"
            ),
            "status": "passed",
            "rootContract": copy.deepcopy(
                state["rootContract"]
            ),
            "appliedBatch": copy.deepcopy(
                state["appliedBatch"]
            ),
            "themeRunId": args.theme_run_id,
            "captureIntent": copy.deepcopy(
                candidate["captureIntent"]
            ),
            "captureCheckpoint": copy.deepcopy(
                candidate["captureCheckpoint"]
            ),
            "candidate": _artifact_ref(candidate_record),
            "reviewPacket": _artifact_ref(packet_record),
            "manualReview": _artifact_ref(review_record),
            "manifest": copy.deepcopy(candidate["manifest"]),
            "mirrorProjection": copy.deepcopy(
                candidate["mirrorProjection"]
            ),
            "supplementalProjection": copy.deepcopy(
                candidate["supplementalProjection"]
            ),
            "runtimeReceipt": copy.deepcopy(
                candidate["runtimeReceipt"]
            ),
        }
        _validate_schema(attestation["schemaVersion"], attestation)
        destination = _theme_shared_lineage_paths(
            state["rootContract"]["sha256"],
            args.theme_run_id,
        )[14]
        record, created = _publish_or_reopen_continuation_file(
            workspace_fd,
            destination,
            _canonical_json_bytes(attestation),
        )
        holder["path"] = destination
        return {
            "exitCode": EXIT_SUCCESS,
            "created": created,
            "attestation": _artifact_ref(record),
        }

    result = _run_continuation_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        holder["path"],
        status_value=(
            "closed" if result.get("created") else "verified"
        ),
    )


def _handle_finalize_theme(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if (
        args.command != "finalize-theme"
        or args.json is not True
    ):
        raise ContractViolation("finalize-theme arguments mismatch")
    holder: dict[str, Any] = {}

    def operation(
        workspace_fd: int,
        source_root_fd: int,
    ) -> dict[str, Any]:
        state = _theme_capture_state(
            workspace_fd,
            source_root_fd,
            "posttheme",
            args.theme_run_id,
        )
        paths = state["paths"]
        candidate_record, candidate = _read_workspace_schema(
            workspace_fd,
            paths["candidate"],
            "quant-radar-ui-ux-posttheme-comparison/v2",
        )
        packet_record, packet = _read_workspace_schema(
            workspace_fd,
            paths["packet"],
            "quant-radar-ui-ux-review-packet/v1",
        )
        _, _, review_path = _review_paths(
            "posttheme",
            state["rootContract"]["sha256"],
            args.theme_run_id,
        )
        review_record, review = _read_workspace_schema(
            workspace_fd,
            review_path,
            "quant-radar-ui-ux-manual-review/v2",
        )
        if (
            packet["machineReport"]
            != _artifact_ref(candidate_record)
            or review["packet"] != _artifact_ref(packet_record)
            or review["status"] != "accepted"
            or review["decision"] != "accepted"
        ):
            raise ContractViolation("posttheme review chain differs")
        closure = {
            "schemaVersion": "quant-radar-ui-ux-theme-closure/v2",
            "status": "passed",
            "rootContract": copy.deepcopy(
                state["rootContract"]
            ),
            "appliedBatch": copy.deepcopy(
                state["appliedBatch"]
            ),
            "stateAttestation": copy.deepcopy(
                state["stateAttestation"]
            ),
            "themeRunId": args.theme_run_id,
            "machineComparison": _artifact_ref(candidate_record),
            "reviewPacket": _artifact_ref(packet_record),
            "manualReview": _artifact_ref(review_record),
            "posttheme": copy.deepcopy(candidate["posttheme"]),
            "mirrorProjection": copy.deepcopy(
                state["appliedValue"]["mirrorProjection"]
            ),
            "supplementalProjection": copy.deepcopy(
                state["appliedValue"][
                    "supplementalProjection"
                ]
            ),
            "runtimeReceipt": copy.deepcopy(
                candidate["runtimeReceipt"]
            ),
        }
        _validate_schema(closure["schemaVersion"], closure)
        destination = _theme_shared_lineage_paths(
            state["rootContract"]["sha256"],
            args.theme_run_id,
        )[23]
        record, created = _publish_or_reopen_continuation_file(
            workspace_fd,
            destination,
            _canonical_json_bytes(closure),
        )
        holder["path"] = destination
        return {
            "exitCode": EXIT_SUCCESS,
            "created": created,
            "closure": _artifact_ref(record),
        }

    result = _run_continuation_descriptor_command(operation)
    if result.get("exitCode") != EXIT_SUCCESS:
        return {"exitCode": result["exitCode"]}
    return _public_success(
        args.command,
        holder["path"],
        status_value=(
            "finalized" if result.get("created") else "verified"
        ),
    )


def _handle_unavailable_public_command(
    args: argparse.Namespace,
) -> dict[str, Any]:
    if args.command not in PUBLIC_COMMANDS:
        raise ContractViolation("unknown public command")
    return {"exitCode": EXIT_CONTRACT}


